package com.waypointer;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("waypointer")
public interface WaypointerConfig extends Config
{
    @ConfigSection(
        name = "Sailing",
        description = "Ocean waypoint pathing via Chart Plotter",
        position = 100
    )
    String sailingSection = "sailing";

    @ConfigItem(
        keyName = "tileRightClickEnabled",
        name = "Right-click tiles to save",
        description = "Adds 'Save as Waypoint' to the Shift + right-click menu on tiles in the 3D world. "
            + "Shift is required, to keep the plain right-click menu uncluttered.",
        position = 10
    )
    default boolean tileRightClickEnabled() { return false; }

    @ConfigItem(
        keyName = "entityRightClickEnabled",
        name = "Right-click NPCs and objects to save",
        description = "Adds 'Save as Waypoint' to the right-click menu on NPCs and game objects. "
            + "Objects require holding Shift; NPCs do not, since Shift hides them. "
            + "The NPC's name and tile at click time are used as the default.",
        position = 11
    )
    default boolean entityRightClickEnabled() { return false; }

    @ConfigItem(
        keyName = "showNearestLandmarkBar",
        name = "Show 'nearest landmark' bar",
        description = "Adds a row of one-click shortcuts in the sidebar to path to the nearest "
            + "landmark. Click the customise button to choose which landmark types appear. "
            + "Off hides the row entirely.",
        position = 15
    )
    default boolean showNearestLandmarkBar() { return true; }

    @ConfigItem(
        keyName = "showPathingBanner",
        name = "Show 'Heading to' card",
        description = "Show the destination at the top of the panel while a path is active.",
        position = 20
    )
    default boolean showPathingBanner() { return true; }

    @ConfigItem(
        keyName = "confirmBeforeWildernessPlay",
        name = "Confirm before pathing into Wilderness",
        description = "Show a confirm dialog when the destination tile is inside the Wilderness.",
        position = 25
    )
    default boolean confirmBeforeWildernessPlay() { return true; }

    @ConfigItem(
        keyName = "showWildernessGlyph",
        name = "Show wilderness skull on row",
        description = "Prefix waypoint rows with a skull when the destination is in the Wilderness.",
        position = 26
    )
    default boolean showWildernessGlyph() { return true; }

    @ConfigItem(
        keyName = "autoPathOnDeath",
        name = "Auto-path to death location",
        description = "When you die, automatically start a path back to the tile you "
            + "died on. Requires the Shortest Path plugin.",
        position = 27
    )
    default boolean autoPathOnDeath() { return false; }

    @ConfigItem(
        keyName = "newestPinAtTop",
        name = "Newest pin at top",
        description = "Order pinned waypoints with the most recently pinned at the top. Off puts newest at the bottom.",
        position = 30
    )
    default boolean newestPinAtTop() { return true; }

    @ConfigItem(
        keyName = "routesEnabled",
        name = "Enable Routes",
        description = "Show the Routes tab for building and running guided multi-step routes "
            + "(farm runs, agility laps). Off hides the feature entirely.",
        position = 40
    )
    default boolean routesEnabled() { return true; }

    @ConfigItem(
        keyName = "routeAdvanceHotkey",
        name = "Route: next step hotkey",
        description = "Key that advances (or skips) the current route step while a route is "
            + "running. Only fires while a route is active.",
        position = 41
    )
    default net.runelite.client.config.Keybind routeAdvanceHotkey()
    {
        return net.runelite.client.config.Keybind.NOT_SET;
    }

    @ConfigItem(
        keyName = "showRouteOverlay",
        name = "Show in-game route box",
        description = "Draw a read-only step box in the game window while a route is running.",
        position = 42
    )
    default boolean showRouteOverlay() { return true; }

    @ConfigItem(
        keyName = "sailingEnabled",
        name = "Sail to ocean waypoints",
        description = "When you press Play on a waypoint that sits on open water, walk to a dock, "
            + "then hand off to the Chart Plotter plugin to sail there. Requires Chart Plotter.",
        position = 101,
        section = sailingSection
    )
    default boolean sailingEnabled() { return true; }

    // Hidden:JSON-encoded map of categoryId -> collapsed boolean. Empty = all expanded.
    @ConfigItem(
        keyName = "categoryCollapsedJson",
        name = "",
        description = "",
        hidden = true
    )
    default String categoryCollapsedJson() { return "{}"; }

    @ConfigItem(keyName = "categoryCollapsedJson", name = "", description = "")
    void setCategoryCollapsedJson(String v);

    // Hidden:set when user dismisses the 'shortest-path missing' banner.
    @ConfigItem(
        keyName = "shortestPathBannerDismissed",
        name = "",
        description = "",
        hidden = true
    )
    default boolean shortestPathBannerDismissed() { return false; }

    @ConfigItem(keyName = "shortestPathBannerDismissed", name = "", description = "")
    void setShortestPathBannerDismissed(boolean v);

    // Hidden: JSON-encoded LandmarkSelection (order + selected subset).
    // Empty seeds with the canonical default on first read.
    @ConfigItem(
        keyName = "landmarkSelectionJson",
        name = "",
        description = "",
        hidden = true
    )
    default String landmarkSelectionJson() { return ""; }

    @ConfigItem(keyName = "landmarkSelectionJson", name = "", description = "")
    void setLandmarkSelectionJson(String v);
}

package com.waypointer;

import com.google.inject.Provides;
import com.waypointer.service.DeathAutoPathfinder;
import com.waypointer.service.WaypointMenuHandler;
import com.waypointer.service.WaypointPathfinder;
import com.waypointer.service.WaypointStore;
import com.waypointer.service.WaypointStorePersistence;
import com.waypointer.ui.Icon;
import com.waypointer.ui.NpcHighlightOverlay;
import com.waypointer.ui.TabHost;
import com.waypointer.ui.WaypointerPanel;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
    name = "Waypointer",
    description = "Save in-game locations and one-click path to them, on land or at sea.",
    tags = {"map", "travel", "pathfinding", "waypoints"}
)
public class WaypointerPlugin extends Plugin
{
    @Inject private WaypointerConfig config;
    @Inject private ClientToolbar clientToolbar;
    @Inject private WaypointerPanel panel;
    @Inject private WaypointStore store;
    @Inject private WaypointStorePersistence persistence;
    @Inject private EventBus eventBus;
    @Inject private WaypointMenuHandler menuHandler;
    @Inject private WaypointPathfinder pathfinderService;
    @Inject private DeathAutoPathfinder deathAutoPathfinder;
    @Inject private TabHost tabHost;
    @Inject private NpcHighlightOverlay npcHighlightOverlay;
    @Inject private OverlayManager overlayManager;
    @Inject private com.waypointer.service.RouteStore routeStore;
    @Inject private com.waypointer.service.RouteStorePersistence routePersistence;
    @Inject private com.waypointer.service.RoutePlaybackEngine routePlaybackEngine;
    @Inject private com.waypointer.ui.RouteOverlay routeOverlay;
    @Inject private com.waypointer.sailing.SailingJourneyOrchestrator sailingOrchestrator;
    @Inject private net.runelite.api.Client client;
    @Inject private net.runelite.client.input.KeyManager keyManager;
    @Inject private com.waypointer.service.Navigator navigator;
    @Inject private com.waypointer.sailing.WaterMap waterMap;
    @Inject private java.util.concurrent.ScheduledExecutorService executor;

    private NavigationButton navButton;
    private net.runelite.client.input.KeyListener routeHotkeyListener;

    @Override
    protected void startUp() throws Exception
    {
        // Load from config first so the panel (subscribed at construction) renders the saved data,
        // then attach the write-through saver so the bootstrap itself does not re-save.
        store.bootstrap(persistence.load());
        store.enablePersistence(() -> persistence.save(store.getLibrary()));
        routeStore.bootstrap(routePersistence.load());
        routeStore.enablePersistence(() -> routePersistence.save(routeStore.getLibrary()));
        routePlaybackEngine.attach(client);
        eventBus.register(routePlaybackEngine);
        overlayManager.add(routeOverlay);

        routeHotkeyListener = new net.runelite.client.input.KeyListener()
        {
            @Override public void keyTyped(java.awt.event.KeyEvent e) {}
            @Override public void keyReleased(java.awt.event.KeyEvent e) {}
            @Override public void keyPressed(java.awt.event.KeyEvent e)
            {
                if (!routePlaybackEngine.isActive()) return;
                if (config.routeAdvanceHotkey().matches(e))
                {
                    routePlaybackEngine.advance();
                    e.consume();
                }
            }
        };
        keyManager.registerKeyListener(routeHotkeyListener);

        BufferedImage icon = Icon.getSize32();
        navButton = NavigationButton.builder()
            .tooltip("Waypointer")
            .icon(icon)
            .priority(7)
            .panel(tabHost)
            .build();
        tabHost.setNavButton(navButton);
        clientToolbar.addNavigation(navButton);
        eventBus.register(menuHandler);
        eventBus.register(pathfinderService);
        eventBus.register(sailingOrchestrator);
        eventBus.register(deathAutoPathfinder);
        eventBus.register(panel);
        eventBus.register(tabHost);

        // Pick up RuneLiteLAF's scrollbar colors now that the LAF is installed (the panel
        // was constructed earlier, against Metal's UIDefaults).
        tabHost.refreshScrollbarStyling();

        overlayManager.add(npcHighlightOverlay);

        warmSeaMapIfSailing();

        log.info("Waypointer started: {} waypoints loaded",
            store.getLibrary().getWaypoints().size());
    }

    @Override
    protected void shutDown() throws Exception
    {
        if (routeHotkeyListener != null)
        {
            keyManager.unregisterKeyListener(routeHotkeyListener);
            routeHotkeyListener = null;
        }
        eventBus.unregister(routePlaybackEngine);
        routePlaybackEngine.detach();
        overlayManager.remove(routeOverlay);
        routeStore.disablePersistence();
        store.disablePersistence();

        eventBus.unregister(menuHandler);
        eventBus.unregister(pathfinderService);
        eventBus.unregister(sailingOrchestrator);
        // The orchestrator is a singleton, so a journey would otherwise outlive the plugin.
        if (sailingOrchestrator.activeDestination() != com.waypointer.model.WorldPointPacker.UNDEFINED)
        {
            sailingOrchestrator.cancel();
        }
        sailingOrchestrator.resetSession();
        eventBus.unregister(deathAutoPathfinder);
        eventBus.unregister(panel);
        eventBus.unregister(tabHost);

        clientToolbar.removeNavigation(navButton);
        tabHost.dispose();
        overlayManager.remove(npcHighlightOverlay);
        log.info("Waypointer stopped");
    }

    // Only users who can sail pay for building the sea map, and they pay it off the game
    // threads. Chart Plotter may start after this plugin, or sailing may be turned on later,
    // so those events warm it too; warm() does the work only once.
    private void warmSeaMapIfSailing()
    {
        if (!navigator.shortestPathOnly()) executor.execute(waterMap::warm);
    }

    @Subscribe
    public void onPluginChanged(net.runelite.client.events.PluginChanged e)
    {
        if (com.waypointer.sailing.ChartPlotterBridge.isChartPlotter(e.getPlugin())) warmSeaMapIfSailing();
    }

    @Subscribe
    public void onConfigChanged(net.runelite.client.events.ConfigChanged e)
    {
        if ("waypointer".equals(e.getGroup()) && "sailingEnabled".equals(e.getKey())) warmSeaMapIfSailing();
    }

    @Subscribe
    public void onRuneScapeProfileChanged(net.runelite.client.events.RuneScapeProfileChanged e)
    {
        // ConfigManager has already switched the active RS profile by the time this fires, so a
        // fresh load() reads the newly-logged-in account's library. The write-through saver stays
        // attached and targets the now-current profile. Marshal the swap to the EDT.
        javax.swing.SwingUtilities.invokeLater(() -> store.bootstrap(persistence.load()));
    }

    @Provides
    WaypointerConfig provideConfig(ConfigManager cm)
    {
        return cm.getConfig(WaypointerConfig.class);
    }
}

package com.waypointer.codec;

import com.waypointer.model.WorldPointPacker;
import java.math.BigInteger;

/**
 * Reads and writes typed tile coordinates such as {@code 2301, 3690} or {@code 2301, 3690, 1}.
 * Numbers may be separated by commas, whitespace, or both. The plane defaults to 0.
 */
public final class CoordinateText
{
    private static final int MAX_XY = 16383;
    private static final int MAX_PLANE = 3;
    private static final BigInteger BIG_MAX_XY = BigInteger.valueOf(MAX_XY);
    private static final BigInteger BIG_MAX_PLANE = BigInteger.valueOf(MAX_PLANE);

    private static final String FORMAT_MESSAGE = "Enter coordinates as x, y or x, y, plane.";
    private static final String RANGE_MESSAGE = "x and y must be between 0 and 16383.";
    private static final String PLANE_MESSAGE = "Plane must be between 0 and 3.";

    private CoordinateText() {}

    /**
     * Parses typed coordinates into a packed tile.
     *
     * @throws IllegalArgumentException with a message fit to show the user
     */
    public static int parse(String text)
    {
        String trimmed = text == null ? "" : text.trim();
        String[] parts = trimmed.split("[\\s,]+", -1);
        if (parts.length < 2 || parts.length > 3)
        {
            throw new IllegalArgumentException(FORMAT_MESSAGE);
        }
        BigInteger[] n = new BigInteger[parts.length];
        for (int i = 0; i < parts.length; i++)
        {
            if (!parts[i].matches("-?\\d+"))
            {
                throw new IllegalArgumentException(FORMAT_MESSAGE);
            }
            n[i] = new BigInteger(parts[i]);
        }
        return parse(n[0], n[1], n.length == 3 ? n[2] : BigInteger.ZERO);
    }

    /**
     * Range-checks already split numbers and packs them.
     *
     * @throws IllegalArgumentException with a message fit to show the user
     */
    public static int parse(BigInteger x, BigInteger y, BigInteger plane)
    {
        if (!inRange(x, BIG_MAX_XY) || !inRange(y, BIG_MAX_XY))
        {
            throw new IllegalArgumentException(RANGE_MESSAGE);
        }
        if (!inRange(plane, BIG_MAX_PLANE))
        {
            throw new IllegalArgumentException(PLANE_MESSAGE);
        }
        return WorldPointPacker.pack(x.intValue(), y.intValue(), plane.intValue());
    }

    /** Formats a packed tile as {@code x, y}, with {@code , plane} appended above plane 0. */
    public static String format(int packed)
    {
        String xy = WorldPointPacker.getX(packed) + ", " + WorldPointPacker.getY(packed);
        int plane = WorldPointPacker.getPlane(packed);
        return plane == 0 ? xy : xy + ", " + plane;
    }

    private static boolean inRange(BigInteger v, BigInteger max)
    {
        return v.signum() >= 0 && v.compareTo(max) <= 0;
    }
}

package com.waypointer.codec;

import com.waypointer.model.Library;

/**
 * Result of decoding a library: the cleaned {@link Library} plus how many entries the sanitizer
 * dropped (missing required fields). Lets the import UI tell the user a pasted code contained
 * entries that could not be read.
 */
public final class DecodeReport
{
    public final Library library;
    public final int droppedWaypoints;
    public final int droppedCategories;

    public DecodeReport(Library library, int droppedWaypoints, int droppedCategories)
    {
        this.library = library;
        this.droppedWaypoints = droppedWaypoints;
        this.droppedCategories = droppedCategories;
    }

    public int totalDropped() { return droppedWaypoints + droppedCategories; }
}

package com.waypointer.codec;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import com.google.gson.JsonParser;
import java.util.function.Function;
import java.util.function.IntFunction;

/**
 * Shared JSON-decode skeleton for the versioned library codecs. Holds the one tolerated
 * {@code new JsonParser()} deprecation so the per-entity codecs stay clean. Each codec keeps
 * its own exception types and supplies them as factories, preserving its public catch contract.
 */
final class JsonDecodeSupport
{
    private JsonDecodeSupport() {}

    /** Migration seam matching {@code LibraryMigrator}/{@code RouteMigrator}'s static signature. */
    @FunctionalInterface
    interface Migrator
    {
        JsonObject migrate(JsonObject obj, int fromVersion);
    }

    /**
     * Parse JSON to an object, wrapping any parse failure via {@code onMalformed}. The single
     * tolerated deprecated {@code JsonParser} call lives here (RuneLite's Gson 2.8.5 predates
     * {@code JsonParser.parseString}).
     */
    static JsonObject parseObject(String json, Function<Throwable, RuntimeException> onMalformed)
    {
        try
        {
            @SuppressWarnings("deprecation")
            JsonObject parsed = new JsonParser().parse(json).getAsJsonObject();
            return parsed;
        }
        catch (JsonParseException | IllegalStateException e)
        {
            throw onMalformed.apply(e);
        }
    }

    /** Parse JSON to an array with the injected Gson, wrapping any failure via {@code onMalformed}. */
    static JsonArray parseArray(Gson gson, String json,
        Function<Throwable, RuntimeException> onMalformed)
    {
        try
        {
            JsonArray parsed = gson.fromJson(json, JsonArray.class);
            if (parsed == null) throw new JsonParseException("empty");
            return parsed;
        }
        catch (JsonParseException e)
        {
            throw onMalformed.apply(e);
        }
    }

    /**
     * The shared parse -> version-guard -> migrate -> bind skeleton. Per-entity field defaults
     * stay in the caller (they differ per codec) and run on the returned object.
     */
    static <T> T decode(
        Gson gson,
        String json,
        int currentSchemaVersion,
        Migrator migrator,
        Class<T> type,
        Function<Throwable, RuntimeException> onMalformed,
        IntFunction<RuntimeException> onUnsupported)
    {
        JsonObject obj = parseObject(json, onMalformed);

        // Treat a missing schemaVersion as 0 (pre-versioned) so the migrator runs. A present-but-
        // non-numeric schemaVersion is a corrupt blob: route it through onMalformed rather than let
        // getAsInt() throw an uncaught UnsupportedOperationException / NumberFormatException.
        int version = 0;
        if (obj.has("schemaVersion"))
        {
            JsonElement sv = obj.get("schemaVersion");
            if (!sv.isJsonPrimitive() || !sv.getAsJsonPrimitive().isNumber())
            {
                throw onMalformed.apply(
                    new JsonParseException("schemaVersion is not a number: " + sv));
            }
            version = sv.getAsInt();
        }
        if (version > currentSchemaVersion)
        {
            throw onUnsupported.apply(version);
        }
        return gson.fromJson(migrator.migrate(obj, version), type);
    }
}

package com.waypointer.codec;

import com.google.gson.Gson;
import com.waypointer.model.Library;
import javax.inject.Inject;

/** Encodes/decodes a Library to/from JSON. Handles schema version checks and missing fields. */
public class LibraryJsonCodec
{
    private final Gson gson;

    @Inject
    public LibraryJsonCodec(Gson injectedGson)
    {
        this.gson = injectedGson;
    }

    public String encode(Library lib)
    {
        return gson.toJson(lib);
    }

    public Library decode(String json)
    {
        return decodeWithReport(json).library;
    }

    public DecodeReport decodeWithReport(String json)
    {
        Library lib = JsonDecodeSupport.decode(
            gson, json, Library.CURRENT_SCHEMA_VERSION, LibraryMigrator::migrate, Library.class,
            e -> new MalformedLibraryException("Failed to parse library JSON", e),
            v -> new UnsupportedSchemaException(
                "Library schemaVersion " + v + " is newer than supported "
                    + Library.CURRENT_SCHEMA_VERSION));
        // Defensive: Gson may leave nulls if fields were absent.
        if (lib.getCategories() == null) lib.setCategories(new java.util.ArrayList<>());
        if (lib.getWaypoints() == null) lib.setWaypoints(new java.util.ArrayList<>());
        if (lib.getSchemaVersion() == 0) lib.setSchemaVersion(Library.CURRENT_SCHEMA_VERSION);
        // Drop entries missing required fields; count drops so the import UI can report them.
        int beforeCategories = lib.getCategories().size();
        int beforeWaypoints = lib.getWaypoints().size();
        lib.setCategories(ModelSanitizer.sanitizeCategories(lib.getCategories()));
        lib.setWaypoints(ModelSanitizer.sanitizeWaypoints(lib.getWaypoints()));
        int droppedCategories = beforeCategories - lib.getCategories().size();
        int droppedWaypoints = beforeWaypoints - lib.getWaypoints().size();
        return new DecodeReport(lib, droppedWaypoints, droppedCategories);
    }

    public static class MalformedLibraryException extends RuntimeException
    {
        public MalformedLibraryException(String msg, Throwable cause) { super(msg, cause); }
    }

    public static class UnsupportedSchemaException extends RuntimeException
    {
        public UnsupportedSchemaException(String msg) { super(msg); }
    }
}

package com.waypointer.codec;

import com.google.gson.JsonObject;
import com.waypointer.model.Library;

/**
 * Schema-version migration hook. Today every supported version maps straight through, so this
 * is an identity passthrough -- the {@code fromVersion} argument is unused on purpose. It exists
 * as the stable seam to slot real migration steps into when the on-disk schema next changes;
 * it is not dead code and is not live migration logic.
 */
public final class LibraryMigrator
{
    private LibraryMigrator() {}

    public static JsonObject migrate(JsonObject obj, int fromVersion)
    {
        return obj;
    }
}

package com.waypointer.codec;

import com.waypointer.model.Category;
import com.waypointer.model.Waypoint;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.model.route.Route;
import com.waypointer.model.route.RouteStep;
import com.waypointer.model.route.StepType;
import java.util.ArrayList;
import java.util.List;

/**
 * Drops decoded entries missing required fields so partial or hostile JSON -- pasted share
 * codes or a corrupted config blob -- cannot push null-field model objects into the panel or
 * the route overlay. Filtering: invalid entries are removed; surviving entries are returned as-is,
 * except a surviving route has its own step list replaced with the sanitized one (see
 * {@link #sanitizeRoutes}). Never throws; callers decide whether a drop becomes a whole-code
 * rejection.
 */
final class ModelSanitizer
{
    private ModelSanitizer() {}

    static List<Waypoint> sanitizeWaypoints(List<Waypoint> in)
    {
        List<Waypoint> out = new ArrayList<>();
        if (in == null) return out;
        for (Waypoint w : in)
        {
            if (isValidWaypoint(w)) out.add(w);
        }
        return out;
    }

    static List<Category> sanitizeCategories(List<Category> in)
    {
        List<Category> out = new ArrayList<>();
        if (in == null) return out;
        for (Category c : in)
        {
            if (isValidCategory(c)) out.add(c);
        }
        return out;
    }

    static boolean isValidWaypoint(Waypoint w)
    {
        return w != null
            && w.getId() != null
            && w.getName() != null
            && isCoordinateUsable(w.getPackedWorldPoint());
    }

    static boolean isValidCategory(Category c)
    {
        if (c == null) return false;
        if (c.isUncategorized()) return true; // the sentinel is never dropped, whatever its fields
        return c.getId() != null && c.getName() != null;
    }

    static List<RouteStep> sanitizeSteps(List<RouteStep> in)
    {
        List<RouteStep> out = new ArrayList<>();
        if (in == null) return out;
        for (RouteStep s : in)
        {
            if (isValidStep(s)) out.add(s);
        }
        return out;
    }

    /** Drops invalid routes and replaces each survivor's step list with its sanitized form. */
    static List<Route> sanitizeRoutes(List<Route> in)
    {
        List<Route> out = new ArrayList<>();
        if (in == null) return out;
        for (Route r : in)
        {
            if (!isValidRoute(r)) continue;
            r.setSteps(sanitizeSteps(r.getSteps()));
            out.add(r);
        }
        return out;
    }

    static boolean isValidStep(RouteStep s)
    {
        if (s == null || s.getId() == null || s.getType() == null) return false;
        if (s.boxTextOrLabel() == null) return false;
        if (s.getType() == StepType.WAYPOINT && !isCoordinateUsable(s.getPackedWorldPoint())) return false;
        return true;
    }

    static boolean isValidRoute(Route r)
    {
        return r != null && r.getId() != null && r.getName() != null;
    }

    /** Shared coordinate check: not the UNDEFINED sentinel and not the (0,0) null-island. */
    static boolean isCoordinateUsable(int packed)
    {
        if (packed == WorldPointPacker.UNDEFINED) return false;
        return !(WorldPointPacker.getX(packed) == 0 && WorldPointPacker.getY(packed) == 0);
    }
}

package com.waypointer.codec;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import com.waypointer.model.Category;
import com.waypointer.model.Library;
import com.waypointer.model.Waypoint;
import com.waypointer.model.WorldPointPacker;
import java.math.BigInteger;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.UUID;
import java.util.regex.Pattern;
import javax.inject.Inject;

/**
 * Turns pasted text into a {@link Library} the import picker can show. The text is either a JSON
 * array of {@code {name, x, y, plane?, category?}} objects or plain lines of
 * {@code name, x, y[, plane]}. A line starting with {@code #} sets the category for the lines
 * after it. Entries without a category go to {@code Imported}.
 */
public class ReadableImport
{
    static final String DEFAULT_CATEGORY = "Imported";
    private static final int MAX_CHARS = 1_048_576;
    private static final int MAX_LINE = 300;
    private static final int MAX_DIGITS = 12;
    private static final Pattern PLAIN_INTEGER = Pattern.compile("-?[0-9]{1,12}");

    private static final String NOTHING = "Nothing to import.";
    private static final String TOO_LARGE = "That list is too large.";
    private static final String NOT_VALID = "That is not a valid list.";

    private final Gson gson;

    @Inject
    public ReadableImport(Gson gson)
    {
        this.gson = gson;
    }

    /** True when the trimmed text starts with a share code prefix. */
    public static boolean isShareCode(String text)
    {
        if (text == null) return false;
        String t = text.trim();
        return t.startsWith("WP1:") || t.startsWith("WPL1:");
    }

    /**
     * Parses pasted text. Entries already in the matching category of {@code existing} (same name,
     * ignoring case, and same tile) are left out and counted in {@link Result#alreadyPresent}.
     *
     * @throws MalformedListException with a message fit to show the user
     */
    public Result parse(String text, Library existing)
    {
        if (text != null && text.length() > MAX_CHARS)
        {
            throw new MalformedListException(TOO_LARGE);
        }
        String trimmed = text == null ? "" : text.trim();
        List<Entry> entries = trimmed.startsWith("[") ? readJson(trimmed) : readLines(text == null ? "" : text);
        if (entries.isEmpty())
        {
            throw new MalformedListException(NOTHING);
        }
        return build(entries, existing);
    }

    // ---- lines ----

    private static List<Entry> readLines(String text)
    {
        List<Entry> out = new ArrayList<>();
        String category = DEFAULT_CATEGORY;
        String[] lines = text.split("\r?\n", -1);
        for (int i = 0; i < lines.length; i++)
        {
            String line = lines[i].trim();
            if (line.isEmpty()) continue;
            if (line.length() > MAX_LINE)
            {
                throw new MalformedListException("Line " + (i + 1) + ": too long.");
            }
            if (line.charAt(0) == '#')
            {
                String name = line.substring(1).trim();
                category = name.isEmpty() ? DEFAULT_CATEGORY : name;
                continue;
            }
            out.add(readLine(line, i + 1, category));
        }
        return out;
    }

    /**
     * Splits a line into name and trailing numbers. Up to three trailing integers are peeled off;
     * all three are the coordinates only when the last is a plane (0 to 3), otherwise the last two
     * are and the third belongs to the name ("Duck 4 2410 3725").
     */
    private static Entry readLine(String line, int lineNumber, String category)
    {
        int[] numStart = new int[3];
        int[] sepStart = new int[3];
        int count = 0;
        int end = line.length();
        while (count < 3)
        {
            int e = end;
            while (e > 0 && Character.isWhitespace(line.charAt(e - 1))) e--;
            int s = e;
            while (s > 0 && Character.isDigit(line.charAt(s - 1))) s--;
            if (s == e) break;
            if (s > 0 && line.charAt(s - 1) == '-') s--;
            int sep = s;
            while (sep > 0 && isSeparator(line.charAt(sep - 1))) sep--;
            if (sep == s) break;
            numStart[count] = s;
            sepStart[count] = sep;
            count++;
            end = sep;
        }
        if (count < 2)
        {
            throw new MalformedListException("Line " + lineNumber
                + ": expected a name followed by x, y.");
        }
        // Index 0 is the rightmost number. Pick how many belong to the coordinates.
        int k = 2;
        if (count == 3)
        {
            String plane = line.substring(numStart[0]).trim();
            if (plane.matches("[0-3]")) k = 3;
        }
        int first = k - 1;
        int nameEnd = sepStart[first];
        while (nameEnd > 0 && isSeparator(line.charAt(nameEnd - 1))) nameEnd--;
        String name = line.substring(0, nameEnd);
        if (name.isEmpty())
        {
            throw new MalformedListException("Line " + lineNumber
                + ": expected a name followed by x, y.");
        }
        int packed;
        try
        {
            packed = CoordinateText.parse(line.substring(numStart[first]));
        }
        catch (IllegalArgumentException ex)
        {
            throw new MalformedListException("Line " + lineNumber + ": " + ex.getMessage());
        }
        if (bothZero(packed))
        {
            throw new MalformedListException("Line " + lineNumber + ": x and y cannot both be 0.");
        }
        return new Entry(name, packed, category);
    }

    private static boolean bothZero(int packed)
    {
        return WorldPointPacker.getX(packed) == 0 && WorldPointPacker.getY(packed) == 0;
    }

    private static boolean isSeparator(char c)
    {
        return c == ',' || Character.isWhitespace(c);
    }

    // ---- json ----

    private List<Entry> readJson(String text)
    {
        JsonArray array = JsonDecodeSupport.parseArray(gson, text,
            t -> new MalformedListException(NOT_VALID));
        List<Entry> out = new ArrayList<>();
        for (int i = 0; i < array.size(); i++)
        {
            out.add(readEntry(array.get(i), i + 1));
        }
        return out;
    }

    private static Entry readEntry(JsonElement el, int index)
    {
        String missing = "Entry " + index + ": needs a name, x and y.";
        if (!el.isJsonObject()) throw new MalformedListException(missing);
        JsonObject o = el.getAsJsonObject();
        String name = stringOrNull(o.get("name"));
        BigInteger x = integerOrNull(o.get("x"));
        BigInteger y = integerOrNull(o.get("y"));
        if (name == null || name.trim().isEmpty() || x == null || y == null)
        {
            throw new MalformedListException(missing);
        }
        BigInteger plane = BigInteger.ZERO;
        if (o.has("plane") && !o.get("plane").isJsonNull())
        {
            plane = integerOrNull(o.get("plane"));
            if (plane == null) throw new MalformedListException(missing);
        }
        String category = DEFAULT_CATEGORY;
        if (o.has("category") && !o.get("category").isJsonNull())
        {
            String c = stringOrNull(o.get("category"));
            if (c == null) throw new MalformedListException(missing);
            if (!c.trim().isEmpty()) category = c.trim();
        }
        try
        {
            int packed = CoordinateText.parse(x, y, plane);
            if (bothZero(packed))
            {
                throw new MalformedListException("Entry " + index + ": x and y cannot both be 0.");
            }
            return new Entry(name.trim(), packed, category);
        }
        catch (IllegalArgumentException ex)
        {
            throw new MalformedListException("Entry " + index + ": " + ex.getMessage());
        }
    }

    private static String stringOrNull(JsonElement e)
    {
        if (e == null || !e.isJsonPrimitive()) return null;
        JsonPrimitive p = e.getAsJsonPrimitive();
        return p.isString() ? p.getAsString() : null;
    }

    private static BigInteger integerOrNull(JsonElement e)
    {
        if (e == null || !e.isJsonPrimitive() || !e.getAsJsonPrimitive().isNumber()) return null;
        String raw = e.getAsString();
        if (raw.length() > MAX_DIGITS + 1 || !PLAIN_INTEGER.matcher(raw).matches()) return null;
        return new BigInteger(raw);
    }

    // ---- assembly ----

    private static Result build(List<Entry> entries, Library existing)
    {
        Library lib = new Library();
        Map<String, Category> byKey = new LinkedHashMap<>();
        Map<UUID, Integer> nextOrder = new LinkedHashMap<>();
        int nextCategoryOrder = 0;
        for (Category c : existing.getCategories())
        {
            nextCategoryOrder = Math.max(nextCategoryOrder, c.getSortOrder() + 1);
        }
        int alreadyPresent = 0;
        for (Entry e : entries)
        {
            String key = e.category.toLowerCase(Locale.ROOT);
            Category match = findExisting(existing, e.category);
            Category target = byKey.get(key);
            if (match != null && isDuplicate(existing, match, e))
            {
                alreadyPresent++;
                continue;
            }
            if (target == null)
            {
                target = match != null ? copyOf(match)
                    : new Category(UUID.randomUUID(), e.category, nextCategoryOrder++, false, null, false);
                byKey.put(key, target);
                lib.getCategories().add(target);
            }
            int order = nextOrder.merge(target.getId(), 1, Integer::sum) - 1;
            lib.getWaypoints().add(new Waypoint(UUID.randomUUID(), e.name, e.packed, target.getId(),
                null, "", Instant.now(), order, false, null, false));
        }
        lib.setWaypoints(ModelSanitizer.sanitizeWaypoints(lib.getWaypoints()));
        if (lib.getWaypoints().isEmpty() && alreadyPresent == 0)
        {
            throw new MalformedListException(NOTHING);
        }
        return new Result(lib, alreadyPresent);
    }

    private static Category findExisting(Library existing, String name)
    {
        for (Category c : existing.getCategories())
        {
            if (c.getName() != null && c.getName().equalsIgnoreCase(name)) return c;
        }
        return null;
    }

    private static boolean isDuplicate(Library existing, Category cat, Entry e)
    {
        for (Waypoint w : existing.getWaypoints())
        {
            if (cat.getId().equals(w.getCategoryId())
                && w.getPackedWorldPoint() == e.packed
                && w.getName() != null && w.getName().equalsIgnoreCase(e.name))
            {
                return true;
            }
        }
        return false;
    }

    private static Category copyOf(Category c)
    {
        Category copy = new Category(c.getId(), c.getName(), c.getSortOrder(), c.isUncategorized(),
            c.getIconId(), c.isBundled());
        copy.setSortMode(c.getSortMode());
        copy.setColor(c.getColor());
        return copy;
    }

    private static final class Entry
    {
        final String name;
        final int packed;
        final String category;

        Entry(String name, int packed, String category)
        {
            this.name = name;
            this.packed = packed;
            this.category = category;
        }
    }

    /** The library to offer in the picker, and how many entries were skipped as already saved. */
    public static final class Result
    {
        public final Library library;
        public final int alreadyPresent;

        Result(Library library, int alreadyPresent)
        {
            this.library = library;
            this.alreadyPresent = alreadyPresent;
        }
    }

    /** Thrown for text that cannot be read as a list; the message is shown to the user. */
    public static final class MalformedListException extends RuntimeException
    {
        public MalformedListException(String message)
        {
            super(message);
        }
    }
}

package com.waypointer.codec;

import com.google.gson.Gson;
import com.waypointer.model.route.RouteLibrary;
import javax.inject.Inject;

/** Encodes/decodes a {@link RouteLibrary} to/from JSON with a schema-version check. */
public class RouteJsonCodec
{
    private final Gson gson;

    @Inject
    public RouteJsonCodec(Gson injectedGson)
    {
        this.gson = injectedGson;
    }

    public String encode(RouteLibrary lib)
    {
        return gson.toJson(lib);
    }

    public RouteLibrary decode(String json)
    {
        RouteLibrary lib = JsonDecodeSupport.decode(
            gson, json, RouteLibrary.CURRENT_SCHEMA_VERSION, RouteMigrator::migrate, RouteLibrary.class,
            e -> new MalformedRouteException("Failed to parse routes JSON", e),
            v -> new UnsupportedSchemaException(
                "Routes schemaVersion " + v + " is newer than supported "
                    + RouteLibrary.CURRENT_SCHEMA_VERSION));
        // Defensive: Gson may leave nulls if fields were absent.
        if (lib.getRoutes() == null) lib.setRoutes(new java.util.ArrayList<>());
        if (lib.getSchemaVersion() == 0) lib.setSchemaVersion(RouteLibrary.CURRENT_SCHEMA_VERSION);
        // Drop routes missing required fields and strip invalid steps from survivors.
        lib.setRoutes(ModelSanitizer.sanitizeRoutes(lib.getRoutes()));
        return lib;
    }

    public static class MalformedRouteException extends RuntimeException
    {
        public MalformedRouteException(String msg, Throwable cause) { super(msg, cause); }
    }

    public static class UnsupportedSchemaException extends RuntimeException
    {
        public UnsupportedSchemaException(String msg) { super(msg); }
    }
}

package com.waypointer.codec;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;

/**
 * Schema-version migration for {@link com.waypointer.model.route.RouteLibrary}.
 *
 * <p>v1 -> v2: route steps gained a {@code boxText} field (the in-game route-box text, distinct
 * from the sidebar {@code label}). Older files have only {@code label}; backfill {@code boxText}
 * from it so existing routes read identically in the box.
 */
public final class RouteMigrator
{
    private RouteMigrator() {}

    public static JsonObject migrate(JsonObject obj, int fromVersion)
    {
        if (fromVersion < 2)
        {
            backfillBoxText(obj);
            obj.addProperty("schemaVersion", 2);
        }
        return obj;
    }

    private static void backfillBoxText(JsonObject obj)
    {
        if (!obj.has("routes") || !obj.get("routes").isJsonArray()) return;
        for (JsonElement routeEl : obj.getAsJsonArray("routes"))
        {
            if (!routeEl.isJsonObject()) continue;
            JsonObject route = routeEl.getAsJsonObject();
            if (!route.has("steps") || !route.get("steps").isJsonArray()) continue;
            for (JsonElement stepEl : route.getAsJsonArray("steps"))
            {
                if (!stepEl.isJsonObject()) continue;
                JsonObject step = stepEl.getAsJsonObject();
                if (!step.has("boxText") && step.has("label"))
                {
                    step.add("boxText", step.get("label"));
                }
            }
        }
    }
}

package com.waypointer.codec;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.waypointer.model.route.Route;
import javax.inject.Inject;

/**
 * Encodes/decodes a single route share code:
 *   RT1:&lt;base64(gzip(json))&gt;
 *
 * Soft cap: gunzipped payload must be &lt; 1 MiB. Mirrors {@link WaypointShareCodec}.
 */
public class RouteShareCodec
{
    public static final String ROUTE_MAGIC = "RT1:";

    private final Gson gson;

    @Inject
    public RouteShareCodec(Gson gson) { this.gson = gson; }

    public String encodeRoute(Route route)
    {
        return ROUTE_MAGIC + ShareCodecSupport.gzipBase64(gson.toJson(route));
    }

    public Route decodeRoute(String input)
    {
        String body = ShareCodecSupport.stripMagic(input, ROUTE_MAGIC, MalformedCodeException::new);
        String json = ShareCodecSupport.ungzipBase64(body, MalformedCodeException::new);
        final Route route;
        try
        {
            route = gson.fromJson(json, Route.class);
        }
        catch (JsonParseException e)
        {
            throw new MalformedCodeException("Bad JSON inside route code");
        }
        if (route == null || route.getId() == null || route.getName() == null)
        {
            throw new MalformedCodeException("Route decoded as null, idless, or nameless");
        }
        // Single-entity code: keep the route but strip any steps missing required fields, so a
        // null-text step can never reach boxTextOrLabel() and the overlay.
        route.setSteps(ModelSanitizer.sanitizeSteps(route.getSteps()));
        return route;
    }

    public static class MalformedCodeException extends RuntimeException
    {
        public MalformedCodeException(String msg) { super(msg); }
    }
}

package com.waypointer.codec;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.function.Function;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;

/**
 * Shared gzip+base64 transport for the share codecs. Each codec keeps its own
 * {@code MalformedCodeException} (it is part of that codec's public surface), so the decode
 * helpers take a factory that wraps a message in the caller's exception type. Guards against
 * gzip bombs with a fixed 1 MiB inflated-size cap.
 */
final class ShareCodecSupport
{
    static final int MAX_INFLATED_BYTES = 1024 * 1024;

    private ShareCodecSupport() {}

    static String stripMagic(String input, String magic, Function<String, RuntimeException> err)
    {
        String trimmed = input.trim();
        if (!trimmed.startsWith(magic))
        {
            throw err.apply("Expected magic " + magic + " at start of code");
        }
        return trimmed.substring(magic.length());
    }

    static String gzipBase64(String input)
    {
        try
        {
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            try (GZIPOutputStream gz = new GZIPOutputStream(baos))
            {
                gz.write(input.getBytes(StandardCharsets.UTF_8));
            }
            return Base64.getEncoder().withoutPadding().encodeToString(baos.toByteArray());
        }
        catch (IOException e)
        {
            throw new RuntimeException("gzip+base64 encode failed", e);
        }
    }

    static String ungzipBase64(String input, Function<String, RuntimeException> err)
    {
        byte[] decoded;
        try { decoded = Base64.getDecoder().decode(input); }
        catch (IllegalArgumentException e) { throw err.apply("Bad base64"); }
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        try (GZIPInputStream gz = new GZIPInputStream(new ByteArrayInputStream(decoded)))
        {
            byte[] buf = new byte[4096];
            int n;
            while ((n = gz.read(buf)) > 0)
            {
                out.write(buf, 0, n);
                if (out.size() > MAX_INFLATED_BYTES)
                {
                    throw err.apply("Share payload exceeds 1 MiB cap");
                }
            }
        }
        catch (IOException e) { throw err.apply("gzip decode failed: " + e.getMessage()); }
        return new String(out.toByteArray(), StandardCharsets.UTF_8);
    }
}

package com.waypointer.codec;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.waypointer.model.Category;
import com.waypointer.model.Library;
import com.waypointer.model.Waypoint;
import javax.inject.Inject;

/**
 * Encodes/decodes share codes:
 *   WP1:<base64(gzip(payload))>      - single waypoint + its category
 *   WPL1:<base64(gzip(payload))>     - full library
 *
 * Soft cap: gunzipped payload must be < 1 MiB. Defends against gzip bombs.
 */
public class WaypointShareCodec
{
    public static final String SINGLE_MAGIC = "WP1:";
    public static final String LIBRARY_MAGIC = "WPL1:";

    private final Gson gson;
    private final LibraryJsonCodec libraryJsonCodec;

    @Inject
    public WaypointShareCodec(Gson gson, LibraryJsonCodec libraryJsonCodec)
    {
        this.gson = gson;
        this.libraryJsonCodec = libraryJsonCodec;
    }

    public SingleResult decodeSingle(String input)
    {
        String body = ShareCodecSupport.stripMagic(input, SINGLE_MAGIC, MalformedCodeException::new);
        String json = ShareCodecSupport.ungzipBase64(body, MalformedCodeException::new);
        JsonObject obj = parseObject(json);
        Waypoint w = gson.fromJson(obj.get("waypoint"), Waypoint.class);
        Category c = gson.fromJson(obj.get("category"), Category.class);
        // Single-entity code: reject the whole code if its one waypoint or category is missing
        // required fields, rather than importing a null-field entity.
        if (!ModelSanitizer.isValidWaypoint(w) || !ModelSanitizer.isValidCategory(c))
        {
            throw new MalformedCodeException("Missing or invalid waypoint or category");
        }
        return new SingleResult(w, c);
    }

    public String encodeLibrary(Library lib)
    {
        JsonObject obj = gson.toJsonTree(lib).getAsJsonObject();
        return LIBRARY_MAGIC + ShareCodecSupport.gzipBase64(obj.toString());
    }

    public Library decodeLibrary(String input)
    {
        return decodeLibraryWithReport(input).library;
    }

    public DecodeReport decodeLibraryWithReport(String input)
    {
        String trimmed = input.trim();
        if (trimmed.startsWith(SINGLE_MAGIC))
        {
            // Caller used the wrong method - wrap a single result as a library. A single decode is
            // reject-whole, so there are no partial drops to report.
            SingleResult sr = decodeSingle(trimmed);
            Library lib = new Library();
            lib.getCategories().add(sr.category);
            lib.getWaypoints().add(sr.waypoint);
            return new DecodeReport(lib, 0, 0);
        }
        String body = ShareCodecSupport.stripMagic(input, LIBRARY_MAGIC, MalformedCodeException::new);
        String json = ShareCodecSupport.ungzipBase64(body, MalformedCodeException::new);
        // Share the file-load decode contract: schema-version guard, migrator, field defaults, sanitize.
        try
        {
            return libraryJsonCodec.decodeWithReport(json);
        }
        catch (LibraryJsonCodec.UnsupportedSchemaException e)
        {
            throw new MalformedCodeException("Share code is from a newer version of the plugin");
        }
        catch (LibraryJsonCodec.MalformedLibraryException e)
        {
            throw new MalformedCodeException("Bad library JSON inside share code");
        }
    }

    // ---- helpers ----

    private static JsonObject parseObject(String json)
    {
        return JsonDecodeSupport.parseObject(json, e -> new MalformedCodeException("Bad JSON inside share code"));
    }

    public static class MalformedCodeException extends RuntimeException
    {
        public MalformedCodeException(String msg) { super(msg); }
    }

    public static final class SingleResult
    {
        public final Waypoint waypoint;
        public final Category category;
        public SingleResult(Waypoint w, Category c) { this.waypoint = w; this.category = c; }
    }
}

package com.waypointer.model;

import java.util.Objects;
import java.util.UUID;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

/** A category groups waypoints in the panel. The single Uncategorized sentinel is flagged. */
@Getter
@Setter
@NoArgsConstructor
public final class Category
{
    private UUID id;
    private String name;
    private int sortOrder;
    private boolean uncategorized;
    /** Optional sprite id for the category icon. {@code null} = no icon. */
    private Integer iconId;
    /** True if this category was shipped as a preset. Sorts after user-created categories. */
    private boolean bundled;
    /**
     * Sort mode for waypoints within this category. {@code null} is equivalent to
     * {@link CategorySortMode#MANUAL} and is how legacy JSON deserializes. Not part of
     * the 6-arg constructor below so that the 23 existing positional call sites compile
     * unchanged; set via {@link #setSortMode(CategorySortMode)}.
     */
    private CategorySortMode sortMode;
    /**
     * Optional accent colour as a packed RGB int. {@code null} = no accent. Like
     * {@link #sortMode}, kept out of the 6-arg constructor so existing positional call
     * sites compile unchanged; set via {@link #setColor(Integer)}.
     */
    private Integer color;

    public Category(UUID id, String name, int sortOrder, boolean uncategorized,
        Integer iconId, boolean bundled)
    {
        this.id = id;
        this.name = name;
        this.sortOrder = sortOrder;
        this.uncategorized = uncategorized;
        this.iconId = iconId;
        this.bundled = bundled;
    }

    @Override
    public boolean equals(Object o)
    {
        if (this == o) return true;
        if (!(o instanceof Category)) return false;
        Category c = (Category) o;
        return Objects.equals(id, c.id);
    }

    @Override
    public int hashCode() { return Objects.hashCode(id); }
}

package com.waypointer.model;

/**
 * Per-category ordering of waypoints in the panel. A {@code null} mode on a {@link Category}
 * is equivalent to {@link #MANUAL} and is how legacy (pre-feature) JSON deserializes.
 */
public enum CategorySortMode
{
    MANUAL,
    NAME,
    DATE_ADDED
}

package com.waypointer.model;

import java.util.ArrayList;
import java.util.List;
import lombok.Getter;
import lombok.Setter;

/** In-memory aggregate of categories and waypoints. */
@Getter
@Setter
public final class Library
{
    public static final int CURRENT_SCHEMA_VERSION = 2;

    private int schemaVersion = CURRENT_SCHEMA_VERSION;
    private List<Category> categories = new ArrayList<>();
    private List<Waypoint> waypoints = new ArrayList<>();
}

package com.waypointer.model;

import java.time.Instant;
import java.util.Objects;
import java.util.UUID;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

/**
 * A saved location. Coordinates use shortest-path's packed-int format so we can pass them
 * through PluginMessage without re-packing on the hot path.
 */
@Getter
@Setter
@NoArgsConstructor
public final class Waypoint
{
    private UUID id;
    private String name;
    private int packedWorldPoint;
    private UUID categoryId;
    private Integer iconId;     // null = no icon
    private String notes;       // never null; "" when empty
    private Instant createdAt;
    private int sortOrder;
    private boolean pinned;
    private Instant pinnedAt;   // null when not pinned
    private boolean bypassWildernessConfirm;

    /**
     * Name of the NPC this waypoint was captured from. {@code null} = not an NPC waypoint.
     * Drives the active-path NPC highlight. Kept out of the canonical constructor below so
     * existing positional call sites compile unchanged; set via {@link #setTargetNpcName}.
     */
    private String targetNpcName;

