/**
 * Bottom action bar shown while the panel is in bulk select mode. Reads "N selected" on the left
 * and offers Move to / Delete / Export on the right. The three action controls are disabled while
 * the selection is empty. Stateless beyond the count + enabled flags; all behaviour is delegated
 * to the callbacks supplied by {@link WaypointerPanel}.
 */
final class BulkActionBar extends JPanel
{
    private final JLabel countLabel = new JLabel("0 selected");
    private final JButton doneBtn = new JButton("Done");
    private final JButton moveBtn = new JButton("Move to ▾"); // down triangle
    private final JButton deleteBtn = new JButton("Delete");
    private final JButton exportBtn = new JButton("Export");

    BulkActionBar(Runnable onDone, Supplier<List<Category>> categorySupplier, Consumer<UUID> onMove,
        Runnable onDelete, Runnable onExport)
    {
        setLayout(new javax.swing.BoxLayout(this, javax.swing.BoxLayout.Y_AXIS));
        setOpaque(false);
        setBorder(BorderFactory.createEmptyBorder(12, 18, 14, 18));

        // Row 1: "N selected" on the left, Done on the right. Both stay enabled regardless of
        // how many rows are selected, so they sit together apart from the action buttons. Done
        // exits select mode -- the counterpart to the right-click "Select multiple" entry.
        countLabel.setForeground(Color.WHITE);
        countLabel.setFont(FontManager.getRunescapeBoldFont());
        Styles.secondaryButton(doneBtn);
        doneBtn.addActionListener(e -> onDone.run());

        JPanel statusRow = new JPanel(new BorderLayout(4, 0));
        statusRow.setOpaque(false);
        statusRow.setAlignmentX(LEFT_ALIGNMENT);
        statusRow.add(countLabel, BorderLayout.WEST);
        statusRow.add(doneBtn, BorderLayout.EAST);
        add(statusRow);

        add(javax.swing.Box.createVerticalStrut(4));

        // Row 2: the three actions, disabled while the selection is empty. They share the row
        // in equal thirds; sized by their text, the last one ran off the sidebar's edge.
        for (JButton b : new JButton[] { moveBtn, deleteBtn, exportBtn })
        {
            Styles.secondaryButton(b);
            b.setBorder(BorderFactory.createEmptyBorder(6, 2, 6, 2));
        }

        moveBtn.addActionListener(e -> {
            JPopupMenu menu = new JPopupMenu();
            for (Category c : categorySupplier.get())
            {
                JMenuItem item = new JMenuItem(c.getName());
                UUID target = c.getId();
                item.addActionListener(ev -> onMove.accept(target));
                menu.add(item);
            }
            menu.show(moveBtn, 0, -menu.getPreferredSize().height);
        });
        deleteBtn.addActionListener(e -> onDelete.run());
        exportBtn.addActionListener(e -> onExport.run());

        JPanel actionRow = new JPanel(new java.awt.GridLayout(1, 3, 4, 0));
        actionRow.setOpaque(false);
        actionRow.setAlignmentX(LEFT_ALIGNMENT);
        actionRow.add(moveBtn);
        actionRow.add(deleteBtn);
        actionRow.add(exportBtn);
        add(actionRow);

        setActionsEnabled(false);
    }

    // A card with an orange outline docked under the list.
    @Override
    protected void paintComponent(java.awt.Graphics g)
    {
        Styles.paintInsetCard(g, this, Styles.SIDE_PAD, Styles.CARD_GAP, Styles.SIDE_PAD, Styles.SIDE_PAD,
            ColorScheme.BRAND_ORANGE);
    }

    void setCount(int n)
    {
        countLabel.setText(n + " selected");
    }

    void setActionsEnabled(boolean enabled)
    {
        moveBtn.setEnabled(enabled);
        deleteBtn.setEnabled(enabled);
        exportBtn.setEnabled(enabled);
    }

    // Cap height to preferred so the SOUTH dock stays a thin fixed-height strip.
    @Override public Dimension getMaximumSize()
    {
        return Styles.capHeight(this);
    }
}

package com.waypointer.ui;

import com.waypointer.codec.WaypointShareCodec;
import com.waypointer.model.Category;
import com.waypointer.model.Waypoint;
import com.waypointer.service.WaypointStore;
import java.awt.Window;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

/**
 * Owns the panel's bulk select mode: the {@link BulkSelection} model, the select-mode flag, the
 * shift-range anchor, and the {@link BulkActionBar}. Splits the selection orchestration out of
 * {@link WaypointerPanel}; every Swing side effect routes back through {@link Host}.
 */
final class BulkSelectController
{
    /** Hooks back into the panel for the side effects the controller cannot perform itself. */
    interface Host
    {
        /** Request a (coalesced) body rebuild so rows re-render with current checkbox state. */
        void rebuild();

        /** Revalidate + repaint the panel after the action bar's visibility or size changes. */
        void revalidateAndRepaint();

        /** Window ancestor used as the export dialog's owner; may be null in tests. */
        Window windowAncestor();
    }

    private final WaypointStore store;
    private final Toasts toasts;
    private final WaypointShareCodec shareCodec;
    private final Host host;
    private final BulkActionBar bar;

    private final BulkSelection selection = new BulkSelection();
    private boolean selectMode = false;
    private UUID lastClickedId;
    // Ordered ids of the waypoints currently rendered in real categories (Pinned excluded),
    // refreshed every render pass so shift-range select honours the active filter and sort.
    private final List<UUID> visibleOrderedIds = new ArrayList<>();

    BulkSelectController(WaypointStore store, Toasts toasts,
        WaypointShareCodec shareCodec, Host host)
    {
        this.store = store;
        this.toasts = toasts;
        this.shareCodec = shareCodec;
        this.host = host;
        this.bar = new BulkActionBar(
            this::exitSelectMode,
            store::getCategoriesOrdered,
            this::bulkMoveTo,
            this::bulkDelete,
            this::bulkExport);
        bar.setVisible(false);
    }

    /** The SOUTH-docked action bar; added to the panel by {@link WaypointerPanel}. */
    BulkActionBar bar() { return bar; }

    boolean isSelectMode() { return selectMode; }

    BulkSelection selection() { return selection; }

    /** Replace the visible-row order used for shift-range selection. Called at the end of each rebuild. */
    void setVisibleOrderedIds(List<UUID> ids)
    {
        visibleOrderedIds.clear();
        visibleOrderedIds.addAll(ids);
    }

    // A row was clicked in select mode: shift extends the range from the last click; a plain
    // click toggles. Keyed by id so it is filter/sort independent.
    void onRowSelectClicked(Waypoint w, boolean shift)
    {
        UUID id = w.getId();
        if (shift && lastClickedId != null)
        {
            selection.selectRange(visibleOrderedIds, lastClickedId, id);
        }
        else
        {
            selection.toggle(id);
        }
        lastClickedId = id;
        afterSelectionChanged();
    }

    void onHeaderSelectToggle(List<UUID> ids, boolean select)
    {
        selection.setCategory(ids, select);
        afterSelectionChanged();
    }

    /** Enter select mode. Triggered by the "Select multiple" right-click entry. */
    void enterSelectMode() { setSelectMode(true); }

    /** Exit select mode. Triggered by the action bar's Done button. */
    void exitSelectMode() { setSelectMode(false); }

    void toggleSelectMode() { setSelectMode(!selectMode); }

    private void setSelectMode(boolean on)
    {
        if (selectMode == on) return;
        selectMode = on;
        if (!selectMode)
        {
            selection.clear();
            lastClickedId = null;
        }
        host.rebuild();
        refreshBulkBar();
    }

    void refreshBulkBar()
    {
        bar.setVisible(selectMode);
        if (selectMode)
        {
            bar.setCount(selection.size());
            bar.setActionsEnabled(!selection.isEmpty());
        }
        host.revalidateAndRepaint();
    }

    private void bulkMoveTo(UUID targetId)
    {
        if (selection.isEmpty()) return;
        Category target = store.getCategoryById(targetId);
        int n = selection.size();
        store.moveWaypointsToCategory(selection.ids(), targetId);
        selection.clear();
        lastClickedId = null;
        afterSelectionChanged();
        toasts.show("Moved " + n + " to " + (target == null ? "category" : target.getName()),
            null, null);
    }

    private void bulkDelete()
    {
        if (selection.isEmpty()) return;
        int n = selection.size();
        store.deleteWaypoints(selection.ids());
        selection.clear();
        lastClickedId = null;
        afterSelectionChanged();
        toasts.show(n + " deleted", "Undo", store::undoLast);
    }

    private void bulkExport()
    {
        if (selection.isEmpty()) return;
        Window owner = host.windowAncestor();
        new ExportPickerDialog(owner, store, shareCodec, toasts,
            selection.ids()).setVisible(true);
        // Selection is non-destructive for export; leave it intact.
    }

    private void afterSelectionChanged()
    {
        host.rebuild();
        refreshBulkBar();
    }

    // Test seams: exercise the non-modal action paths without driving the popup menu / dialog.
    void bulkDeleteForTest() { bulkDelete(); }
    void bulkMoveToForTest(UUID targetId) { bulkMoveTo(targetId); }
}

package com.waypointer.ui;

import java.util.Collection;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.UUID;

/**
 * Pure selection state for the panel's bulk select mode. Keyed by waypoint UUID so the selection
 * survives filter changes and panel rebuilds. No Swing imports; fully unit-testable.
 */
final class BulkSelection
{
    enum TriState { NONE, PARTIAL, ALL }

    private final Set<UUID> ids = new LinkedHashSet<>();

    void toggle(UUID id)
    {
        if (!ids.add(id)) ids.remove(id);
    }

    /**
     * Additively selects the inclusive range of {@code ordered} between {@code fromId} and
     * {@code toId} (anchor order does not matter). No-op if either id is not in {@code ordered}.
     * Assumes {@code ordered} contains distinct ids (the panel's visible row list does).
     */
    void selectRange(List<UUID> ordered, UUID fromId, UUID toId)
    {
        int from = ordered.indexOf(fromId);
        int to = ordered.indexOf(toId);
        if (from < 0 || to < 0) return;
        int lo = Math.min(from, to);
        int hi = Math.max(from, to);
        for (int i = lo; i <= hi; i++) ids.add(ordered.get(i));
    }

    void setCategory(Collection<UUID> categoryWaypointIds, boolean selected)
    {
        if (selected) ids.addAll(categoryWaypointIds);
        else ids.removeAll(categoryWaypointIds);
    }

    /** Tri-state for a category's waypoints. Assumes {@code categoryWaypointIds} are distinct. */
    TriState categoryState(Collection<UUID> categoryWaypointIds)
    {
        if (categoryWaypointIds.isEmpty()) return TriState.NONE;
        int present = 0;
        for (UUID id : categoryWaypointIds) if (ids.contains(id)) present++;
        if (present == 0) return TriState.NONE;
        if (present == categoryWaypointIds.size()) return TriState.ALL;
        return TriState.PARTIAL;
    }

    boolean isEmpty() { return ids.isEmpty(); }

    int size() { return ids.size(); }

    // Insertion-ordered copy: bulk move assigns tail sortOrder in iteration order, so callers
    // get the rows back in the order they were selected, not arbitrary hash order.
    Set<UUID> ids() { return new LinkedHashSet<>(ids); }

    void clear() { ids.clear(); }
}

