        Styles.compactSecondaryButton(newCategoryCancel);
        newCategoryCreate.addActionListener(e -> doCreateInlineCategory());
        newCategoryCancel.addActionListener(e -> cancelInlineCategory());
        GridBagConstraints gn = new GridBagConstraints();
        gn.fill = GridBagConstraints.HORIZONTAL;
        gn.insets = new Insets(2, 2, 2, 2);
        gn.gridx = 0; gn.gridy = 0; gn.weightx = 1;
        newCategoryRow.add(newCategoryName, gn);
        gn.gridx = 1; gn.weightx = 0;
        newCategoryRow.add(newCategoryCreate, gn);
        gn.gridx = 2;
        newCategoryRow.add(newCategoryCancel, gn);
        stack.add(newCategoryRow);

        errorLabel.setAlignmentX(LEFT_ALIGNMENT);
        stack.add(errorLabel);

        add(stack, BorderLayout.CENTER);

        JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
        buttons.setOpaque(false);
        Styles.secondaryButton(cancelBtn);
        cancelBtn.addActionListener(e -> dismiss());
        Styles.primaryButton(saveBtn);
        saveBtn.addActionListener(e -> doSave());
        buttons.add(cancelBtn);
        buttons.add(saveBtn);
        add(buttons, BorderLayout.SOUTH);

        // ESC cancels, ENTER on the name field saves. Both bound on the form's own
        // input map so they don't fire when focus is somewhere else in the panel.
        getInputMap(JComponent.WHEN_ANCESTOR_OF_FOCUSED_COMPONENT)
            .put(KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0), "captureCancel");
        getActionMap().put("captureCancel", new AbstractAction()
        {
            @Override public void actionPerformed(ActionEvent e) { dismiss(); }
        });
        nameField.getInputMap(JComponent.WHEN_FOCUSED)
            .put(KeyStroke.getKeyStroke(KeyEvent.VK_ENTER, 0), "captureSave");
        nameField.getActionMap().put("captureSave", new AbstractAction()
        {
            @Override public void actionPerformed(ActionEvent e) { saveBtn.doClick(); }
        });

        categoryCombo.addActionListener(e -> onCategorySelectionChanged());
        setVisible(false);
    }

    @Override
    public void addNotify()
    {
        super.addNotify();
        JRootPane root = getRootPane();
        if (root != null) root.setDefaultButton(saveBtn);
    }

    // The form is a card with an orange outline, inset from the panel edge.
    @Override
    protected void paintComponent(java.awt.Graphics g)
    {
        Styles.paintInsetCard(g, this, Styles.SIDE_PAD, 0, Styles.SIDE_PAD, Styles.CARD_GAP, ColorScheme.BRAND_ORANGE);
    }

    private java.util.function.Consumer<Boolean> onShownChange;

    /** Tells the panel when the form opens or closes, so the Mark button can step aside. */
    void setOnShownChange(java.util.function.Consumer<Boolean> listener)
    {
        this.onShownChange = listener;
    }

    @Override
    public void setVisible(boolean visible)
    {
        super.setVisible(visible);
        if (onShownChange != null) onShownChange.accept(visible);
    }

    void show(int packed)
    {
        show(packed, null, null);
    }

    void show(int packed, String defaultName, String npcName)
    {
        this.packedPoint = packed;
        this.targetNpcName = npcName;
        newCategoryRow.setVisible(false);
        newCategoryName.setText("");
        errorLabel.setVisible(false);
        errorLabel.setText(" ");
        categoryController.rebuild(store.getUncategorized().getId());
        String prefill = (defaultName != null && !defaultName.isEmpty())
            ? defaultName : capture.defaultName(packed);
        nameField.setText(prefill);
        nameField.selectAll();
        setVisible(true);
        nameField.requestFocusInWindow();
        revalidate();
        repaint();
    }

    void dismiss()
    {
        setVisible(false);
        revalidate();
        repaint();
    }

    String getNameText()
    {
        return nameField.getText();
    }

    private void onCategorySelectionChanged()
    {
        if (!categoryController.isSentinelSelected())
        {
            CategoryComboItem sel = (CategoryComboItem) categoryCombo.getSelectedItem();
            if (sel != null) categoryController.setLastNonSentinel(sel);
            newCategoryRow.setVisible(false);
            errorLabel.setVisible(false);
            revalidate();
            repaint();
            return;
        }
        newCategoryName.setText("");
        newCategoryRow.setVisible(true);
        revalidate();
        repaint();
        newCategoryName.requestFocusInWindow();
    }

    private void doCreateInlineCategory()
    {
        String name = newCategoryName.getText();
        if (name == null || name.trim().isEmpty()) return;
        try
        {
            Category created = store.createCategory(name.trim());
            categoryController.rebuild(created.getId());
            newCategoryRow.setVisible(false);
            errorLabel.setVisible(false);
            errorLabel.setText(" ");
        }
        catch (IllegalArgumentException ex)
        {
            errorLabel.setText(ex.getMessage());
            errorLabel.setVisible(true);
        }
        revalidate();
        repaint();
    }

    private void cancelInlineCategory()
    {
        CategoryComboItem last = categoryController.lastNonSentinel();
        UUID revertTo = last != null ? last.id() : store.getUncategorized().getId();
        categoryController.rebuild(revertTo);
        newCategoryRow.setVisible(false);
        errorLabel.setVisible(false);
        revalidate();
        repaint();
    }

    private void doSave()
    {
        String typed = nameField.getText();
        String trimmed = typed == null ? "" : typed.trim();
        if (trimmed.isEmpty()) trimmed = capture.defaultName(packedPoint);

        UUID categoryId = categoryController.resolveSelectedId();

        store.createWaypoint(packedPoint, trimmed, categoryId, targetNpcName);
        dismiss();
    }

    void setNameText(String text)
    {
        nameField.setText(text);
    }

    void selectCategoryByName(String name)
    {
        for (int i = 0; i < categoryCombo.getItemCount(); i++)
        {
            CategoryComboItem item = categoryCombo.getItemAt(i);
            if (!item.isSentinel() && name.equals(item.toString()))
            {
                categoryCombo.setSelectedIndex(i);
                return;
            }
        }
        throw new IllegalArgumentException("No category named: " + name);
    }

    void clickSave()
    {
        saveBtn.doClick();
    }

    void clickCancel()
    {
        cancelBtn.doClick();
    }

    boolean isNewCategoryRowVisible()
    {
        return newCategoryRow.isVisible();
    }

    void selectNewCategorySentinel()
    {
        for (int i = 0; i < categoryCombo.getItemCount(); i++)
        {
            if (categoryCombo.getItemAt(i).isSentinel())
            {
                categoryCombo.setSelectedIndex(i);
                return;
            }
        }
    }

    void setNewCategoryNameText(String text)
    {
        newCategoryName.setText(text);
    }

    void clickCreateNewCategory()
    {
        newCategoryCreate.doClick();
    }

    void clickCancelNewCategory()
    {
        newCategoryCancel.doClick();
    }

    Object selectedCategoryItem()
    {
        return categoryCombo.getSelectedItem();
    }

    String getErrorText()
    {
        return errorLabel.getText();
    }
}

package com.waypointer.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.RenderingHints;
import javax.swing.JPanel;

// A rounded block on the panel background. Everything in the sidebar that groups rows (a
// category, the trip status, a form) sits in one, so the list reads as separate objects.
class CardPanel extends JPanel
{
    private Color outline;

    CardPanel(LayoutManager layout)
    {
        super(layout);
        setOpaque(false);
        setBackground(Styles.CARD_BG);
        setAlignmentX(LEFT_ALIGNMENT);
    }

    // An outline marks the card the user is acting on: the trip in progress, an open form.
    void setOutline(Color outline)
    {
        this.outline = outline;
        repaint();
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        paintCard(g, this, getBackground(), outline);
    }

    static void paintCard(Graphics g, Component c, Color fill, Color outline)
    {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setColor(fill);
        g2.fillRoundRect(0, 0, c.getWidth(), c.getHeight(), Styles.CARD_ARC, Styles.CARD_ARC);
        if (outline != null)
        {
            g2.setColor(outline);
            g2.drawRoundRect(0, 0, c.getWidth() - 1, c.getHeight() - 1, Styles.CARD_ARC, Styles.CARD_ARC);
        }
        g2.dispose();
    }

    @Override
    public Dimension getMaximumSize()
    {
        return Styles.capHeight(this);
    }
}

package com.waypointer.ui;

import java.awt.Cursor;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;

// Card-row pattern helpers. A "card" is a JPanel styled as a hover-aware row:
// DARKER_GRAY background, DARK_GRAY_HOVER on hover, HAND_CURSOR, and a left-click handler.
// Swing does not propagate mouse events from a child component with no listeners up to its
// parent, so callers must attach the returned MouseAdapter to any child label that should
// also be in the click hit region.
final class Cards
{
    private Cards() {}

    static MouseAdapter clickable(JPanel card, Runnable onClick)
    {
        card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        card.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        MouseAdapter ma = new MouseAdapter()
        {
            @Override public void mouseEntered(MouseEvent e)
            {
                card.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
            }

            @Override public void mouseExited(MouseEvent e)
            {
                // mouseExited fires when the cursor crosses into a child component too, and the
                // event point arrives in that child's coordinate space. Convert to the card's
                // space before the bounds test, or exiting via a child whose bounds overlap the
                // card origin leaves the hover tint stuck (mirrors WaypointRow's select adapter).
                java.awt.Point p = SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), card);
                if (card.contains(p)) return;
                card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            }

            @Override public void mouseClicked(MouseEvent e)
            {
                if (SwingUtilities.isLeftMouseButton(e)) onClick.run();
            }
        };
        card.addMouseListener(ma);
        return ma;
    }
}

package com.waypointer.ui;

import com.waypointer.model.Category;
import com.waypointer.service.WaypointStore;
import java.awt.event.ActionListener;
import java.util.UUID;
import javax.swing.JComboBox;

/**
 * Shared category-combo machinery for the capture forms. Owns populating the combo with the
 * ordered categories plus the "+ New category..." sentinel, tracking the last real selection,
 * and resolving the selected id at save time. The "+ New category" reaction itself stays with
 * the host -- CaptureForm's inline row -- while only the mechanical rebuild + resolution are
 * shared here.
 */
class CategoryComboController
{
    private final JComboBox<CategoryComboItem> combo;
    private final WaypointStore store;
    private CategoryComboItem lastNonSentinel;

    CategoryComboController(JComboBox<CategoryComboItem> combo, WaypointStore store)
    {
        this.combo = combo;
        this.store = store;
    }

    /** Repopulate from the store and select {@code selectId}, suppressing action events. */
    void rebuild(UUID selectId)
    {
        ActionListener[] listeners = combo.getActionListeners();
        for (ActionListener l : listeners) combo.removeActionListener(l);

        combo.removeAllItems();
        CategoryComboItem toSelect = null;
        for (Category c : store.getCategoriesOrdered())
        {
            CategoryComboItem item = new CategoryComboItem(c);
            combo.addItem(item);
            if (c.getId().equals(selectId)) toSelect = item;
        }
        combo.addItem(CategoryComboItem.sentinel("+ New category..."));
        if (toSelect != null)
        {
            combo.setSelectedItem(toSelect);
            lastNonSentinel = toSelect;
        }

        for (ActionListener l : listeners) combo.addActionListener(l);
    }

    boolean isSentinelSelected()
    {
        CategoryComboItem sel = selected();
        return sel != null && sel.isSentinel();
    }

    /** The last real (non-sentinel) selection; null only until the first rebuild that matches a category. */
    CategoryComboItem lastNonSentinel()
    {
        return lastNonSentinel;
    }

    void setLastNonSentinel(CategoryComboItem item)
    {
        this.lastNonSentinel = item;
    }

    /** Save-time resolution: uncategorized for null/sentinel, else the selected category id. */
    UUID resolveSelectedId()
    {
        CategoryComboItem sel = selected();
        return (sel == null || sel.isSentinel()) ? store.getUncategorized().getId() : sel.id();
    }

    private CategoryComboItem selected()
    {
        return (CategoryComboItem) combo.getSelectedItem();
    }
}

package com.waypointer.ui;

import com.waypointer.model.Category;
import java.util.UUID;

// JComboBox item wrapping a Category. A sentinel item (null category) carries a plain label
// instead - used by CaptureForm for its "+ New category..." row. The combo box renders
// items via toString().
final class CategoryComboItem
{
    private final Category category;     // null for a sentinel item
    private final String sentinelLabel;  // non-null only for a sentinel item

    CategoryComboItem(Category category)
    {
        this.category = category;
        this.sentinelLabel = null;
    }

    private CategoryComboItem(String sentinelLabel)
    {
        this.category = null;
        this.sentinelLabel = sentinelLabel;
    }

    static CategoryComboItem sentinel(String label)
    {
        return new CategoryComboItem(label);
    }

    boolean isSentinel()
    {
        return category == null;
    }

    UUID id()
    {
        return category == null ? null : category.getId();
    }

    @Override
    public String toString()
    {
        return category == null ? sentinelLabel : category.getName();
    }
}

package com.waypointer.ui;

import com.waypointer.model.Category;
import com.waypointer.service.IconCatalog;
import com.waypointer.service.WaypointStore;
import java.awt.Component;
import java.awt.Window;
import javax.swing.JComponent;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import net.runelite.client.game.SpriteManager;

/**
 * Category-level menu actions wired into each {@link CategorySection} via
 * {@link CategorySection.Actions}: rename, delete (with undo toast), set icon, set colour.
 * Pure dialog + store glue extracted from {@link WaypointerPanel}; holds no state of its own.
 */
final class CategoryMenuController
{
    private final WaypointStore store;
    private final SpriteManager spriteManager;
    private final IconCatalog iconCatalog;
    private final Toasts toasts;
    // Parent for modal dialogs and the source of the window ancestor the icon picker needs.
    private final JComponent parent;

    CategoryMenuController(WaypointStore store, SpriteManager spriteManager,
        IconCatalog iconCatalog, Toasts toasts, JComponent parent)
    {
        this.store = store;
        this.spriteManager = spriteManager;
        this.iconCatalog = iconCatalog;
        this.toasts = toasts;
        this.parent = parent;
    }

    void promptRename(Category c)
    {
        String newName = JOptionPane.showInputDialog(parent,
            "Rename '" + c.getName() + "' to:", c.getName());
        if (newName == null || newName.trim().isEmpty()) return;
        try { store.renameCategory(c.getId(), newName.trim()); }
        catch (IllegalArgumentException ex) {
            JOptionPane.showMessageDialog(parent, ex.getMessage(), "Waypointer",
                JOptionPane.WARNING_MESSAGE);
        }
    }

    void promptDelete(Category c)
    {
        String[] options = {"Move to Uncategorized", "Delete waypoints", "Cancel"};
        int choice = JOptionPane.showOptionDialog(parent,
            "Delete category '" + c.getName() + "'?\n\nWhat to do with its waypoints?",
            "Delete category", JOptionPane.DEFAULT_OPTION, JOptionPane.QUESTION_MESSAGE,
            null, options, options[0]);
        String name = c.getName();
        if (choice == 0)
        {
            store.deleteCategory(c.getId(), true);
            toasts.show("Deleted category '" + name + "'", "Undo", store::undoLast);
        }
        else if (choice == 1)
        {
            // childCount is captured BEFORE the delete - deleteCategory(_, false) removes
            // those waypoints so getWaypointsInCategory would return 0 afterwards.
            int childCount = store.getWaypointsInCategory(c.getId()).size();
            store.deleteCategory(c.getId(), false);
            String msg = "Deleted '" + name + "' and " + childCount
                + (childCount == 1 ? " waypoint" : " waypoints");
            toasts.show(msg, "Undo", store::undoLast);
        }
    }

    void promptSetIcon(Category c)
    {
        Window owner = SwingUtilities.getWindowAncestor(parent);
        new IconPickerDialog(owner, spriteManager, iconCatalog, c.getIconId(),
            iconId -> store.setCategoryIcon(c.getId(), iconId)).setVisible(true);
    }

    void promptSetColour(Category c, Component anchor)
    {
        ColorPalettePopup.build(c.getColor(), rgb -> store.setCategoryColor(c.getId(), rgb))
            .show(anchor, 0, anchor.getHeight());
    }
}

package com.waypointer.ui;

import com.waypointer.model.Category;
import com.waypointer.model.CategorySortMode;
import com.waypointer.model.Waypoint;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.service.Wilderness;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import java.util.function.Function;
import javax.swing.BorderFactory;
import javax.swing.JCheckBoxMenuItem;
import javax.swing.JLabel;
import javax.swing.JMenu;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.border.Border;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;

// One category as a card: header + body of WaypointRows. The header carries the colour dot, the
// title (click target for collapse, drag source for reorder), an optional 16x16 icon, the count,
// and on the right the menu trigger (rename / delete / set-icon) and the chevron.
public class CategorySection extends CollapsibleSection
{
    private static javax.swing.Icon colourDot(Color color)
    {
        return new javax.swing.Icon()
        {
            @Override public int getIconWidth() { return 8; }
            @Override public int getIconHeight() { return 8; }
            @Override public void paintIcon(Component c, java.awt.Graphics g, int x, int y)
            {
                java.awt.Graphics2D g2 = (java.awt.Graphics2D) g.create();
                g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING,
                    java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setColor(color);
                g2.fillOval(x, y, 8, 8);
                g2.dispose();
            }
        };
    }

    private final Category category;

    public static Spec spec(Category category, List<Waypoint> waypoints)
    {
        return new Spec(category, waypoints);
    }

    /** Named, defaulted parameter object for {@link CategorySection}. Mirrors {@link WaypointRow.Spec}. */
    public static final class Spec
    {
        private final Category category;
        private final List<Waypoint> waypoints;
        private int activePathTarget = WorldPointPacker.UNDEFINED;
        private boolean collapsed;
        private Consumer<Boolean> onCollapseChange = c -> {};
        private BiConsumer<Waypoint, RowAction> onRowAction = (w, a) -> {};
        private Function<Waypoint, Component> inlineProvider = w -> null;
        private DragAndDropHandler dnd;
        private Actions actions;
        private SpriteManager spriteManager;
        private boolean selectMode;
        private BulkSelection selection;
        private BiConsumer<Waypoint, Boolean> onRowSelectClick = (w, sel) -> {};
        private BiConsumer<List<UUID>, Boolean> onHeaderSelectToggle = (ids, sel) -> {};

        private Spec(Category category, List<Waypoint> waypoints)
        {
            this.category = category;
            this.waypoints = waypoints;
        }

        public Spec activePathTarget(int v) { this.activePathTarget = v; return this; }
        public Spec collapsed(boolean v) { this.collapsed = v; return this; }
        public Spec onCollapseChange(Consumer<Boolean> v) { this.onCollapseChange = v; return this; }
        public Spec onRowAction(BiConsumer<Waypoint, RowAction> v) { this.onRowAction = v; return this; }
        public Spec inlineProvider(Function<Waypoint, Component> v) { this.inlineProvider = v; return this; }
        public Spec dnd(DragAndDropHandler v) { this.dnd = v; return this; }
        public Spec actions(Actions v) { this.actions = v; return this; }
        public Spec spriteManager(SpriteManager v) { this.spriteManager = v; return this; }
        public Spec selectMode(boolean v) { this.selectMode = v; return this; }
        public Spec selection(BulkSelection v) { this.selection = v; return this; }
        public Spec onRowSelectClick(BiConsumer<Waypoint, Boolean> v) { this.onRowSelectClick = v; return this; }
        public Spec onHeaderSelectToggle(BiConsumer<List<UUID>, Boolean> v) { this.onHeaderSelectToggle = v; return this; }

        public CategorySection build() { return new CategorySection(this); }
    }

    private CategorySection(Spec s)
    {
        super(s.collapsed, s.onCollapseChange);
        this.category = s.category;
        // Unpack the spec into locals so the construction logic below reads unchanged.
        List<Waypoint> waypoints = s.waypoints;
        int activePathTarget = s.activePathTarget;
        BiConsumer<Waypoint, RowAction> onRowAction = s.onRowAction;
        Function<Waypoint, Component> inlineProvider = s.inlineProvider;
        DragAndDropHandler dnd = s.dnd;
        Actions actions = s.actions;
        SpriteManager spriteManager = s.spriteManager;
        boolean selectMode = s.selectMode;
        BulkSelection selection = s.selection;
        BiConsumer<Waypoint, Boolean> onRowSelectClick = s.onRowSelectClick;
        BiConsumer<List<UUID>, Boolean> onHeaderSelectToggle = s.onHeaderSelectToggle;
        JPanel headerRow = buildHeaderRow(waypoints.size());
        // The category colour shows as a dot before the name; uncoloured ones get a grey dot so
        // every name starts in the same column.
        Integer accent = category.getColor();
        JLabel dot = new JLabel(colourDot(accent == null ? Styles.FAINT_TEXT : new Color(accent)));
        dot.addMouseListener(headerLabel.getMouseListeners()[0]);
        headerCenter.add(dot, 0);
        final Border restingHeaderBorder = headerRow.getBorder();
        final Color restingHeaderBg = headerRow.getBackground();

        // Drag must come from the label only; on headerRow, a click on the menu trigger
        // would accidentally start a drag.
        DropIndicatable headerIndicator = mode ->
            DropIndicators.apply(headerRow, mode, restingHeaderBorder, restingHeaderBg);
        if (dnd != null) dnd.attachCategoryHeader(headerLabel, headerIndicator, category.getId(), this, headerRow);

        // Optional icon beside the category name.
        if (!selectMode && category.getIconId() != null && spriteManager != null)
        {
            JLabel iconLabel = new JLabel();
            iconLabel.setPreferredSize(new Dimension(16, 16));
            iconLabel.setOpaque(false);
            SpriteIcons.apply(iconLabel, category.getIconId(), spriteManager);
            // After the name, so every category name starts in the same column.
            headerCenter.add(iconLabel, 2);
        }

        // Select-mode tri-state checkbox at the header's left edge. Clicking it selects or
        // deselects all of this category's currently-visible waypoints.
        if (selectMode)
        {
            List<UUID> catIds = new ArrayList<>();
            for (Waypoint w : waypoints) catIds.add(w.getId());
            TriStateBox headerBox = new TriStateBox();
            switch (selection.categoryState(catIds))
            {
                case ALL:     headerBox.setState(TriStateBox.State.CHECKED); break;
                case PARTIAL: headerBox.setState(TriStateBox.State.PARTIAL); break;
                default:      headerBox.setState(TriStateBox.State.UNCHECKED); break;
            }
            headerBox.addMouseListener(new MouseAdapter()
            {
                @Override public void mouseClicked(MouseEvent e)
                {
                    boolean allSelected = selection.categoryState(catIds) == BulkSelection.TriState.ALL;
                    onHeaderSelectToggle.accept(catIds, !allSelected);
                }
            });
            JPanel headerWest = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
            headerWest.setOpaque(false);
            headerWest.setBorder(BorderFactory.createEmptyBorder(0, 2, 0, 2));
            headerWest.add(headerBox);
            headerRow.add(headerWest, BorderLayout.WEST);
        }

        // Build the popup menu and the trigger glyph on the RIGHT.
        if (!category.isUncategorized())
        {
            JPopupMenu menu = new JPopupMenu();
            JMenuItem rename = new JMenuItem("Rename");
            rename.addActionListener(e -> actions.onRename.run());
            JMenuItem setIcon = new JMenuItem("Set icon...");
            setIcon.addActionListener(e -> { if (actions.onSetIcon != null) actions.onSetIcon.run(); });
            JMenuItem setColour = new JMenuItem("Set colour...");
            setColour.addActionListener(e -> { if (actions.onSetColour != null) actions.onSetColour.run(); });

            JMenu sortBy = new JMenu("Sort by");
            CategorySortMode active =
                category.getSortMode() == null ? CategorySortMode.MANUAL : category.getSortMode();
            sortBy.add(buildSortItem("Manual",
                CategorySortMode.MANUAL, active, actions));
            sortBy.add(buildSortItem("Name (A-Z)",
                CategorySortMode.NAME, active, actions));
            sortBy.add(buildSortItem("Date added (newest first)",
                CategorySortMode.DATE_ADDED, active, actions));

            JMenuItem selectMultiple = new JMenuItem("Select multiple");
            selectMultiple.addActionListener(e -> { if (actions.onEnterSelect != null) actions.onEnterSelect.run(); });

            JMenuItem delete = new JMenuItem("Delete category");
            delete.addActionListener(e -> actions.onDelete.run());
            menu.add(rename);
            menu.add(setIcon);
            menu.add(setColour);
            menu.add(sortBy);
            menu.addSeparator();
            menu.add(selectMultiple);
            menu.add(delete);
            // Right-click on the label still opens the popup (legacy discoverability).
            headerLabel.setComponentPopupMenu(menu);

            javax.swing.JButton menuTrigger = Styles.iconButton(
                Glyphs.of(Glyphs.Shape.MENU, Styles.FAINT_TEXT), "Category options");
            HoverHint.shared().attach(menuTrigger, () -> "Category options");
            menuTrigger.addActionListener(e -> menu.show(menuTrigger, 0, menuTrigger.getHeight()));
            headerEast.add(menuTrigger, 0);
        }

        add(headerRow, BorderLayout.NORTH);

        // Hide the drag handle when the row can't actually be dragged: either the category
        // sort mode is non-MANUAL (reorder is auto), or the panel passed a null dnd because
        // a search filter is active and drop targets would refer to invisible neighbours.
        boolean sortDisablesDrag = category.getSortMode() != null
            && category.getSortMode() != CategorySortMode.MANUAL;
        boolean dragDisabled = sortDisablesDrag || dnd == null;

        for (Waypoint w : waypoints)
        {
            boolean active = activePathTarget != WorldPointPacker.UNDEFINED
                && w.getPackedWorldPoint() == activePathTarget;
            WaypointRow row = WaypointRow.spec(w)
                .active(active)
                .pinned(w.isPinned())
                .wilderness(Wilderness.isInWilderness(w.getPackedWorldPoint()))
                .dragDisabled(dragDisabled)
                .onPlay(() -> onRowAction.accept(w, RowAction.PLAY))
                .onClickBody(() -> onRowAction.accept(w, RowAction.EXPAND))
                .onTogglePin(() -> onRowAction.accept(w, RowAction.TOGGLE_PIN))
                .onDelete(() -> onRowAction.accept(w, RowAction.DELETE))
                .onEnterSelectMode(() -> onRowAction.accept(w, RowAction.ENTER_SELECT))
                .spriteManager(spriteManager)
                .selectMode(selectMode)
                .selected(selection.ids().contains(w.getId()))
                .onSelectClick(shift -> onRowSelectClick.accept(w, shift))
                .build();
            if (dnd != null) dnd.attachWaypointRow(row, row.getDragHandle(), row, w.getId(), category.getId());
            addRow(row, w, inlineProvider);
        }
        if (waypoints.isEmpty())
        {
            EmptyDropZone empty = new EmptyDropZone();
            body.add(empty);
            // When dnd == null (a search filter is active) the zone is shown for affordance
            // but not wired as a drop target, mirroring the non-empty tail zone.
            if (dnd != null) dnd.attachTailZone(empty, empty, category.getId());
        }
        else
        {
            TailDropZone tail = new TailDropZone();
            body.add(tail);
            if (dnd != null) dnd.attachTailZone(tail, tail, category.getId());
        }
        attachBody();
    }

    @Override
    protected String headerText()
    {
        return category.getName();
    }

    public UUID getCategoryId()
    {
        return category.getId();
    }

    private static JMenuItem buildSortItem(String label,
        CategorySortMode mode,
        CategorySortMode active,
        Actions actions)
    {
        JCheckBoxMenuItem item = new JCheckBoxMenuItem(label, mode == active);
        item.addActionListener(e -> {
            if (actions.onSetSortMode != null) actions.onSetSortMode.accept(mode);
        });
        return item;
    }

    /** Row-level user actions plumbed up from {@link WaypointRow} to the panel. */
    public enum RowAction { PLAY, EXPAND, EXPAND_PINNED, DELETE, TOGGLE_PIN, ENTER_SELECT }

    /** The category-level menu actions, bundled so the constructor stays readable. */
    public static final class Actions
    {
        final Runnable onRename;
        final Runnable onDelete;
        final Runnable onSetIcon;
        final Runnable onSetColour;
        final Consumer<CategorySortMode> onSetSortMode;
        final Runnable onEnterSelect;

        public Actions(Runnable onRename, Runnable onDelete, Runnable onSetIcon,
            Runnable onSetColour,
            Consumer<CategorySortMode> onSetSortMode,
            Runnable onEnterSelect)
        {
            this.onRename = onRename;
            this.onDelete = onDelete;
            this.onSetIcon = onSetIcon;
            this.onSetColour = onSetColour;
            this.onSetSortMode = onSetSortMode;
            this.onEnterSelect = onEnterSelect;
        }
    }

    /**
     * Thin (~8 px) hit zone appended after the last waypoint row in an expanded section.
     * Invisible at rest; paints a 2 px top border in {@link ColorScheme#BRAND_ORANGE}
     * when {@link DropIndicatable#setDropIndicator} is called with
     * {@link DropIndicatorMode#BORDER_AND_TINT}. Mirrors the existing indicator
     * vocabulary from {@code DragAndDropHandler}.
     */
    private static final class TailDropZone extends JPanel implements DropIndicatable
    {
        private static final int HEIGHT = 8;
        private final Border resting;

        TailDropZone()
        {
            setOpaque(false);
            setAlignmentX(LEFT_ALIGNMENT);
            setPreferredSize(new Dimension(0, HEIGHT));
            setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
            resting = BorderFactory.createEmptyBorder(0, 8, 0, 8);
            setBorder(resting);
        }

        @Override
        public void setDropIndicator(DropIndicatorMode mode)
        {
            // Transparent zone: it carries the orange accent border but never the tint.
            setBorder(mode == DropIndicatorMode.BORDER_AND_TINT
                ? DropIndicators.topAccentOver(resting) : resting);
            repaint();
        }
    }

    /**
     * Visible drop affordance shown in place of rows when a category is empty. Carries the
     * "(empty - drag here)" hint with a dashed resting border so it reads as a target, and
     * lights up with the shared orange-top-border + tint vocabulary when a waypoint is dragged
     * over it. Wired through {@link DragAndDropHandler#attachTailZone}, so a drop appends the
     * waypoint to this category -- matching {@link TailDropZone} on non-empty categories.
     */
    private static final class EmptyDropZone extends JPanel implements DropIndicatable
    {
        private final Border resting = BorderFactory.createCompoundBorder(
            BorderFactory.createDashedBorder(Styles.MUTED_TEXT),
            BorderFactory.createEmptyBorder(2, 10, 2, 4));

        EmptyDropZone()
        {
            setLayout(new BorderLayout());
            setOpaque(false);
            setAlignmentX(LEFT_ALIGNMENT);
            setBorder(resting);
            JLabel label = new JLabel("(empty - drag here)");
            label.setForeground(Styles.MUTED_TEXT);
            add(label, BorderLayout.WEST);
        }

        @Override
        public void setDropIndicator(DropIndicatorMode mode)
        {
            if (mode == DropIndicatorMode.BORDER_AND_TINT)
            {
                setOpaque(true);
                setBackground(DropIndicators.TINT_BG);
                // Accent over the zone's own padding (not the dashed resting border).
                setBorder(DropIndicators.topAccentOver(BorderFactory.createEmptyBorder(2, 10, 2, 4)));
            }
            else
            {
                setOpaque(false);
                setBorder(resting);
            }
            repaint();
        }

        @Override public Dimension getMaximumSize()
        {
            return Styles.capHeight(this);
        }
    }
}

package com.waypointer.ui;

import java.awt.Cursor;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Insets;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseMotionAdapter;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;

/**
 * Search-style text field that paints a small clear glyph inside its right inset and
 * clears its contents when the glyph is clicked. The glyph appears only while the
 * field has text. Callers reserve room for it via the border's right inset; the paint
 * position and hit zone both derive from {@link #getInsets()} so any border tweak
 * keeps glyph + click in sync.
 */
class ClearableTextField extends PlaceholderTextField
{
    private static final String CLEAR_GLYPH = "✕"; // U+2715 multiplication X
    // How wide a slice of the right inset the click hit zone occupies. Sized generously
    // so the glyph remains comfortably clickable at default font metrics.
    private static final int HIT_BAND_PX = 16;

    private static final Cursor TEXT_CURSOR = Cursor.getPredefinedCursor(Cursor.TEXT_CURSOR);
    private static final Cursor HAND_CURSOR = Cursor.getPredefinedCursor(Cursor.HAND_CURSOR);

    ClearableTextField(String placeholder)
    {
        super(placeholder);

        addMouseMotionListener(new MouseMotionAdapter()
        {
            @Override public void mouseMoved(MouseEvent e)
            {
                setCursor(isOverClearGlyph(e) ? HAND_CURSOR : TEXT_CURSOR);
            }
        });
        addMouseListener(new MouseAdapter()
        {
            @Override public void mousePressed(MouseEvent e)
            {
                if (!SwingUtilities.isLeftMouseButton(e)) return;
                if (!isOverClearGlyph(e)) return;
                setText("");
                e.consume();
            }
        });
    }

    private boolean isOverClearGlyph(MouseEvent e)
    {
        if (getText().isEmpty()) return false;
        Rectangle hit = clearGlyphHitBox();
        return hit != null && hit.contains(e.getPoint());
    }

    // Hit zone occupies a HIT_BAND_PX-wide stripe at the right edge, just inside the border.
    private Rectangle clearGlyphHitBox()
    {
        Insets in = getInsets();
        int w = getWidth();
        int h = getHeight();
        int left = Math.max(in.left, w - in.right - HIT_BAND_PX);
        return new Rectangle(left, in.top, w - in.right - left, h - in.top - in.bottom);
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        super.paintComponent(g);
        if (getText().isEmpty()) return;

        Graphics2D g2 = (Graphics2D) g.create();
        try
        {
            g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
                RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            g2.setFont(getFont());
            FontMetrics fm = g2.getFontMetrics();
            int glyphW = fm.stringWidth(CLEAR_GLYPH);
            Insets in = getInsets();
            // Centre the glyph horizontally within the band, vertically on the baseline.
            int bandCenterX = getWidth() - in.right - HIT_BAND_PX / 2;
            int x = bandCenterX - glyphW / 2;
            int y = (getHeight() + fm.getAscent() - fm.getDescent()) / 2;
            g2.setColor(ColorScheme.LIGHT_GRAY_COLOR);
            g2.drawString(CLEAR_GLYPH, x, y);
        }
        finally
        {
            g2.dispose();
        }
    }
}

package com.waypointer.ui;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;
import javax.inject.Inject;

/** Codec for the categoryCollapsedJson config string. Map<categoryId, collapsed?>. */
public class CollapseStateCodec
{
    private final Gson gson;

    @Inject
    public CollapseStateCodec(Gson gson) { this.gson = gson; }

    public Map<UUID, Boolean> decode(String s)
    {
        if (s == null || s.isEmpty()) return new HashMap<>();
        try
        {
            Map<String, Boolean> raw = gson.fromJson(s,
                new TypeToken<Map<String, Boolean>>(){}.getType());
            if (raw == null) return new HashMap<>();
            Map<UUID, Boolean> out = new HashMap<>();
            for (Map.Entry<String, Boolean> e : raw.entrySet())
            {
                try { out.put(UUID.fromString(e.getKey()), e.getValue()); }
                catch (IllegalArgumentException ignored) {}
            }
            return out;
        }
        catch (JsonSyntaxException e)
        {
            return new HashMap<>();
        }
    }

    public String encode(Map<UUID, Boolean> map)
    {
        Map<String, Boolean> raw = new HashMap<>();
        for (Map.Entry<UUID, Boolean> e : map.entrySet())
        {
            raw.put(e.getKey().toString(), e.getValue());
        }
        return gson.toJson(raw);
    }
}

package com.waypointer.ui;

import com.waypointer.model.Waypoint;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;
import java.util.function.Function;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

// Base for collapsible panel sections: a clickable chevron header that toggles a vertically
// stacked body. Subclasses supply the title via headerText() and fill the protected `body`
// field; the base owns collapse state, the collapse-on-click wiring, the transient-expand
// hooks used by drag auto-expand, and the height cap that keeps a BoxLayout(Y_AXIS) parent
// from stretching each section into leftover column space.
abstract class CollapsibleSection extends JPanel
{
    protected final JPanel body = new JPanel();
    protected JLabel headerLabel;
    // The flow of title, count and any extras; and the right-hand cluster ending in the chevron.
    protected JPanel headerCenter;
    protected JPanel headerEast;
    private JLabel chevron;
    protected boolean collapsed;
    private final Consumer<Boolean> onCollapseChange;

    protected CollapsibleSection(boolean collapsed, Consumer<Boolean> onCollapseChange)
    {
        this.collapsed = collapsed;
        this.onCollapseChange = onCollapseChange;
        setLayout(new BorderLayout());
        setOpaque(false);
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        // BoxLayout in the parent horizontal-stretches us to the column width but must not
        // centre us. Pin to the left edge.
        setAlignmentX(LEFT_ALIGNMENT);

        body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
        body.setOpaque(false);
        body.setBorder(BorderFactory.createEmptyBorder(0, 0, 2, 0));
        body.setAlignmentX(LEFT_ALIGNMENT);
    }

    // Builds the header row: a BorderLayout panel whose CENTER holds the chevron+title label
    // and a "(count)" label, every surface wired to toggle collapse on click. Returns the row
    // so subclasses can add WEST/EAST decorations before placing it via add(..., NORTH).
    // Assigns this.headerLabel as a side effect (headerText() is read here, so subclass fields
    // it depends on must be set before calling this).
    protected JPanel buildHeaderRow(int count)
    {
        // Paints a rounded tint when a drag hovers it; otherwise the card shows through.
        JPanel headerRow = new JPanel(new BorderLayout(4, 0))
        {
            @Override protected void paintComponent(java.awt.Graphics g)
            {
                if (!getBackground().equals(Styles.CARD_BG)) CardPanel.paintCard(g, this, Styles.ROW_HOVER, null);
            }
        };
        headerRow.setOpaque(false);
        headerRow.setBackground(Styles.CARD_BG);
        headerRow.setBorder(BorderFactory.createEmptyBorder(5, 8, 5, 6));
        headerRow.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        MouseAdapter collapseOnClick = new MouseAdapter()
        {
            @Override public void mouseClicked(MouseEvent e) { toggleCollapse(); }
        };
        headerRow.addMouseListener(collapseOnClick);

        headerLabel = new JLabel(headerText());
        headerLabel.setForeground(Color.WHITE);
        headerLabel.setFont(FontManager.getRunescapeBoldFont());
        headerLabel.setOpaque(false);
        headerLabel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        headerLabel.addMouseListener(collapseOnClick);

        JLabel countLabel = Styles.pill(String.valueOf(count));
        countLabel.addMouseListener(collapseOnClick);

        headerCenter = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 0));
        headerCenter.setOpaque(false);
        headerCenter.addMouseListener(collapseOnClick);
        headerCenter.add(headerLabel);
        headerCenter.add(countLabel);
        headerRow.add(headerCenter, BorderLayout.CENTER);

        chevron = new JLabel(chevronIcon());
        chevron.addMouseListener(collapseOnClick);
        headerEast = new JPanel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
        headerEast.setOpaque(false);
        headerEast.addMouseListener(collapseOnClick);
        headerEast.add(chevron);
        headerRow.add(headerEast, BorderLayout.EAST);
        return headerRow;
    }

    private javax.swing.Icon chevronIcon()
    {
        return Glyphs.of(collapsed ? Glyphs.Shape.CHEVRON_RIGHT : Glyphs.Shape.CHEVRON_DOWN, Styles.FAINT_TEXT);
    }

    @Override
    protected void paintComponent(java.awt.Graphics g)
    {
        CardPanel.paintCard(g, this, Styles.CARD_BG, null);
    }

    // Places the (already-populated) body to CENTER, honouring the current collapse state.
    // Subclasses add the header to NORTH themselves (after decorating it), then call this once
    // the body rows are built.
    protected void attachBody()
    {
        body.setVisible(!collapsed);
        add(body, BorderLayout.CENTER);
    }

    protected abstract String headerText();

    protected void toggleCollapse()
    {
        collapsed = !collapsed;
        body.setVisible(!collapsed);
        headerLabel.setText(headerText());
        chevron.setIcon(chevronIcon());
        revalidate();
        repaint();
        onCollapseChange.accept(collapsed);
    }

    // Cap vertical extent at preferred height so BoxLayout(Y_AXIS) in the parent stacks
    // sections tight instead of stretching each one to fill leftover space.
    @Override
    public Dimension getMaximumSize()
    {
        return Styles.capHeight(this);
    }

    // Appends a built row plus its optional inline editor to the body, both left-aligned. Shared
    // by CategorySection and PinnedSection, which build their own WaypointRow.spec(...) (the spec
    // config differs) but stack rows identically.
    protected void addRow(WaypointRow row, Waypoint w, Function<Waypoint, Component> inlineProvider)
    {
        row.setAlignmentX(LEFT_ALIGNMENT);
        body.add(row);
        if (inlineProvider != null)
        {
            Component inline = inlineProvider.apply(w);
            if (inline != null)
            {
                if (inline instanceof JComponent)
                {
                    ((JComponent) inline).setAlignmentX(LEFT_ALIGNMENT);
                }
                body.add(inline);
            }
        }
    }

    public boolean isCollapsed() { return collapsed; }

    // Flip collapsed state WITHOUT persisting (no onCollapseChange fired). Used by the
    // spring-loaded auto-expand during a drag; persistence happens via confirmTransientExpand()
    // when a drop confirms the expansion.
    public void setExpandedTransient(boolean expanded)
    {
        if (collapsed == !expanded) return;
        collapsed = !expanded;
        body.setVisible(expanded);
        headerLabel.setText(headerText());
        chevron.setIcon(chevronIcon());
        revalidate();
        repaint();
    }

    // Promote a transient expansion to persistent: fire onCollapseChange(false) once so the
    // panel's persisted collapse map reflects "user wants this open". No-op if collapsed.
    public void confirmTransientExpand()
    {
        if (!collapsed) onCollapseChange.accept(false);
    }
}

package com.waypointer.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.JComponent;
import javax.swing.JMenuItem;
import javax.swing.JPopupMenu;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * A compact palette of category accent colours. Fixed swatches chosen to read against the
 * RuneLite dark panel; none is brand orange, which signals active-path status elsewhere.
 * Reports the chosen packed RGB (or null for "None") to the supplied consumer.
 */
final class ColorPalettePopup
{
    // Packed RGB. Amber here is intentionally not BRAND_ORANGE.
    static final int[] SWATCHES = {
        0xCC4040, // muted red
        0xC8922A, // amber
        0x4F9D4F, // green
        0x3FA39A, // teal
        0x4477BB, // blue
        0x8A5FB0, // purple
        0xB05592, // magenta
        0x8A8F96, // grey
    };

    private ColorPalettePopup() {}

    static JPopupMenu build(Integer current, Consumer<Integer> onPick)
    {
        JPopupMenu popup = new JPopupMenu();
        popup.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        popup.setBorder(BorderFactory.createLineBorder(ColorScheme.DARK_GRAY_COLOR));
        for (int rgb : SWATCHES)
        {
            JMenuItem item = new JMenuItem();
            item.setOpaque(true);
            item.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            item.getAccessibleContext().setAccessibleName("Category colour " + String.format("#%06X", rgb));
            item.add(new Swatch(new Color(rgb), current != null && current == rgb));
            item.addActionListener(e -> onPick.accept(rgb));
            popup.add(item);
        }
        popup.addSeparator();
        JMenuItem none = new JMenuItem("None");
        none.setOpaque(true);
        none.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        none.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        none.setFont(FontManager.getRunescapeSmallFont());
        none.getAccessibleContext().setAccessibleName("Clear category colour");
        none.addActionListener(e -> onPick.accept(null));
        popup.add(none);
        return popup;
    }

    /** A fixed-size colour chip; outlined when it is the current selection. */
    private static final class Swatch extends JComponent
    {
        private final Color color;
        private final boolean selected;

        Swatch(Color color, boolean selected)
        {
            this.color = color;
            this.selected = selected;
            setOpaque(true);
            setBackground(ColorScheme.DARKER_GRAY_COLOR);
            setPreferredSize(new Dimension(96, 16));
            setBorder(BorderFactory.createEmptyBorder(2, 2, 2, 2));
        }

        @Override
        protected void paintComponent(Graphics g)
        {
            g.setColor(getBackground());
            g.fillRect(0, 0, getWidth(), getHeight());
            g.setColor(color);
            g.fillRect(2, 2, getWidth() - 4, getHeight() - 4);
            if (selected)
            {
                g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
                g.drawRect(1, 1, getWidth() - 3, getHeight() - 3);
            }
        }
    }
}

