/**
 * Inline picker shown below the {@link NearestLandmarkBar} when the customize button is
 * clicked. One row per landmark type. Each row: drag-handle, checkbox, icon, name.
 * Rows support drag-to-reorder via a Swing {@link TransferHandler} with string-flavor payload.
 */
final class ConfigureLandmarksPanel extends JPanel
{
    private static final int ROW_HEIGHT = 24;
    private static final int DRAG_THRESHOLD_SQ = 25;
    private static final String PAYLOAD_PREFIX = "landmark:";
    private static final DataFlavor STR = DataFlavor.stringFlavor;

    private final SpriteManager spriteManager;
    private final Map<LandmarkType, Integer> spriteIds;
    private final BiConsumer<LandmarkType, Boolean> onToggle;
    private final BiConsumer<Integer, Integer> onReorder;
    private final Runnable onClose;

    private LandmarkSelection selection;

    ConfigureLandmarksPanel(SpriteManager spriteManager,
        Map<LandmarkType, Integer> spriteIds,
        LandmarkSelection initial,
        BiConsumer<LandmarkType, Boolean> onToggle,
        BiConsumer<Integer, Integer> onReorder,
        Runnable onClose)
    {
        this.spriteManager = spriteManager;
        this.spriteIds = spriteIds;
        this.selection = initial;
        this.onToggle = onToggle;
        this.onReorder = onReorder;
        this.onClose = onClose;

        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setOpaque(false);
        // The top inset is the gap under the tiles; see paintComponent.
        setBorder(BorderFactory.createEmptyBorder(Styles.CARD_GAP + 4, 8, 6, 8));
        setVisible(false);

        rebuild();
    }

    @Override
    protected void paintComponent(java.awt.Graphics g)
    {
        Styles.paintInsetCard(g, this, 0, Styles.CARD_GAP, 0, 0, null);
    }

    void setSelection(LandmarkSelection s)
    {
        this.selection = s;
        rebuild();
    }

    private void rebuild()
    {
        removeAll();
        add(buildHeader());
        int index = 0;
        for (LandmarkType type : selection.order())
        {
            add(buildRow(type, index));
            index++;
        }
        revalidate();
        repaint();
    }

    // Title row with a close (X) affordance. The picker is otherwise only dismissable by
    // re-clicking the overflow toggle, which isn't obvious -- the X makes it explicit.
    private JPanel buildHeader()
    {
        JPanel header = new JPanel(new java.awt.BorderLayout());
        header.setOpaque(false);
        header.setMaximumSize(new Dimension(Integer.MAX_VALUE, ROW_HEIGHT));
        header.setPreferredSize(new Dimension(0, ROW_HEIGHT));

        JLabel title = Styles.caption("Tick to show, drag to reorder");
        header.add(title, java.awt.BorderLayout.WEST);

        JLabel close = new JLabel("✕"); // U+2715 multiplication X -- close glyph
        close.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        close.setFont(FontManager.getRunescapeFont());
        close.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
        close.setToolTipText("Close");
        close.getAccessibleContext().setAccessibleName("Close landmark picker");
        close.addMouseListener(new MouseAdapter()
        {
            @Override public void mouseClicked(MouseEvent e) { if (onClose != null) onClose.run(); }
        });
        header.add(close, java.awt.BorderLayout.EAST);
        return header;
    }

    private JPanel buildRow(LandmarkType type, int index)
    {
        JPanel row = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0))
        {
            @Override
            protected void paintComponent(java.awt.Graphics g)
            {
                g.setColor(Styles.ROW_LINE);
                g.fillRect(0, 0, getWidth(), 1);
            }
        };
        row.setOpaque(false);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, ROW_HEIGHT));
        row.setPreferredSize(new Dimension(0, ROW_HEIGHT));

        JLabel handle = new JLabel("⋮"); // U+22EE VERTICAL ELLIPSIS -- drag-handle glyph
        handle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        handle.setFont(FontManager.getRunescapeFont());
        handle.setPreferredSize(new Dimension(10, ROW_HEIGHT));
        handle.getAccessibleContext().setAccessibleName("Reorder " + type.displayName());
        row.add(handle);

        JCheckBox cb = new JCheckBox();
        cb.setSelected(selection.isSelected(type));
        cb.setOpaque(false);
        cb.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        cb.setFocusPainted(false);
        cb.addActionListener(e -> onToggle.accept(type, cb.isSelected()));
        row.add(cb);

        JLabel iconLbl = new JLabel();
        iconLbl.setPreferredSize(new Dimension(20, ROW_HEIGHT));
        applySprite(iconLbl, type);
        row.add(iconLbl);

        JLabel nameLbl = new JLabel(type.displayName());
        nameLbl.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        nameLbl.setFont(FontManager.getRunescapeSmallFont());
        row.add(nameLbl);

        // Drop target: row accepts another row's payload and forwards to onReorder.
        final int targetIndex = index;
        row.setTransferHandler(new TransferHandler()
        {
            @Override public boolean canImport(TransferSupport s)
            {
                return s.isDataFlavorSupported(STR);
            }

            @Override public boolean importData(TransferSupport s)
            {
                String payload = readPayload(s);
                if (payload == null || !payload.startsWith(PAYLOAD_PREFIX)) return false;
                LandmarkType dragged = parseTypeOrNull(payload.substring(PAYLOAD_PREFIX.length()));
                if (dragged == null) return false;
                int from = selection.order().indexOf(dragged);
                if (from < 0 || from == targetIndex) return false;
                onReorder.accept(from, targetIndex);
                return true;
            }
        });

        // Drag source: handle starts a MOVE drag after a 5 px-squared threshold.
        // Installs a SourceCapable TransferHandler on the row on first press so exportAsDrag has a payload.
        DragGesture gesture = new DragGesture(row, type);
        handle.addMouseListener(gesture);
        handle.addMouseMotionListener(gesture);

        return row;
    }

    private static String readPayload(TransferHandler.TransferSupport s)
    {
        try { return (String) s.getTransferable().getTransferData(STR); }
        catch (Exception e) { return null; }
    }

    private static LandmarkType parseTypeOrNull(String name)
    {
        try { return LandmarkType.valueOf(name); }
        catch (IllegalArgumentException e) { return null; }
    }

    /** Tracks press + drag-distance on a row's drag-handle and triggers exportAsDrag. */
    private static final class DragGesture extends MouseAdapter implements MouseMotionListener
    {
        private final JComponent dragSource;
        private final LandmarkType type;
        private Point pressPoint;
        private boolean started;

        DragGesture(JComponent dragSource, LandmarkType type)
        {
            this.dragSource = dragSource;
            this.type = type;
        }

        @Override public void mousePressed(MouseEvent e)
        {
            pressPoint = e.getPoint();
            started = false;
            // Lazily install a source-capable wrapper on the row TransferHandler so exportAsDrag has a payload.
            TransferHandler current = dragSource.getTransferHandler();
            if (!(current instanceof SourceCapable))
            {
                dragSource.setTransferHandler(new SourceCapable(current, type));
            }
        }

        @Override public void mouseReleased(MouseEvent e)
        {
            pressPoint = null;
            started = false;
        }

        @Override public void mouseDragged(MouseEvent e)
        {
            if (pressPoint == null || started) return;
            int dx = e.getX() - pressPoint.x;
            int dy = e.getY() - pressPoint.y;
            if (dx * dx + dy * dy >= DRAG_THRESHOLD_SQ)
            {
                started = true;
                TransferHandler th = dragSource.getTransferHandler();
                if (th != null) th.exportAsDrag(dragSource, e, TransferHandler.MOVE);
            }
        }

        @Override public void mouseMoved(MouseEvent e) { }
    }

    /**
     * Adapter that augments the row's drop-target TransferHandler with source semantics
     * (createTransferable + getSourceActions) so exportAsDrag has a payload to ship.
     */
    private static final class SourceCapable extends TransferHandler
    {
        private final TransferHandler delegate;
        private final LandmarkType type;

        SourceCapable(TransferHandler delegate, LandmarkType type)
        {
            this.delegate = delegate;
            this.type = type;
        }

        @Override public int getSourceActions(JComponent c) { return MOVE; }

        @Override protected Transferable createTransferable(JComponent c)
        {
            return new StringSelection(PAYLOAD_PREFIX + type.name());
        }

        @Override public boolean canImport(TransferSupport s)
        {
            return delegate != null && delegate.canImport(s);
        }

        @Override public boolean importData(TransferSupport s)
        {
            return delegate != null && delegate.importData(s);
        }
    }

    private void applySprite(JLabel target, LandmarkType type)
    {
        Integer id = spriteIds.get(type);
        if (id == null || spriteManager == null) return;
        spriteManager.getSpriteAsync(id, 0, img -> {
            if (img == null) return;
            SwingUtilities.invokeLater(() -> {
                target.setIcon(new ImageIcon(scaleDownIfNeeded(img)));
            });
        });
    }

    private static Image scaleDownIfNeeded(BufferedImage src)
    {
        int longest = Math.max(src.getWidth(), src.getHeight());
        if (longest <= 16) return src;
        double scale = 16.0 / longest;
        return src.getScaledInstance((int) Math.round(src.getWidth() * scale),
            (int) Math.round(src.getHeight() * scale), Image.SCALE_SMOOTH);
    }
}

package com.waypointer.ui;

import java.awt.BorderLayout;
import java.awt.Window;
import java.awt.event.ActionEvent;
import java.awt.event.KeyEvent;
import javax.swing.AbstractAction;
import javax.swing.BorderFactory;
import javax.swing.JComponent;
import javax.swing.JDialog;
import javax.swing.JPanel;
import javax.swing.KeyStroke;
import javax.swing.WindowConstants;
import net.runelite.client.ui.ColorScheme;

/**
 * Shared scaffolding for the plugin's modal dialogs: a dark content pane with the standard
 * border and gap, ESC-to-close, and pack/center. Keeps each dialog from re-deriving the same
 * dark-panel setup by hand.
 */
final class Dialogs
{
    private Dialogs()
    {
    }

    /** Dark content pane with the standard 8px gap and border. See the gap overload for exceptions. */
    static JPanel applyDarkContentPane(JDialog d)
    {
        return applyDarkContentPane(d, 8, 8);
    }

    /** Gap overload for dialogs that need tighter inner spacing than the 8px default. */
    static JPanel applyDarkContentPane(JDialog d, int hgap, int vgap)
    {
        d.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);
        JPanel content = (JPanel) d.getContentPane();
        content.setLayout(new BorderLayout(hgap, vgap));
        content.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
        content.setBackground(ColorScheme.DARK_GRAY_COLOR);
        return content;
    }

    /** Closes the dialog when ESC is pressed anywhere within it. */
    static void bindEscape(JDialog d)
    {
        JComponent root = d.getRootPane();
        root.getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW)
            .put(KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0), "waypointer.dialog.close");
        root.getActionMap().put("waypointer.dialog.close", new AbstractAction()
        {
            @Override
            public void actionPerformed(ActionEvent e)
            {
                d.dispose();
            }
        });
    }

    /** Sizes the dialog to its contents and centers it over the owner. */
    static void finish(JDialog d, Window owner)
    {
        d.pack();
        d.setLocationRelativeTo(owner);
    }
}

package com.waypointer.ui;

import com.waypointer.model.Category;
import com.waypointer.model.Waypoint;
import com.waypointer.service.WaypointStore;
import java.awt.AlphaComposite;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.StringSelection;
import java.awt.datatransfer.Transferable;
import java.awt.datatransfer.UnsupportedFlavorException;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseMotionListener;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.CopyOnWriteArrayList;
import javax.swing.JComponent;
import javax.swing.TransferHandler;
import lombok.extern.slf4j.Slf4j;

// Swing drag-and-drop on waypoint rows and category headers. Transfer payloads are
// string-encoded ("waypoint:<uuid>" or "category:<uuid>"). Drag fires from mouseDragged
// after a 5px threshold so single clicks pass through to mouseClicked. Instantiated fresh
// per panel rebuild because onChange captures the panel's rebuild method.
@Slf4j
public class DragAndDropHandler
{
    static final DataFlavor STR = DataFlavor.stringFlavor;
    public static final String WAYPOINT_PREFIX = "waypoint:";
    public static final String CATEGORY_PREFIX = "category:";

    // 5 px squared: how far the mouse must move before a press becomes a drag.
    private static final int DRAG_THRESHOLD_SQ = 25;

    private final SpringLoadController springLoad = new SpringLoadController();

    private final WaypointStore store;
    private final Runnable onChange;

    // Closures that clear indicator state on each attached target. Run on every
    // mouseReleased so an aborted drag (ESC, cursor leaves the window) doesn't
    // leave a row stuck in a highlighted state.
    private final List<Runnable> clearActions = new CopyOnWriteArrayList<>();

    // The indicator that's currently visually active. Tracked so canImport on a new
    // target can clear the old one before lighting itself up.
    private DropIndicatable activeIndicator;

    public DragAndDropHandler(WaypointStore store, Runnable onChange)
    {
        this.store = store;
        this.onChange = onChange;
    }

    // Row is the drop target; drag only fires from dragHandle so the row body's click-to-expand
    // still works.
    public void attachWaypointRow(JComponent row, JComponent dragHandle,
        DropIndicatable indicatable, UUID waypointId, UUID categoryId)
    {
        row.setTransferHandler(new TransferHandler()
        {
            @Override public int getSourceActions(JComponent c) { return MOVE; }

            @Override protected Transferable createTransferable(JComponent c)
            {
                return new StringSelection(WAYPOINT_PREFIX + waypointId);
            }

            @Override public boolean canImport(TransferSupport s)
            {
                if (!s.isDataFlavorSupported(STR)) return false;
                String payload = readPayload(s.getTransferable());
                if (isSelfDrop(payload, TargetKind.WAYPOINT_ROW, waypointId))
                {
                    if (activeIndicator == indicatable)
                    {
                        indicatable.setDropIndicator(DropIndicatorMode.NONE);
                        activeIndicator = null;
                    }
                    return false;
                }
                return beginHover(indicatable, decideMode(payload, TargetKind.WAYPOINT_ROW), categoryId);
            }

            @Override public boolean importData(TransferSupport s)
            {
                String payload = read(s);
                if (payload == null) return false;
                if (payload.startsWith(WAYPOINT_PREFIX))
                {
                    UUID dragged = UUID.fromString(payload.substring(WAYPOINT_PREFIX.length()));
                    if (dragged.equals(waypointId)) return false;
                    Waypoint draggedW = store.getWaypointById(dragged);
                    if (draggedW == null) return false;
                    store.batch(() -> {
                        if (!draggedW.getCategoryId().equals(categoryId))
                        {
                            store.moveWaypointToCategory(dragged, categoryId);
                        }
                        moveBefore(categoryId, dragged, waypointId);
                    });
                    springLoad.resolveOnDrop(categoryId);
                    onChange.run();
                    return true;
                }
                return false;
            }
        });
        clearActions.add(() -> indicatable.setDropIndicator(DropIndicatorMode.NONE));
        // dragHandle is null when the row was constructed with dragDisabled (e.g. inside the
        // synthetic Pinned section, where rows can't be drag-reordered). Skip the drag-source
        // setup but leave the row's drop-target behavior intact.
        if (dragHandle != null)
        {
            DragGestureListener gesture = new DragGestureListener(row);
            dragHandle.addMouseListener(gesture);
            dragHandle.addMouseMotionListener(gesture);
        }
    }

    public void attachCategoryHeader(JComponent dragTarget, DropIndicatable indicatable,
        UUID categoryId, CategorySection section, JComponent snapshotComponent)
    {
        springLoad.register(categoryId, section);
        dragTarget.setTransferHandler(new TransferHandler()
        {
            @Override public int getSourceActions(JComponent c) { return MOVE; }

            @Override protected Transferable createTransferable(JComponent c)
            {
                return new StringSelection(CATEGORY_PREFIX + categoryId);
            }

            @Override public boolean canImport(TransferSupport s)
            {
                if (!s.isDataFlavorSupported(STR)) return false;
                String payload = readPayload(s.getTransferable());
                if (isSelfDrop(payload, TargetKind.CATEGORY_HEADER, categoryId))
                {
                    if (activeIndicator == indicatable)
                    {
                        indicatable.setDropIndicator(DropIndicatorMode.NONE);
                        activeIndicator = null;
                    }
                    springLoad.cancelExpand();
                    return false;
                }
                // Spring-load: hover a collapsed header with a waypoint payload schedules an auto-expand.
                boolean isWaypoint = payload != null && payload.startsWith(WAYPOINT_PREFIX);
                if (isWaypoint && section != null && section.isCollapsed())
                {
                    springLoad.scheduleExpand(section);
                }
                else
                {
                    springLoad.cancelExpand();
                }
                // Common hover tail (cannot use beginHover here: the schedule/cancel decision above must run first).
                springLoad.onHover(categoryId);
                onHoverEnter(indicatable, decideMode(payload, TargetKind.CATEGORY_HEADER));
                return true;
            }

            @Override public boolean importData(TransferSupport s)
            {
                String payload = read(s);
                if (payload == null) return false;
                if (payload.startsWith(WAYPOINT_PREFIX))
                {
                    UUID dragged = UUID.fromString(payload.substring(WAYPOINT_PREFIX.length()));
                    store.moveWaypointToCategory(dragged, categoryId);
                    springLoad.resolveOnDrop(categoryId);
                    onChange.run();
                    return true;
                }
                if (payload.startsWith(CATEGORY_PREFIX))
                {
                    UUID dragged = UUID.fromString(payload.substring(CATEGORY_PREFIX.length()));
                    if (dragged.equals(categoryId)) return false;
                    swapCategoryOrder(dragged, categoryId);
                    springLoad.onDragEnd();
                    onChange.run();
                    return true;
                }
                return false;
            }
        });
        clearActions.add(() -> indicatable.setDropIndicator(DropIndicatorMode.NONE));
        DragGestureListener gesture = new DragGestureListener(dragTarget, snapshotComponent);
        dragTarget.addMouseListener(gesture);
        dragTarget.addMouseMotionListener(gesture);
    }

    /**
     * Wires a tail-drop hit zone for a category. Drops here move (or reorder-to-end-within)
     * the dragged waypoint into {@code categoryId} via {@link WaypointStore#moveWaypointToCategory}
     * which assigns {@code sortOrder = max+1}, naturally appending.
     */
    public void attachTailZone(JComponent tail, DropIndicatable indicatable, UUID categoryId)
    {
        tail.setTransferHandler(new TransferHandler()
        {
            @Override public int getSourceActions(JComponent c) { return NONE; }

            @Override public boolean canImport(TransferSupport s)
            {
                if (!s.isDataFlavorSupported(STR)) return false;
                String payload = readPayload(s.getTransferable());
                if (!tailZoneAccepts(payload))
                {
                    if (activeIndicator == indicatable)
                    {
                        indicatable.setDropIndicator(DropIndicatorMode.NONE);
                        activeIndicator = null;
                    }
                    return false;
                }
                return beginHover(indicatable, DropIndicatorMode.BORDER_AND_TINT, categoryId);
            }

            @Override public boolean importData(TransferSupport s)
            {
                String payload = read(s);
                if (!tailZoneAccepts(payload)) return false;
                UUID dragged = UUID.fromString(payload.substring(WAYPOINT_PREFIX.length()));
                store.moveWaypointToCategory(dragged, categoryId);
                springLoad.resolveOnDrop(categoryId);
                onChange.run();
                return true;
            }
        });
        clearActions.add(() -> indicatable.setDropIndicator(DropIndicatorMode.NONE));
    }

    // Shared canImport tail: clear any pending spring-load, do hover bookkeeping for this
    // category, and light up this target's indicator. Returns true (canImport accepts).
    private boolean beginHover(DropIndicatable indicatable, DropIndicatorMode mode, UUID categoryId)
    {
        springLoad.cancelExpand();
        springLoad.onHover(categoryId);
        onHoverEnter(indicatable, mode);
        return true;
    }

    private final class DragGestureListener extends MouseAdapter
        implements MouseMotionListener
    {
        private final JComponent dragSource;
        private final JComponent snapshotSource; // what the ghost image paints (row, not the label)
        private Point pressPoint;
        private boolean dragStarted;

        DragGestureListener(JComponent dragSource) { this(dragSource, dragSource); }
        DragGestureListener(JComponent dragSource, JComponent snapshotSource)
        {
            this.dragSource = dragSource;
            this.snapshotSource = snapshotSource;
        }

        @Override public void mousePressed(MouseEvent e)
        {
            pressPoint = e.getPoint();
            dragStarted = false;
        }

        @Override public void mouseReleased(MouseEvent e)
        {
            pressPoint = null;
            dragStarted = false;
            springLoad.onDragEnd();
            clearAllIndicators();
        }

        @Override public void mouseDragged(MouseEvent e)
        {
            if (pressPoint == null || dragStarted) return;
            int dx = e.getX() - pressPoint.x;
            int dy = e.getY() - pressPoint.y;
            if (dx * dx + dy * dy >= DRAG_THRESHOLD_SQ)
            {
                dragStarted = true;
                TransferHandler th = dragSource.getTransferHandler();
                if (th != null)
                {
                    th.setDragImage(snapshotForDrag(snapshotSource));
                    th.setDragImageOffset(new Point(pressPoint));
                    th.exportAsDrag(dragSource, e, TransferHandler.MOVE);
                }
            }
        }

        @Override public void mouseMoved(MouseEvent e) { }
    }

    private static String read(TransferHandler.TransferSupport s)
    {
        try
        {
            return (String) s.getTransferable().getTransferData(STR);
        }
        catch (UnsupportedFlavorException | IOException e)
        {
            return null;
        }
    }

    // Called from canImport on every target the drag passes over. Clears the previous
    // active indicator (if it's a different target) and sets the new one.
    private void onHoverEnter(DropIndicatable indicatable, DropIndicatorMode mode)
    {
        if (activeIndicator != null && activeIndicator != indicatable)
        {
            activeIndicator.setDropIndicator(DropIndicatorMode.NONE);
        }
        indicatable.setDropIndicator(mode);
        activeIndicator = indicatable;
    }

    private void clearAllIndicators()
    {
        for (Runnable r : clearActions) r.run();
        activeIndicator = null;
    }

    private static String readPayload(Transferable t)
    {
        if (t == null) return null;
        try { return (String) t.getTransferData(STR); }
        catch (Exception e) { return null; }
    }

    private static boolean isSelfDrop(String payload, TargetKind kind, UUID selfId)
    {
        if (payload == null || selfId == null) return false;
        if (kind == TargetKind.WAYPOINT_ROW && payload.startsWith(WAYPOINT_PREFIX))
        {
            return payload.substring(WAYPOINT_PREFIX.length()).equals(selfId.toString());
        }
        if (kind == TargetKind.CATEGORY_HEADER && payload.startsWith(CATEGORY_PREFIX))
        {
            return payload.substring(CATEGORY_PREFIX.length()).equals(selfId.toString());
        }
        return false;
    }

    private void moveBefore(UUID categoryId, UUID dragged, UUID target)
    {
        List<UUID> order = new ArrayList<>();
        for (Waypoint w : store.getWaypointsInCategory(categoryId)) order.add(w.getId());
        List<UUID> moved = move(order, dragged, target);
        if (moved == null) return;
        store.reorderWithinCategory(categoryId, moved);
    }

    private void swapCategoryOrder(UUID dragged, UUID target)
    {
        List<UUID> order = new ArrayList<>();
        for (Category c : store.getCategoriesOrdered()) order.add(c.getId());
        List<UUID> moved = move(order, dragged, target);
        if (moved == null) return;
        store.reorderCategories(moved);
    }

    /** Which kind of component the drag is hovering over. */
    enum TargetKind { WAYPOINT_ROW, CATEGORY_HEADER }

    /**
     * Decides which indicator visual to apply for the (payload, target) combination.
     * Pure function: the per-target rule lives here and only here.
     */
    static DropIndicatorMode decideMode(String payload, TargetKind kind)
    {
        if (payload == null) return DropIndicatorMode.NONE;
        boolean isWaypoint = payload.startsWith(WAYPOINT_PREFIX);
        boolean isCategory = payload.startsWith(CATEGORY_PREFIX);
        if (kind == TargetKind.WAYPOINT_ROW)
        {
            return isWaypoint ? DropIndicatorMode.BORDER_AND_TINT : DropIndicatorMode.NONE;
        }
        // CATEGORY_HEADER
        if (isCategory) return DropIndicatorMode.BORDER_AND_TINT;
        if (isWaypoint) return DropIndicatorMode.TINT;
        return DropIndicatorMode.NONE;
    }

    /** Pure rule: tail zone accepts only waypoint payloads. */
    static boolean tailZoneAccepts(String payload)
    {
        return payload != null && payload.startsWith(WAYPOINT_PREFIX);
    }

    // Moves dragged to immediately before target. Returns null if either id is missing or
    // dragged == target (caller treats null as no-op).
    static List<UUID> move(List<UUID> order, UUID dragged, UUID target)
    {
        int from = order.indexOf(dragged);
        int to = order.indexOf(target);
        if (from < 0 || to < 0 || from == to) return null;
        List<UUID> out = new ArrayList<>(order);
        UUID m = out.remove(from);
        int insertAt = out.indexOf(target);
        if (insertAt < 0) return null;
        out.add(insertAt, m);
        return out;
    }

    private static BufferedImage snapshotForDrag(JComponent target)
    {
        int w = Math.max(1, target.getWidth());
        int h = Math.max(1, target.getHeight());
        BufferedImage img =
            new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();
        g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.60f));
        target.paint(g);
        g.dispose();
        return img;
    }
}

package com.waypointer.ui;

/**
 * Surface used by DragAndDropHandler to push indicator state onto a target component
 * during a drag. WaypointRow implements this directly; CategorySection supplies a lambda
 * that targets its header row panel.
 */
@FunctionalInterface
interface DropIndicatable
{
    void setDropIndicator(DropIndicatorMode mode);

    /** No-op default for wiring sites that don't have a real target yet. */
    DropIndicatable NO_OP = mode -> { };
}

package com.waypointer.ui;

/**
 * Visual state of a drag-and-drop target while a drag is hovering over it. NONE is the
 * resting state; TINT alone signals "this category will receive the dragged waypoint";
 * BORDER_AND_TINT signals "drop will insert before this row".
 */
enum DropIndicatorMode
{
    NONE, TINT, BORDER_AND_TINT
}

package com.waypointer.ui;

import java.awt.Color;
import javax.swing.BorderFactory;
import javax.swing.JComponent;
import javax.swing.border.Border;
import net.runelite.client.ui.ColorScheme;

/**
 * The shared visual vocabulary for drag-and-drop targets: a hover tint and a 2 px orange
 * top-accent border. Defined once here so the rows ({@link WaypointRow}), category headers,
 * and drop zones ({@link CategorySection}) cannot drift apart.
 */
final class DropIndicators
{
    private DropIndicators() {}

    /** Hover tint applied to a target the drag is currently over. */
    static final Color TINT_BG = ColorScheme.DARK_GRAY_HOVER_COLOR;

    /** The 2 px {@link ColorScheme#BRAND_ORANGE} top border, compounded over {@code resting}. */
    static Border topAccentOver(Border resting)
    {
        return BorderFactory.createCompoundBorder(
            BorderFactory.createMatteBorder(2, 0, 0, 0, ColorScheme.BRAND_ORANGE),
            resting == null ? BorderFactory.createEmptyBorder() : resting);
    }

    /**
     * Apply the standard three-state indicator to {@code c}, restoring {@code resting} /
     * {@code restingBg} on {@link DropIndicatorMode#NONE}. Repaints {@code c}; callers need not.
     */
    static void apply(JComponent c, DropIndicatorMode mode, Border resting, Color restingBg)
    {
        switch (mode)
        {
            case NONE:
                c.setBorder(resting);
                c.setBackground(restingBg);
                break;
            case TINT:
                c.setBackground(TINT_BG);
                break;
            case BORDER_AND_TINT:
                c.setBorder(topAccentOver(resting));
                c.setBackground(TINT_BG);
                break;
        }
        c.repaint();
    }
}

package com.waypointer.ui;

import java.awt.event.ActionEvent;
import java.awt.event.KeyEvent;
import javax.swing.AbstractAction;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.KeyStroke;

/**
 * Shared keyboard wiring for the inline editor panels: Enter on the name field triggers the
 * primary action, Escape anywhere in the panel cancels. Mirrors the bindings CaptureForm sets up
 * inline so the dev-tools and category editors don't each re-implement them. Enter is bound on the
 * single-line name field only, so editors with a multi-line description area keep normal newline
 * behaviour there.
 */
final class EditorKeyBindings
{
    private EditorKeyBindings()
    {
    }

    static void commitOnEnterCancelOnEscape(JPanel panel, JTextField commitField,
        JButton primary, JButton cancel)
    {
        commitField.getInputMap(JComponent.WHEN_FOCUSED)
            .put(KeyStroke.getKeyStroke(KeyEvent.VK_ENTER, 0), "editorCommit");
        commitField.getActionMap().put("editorCommit", new AbstractAction()
        {
            @Override public void actionPerformed(ActionEvent e) { primary.doClick(); }
        });

        panel.getInputMap(JComponent.WHEN_ANCESTOR_OF_FOCUSED_COMPONENT)
            .put(KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0), "editorCancel");
        panel.getActionMap().put("editorCancel", new AbstractAction()
        {
            @Override public void actionPerformed(ActionEvent e) { cancel.doClick(); }
        });
    }
}

package com.waypointer.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Font;
import java.awt.GridLayout;
import java.awt.Insets;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.Function;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;

// Generic tab strip: a horizontal row of clickable labels, one per enum constant supplied in
// `visible`. The active tab gets a BRAND_ORANGE matte underline; inactive tabs get a
// DARKER_GRAY_COLOR matte of equal thickness so the row height stays constant on swap.
// Custom-rolled instead of JTabbedPane to keep full styling control and avoid LAF surprises
// (these strips are constructed before RuneLiteLAF is installed).
abstract class EnumTabStrip<E extends Enum<E>> extends JPanel
{
    private final Map<E, JLabel> labels;
    private final Consumer<E> onSelect;
    private final Font font;
    private final int underlineThickness;
    private final Insets labelInsets;
    private E active;

    EnumTabStrip(Class<E> type, List<E> visible, E initialActive, Consumer<E> onSelect,
        Function<E, String> displayName, Font font, int underlineThickness, Insets labelInsets)
    {
        this.labels = new EnumMap<>(type);
        this.onSelect = onSelect;
        this.font = font;
        this.underlineThickness = underlineThickness;
        this.labelInsets = labelInsets;
        this.active = initialActive;

        setLayout(new GridLayout(1, visible.size(), 0, 0));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        for (E e : visible)
        {
            labels.put(e, buildTab(displayName.apply(e), e));
        }
        for (JLabel l : labels.values())
        {
            add(l);
        }
        applyStyles();
    }

    final E getActive() { return active; }

    final void setActive(E tab)
    {
        if (tab == active) return;
        active = tab;
        applyStyles();
    }

    // Test seam - lets strip tests grab a specific tab label to dispatch mouse events.
    final JLabel labelFor(E tab) { return labels.get(tab); }

    private JLabel buildTab(String text, E tab)
    {
        JLabel l = new JLabel(text, SwingConstants.CENTER);
        l.setFont(font);
        l.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        l.setOpaque(true);
        l.setBackground(ColorScheme.DARK_GRAY_COLOR);
        l.addMouseListener(new MouseAdapter()
        {
            @Override public void mouseClicked(MouseEvent e) { onSelect.accept(tab); }
        });
        return l;
    }

    private void applyStyles()
    {
        for (Map.Entry<E, JLabel> e : labels.entrySet())
        {
            JLabel l = e.getValue();
            boolean isActive = e.getKey() == active;
            l.setForeground(isActive ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
            Color underline = isActive ? ColorScheme.BRAND_ORANGE : ColorScheme.DARKER_GRAY_COLOR;
            l.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createMatteBorder(0, 0, underlineThickness, 0, underline),
                BorderFactory.createEmptyBorder(labelInsets.top, labelInsets.left,
                    labelInsets.bottom, labelInsets.right)));
        }
    }
}

package com.waypointer.ui;

import com.waypointer.codec.WaypointShareCodec;
import com.waypointer.model.Library;
import com.waypointer.service.LibrarySubsetBuilder;
import com.waypointer.service.WaypointStore;
import java.awt.BorderLayout;
import java.awt.Dialog;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Window;
import java.util.Set;
import java.util.UUID;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JDialog;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import net.runelite.client.ui.ColorScheme;

/**
 * Modal export dialog: tick any mix of categories / waypoints from the live library, then copy a
 * share code to the clipboard. Opens with everything checked, unless an initial waypoint selection
 * is supplied (issue #28 bulk export passes its selected ids to pre-check that subset). The copy
 * button stays disabled while the selection is empty.
 */
final class ExportPickerDialog extends JDialog
{
    private final WaypointStore store;
    private final WaypointShareCodec shareCodec;
    private final Toasts toasts;
    private final WaypointPickerModel model;
    private final WaypointTreePicker tree;
    private final JButton copyBtn = new JButton("Copy code");

    ExportPickerDialog(Window owner, WaypointStore store, WaypointShareCodec shareCodec,
        Toasts toasts, Set<UUID> initialWaypointIds)
    {
        super(owner, "Export waypoints", Dialog.ModalityType.APPLICATION_MODAL);
        this.store = store;
        this.shareCodec = shareCodec;
        this.toasts = toasts == null ? Toasts.NO_OP : toasts;

        this.model = new WaypointPickerModel(store.getLibrary());
        if (initialWaypointIds != null)
        {
            model.selectNone();
            for (UUID id : initialWaypointIds) model.setWaypointChecked(id, true);
        }
        this.tree = new WaypointTreePicker(model, this::updateButtons);

        JPanel content = Dialogs.applyDarkContentPane(this);
        Dialogs.bindEscape(this);

        content.add(buildSelectBar(), BorderLayout.NORTH);

        JScrollPane scroll = new JScrollPane(tree);
        scroll.setBorder(BorderFactory.createLineBorder(ColorScheme.LIGHT_GRAY_COLOR, 1));
        scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
        scroll.setPreferredSize(new Dimension(320, 360));
        content.add(scroll, BorderLayout.CENTER);

        content.add(buildFooter(), BorderLayout.SOUTH);

        updateButtons();
        getRootPane().setDefaultButton(copyBtn);
        Dialogs.finish(this, owner);
    }

    private JPanel buildSelectBar()
    {
        JPanel bar = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 0));
        bar.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JButton all = new JButton("Select all");
        JButton none = new JButton("Select none");
        Styles.secondaryButton(all);
        Styles.secondaryButton(none);
        all.addActionListener(e -> { model.selectAll(); tree.refreshAll(); updateButtons(); });
        none.addActionListener(e -> { model.selectNone(); tree.refreshAll(); updateButtons(); });
        bar.add(all);
        bar.add(none);
        return bar;
    }

    private JPanel buildFooter()
    {
        JPanel footer = new JPanel(new FlowLayout(FlowLayout.RIGHT));
        footer.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JButton cancel = new JButton("Cancel");
        Styles.secondaryButton(cancel);
        Styles.primaryButton(copyBtn);
        cancel.addActionListener(e -> dispose());
        copyBtn.addActionListener(e -> copyCode());
        footer.add(cancel);
        footer.add(copyBtn);
        return footer;
    }

    private void updateButtons()
    {
        boolean enabled = !model.isEmptySelection();
        copyBtn.setEnabled(enabled);
    }

    private Library buildSubset()
    {
        return LibrarySubsetBuilder.build(store.getLibrary(),
            model.getSelectedWaypointIds(), model.getSelectedCategoryIds());
    }

    private void copyCode()
    {
        Library subset = buildSubset();
        String code = shareCodec.encodeLibrary(subset);
        java.awt.Toolkit.getDefaultToolkit().getSystemClipboard()
            .setContents(new java.awt.datatransfer.StringSelection(code), null);
        toasts.show(String.format("Library code copied - %d waypoints.",
            subset.getWaypoints().size()));
        dispose();
    }
}

package com.waypointer.ui;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;

/**
 * Footer strip: a centered count line plus one static tip, appended as the last body child after
 * the vertical glue so on a short list the glue pins it to the bottom of the viewport and on a
 * long list it scrolls in after the last section. Height-capped like the banners so the body's
 * {@code BoxLayout(Y_AXIS)} does not stretch it. Never hidden -- renders in every state. With no
 * filter the count line shows the full library total and the non-empty category count; while a
 * search filter is active it switches to "N of M shown" plus the number of categories that match.
 */
final class FooterStrip extends JPanel
{
    // One static tip chosen once per instance (one plugin-enable). No timer, no rotation at
    // runtime. The index varies across restarts via the nanoTime seed. The tips are verified
    // against current features (export lives on the overflow menu).
    private static final String[] TIPS = {
        "Drag the dot-grip to reorder",
        "Click a row to edit it inline",
        "Open the ⋮ menu to import or export",
        "Pin a waypoint to keep it up top",
        "Use Select for bulk move and delete",
        "Right-click a waypoint for quick actions",
        "Search by name or category",
    };

    private final int tipIndex = Math.floorMod(System.nanoTime(), TIPS.length);
    private final JLabel label = new JLabel("", SwingConstants.CENTER);

    FooterStrip()
    {
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setAlignmentX(Component.LEFT_ALIGNMENT);
        setBorder(BorderFactory.createEmptyBorder(8, 10, 8, 10));
        add(label, BorderLayout.CENTER);
    }

    // Pure count-line formatter. Package-private so it is unit-testable without constructing
    // the Swing panel. Separator is U+00B7 (middle dot).
    static String countText(int waypoints, int categories)
    {
        return waypoints + (waypoints == 1 ? " waypoint" : " waypoints")
            + " · "
            + categories + (categories == 1 ? " category" : " categories");
    }

    // Pure filtered count-line formatter: shown-of-total plus the count of categories with
    // matches. Package-private for unit tests, like countText. Separator is U+00B7.
    static String countTextFiltered(int shown, int total, int categories)
    {
        return shown + " of " + total + " shown"
            + " · "
            + categories + (categories == 1 ? " category" : " categories");
    }

    /** Refresh the label from counts the caller already computed. {@code waypoints} is the full
     * library total; {@code categories} is non-empty categories only. */
    void refresh(int waypoints, int categories)
    {
        label.setText("<html><div style='text-align:center;'>"
            + "<span style='color:" + Styles.MUTED_HEX + ";'>" + countText(waypoints, categories) + "</span><br>"
            + "<span style='color:" + Styles.FAINT_HEX + ";font-style:italic;'>" + TIPS[tipIndex] + "</span>"
            + "</div></html>");
    }

    /** Refresh the label for the filtered state. {@code shown} is the count of waypoints
     * matching the active filter; {@code total} is the full library size; {@code categories}
     * is the number of categories that have at least one match. */
    void refreshFiltered(int shown, int total, int categories)
    {
        label.setText("<html><div style='text-align:center;'>"
            + "<span style='color:" + Styles.MUTED_HEX + ";'>" + countTextFiltered(shown, total, categories) + "</span><br>"
            + "<span style='color:" + Styles.FAINT_HEX + ";font-style:italic;'>" + TIPS[tipIndex] + "</span>"
            + "</div></html>");
    }

    // Cap height to preferred so the body's BoxLayout(Y_AXIS) does not stretch the footer.
    @Override public Dimension getMaximumSize()
    {
        return Styles.capHeight(this);
    }
}

package com.waypointer.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import javax.swing.Icon;

// Small drawn icons. The RuneScape fonts lack most symbol glyphs, and the fallback fonts Swing
// picks for them differ per machine, so the shapes the panel leans on are painted here.
final class Glyphs
{
    private Glyphs() {}

    enum Shape { CHEVRON_DOWN, CHEVRON_RIGHT, STAR, STAR_OUTLINE, PLUS, CHECK, CROSS, SEARCH, STOP, PLAY, BACK, MENU }

    static Icon of(Shape shape, Color color)
    {
        return of(shape, color, 14);
    }

    static Icon of(Shape shape, Color color, int size)
    {
        return new Icon()
        {
            @Override public int getIconWidth() { return size; }
            @Override public int getIconHeight() { return size; }

            @Override public void paintIcon(Component c, Graphics g, int x, int y)
            {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.translate(x + size / 2, y + size / 2);
                g2.setColor(color);
                paint(g2, shape);
                g2.dispose();
            }
        };
    }

    private static void paint(Graphics2D g, Shape shape)
    {
        switch (shape)
        {
            case CHEVRON_DOWN: triangle(g, -4, -2, 4, -2, 0, 3); break;
            case CHEVRON_RIGHT: triangle(g, -2, -4, 3, 0, -2, 4); break;
            case PLAY: triangle(g, -3, -5, 5, 0, -3, 5); break;
            case BACK: triangle(g, 3, -5, -5, 0, 3, 5); break;
            case STOP: g.fillRect(-4, -4, 8, 8); break;
            case MENU:
                for (int i = -1; i <= 1; i++) g.fillRect(-1, i * 4 - 1, 2, 2);
                break;
            case PLUS:
                g.fillRect(-4, -1, 9, 2);
                g.fillRect(-1, -4, 2, 9);
                break;
            case CHECK:
                g.setStroke(new BasicStroke(1.6f));
                g.drawLine(-4, 0, -1, 3);
                g.drawLine(-1, 3, 4, -3);
                break;
            case CROSS:
                g.setStroke(new BasicStroke(1.4f));
                g.drawLine(-3, -3, 3, 3);
                g.drawLine(-3, 3, 3, -3);
                break;
            case SEARCH:
                g.setStroke(new BasicStroke(1.5f));
                g.drawOval(-5, -5, 8, 8);
                g.drawLine(2, 2, 5, 5);
                break;
            default:
                Path2D.Double p = new Path2D.Double();
                for (int i = 0; i < 10; i++)
                {
                    double r = i % 2 == 0 ? 6 : 2.6;
                    double a = -Math.PI / 2 + i * Math.PI / 5;
                    if (i == 0) p.moveTo(r * Math.cos(a), r * Math.sin(a));
                    else p.lineTo(r * Math.cos(a), r * Math.sin(a));
                }
                p.closePath();
                g.setStroke(new BasicStroke(1.1f));
                if (shape == Shape.STAR) g.fill(p); else g.draw(p);
                break;
        }
    }

    private static void triangle(Graphics2D g, double... pts)
    {
        Path2D.Double t = new Path2D.Double();
        t.moveTo(pts[0], pts[1]);
        t.lineTo(pts[2], pts[3]);
        t.lineTo(pts[4], pts[5]);
        t.closePath();
        g.fill(t);
    }
}

package com.waypointer.ui;

import java.awt.GraphicsEnvironment;
import java.awt.Point;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JWindow;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Immediate-hover hint: a dark-themed borderless {@link JWindow} with a single styled
 * {@link JLabel} that appears the instant the cursor enters an attached component, four
 * pixels above it. The house style for affordance hints across the panel, replacing the
 * native (delayed, light-on-dark) Swing tooltip.
 *
 * <p>Most call sites use the process-shared instance via {@link #shared()} -- one reused
 * window for the whole plugin UI, never more than one visible at a time. The instance API
 * (constructor + {@link #attach} + {@link #dispose}) is retained for unit tests.
 *
 * <p>Headless safety: tests run without a display, so visibility is tracked in
 * {@code visibleIntent} and {@link JWindow#setVisible} calls are skipped in headless
 * environments. Production code reads visibility through the window; tests read it
 * through {@link #visibleIntentForTest()}.
 */
final class HoverHint
{
	private static HoverHint shared;

	/**
	 * Process-shared hint. Lazily created on first use and kept for the JVM session: a single
	 * invisible window is cheap and is reused across every panel rebuild and plugin
	 * enable/disable cycle, so nothing accumulates. {@code attach} only ever adds a listener to
	 * the (freshly built) target component, so re-enabling the plugin re-attaches new components
	 * to the same window without stacking.
	 * Do not call {@link #dispose()} on the shared instance -- {@code disposed} is sticky and would permanently silence all hints for the session.
	 */
	static HoverHint shared()
	{
		if (shared == null) shared = new HoverHint();
		return shared;
	}

	private final JWindow window;
	private final JLabel label;
	private boolean visibleIntent;
	private boolean disposed;

	HoverHint()
	{
		this.label = new JLabel("");
		this.label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		this.label.setFont(FontManager.getRunescapeSmallFont());
		this.label.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.LIGHT_GRAY_COLOR, 1),
			BorderFactory.createEmptyBorder(4, 6, 4, 6)));
		this.label.setOpaque(true);
		this.label.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		if (displayAvailable())
		{
			this.window = new JWindow();
			this.window.setFocusableWindowState(false);
			this.window.getContentPane().add(label);
			this.window.pack();
		}
		else
		{
			this.window = null;
		}
	}

	boolean visibleIntentForTest() { return visibleIntent; }
	String labelTextForTest() { return label.getText(); }

	private static boolean displayAvailable()
	{
		return !GraphicsEnvironment.isHeadless();
	}

	/**
	 * Attach this hint to {@code target}. While the cursor is inside the target, the hint shows
	 * {@code textSupplier.get()} four pixels above it, horizontally centred. The supplier is
	 * re-read on every enter so the text follows late updates (e.g. a button changing meaning).
	 *
	 * <p>Attach is single-use per target component: calling it twice on the same target registers
	 * two listeners which would race on every hover. Callers rebuild their components from scratch
	 * on every panel rebuild, so re-attaching is naturally avoided.
	 *
	 * <p>Attach is a no-op after {@link #dispose()}.
	 */
	void attach(JComponent target, Supplier<String> textSupplier)
	{
		target.addMouseListener(new MouseAdapter()
		{
			@Override public void mouseEntered(MouseEvent e)
			{
				if (disposed) return;
				String text = textSupplier.get();
				label.setText(text == null ? "" : text);
				visibleIntent = true;
				if (window == null) return;
				window.pack();
				positionAbove(target);
				window.setVisible(true);
			}

			@Override public void mouseExited(MouseEvent e)
			{
				if (disposed) return;
				visibleIntent = false;
				if (window != null) window.setVisible(false);
			}
		});
	}

	private void positionAbove(JComponent target)
	{
		if (window == null) return;
		if (!target.isShowing()) return;
		Point onScreen = target.getLocationOnScreen();
		int gap = 4;
		int x = onScreen.x + (target.getWidth() - window.getWidth()) / 2;
		int y = onScreen.y - window.getHeight() - gap;
		window.setLocation(x, y);
	}

	/**
	 * Releases the hint's {@link JWindow}. Subsequent {@link #attach} calls still register
	 * listeners but those listeners short-circuit because {@code disposed} is sticky. Safe to
	 * call multiple times.
	 */
	void dispose()
	{
		if (disposed) return;
		disposed = true;
		visibleIntent = false;
		if (window != null) window.dispose();
	}
}

