    private JButton nextBtn;
    private JLabel pageLabel;

    public IconPickerDialog(Window owner, SpriteManager spriteManager, IconCatalog catalog,
        Integer currentIconId, Consumer<Integer> onSelect)
    {
        super(owner, "Pick icon", ModalityType.APPLICATION_MODAL);
        this.spriteManager = spriteManager;
        this.onSelect = onSelect;
        this.currentIconId = currentIconId;
        this.categories = buildCategoryViews(catalog);

        // Find the category that currently owns the active icon, if any.
        this.currentCategoryIdx = findCategoryFor(currentIconId);
        recomputePagination();

        setResizable(false);

        JPanel root = Dialogs.applyDarkContentPane(this, 0, 6);

        JLabel title = new JLabel("Choose an icon", SwingConstants.LEFT);
        title.setForeground(Color.WHITE);
        root.add(title, BorderLayout.NORTH);

        // Center stack: category combo + None row (NORTH), grid (CENTER), pagination (SOUTH).
        JPanel center = new JPanel(new BorderLayout(0, 6));
        center.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel topStack = new JPanel(new BorderLayout(0, 6));
        topStack.setBackground(ColorScheme.DARK_GRAY_COLOR);
        topStack.add(buildCategoryRow(), BorderLayout.NORTH);
        JPanel noneRow = new JPanel(new BorderLayout());
        noneRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        noneRow.add(buildNoneCell(currentIconId == null), BorderLayout.CENTER);
        topStack.add(noneRow, BorderLayout.SOUTH);
        center.add(topStack, BorderLayout.NORTH);

        JPanel grid = new JPanel(new GridLayout(GRID_ROWS, GRID_COLS, 4, 4));
        grid.setBackground(ColorScheme.DARK_GRAY_COLOR);
        for (int i = 0; i < PAGE_SIZE; i++)
        {
            JLabel cell = buildIconCell();
            cellLabels.add(cell);
            grid.add(cell);
        }
        center.add(grid, BorderLayout.CENTER);

        center.add(buildPaginationFooter(), BorderLayout.SOUTH);

        root.add(center, BorderLayout.CENTER);

        Dialogs.bindEscape(this);

        renderPage(currentPage);

        Dialogs.finish(this, owner);
    }

    private void recomputePagination()
    {
        List<Integer> ids = currentCategoryIds();
        this.totalPages = Math.max(1, (ids.size() + PAGE_SIZE - 1) / PAGE_SIZE);
        this.currentPage = computeInitialPage(currentIconId, ids, PAGE_SIZE);
    }

    private List<Integer> currentCategoryIds()
    {
        if (categories.isEmpty()) return Collections.emptyList();
        return categories.get(currentCategoryIdx).ids;
    }

    private int findCategoryFor(Integer iconId)
    {
        if (iconId == null) return 0;
        for (int i = 0; i < categories.size(); i++)
        {
            if (categories.get(i).ids.contains(iconId)) return i;
        }
        return 0;
    }

    static int computeInitialPage(Integer currentIconId, List<Integer> sortedIds, int pageSize)
    {
        if (currentIconId == null) return 0;
        int idx = Collections.binarySearch(sortedIds, currentIconId);
        if (idx < 0) return 0;
        return idx / pageSize;
    }

    private JComponent buildCategoryRow()
    {
        JPanel row = new JPanel(new BorderLayout(6, 0));
        row.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JLabel label = new JLabel("Category:");
        label.setForeground(Color.LIGHT_GRAY);
        row.add(label, BorderLayout.WEST);

        String[] names = new String[categories.size()];
        for (int i = 0; i < categories.size(); i++) names[i] = categories.get(i).label;
        categoryCombo = new JComboBox<>(names);
        categoryCombo.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        categoryCombo.setForeground(Color.WHITE);
        if (!categories.isEmpty()) categoryCombo.setSelectedIndex(currentCategoryIdx);
        categoryCombo.addActionListener(e -> {
            int sel = categoryCombo.getSelectedIndex();
            if (sel < 0 || sel == currentCategoryIdx) return;
            currentCategoryIdx = sel;
            // Start at page 0 on manual category switch; finding the current icon in the
            // newly-selected list rarely matches user intent.
            currentPage = 0;
            totalPages = Math.max(1, (currentCategoryIds().size() + PAGE_SIZE - 1) / PAGE_SIZE);
            renderPage(0);
        });
        row.add(categoryCombo, BorderLayout.CENTER);
        return row;
    }

    private JPanel buildPaginationFooter()
    {
        JPanel footer = new JPanel(new BorderLayout(6, 0));
        footer.setBackground(ColorScheme.DARK_GRAY_COLOR);

        prevBtn = new JButton("< Prev");
        Styles.secondaryButton(prevBtn);
        prevBtn.addActionListener(e -> {
            if (currentPage > 0) renderPage(currentPage - 1);
        });

        nextBtn = new JButton("Next >");
        Styles.secondaryButton(nextBtn);
        nextBtn.addActionListener(e -> {
            if (currentPage < totalPages - 1) renderPage(currentPage + 1);
        });

        pageLabel = new JLabel("", SwingConstants.CENTER);
        pageLabel.setForeground(Color.LIGHT_GRAY);

        footer.add(prevBtn, BorderLayout.WEST);
        footer.add(pageLabel, BorderLayout.CENTER);
        footer.add(nextBtn, BorderLayout.EAST);
        return footer;
    }

    private void renderPage(int page)
    {
        currentPage = page;
        List<Integer> ids = currentCategoryIds();
        int start = page * PAGE_SIZE;
        int end = Math.min(start + PAGE_SIZE, ids.size());

        for (int i = 0; i < PAGE_SIZE; i++)
        {
            JLabel cell = cellLabels.get(i);
            for (java.awt.event.MouseListener ml : cell.getMouseListeners())
            {
                cell.removeMouseListener(ml);
            }
            cell.setIcon(null);

            int globalIdx = start + i;
            if (globalIdx >= end)
            {
                cell.setVisible(false);
                cell.setToolTipText(null);
                styleCell(cell, false);
                continue;
            }

            cell.setVisible(true);
            final int spriteId = ids.get(globalIdx);
            boolean selected = currentIconId != null && currentIconId == spriteId;
            cell.setToolTipText("Sprite " + spriteId);
            styleCell(cell, selected);

            spriteManager.getSpriteAsync(spriteId, 0, img -> {
                if (img == null) return;
                SwingUtilities.invokeLater(() -> {
                    if (("Sprite " + spriteId).equals(cell.getToolTipText()))
                    {
                        cell.setIcon(new ImageIcon(img));
                        cell.revalidate();
                        cell.repaint();
                    }
                });
            });

            final boolean cellSelected = selected;
            cell.addMouseListener(new MouseAdapter() {
                @Override public void mouseClicked(MouseEvent e)
                {
                    onSelect.accept(spriteId);
                    dispose();
                }
                @Override public void mouseEntered(MouseEvent e)
                {
                    if (!cellSelected) hover(cell, true);
                }
                @Override public void mouseExited(MouseEvent e)
                {
                    if (!cellSelected) hover(cell, false);
                }
            });
        }

        if (prevBtn != null) prevBtn.setEnabled(currentPage > 0);
        if (nextBtn != null) nextBtn.setEnabled(currentPage < totalPages - 1);
        if (pageLabel != null)
        {
            pageLabel.setText(String.format("Page %d of %d (%d icons)",
                currentPage + 1, totalPages, ids.size()));
        }

        revalidate();
        repaint();
    }

    private JComponent buildNoneCell(boolean selected)
    {
        JLabel cell = new JLabel("None", SwingConstants.CENTER);
        cell.setOpaque(true);
        cell.setForeground(Color.LIGHT_GRAY);
        cell.setPreferredSize(new Dimension(0, 28));
        cell.setToolTipText("No icon");
        styleCell(cell, selected);
        cell.addMouseListener(new MouseAdapter() {
            @Override public void mouseClicked(MouseEvent e)
            {
                onSelect.accept(null);
                dispose();
            }
            @Override public void mouseEntered(MouseEvent e) { if (!selected) hover(cell, true); }
            @Override public void mouseExited(MouseEvent e) { if (!selected) hover(cell, false); }
        });
        return cell;
    }

    private JLabel buildIconCell()
    {
        JLabel cell = new JLabel("", SwingConstants.CENTER);
        cell.setOpaque(true);
        cell.setPreferredSize(new Dimension(28, 28));
        styleCell(cell, false);
        return cell;
    }

    private static void styleCell(Component c, boolean selected)
    {
        c.setBackground(selected ? ColorScheme.BRAND_ORANGE.darker() : ColorScheme.DARKER_GRAY_COLOR);
        if (c instanceof JComponent)
        {
            ((JComponent) c).setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(selected
                    ? ColorScheme.BRAND_ORANGE
                    : ColorScheme.DARK_GRAY_COLOR.darker(), 1),
                BorderFactory.createEmptyBorder(2, 2, 2, 2)));
        }
        c.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
    }

    private static void hover(JComponent c, boolean hovering)
    {
        c.setBackground(hovering
            ? ColorScheme.DARKER_GRAY_HOVER_COLOR
            : ColorScheme.DARKER_GRAY_COLOR);
    }

    private static List<CategoryView> buildCategoryViews(IconCatalog catalog)
    {
        List<CategoryView> out = new ArrayList<>();
        if (catalog != null)
        {
            for (IconCatalog.Category c : catalog.getCategories())
            {
                if (c.getSpriteIds().isEmpty()) continue;
                out.add(new CategoryView(
                    c.getName() + " (" + c.getSpriteIds().size() + ")",
                    c.getSpriteIds()));
            }
        }
        // If the bundled catalog is missing or malformed the picker simply shows no
        // categories; "None" stays selectable. This only happens with a corrupt jar.
        return out;
    }

    private static final class CategoryView
    {
        final String label;
        final List<Integer> ids;
        CategoryView(String label, List<Integer> ids) { this.label = label; this.ids = ids; }
    }
}

package com.waypointer.ui;

import com.waypointer.service.PresetImportResolver.Choice;
import com.waypointer.service.PresetImportResolver.PendingConflict;
import java.awt.BorderLayout;
import java.awt.FlowLayout;
import java.awt.Window;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

public final class ImportConflictDialog
{
    public static final class Result
    {
        public final Choice choice;
        public final boolean applyToAll;
        public Result(Choice c, boolean a) { this.choice = c; this.applyToAll = a; }
    }

    public static Result prompt(Window owner, PendingConflict c)
    {
        Result[] out = { new Result(Choice.SKIP, false) };
        JDialog d = new JDialog(owner, "Conflict in " + c.category, JDialog.ModalityType.APPLICATION_MODAL);
        Dialogs.applyDarkContentPane(d);
        Dialogs.bindEscape(d);

        JLabel msg = new JLabel("'" + c.imported.getName() + "' already exists.");
        msg.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        d.add(msg, BorderLayout.NORTH);

        JCheckBox applyAll = new JCheckBox("Apply to all conflicts");
        applyAll.setBackground(ColorScheme.DARK_GRAY_COLOR);
        applyAll.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        d.add(applyAll, BorderLayout.CENTER);

        JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 6, 0));
        buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JButton keep = new JButton("Keep existing");
        Styles.secondaryButton(keep);
        JButton repl = new JButton("Replace with imported");
        Styles.secondaryButton(repl);
        JButton skip = new JButton("Skip");
        Styles.secondaryButton(skip);
        keep.addActionListener(e -> { out[0] = new Result(Choice.KEEP_EXISTING, applyAll.isSelected()); d.dispose(); });
        repl.addActionListener(e -> { out[0] = new Result(Choice.REPLACE, applyAll.isSelected()); d.dispose(); });
        skip.addActionListener(e -> { out[0] = new Result(Choice.SKIP, applyAll.isSelected()); d.dispose(); });
        buttons.add(keep);
        buttons.add(repl);
        buttons.add(skip);
        d.add(buttons, BorderLayout.SOUTH);

        Dialogs.finish(d, owner);
        d.setVisible(true);
        return out[0];
    }
}

package com.waypointer.ui;

import com.waypointer.codec.DecodeReport;
import com.waypointer.codec.ReadableImport;
import com.waypointer.codec.WaypointShareCodec;
import com.waypointer.model.Library;
import com.waypointer.service.LibrarySubsetBuilder;
import com.waypointer.service.WaypointStore;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dialog;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Window;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import net.runelite.client.ui.ColorScheme;

/**
 * Modal import dialog. A source row at the top loads an incoming library from a pasted share code
 * ({@code WP1:} / {@code WPL1:}); the tree below then lets the recipient pick which categories /
 * waypoints to merge. {@code Import selected} stays disabled until a source is loaded and the
 * selection is non-empty. Decode/populate/import are package-private so they can be tested without
 * driving modal Swing.
 */
final class ImportPickerDialog extends JDialog
{
    private static final String BAD_CODE_MESSAGE =
        "Not a readable share code (expected WP1: or WPL1:).";

    private final WaypointStore store;
    private final WaypointShareCodec shareCodec;
    private final ReadableImport readableImport;
    private final Toasts toasts;

    private final JTextArea codeArea = new JTextArea(3, 32);
    private final JPanel treeHolder = new JPanel(new BorderLayout());
    private final JButton importBtn = new JButton("Import selected");
    private final JLabel errorLabel = Styles.errorLabel();

    private Library incoming;            // null until a source loads
    private WaypointPickerModel model;   // null until a source loads

    ImportPickerDialog(Window owner, WaypointStore store, WaypointShareCodec shareCodec,
        ReadableImport readableImport, Toasts toasts)
    {
        super(owner, "Import waypoints", Dialog.ModalityType.APPLICATION_MODAL);
        this.store = store;
        this.shareCodec = shareCodec;
        this.readableImport = readableImport;
        this.toasts = toasts == null ? Toasts.NO_OP : toasts;

        JPanel content = Dialogs.applyDarkContentPane(this);
        Dialogs.bindEscape(this);

        content.add(buildSourceRow(), BorderLayout.NORTH);

        treeHolder.setBackground(ColorScheme.DARK_GRAY_COLOR);
        treeHolder.setPreferredSize(new Dimension(320, 320));
        content.add(treeHolder, BorderLayout.CENTER);

        content.add(buildFooter(), BorderLayout.SOUTH);

        updateImportButton();
        getRootPane().setDefaultButton(importBtn);
        Dialogs.finish(this, owner);
    }

    private JPanel buildSourceRow()
    {
        JPanel wrap = new JPanel(new BorderLayout(4, 4));
        wrap.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JLabel prompt = new JLabel("Paste a share code or a list of coordinates:");
        prompt.setToolTipText("<html>One per line, for example: Shipwreck, 2301, 3690<br>"
            + "A line such as # Category sets the category for the lines after it.</html>");
        prompt.setForeground(Color.WHITE);
        wrap.add(prompt, BorderLayout.NORTH);

        Styles.textArea(codeArea);
        JScrollPane codeScroll = new JScrollPane(codeArea);
        codeScroll.setBorder(BorderFactory.createLineBorder(ColorScheme.LIGHT_GRAY_COLOR, 1));
        wrap.add(codeScroll, BorderLayout.CENTER);

        JPanel buttons = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 0));
        buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JButton loadCode = new JButton("Load code");
        Styles.secondaryButton(loadCode);
        loadCode.addActionListener(e -> onLoadCode());
        buttons.add(loadCode);
        buttons.add(errorLabel);
        wrap.add(buttons, BorderLayout.SOUTH);
        return wrap;
    }

    private JPanel buildFooter()
    {
        JPanel footer = new JPanel(new FlowLayout(FlowLayout.RIGHT));
        footer.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JButton cancel = new JButton("Cancel");
        Styles.secondaryButton(cancel);
        Styles.primaryButton(importBtn);
        cancel.addActionListener(e -> dispose());
        importBtn.addActionListener(e -> onImport());
        footer.add(cancel);
        footer.add(importBtn);
        return footer;
    }

    // ---- package-private seams (no dialogs popped; used by handlers and by tests) ----

    Library decodeCodeOrNull(String text)
    {
        DecodeReport r = decodeReportOrNull(text);
        return r == null ? null : r.library;
    }

    DecodeReport decodeReportOrNull(String text)
    {
        try { return shareCodec.decodeLibraryWithReport(text); }
        catch (RuntimeException ex) { return null; }
    }

    /** Load-time notice when a pasted code had unreadable entries; null when nothing was dropped. */
    static String loadNoticeOrNull(DecodeReport report)
    {
        if (report == null || report.totalDropped() == 0) return null;
        return String.format("Loaded %d waypoints, %d categories; %d invalid entries skipped.",
            report.library.getWaypoints().size(), report.library.getCategories().size(),
            report.totalDropped());
    }

    /** Load-time notice for pasted entries that were already saved; null when there are none. */
    static String alreadyPresentNoticeOrNull(int alreadyPresent)
    {
        if (alreadyPresent <= 0) return null;
        return alreadyPresent + " already in your library, skipped.";
    }

    /** Import summary: base counts, plus a duplicates clause only when some were skipped. */
    static String importSummary(WaypointStore.ImportResult r)
    {
        String summary = String.format("Imported %d waypoints, %d categories.",
            r.waypointsAdded, r.categoriesAdded);
        if (r.waypointsSkipped > 0)
        {
            summary += String.format(" Skipped %d already in your library.", r.waypointsSkipped);
        }
        return summary;
    }

    void populate(Library loaded)
    {
        this.incoming = loaded;
        this.model = new WaypointPickerModel(loaded);
        WaypointTreePicker tree = new WaypointTreePicker(model, this::updateImportButton);
        JScrollPane scroll = new JScrollPane(tree);
        scroll.setBorder(BorderFactory.createLineBorder(ColorScheme.LIGHT_GRAY_COLOR, 1));
        scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
        treeHolder.removeAll();
        treeHolder.add(scroll, BorderLayout.CENTER);
        treeHolder.revalidate();
        treeHolder.repaint();
        updateImportButton();
    }

    boolean hasLoadedSource() { return model != null; }

    WaypointStore.ImportResult importSelected()
    {
        if (model == null || incoming == null) return null;
        Library subset = LibrarySubsetBuilder.build(incoming,
            model.getSelectedWaypointIds(), model.getSelectedCategoryIds());
        return store.importMerge(subset);
    }

    // ---- handlers ----

    private void onLoadCode()
    {
        loadCode(codeArea.getText());
    }

    /** Package-private so a test can drive load without popping any dialog. */
    void loadCode(String text)
    {
        if (!ReadableImport.isShareCode(text))
        {
            loadList(text);
            return;
        }
        DecodeReport report = decodeReportOrNull(text);
        if (report == null)
        {
            showError(BAD_CODE_MESSAGE);
            return;
        }
        clearError();
        populate(report.library);
        String notice = loadNoticeOrNull(report);
        if (notice != null) toasts.show(notice);
    }

    private void loadList(String text)
    {
        ReadableImport.Result result;
        try
        {
            result = readableImport.parse(text, store.getLibrary());
        }
        catch (ReadableImport.MalformedListException ex)
        {
            // One token with no spaces or line breaks is most likely a mistyped or cut-off code.
            String trimmed = text == null ? "" : text.trim();
            boolean oneToken = !trimmed.isEmpty() && trimmed.charAt(0) != '['
                && trimmed.chars().noneMatch(Character::isWhitespace);
            showError(oneToken ? BAD_CODE_MESSAGE : ex.getMessage());
            return;
        }
        clearError();
        populate(result.library);
        String notice = alreadyPresentNoticeOrNull(result.alreadyPresent);
        if (notice != null) toasts.show(notice);
    }

    private void showError(String msg)
    {
        errorLabel.setText(msg);
        errorLabel.setVisible(true);
        errorLabel.getParent().revalidate();
        errorLabel.getParent().repaint();
        codeArea.requestFocusInWindow();
    }

    private void clearError()
    {
        errorLabel.setText(" ");
        errorLabel.setVisible(false);
    }

    String getErrorText() { return errorLabel.getText(); }

    boolean isErrorVisible() { return errorLabel.isVisible(); }

    private void onImport()
    {
        WaypointStore.ImportResult r = importSelected();
        if (r != null)
        {
            toasts.show(importSummary(r));
        }
        dispose();
    }

    private void updateImportButton()
    {
        importBtn.setEnabled(model != null && !model.isEmptySelection());
    }
}

package com.waypointer.ui;

import com.waypointer.codec.CoordinateText;
import com.waypointer.model.Category;
import com.waypointer.model.Waypoint;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.service.IconCatalog;
import com.waypointer.service.WaypointCapture;
import com.waypointer.service.WaypointStore;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.awt.Window;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.UUID;
import javax.swing.BorderFactory;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;

// Form shown when a WaypointRow is expanded. Name and notes edits are deferred: the user
// types into local Swing fields, and on focus loss (or panel removal) the pending text is
// committed. This avoids the keystroke -> store-update -> panel-rebuild -> field-recreated
// -> cursor-lost loop the older synchronous variant had.
public class InlineEditPanel extends JPanel
{
    private final WaypointStore store;
    private final UUID waypointId;
    private final Toasts toasts;

    private final JTextField nameField;
    private final JTextArea notesArea;
    private final JComboBox<CategoryComboItem> categoryCombo;
    private final JTextField coordsField;
    private boolean nameDirty = false;
    private boolean notesDirty = false;
    private boolean categoryDirty = false;
    private boolean coordsDirty = false;
    private boolean settingCoords = false;

    public InlineEditPanel(Waypoint w, WaypointStore store, WaypointCapture capture,
        SpriteManager spriteManager, IconCatalog iconCatalog, Toasts toasts,
        Runnable onClose, Runnable onShowOnMap)
    {
        this.store = store;
        this.waypointId = w.getId();
        this.toasts = toasts;
        setLayout(new GridBagLayout());
        setBorder(BorderFactory.createEmptyBorder(8, 12, 8, 12));
        setOpaque(false);
        GridBagConstraints g = new GridBagConstraints();
        g.fill = GridBagConstraints.HORIZONTAL;
        g.insets = new Insets(2, 2, 2, 2);

        // Top-right close affordance. Spans both columns so the X anchors to the panel edge.
        if (onClose != null)
        {
            g.gridx = 0; g.gridy = 0; g.gridwidth = 2; g.weightx = 1;
            g.anchor = GridBagConstraints.EAST; g.fill = GridBagConstraints.NONE;
            JLabel closeBtn = new JLabel("✕"); // U+2715 multiplication X
            closeBtn.setForeground(Color.LIGHT_GRAY);
            closeBtn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            closeBtn.setToolTipText("Close");
            closeBtn.getAccessibleContext().setAccessibleName("Close editor");
            closeBtn.addMouseListener(new MouseAdapter()
            {
                @Override public void mouseClicked(MouseEvent e)
                {
                    flushPending();
                    onClose.run();
                }
            });
            add(closeBtn, g);
            g.gridwidth = 1; g.anchor = GridBagConstraints.CENTER; g.fill = GridBagConstraints.HORIZONTAL;
        }

        g.gridx = 0; g.gridy = 1; g.weightx = 0;
        add(Styles.fieldLabel("Name"), g);
        nameField = new JTextField(w.getName());
        Styles.textField(nameField);
        nameField.getDocument().addDocumentListener(Styles.documentListener(() -> nameDirty = true));
        nameField.addFocusListener(new FocusAdapter()
        {
            @Override public void focusLost(FocusEvent e) { flushName(); }
        });
        g.gridx = 1; g.weightx = 1; add(nameField, g);

        g.gridx = 0; g.gridy++; g.weightx = 0; add(Styles.fieldLabel("Category"), g);
        categoryCombo = new JComboBox<>();
        Styles.combo(categoryCombo);
        for (Category c : store.getCategoriesOrdered()) categoryCombo.addItem(new CategoryComboItem(c));
        for (int i = 0; i < categoryCombo.getItemCount(); i++)
            if (categoryCombo.getItemAt(i).id().equals(w.getCategoryId())) categoryCombo.setSelectedIndex(i);
        // Deferred commit: track changes here, apply on focus loss / detach. An immediate
        // moveWaypointToCategory on every action would fire for any stray click or scroll-wheel
        // tick over the combo, with no way to undo without manually moving the row back.
        categoryCombo.addActionListener(e -> categoryDirty = true);
        categoryCombo.addFocusListener(new FocusAdapter()
        {
            @Override public void focusLost(FocusEvent e) { flushCategory(); }
        });
        g.gridx = 1; g.weightx = 1; add(categoryCombo, g);

        g.gridx = 0; g.gridy++; g.weightx = 0; add(Styles.fieldLabel("Notes"), g);
        notesArea = new JTextArea(w.getNotes(), 3, 12);
        notesArea.setLineWrap(true);
        notesArea.setWrapStyleWord(true);
        Styles.textArea(notesArea);
        notesArea.getDocument().addDocumentListener(Styles.documentListener(() -> notesDirty = true));
        notesArea.addFocusListener(new FocusAdapter()
        {
            @Override public void focusLost(FocusEvent e) { flushNotes(); }
        });
        JScrollPane notesScroll = new JScrollPane(notesArea);
        notesScroll.setBorder(null);
        notesScroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
        // Pin the notes pane to ~3 visible rows. The JTextArea(rows=3) hint flows up through
        // getPreferredScrollableViewportSize, but inside the outer body's JScrollPane it ends
        // up collapsing to a single visible row; setting an explicit preferred + minimum
        // height keeps the field at its intended size regardless of the surrounding chain.
        int rowH = notesArea.getFontMetrics(notesArea.getFont()).getHeight();
        Dimension notesPref = new Dimension(0, rowH * 3 + 6);
        notesScroll.setPreferredSize(notesPref);
        notesScroll.setMinimumSize(notesPref);
        g.gridx = 1; g.weightx = 1; add(notesScroll, g);

        g.gridx = 0; g.gridy++; g.weightx = 0; add(Styles.fieldLabel("Coords"), g);
        coordsField = new JTextField(CoordinateText.format(w.getPackedWorldPoint()));
        Styles.textField(coordsField);
        coordsField.getAccessibleContext().setAccessibleName("Coordinates");
        coordsField.getDocument().addDocumentListener(Styles.documentListener(() ->
        {
            if (!settingCoords) coordsDirty = true;
        }));
        coordsField.addFocusListener(new FocusAdapter()
        {
            @Override public void focusLost(FocusEvent e) { flushCoords(); }
        });
        g.gridx = 1; g.weightx = 1; add(coordsField, g);

        g.gridx = 0; g.gridy++; g.weightx = 0; add(Styles.fieldLabel("Tile"), g);
        JLabel showOnMap = Styles.link("Show on world map", ColorScheme.BRAND_ORANGE,
            onShowOnMap == null ? () -> {} : onShowOnMap);
        g.gridx = 1; g.weightx = 1; add(showOnMap, g);

        // Footer: thin divider followed by a single FlowLayout row of links separated by ·
        g.gridx = 0; g.gridy++; g.gridwidth = 2; g.weightx = 1;
        add(makeDivider(), g);

        g.gridx = 0; g.gridy++; g.gridwidth = 2; g.weightx = 1;
        JPanel footer = new JPanel(new FlowLayout(FlowLayout.LEFT, 12, 0));
        footer.setOpaque(false);
        JLabel recapture = Styles.link("Recapture", ColorScheme.BRAND_ORANGE, () -> {
            // Flush any in-flight name/notes edits before swapping the tile under us.
            flushPending();
            capture.readCurrentLocation(packed -> {
                if (packed == WorldPointPacker.UNDEFINED) return;
                Waypoint cur = store.getWaypointById(waypointId);
                if (cur == null) return;
                String name = cur.getName();
                store.updateWaypointPoint(waypointId, packed);
                toasts.show("Recaptured '" + name + "'", "Undo", store::undoLast);
            });
        });
        JLabel setIcon = Styles.link("Set icon", ColorScheme.BRAND_ORANGE, () -> {
            Waypoint cur = store.getWaypointById(waypointId);
            if (cur == null) return;
            Window owner = SwingUtilities.getWindowAncestor(this);
            new IconPickerDialog(owner, spriteManager, iconCatalog, cur.getIconId(), iconId -> {
                store.updateWaypointIcon(waypointId, iconId);
            }).setVisible(true);
        });
        footer.add(recapture);
        footer.add(makeSeparator());
        footer.add(setIcon);
        footer.add(makeSeparator());
        JLabel delete = Styles.link("Delete", Styles.DELETE_RED, () -> {
            flushPending();
            WaypointerPanel.softDeleteWithUndo(store, store.getWaypointById(waypointId), toasts);
        });
        footer.add(delete);
        add(footer, g);
    }

    // Commits in-flight edits. Called on focus loss, on detach, and before recapture so the
    // swap doesn't drop the user's pending text.
    public void flushPending()
    {
        flushName();
        flushNotes();
        flushCategory();
        flushCoords();
    }

    // Only acts on text the user typed. An untouched field must not write: a store change from
    // elsewhere (Recapture, Undo) rebuilds the panel, and this panel's removeNotify flush would
    // otherwise put its stale text back over the new tile.
    private void flushCoords()
    {
        if (!coordsDirty) return;
        coordsDirty = false;
        Waypoint cur = store.getWaypointById(waypointId);
        if (cur == null) return;
        int packed;
        try
        {
            packed = CoordinateText.parse(coordsField.getText());
        }
        catch (IllegalArgumentException ex)
        {
            showCoords(cur.getPackedWorldPoint());
            toasts.show(ex.getMessage(), Toasts.Severity.WARN);
            return;
        }
        showCoords(packed);
        if (packed == cur.getPackedWorldPoint()) return;
        String name = cur.getName();
        store.updateWaypointPoint(waypointId, packed);
        toasts.show("Moved '" + name + "'", "Undo", store::undoLast);
    }

    private void showCoords(int packed)
    {
        settingCoords = true;
        try { coordsField.setText(CoordinateText.format(packed)); }
        finally { settingCoords = false; }
    }

    private void flushName()
    {
        if (!nameDirty) return;
        nameDirty = false;
        store.renameWaypoint(waypointId, nameField.getText());
    }

    private void flushNotes()
    {
        if (!notesDirty) return;
        notesDirty = false;
        store.updateWaypointNotes(waypointId, notesArea.getText());
    }

    private void flushCategory()
    {
        if (!categoryDirty) return;
        categoryDirty = false;
        CategoryComboItem sel = (CategoryComboItem) categoryCombo.getSelectedItem();
        if (sel == null) return;
        Waypoint cur = store.getWaypointById(waypointId);
        if (cur == null || sel.id().equals(cur.getCategoryId())) return;
        store.moveWaypointToCategory(waypointId, sel.id());
    }

    // Safety net for parent rebuilds that fire before focus loss.
    @Override
    public void removeNotify()
    {
        flushPending();
        super.removeNotify();
    }

    // test seams
    void setCoordinatesText(String text) { coordsField.setText(text); }
    String getCoordinatesText() { return coordsField.getText(); }

    // Cap vertical extent at preferred height so BoxLayout(Y_AXIS) in the parent stacks tight
    // instead of stretching us into leftover space.
    @Override
    public Dimension getMaximumSize()
    {
        return Styles.capHeight(this);
    }

    // An outlined card marks the waypoint being edited, whether it sits in a category card or
    // under the pinned tiles.
    @Override
    protected void paintComponent(java.awt.Graphics g)
    {
        Styles.paintInsetCard(g, this, 4, 2, 4, 2, ColorScheme.BRAND_ORANGE);
    }

    private static JPanel makeDivider()
    {
        JPanel d = new JPanel();
        d.setBackground(Styles.ROW_LINE);
        Dimension dim = new Dimension(0, 1);
        d.setPreferredSize(dim);
        d.setMinimumSize(dim);
        d.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));
        return d;
    }

    private static JLabel makeSeparator()
    {
        JLabel sep = new JLabel("·"); // middle dot
        sep.setForeground(Color.LIGHT_GRAY);
        return sep;
    }

}

package com.waypointer.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.FlowLayout;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.awt.event.ActionEvent;
import java.awt.event.KeyEvent;
import javax.swing.AbstractAction;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.KeyStroke;
import net.runelite.client.ui.ColorScheme;

/**
 * Reusable inline form: a caption, one text field, a hidden error label, and Submit / Cancel
 * buttons. Parked inline rather than shown as a dialog, so opening it never steals focus the way
 * a {@code JOptionPane} does. Configured per use through {@link #openFor}. Submit stays disabled
 * until the field holds non-blank text; the submit handler reports a failure by returning an
 * error message, which is shown in red while the form stays open.
 */
class InlineInputForm extends JPanel
{
    /** Submit handler: return {@code null} on success (form hides), or a message to show inline. */
    interface Submit
    {
        String onSubmit(String text);
    }

    private final JLabel caption = new JLabel(" ");
    private final PlaceholderTextField field = new PlaceholderTextField("");
    private final JLabel errorLabel = Styles.errorLabel();
    private final JButton submitBtn = new JButton("Submit");
    private final JButton cancelBtn = new JButton("Cancel");

    private Submit submit = text -> null;

    InlineInputForm()
    {
        setLayout(new BorderLayout(0, 4));
        setOpaque(false);
        setBorder(BorderFactory.createEmptyBorder(8, 18, 14, 18));

        JPanel stack = new JPanel();
        stack.setLayout(new BoxLayout(stack, BoxLayout.Y_AXIS));
        stack.setOpaque(false);

        caption.setForeground(ColorScheme.BRAND_ORANGE);
        caption.setFont(net.runelite.client.ui.FontManager.getRunescapeSmallFont());
        caption.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));
        caption.setAlignmentX(Component.LEFT_ALIGNMENT);
        stack.add(caption);

        // Field sits in a one-cell GridBag so it fills the width but keeps its preferred height,
        // instead of stretching vertically the way a bare component does inside BoxLayout(Y_AXIS).
        JPanel fieldRow = new JPanel(new GridBagLayout());
        fieldRow.setOpaque(false);
        fieldRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        GridBagConstraints g = new GridBagConstraints();
        g.fill = GridBagConstraints.HORIZONTAL;
        g.insets = new Insets(2, 0, 2, 0);
        g.gridx = 0; g.gridy = 0; g.weightx = 1;
        Styles.textField(field);
        fieldRow.add(field, g);
        stack.add(fieldRow);

        errorLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        stack.add(errorLabel);

        add(stack, BorderLayout.CENTER);

        JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
        buttons.setOpaque(false);
        Styles.secondaryButton(cancelBtn);
        Styles.primaryButton(submitBtn);
        cancelBtn.addActionListener(e -> dismiss());
        submitBtn.addActionListener(e -> doSubmit());
        buttons.add(cancelBtn);
        buttons.add(submitBtn);
        add(buttons, BorderLayout.SOUTH);

        // Keep Submit disabled until the field holds non-blank text - this is what stops an empty
        // value from being submitted and silently dropped.
        field.getDocument().addDocumentListener(Styles.documentListener(this::updateSubmitEnabled));

        // ENTER in the field submits; ESC anywhere in the form cancels. Bound on the form's own
        // maps so they don't fire when focus is elsewhere in the panel.
        field.getInputMap(JComponent.WHEN_FOCUSED)
            .put(KeyStroke.getKeyStroke(KeyEvent.VK_ENTER, 0), "inlineSubmit");
        field.getActionMap().put("inlineSubmit", new AbstractAction()
        {
            @Override public void actionPerformed(ActionEvent e) { doSubmit(); }
        });
        getInputMap(JComponent.WHEN_ANCESTOR_OF_FOCUSED_COMPONENT)
            .put(KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0), "inlineCancel");
        getActionMap().put("inlineCancel", new AbstractAction()
        {
            @Override public void actionPerformed(ActionEvent e) { dismiss(); }
        });

        updateSubmitEnabled();
        setVisible(false);
    }

    /** Configure the form for one use and show it: caption, submit-button text, submit handler. */
    void openFor(String captionText, String submitText, Submit submit)
    {
        openFor(captionText, "", submitText, submit);
    }

    /** As {@link #openFor(String, String, Submit)}, with a hint painted in the empty field. */
    void openFor(String captionText, String placeholder, String submitText, Submit submit)
    {
        this.submit = submit;
        field.setPlaceholder(placeholder);
        caption.setText(captionText);
        submitBtn.setText(submitText);
        field.setText("");
        errorLabel.setText(" ");
        errorLabel.setVisible(false);
        updateSubmitEnabled();
        setVisible(true);
        revalidate();
        repaint();
        field.requestFocusInWindow();
    }

    void dismiss()
    {
        field.setText("");
        errorLabel.setVisible(false);
        setVisible(false);
        revalidate();
        repaint();
    }

    private void doSubmit()
    {
        String typed = field.getText();
        String trimmed = typed == null ? "" : typed.trim();
        if (trimmed.isEmpty()) return;   // Submit is gated; guard the ENTER path too.
        String error = submit.onSubmit(trimmed);
        if (error == null)
        {
            dismiss();
            return;
        }
        errorLabel.setText(error);
        errorLabel.setVisible(true);
        revalidate();
        repaint();
        field.requestFocusInWindow();
    }

    private void updateSubmitEnabled()
    {
        String text = field.getText();
        submitBtn.setEnabled(text != null && !text.trim().isEmpty());
    }

    // ---- test seams ----
    void setText(String text) { field.setText(text); }
    String getPlaceholder() { return field.getPlaceholder(); }
    void clickSubmit() { submitBtn.doClick(); }
    void clickCancel() { cancelBtn.doClick(); }
    String getErrorText() { return errorLabel.getText(); }
    boolean isSubmitEnabled() { return submitBtn.isEnabled(); }

    // A card with an orange outline, inset from the panel edge, like the capture form.
    @Override
    protected void paintComponent(java.awt.Graphics g)
    {
        Styles.paintInsetCard(g, this, Styles.SIDE_PAD, 0, Styles.SIDE_PAD, Styles.CARD_GAP, ColorScheme.BRAND_ORANGE);
    }
}

