/**
 * Grid of labelled landmark tiles in the panel header. Each button pathfinds to the nearest
 * landmark of its type from the player's current tile. The user-selected subset and order
 * is controlled by {@link LandmarkSelection}; the panel menu's "Customise landmark bar"
 * entry toggles the inline {@link ConfigureLandmarksPanel} picker.
 */
@Singleton
public final class NearestLandmarkBar extends JPanel
{
    private static final int TILES_PER_ROW = 4;
    private static final int TILE_HEIGHT = 38;
    // Cap icon dimension so MINIMAP_BOAT_SLOOP and other oversized sprites match the
    // MAP_ICON_* set, which tops out around 16x16. Smaller sprites render unscaled.
    private static final int MAX_ICON_PX = 18;

    private static final Map<LandmarkType, Integer> SPRITE_IDS = spriteIds();

    private final BboxIndex bbox;
    private final WaypointPathfinder pathfinder;
    private final Navigator navigator;
    private final Client client;
    private final ClientThread clientThread;
    private final SpriteManager spriteManager;
    private final WaypointerConfig config;
    private final Gson gson;
    private final PlayerPosition playerPosition;

    private LandmarkSelection selection;
    private final ConfigureLandmarksPanel picker;
    private final JPanel iconRow;
    private final Map<LandmarkType, JButton> primaryButtons = new EnumMap<>(LandmarkType.class);
    private boolean loggedIn;
    private Toasts toasts = Toasts.NO_OP;
    // Fires when dev-mode landmark overrides reload BboxIndex; rebuilds the row so button
    // text and click targets reflect the current data. Closed in dispose(); the field is
    // nullable because the BboxIndex mock in unit tests returns null from subscribe(...).
    private final com.waypointer.util.Listeners.Subscription bboxSub;

    public void setToasts(Toasts toasts)
    {
        this.toasts = toasts;
    }

    @Inject
    public NearestLandmarkBar(BboxIndex bbox, WaypointPathfinder pathfinder, Navigator navigator, Client client,
        ClientThread clientThread, SpriteManager spriteManager,
        WaypointerConfig config, Gson gson, PlayerPosition playerPosition)
    {
        this.playerPosition = playerPosition;
        this.bbox = bbox;
        this.pathfinder = pathfinder;
        this.navigator = navigator;
        this.client = client;
        this.clientThread = clientThread;
        this.spriteManager = spriteManager;
        this.config = config;
        this.gson = gson;

        this.selection = LandmarkSelection.parse(config.landmarkSelectionJson(), gson);
        String canonical = selection.toJson(gson);
        if (!canonical.equals(config.landmarkSelectionJson()))
        {
            config.setLandmarkSelectionJson(canonical);
        }

        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(BorderFactory.createEmptyBorder());
        setAlignmentX(LEFT_ALIGNMENT);

        // Four tiles to a line. A grid sizes itself from the tile count alone, so the height
        // never depends on a width that is still settling during the first layout passes.
        iconRow = new JPanel(new GridLayout(0, TILES_PER_ROW, Styles.CARD_GAP, Styles.CARD_GAP));
        iconRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        iconRow.setAlignmentX(LEFT_ALIGNMENT);
        add(iconRow);

        picker = new ConfigureLandmarksPanel(
            spriteManager,
            SPRITE_IDS,
            selection,
            this::onPickerToggle,
            this::onPickerReorder,
            this::hidePicker);
        // Match the icon row's left alignment; a mismatched alignmentX makes BoxLayout narrow
        // the icon row when the picker is shown, forcing the bar to wrap earlier than it should.
        picker.setAlignmentX(LEFT_ALIGNMENT);
        add(picker);

        rebuildBar();

        this.bboxSub = bbox.subscribe(() ->
            SwingUtilities.invokeLater(this::rebuildBar));
    }

    /**
     * Releases the {@link BboxIndex} subscription so the bar doesn't outlive the plugin
     * lifecycle. Called from {@link WaypointerPanel#dispose()}.
     */
    public void dispose()
    {
        if (bboxSub != null) bboxSub.close();
    }

    /**
     * Rebuilds the icon row from the current selection. Old buttons leave the component
     * hierarchy along with their hover listeners; new buttons get a fresh
     * HoverHint.shared().attach in the per-type loop and on the overflow button.
     */
    private void rebuildBar()
    {
        iconRow.removeAll();
        primaryButtons.clear();

        for (LandmarkType type : selection.selectedInBarOrder())
        {
            JButton b = makeButton(type);
            b.addActionListener(e -> onPick(type));
            b.getAccessibleContext().setAccessibleName("Path to nearest " + type.displayName());
            applySprite(b, type);
            primaryButtons.put(type, b);
            iconRow.add(b);
            HoverHint.shared().attach(b, () -> type.displayName());
        }

        applyEnabledState();
        iconRow.revalidate();
        iconRow.repaint();
    }

    /** Opens or closes the inline picker. Called from the panel menu. */
    void togglePicker()
    {
        picker.setVisible(!picker.isVisible());
        revalidate();
        repaint();
    }

    // Closes the inline picker (the X in its header).
    private void hidePicker()
    {
        picker.setVisible(false);
        revalidate();
        repaint();
    }

    private void onPickerToggle(LandmarkType type, boolean include)
    {
        applySelection(selection.withSelected(type, include));
    }

    private void onPickerReorder(int fromIndex, int toIndex)
    {
        applySelection(selection.withOrderMove(fromIndex, toIndex));
    }

    private void applySelection(LandmarkSelection next)
    {
        if (next == selection) return;
        selection = next;
        config.setLandmarkSelectionJson(selection.toJson(gson));
        rebuildBar();
        picker.setSelection(selection);
    }

    private JButton makeButton(LandmarkType type)
    {
        JButton b = Styles.roundButton(shortName(type), false);
        b.setBackground(Styles.CARD_BG);
        b.setForeground(Styles.MUTED_TEXT);
        b.setFont(net.runelite.client.ui.FontManager.getRunescapeSmallFont());
        b.setVerticalTextPosition(javax.swing.SwingConstants.BOTTOM);
        b.setHorizontalTextPosition(javax.swing.SwingConstants.CENTER);
        b.setIconTextGap(2);
        b.setBorder(BorderFactory.createEmptyBorder(4, 0, 3, 0));
        Dimension d = new Dimension(0, TILE_HEIGHT);
        b.setPreferredSize(d);
        b.setMinimumSize(d);
        return b;
    }

    // Tile labels have about 50 px, so the longer names are cut to one word.
    static String shortName(LandmarkType type)
    {
        switch (type)
        {
            case SPINNING_WHEEL: return "Wheel";
            case SPIRIT_TREE:    return "Spirit tree";
            case CHARTER_SHIP:   return "Charter";
            case SLAYER_MASTER:  return "Slayer";
            default:             return type.displayName();
        }
    }

    private void applyEnabledState()
    {
        // setEnabled(false) triggers Swing's setDisabledIcon swap (see applySprite),
        // which is the only visible signal we need. Tooltips were replaced by the
        // immediate hover hint in rebuildBar.
        for (JButton b : primaryButtons.values()) b.setEnabled(loggedIn);
    }

    public void setLoggedIn(boolean loggedIn)
    {
        this.loggedIn = loggedIn;
        applyEnabledState();
    }

    private void applySprite(AbstractButton b, LandmarkType type)
    {
        Integer id = SPRITE_IDS.get(type);
        if (id == null || spriteManager == null) return;
        spriteManager.getSpriteAsync(id, 0, img -> {
            if (img == null) return;
            SwingUtilities.invokeLater(() -> {
                Image scaled = scaleDownIfNeeded(img);
                b.setIcon(new ImageIcon(scaled));
                // GrayFilter produces a desaturated copy so the disabled (logged-out)
                // state reads as obviously inactive on the RuneLite dark theme.
                b.setDisabledIcon(new ImageIcon(GrayFilter.createDisabledImage(scaled)));
                b.revalidate();
                b.repaint();
            });
        });
    }

    private static Image scaleDownIfNeeded(BufferedImage src)
    {
        int w = src.getWidth();
        int h = src.getHeight();
        int longest = Math.max(w, h);
        if (longest <= MAX_ICON_PX) return src;
        double scale = (double) MAX_ICON_PX / longest;
        return src.getScaledInstance((int) Math.round(w * scale),
            (int) Math.round(h * scale), Image.SCALE_SMOOTH);
    }

    void onPick(LandmarkType type)
    {
        // Without sailing routes every landmark goes to Shortest Path, so check before the lookup.
        // Otherwise the check waits until the landmark's router is known.
        if (navigator.shortestPathOnly() && !pathfinder.isAvailable())
        {
            toasts.show("Install the Shortest Path plugin to use Play.", Toasts.Severity.WARN);
            return;
        }
        clientThread.invoke(() -> {
            if (client.getGameState() != GameState.LOGGED_IN) return true;
            WorldPoint loc = playerPosition.current();
            if (loc == null) return true;
            int fromPacked = WorldPointPacker.pack(loc);
            BboxIndex.Hit hit = bbox.nearest(type, fromPacked);
            SwingUtilities.invokeLater(() -> applyHit(type, hit));
            return true;
        });
    }

    void applyHit(LandmarkType type, @javax.annotation.Nullable BboxIndex.Hit hit)
    {
        if (hit == null)
        {
            toasts.show("No " + type.displayName().toLowerCase() + " found.", Toasts.Severity.WARN);
            return;
        }
        if (navigator.shortestPathOnly())
        {
            // onPick already checked that Shortest Path is installed.
            navigator.go(hit.packed, hit.name, Navigator.Router.SHORTEST_PATH);
            return;
        }
        navigator.resolveRouter(hit.packed, router ->
        {
            if (router == Navigator.Router.SHORTEST_PATH && !pathfinder.isAvailable())
            {
                toasts.show("Install the Shortest Path plugin to use Play.", Toasts.Severity.WARN);
                return;
            }
            navigator.go(hit.packed, hit.name, router);
        });
    }

    private static Map<LandmarkType, Integer> spriteIds()
    {
        // IDs correspond to net.runelite.api.SpriteID constants. RuneLite has no
        // dedicated SpriteID for fairy rings, spirit trees, or charter ships -- the
        // stock WorldMapPlugin uses bundled PNGs for those. We substitute the closest
        // visual match from the MAP_ICON_* sprite set instead.
        EnumMap<LandmarkType, Integer> m = new EnumMap<>(LandmarkType.class);
        m.put(LandmarkType.BANK,           1453);  // MAP_ICON_BANK
        m.put(LandmarkType.ALTAR,          1467);  // MAP_ICON_ALTAR
        m.put(LandmarkType.ANVIL,          1458);  // MAP_ICON_ANVIL
        m.put(LandmarkType.FURNACE,        1457);  // MAP_ICON_FURNACE
        m.put(LandmarkType.LOOM,           1507);  // MAP_ICON_LOOM
        m.put(LandmarkType.SPINNING_WHEEL, 1483);  // MAP_ICON_SPINNING_WHEEL
        m.put(LandmarkType.TANNER,         1481);  // MAP_ICON_TANNERY
        m.put(LandmarkType.SPIRIT_TREE,    1482);  // MAP_ICON_RARE_TREES (tree silhouette)
        m.put(LandmarkType.CHARTER_SHIP,   7290);  // MINIMAP_BOAT_SLOOP
        m.put(LandmarkType.FAIRY_RING,     1504);  // MAP_ICON_TRANSPORTATION
        m.put(LandmarkType.SLAYER_MASTER,  1499);  // MAP_ICON_SLAYER_MASTER
        return m;
    }
}

package com.waypointer.ui;

import com.waypointer.model.WorldPointPacker;
import java.util.Map;
import com.waypointer.service.Navigator;
import com.waypointer.service.WaypointStore;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.WorldView;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Outlines and labels the NPC a saved NPC-waypoint points at, but only while that waypoint is
 * the active path target. Deliberately renders nothing otherwise. Cyan is used rather than
 * brand orange, which signals active-path status elsewhere in the plugin.
 */
@Singleton
public class NpcHighlightOverlay extends Overlay
{
    private static final Color HIGHLIGHT = new Color(0, 200, 220);

    private final Client client;
    private final WaypointStore store;
    private final Navigator navigator;

    @Inject
    public NpcHighlightOverlay(Client client, WaypointStore store, Navigator navigator)
    {
        this.client = client;
        this.store = store;
        this.navigator = navigator;
        setLayer(OverlayLayer.ABOVE_SCENE);
        setPosition(OverlayPosition.DYNAMIC);
    }

    /**
     * The NPC name to highlight given the active path target, or null if there is no active path
     * or its target is not an NPC waypoint. Reads a pre-built packed->name snapshot, so it does no
     * allocation on the render hot path. Pure; unit-tested.
     */
    @Nullable
    static String activeNpcName(Map<Integer, String> npcNamesByPacked, int activeTarget)
    {
        if (activeTarget == WorldPointPacker.UNDEFINED) return null;
        return npcNamesByPacked.get(activeTarget);
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        String name = activeNpcName(store.npcNamesSnapshot(), navigator.activeTarget());
        if (name == null) return null;

        WorldView wv = client.getTopLevelWorldView();
        if (wv == null) return null;

        NPC match = null;
        for (NPC npc : wv.npcs())
        {
            if (npc != null && name.equals(npc.getName()))
            {
                match = npc;
                break;
            }
        }
        if (match == null) return null;

        OverlayUtil.renderActorOverlay(g, match, name, HIGHLIGHT);
        return null;
    }
}

package com.waypointer.ui;

import com.waypointer.codec.ReadableImport;
import com.waypointer.codec.WaypointShareCodec;
import com.waypointer.model.Library;
import com.waypointer.service.WaypointStore;
import java.awt.Component;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JMenuItem;
import javax.swing.JOptionPane;
import javax.swing.JPopupMenu;
import javax.swing.SwingUtilities;

/**
 * Builds the panel's "⋮" overflow menu. Constructed by Guice with all of its services so the
 * panel doesn't need to hold them just to forward them in. The panel passes its own component
 * as the anchor at {@link #show(Component, Component)} time so JOption dialogs land on the
 * right window.
 */
@Singleton
final class OverflowMenu
{
    private final WaypointStore store;
    private final WaypointShareCodec shareCodec;
    private final ReadableImport readableImport;

    @Inject
    OverflowMenu(WaypointStore store, WaypointShareCodec shareCodec,
        ReadableImport readableImport)
    {
        this.store = store;
        this.shareCodec = shareCodec;
        this.readableImport = readableImport;
    }

    /** Show the popup anchored just below {@code near}; uses {@code panel} as JOption parent. */
    void show(Component near, WaypointerPanel panel, Toasts toasts)
    {
        Component anchor = panel;
        JPopupMenu menu = new JPopupMenu();

        JMenuItem select = new JMenuItem("Select waypoints");
        select.addActionListener(e -> panel.enterSelectMode());
        menu.add(select);

        JMenuItem newCategory = new JMenuItem("New category...");
        newCategory.addActionListener(e -> {
            String name = JOptionPane.showInputDialog(anchor, "Category name:", "New category",
                JOptionPane.PLAIN_MESSAGE);
            if (name == null || name.trim().isEmpty()) return;
            try { store.createCategory(name.trim()); }
            catch (IllegalArgumentException ex) {
                JOptionPane.showMessageDialog(anchor, ex.getMessage(), "Waypointer",
                    JOptionPane.WARNING_MESSAGE);
            }
        });
        menu.add(newCategory);

        JMenuItem addByCoordinates = new JMenuItem("Add by coordinates...");
        addByCoordinates.addActionListener(e -> panel.openAddByCoordinates());
        menu.add(addByCoordinates);

        // Expand all / Collapse all: one toggle whose label flips based on current state.
        // Majority-collapsed → "Expand all"; otherwise "Collapse all". Walks both Pinned and
        // real categories via WaypointerPanel.setAllSectionsExpanded.
        boolean expandLabel = panel.isMajorityCollapsed();
        JMenuItem expandToggle = new JMenuItem(expandLabel ? "Expand all" : "Collapse all");
        expandToggle.addActionListener(e -> panel.setAllSectionsExpanded(expandLabel));
        menu.add(expandToggle);

        if (panel.landmarkBarShown())
        {
            JMenuItem landmarks = new JMenuItem("Choose nearest buttons");
            landmarks.addActionListener(e -> panel.toggleLandmarkPicker());
            menu.add(landmarks);
        }
        javax.swing.JMenu boat = panel.boatMenu();
        if (boat != null) menu.add(boat);
        menu.addSeparator();

        JMenuItem exportItem = new JMenuItem("Export...");
        exportItem.addActionListener(e ->
            new ExportPickerDialog(SwingUtilities.getWindowAncestor(anchor), store, shareCodec,
                toasts, null).setVisible(true));
        menu.add(exportItem);

        JMenuItem importItem = new JMenuItem("Import...");
        importItem.addActionListener(e ->
            new ImportPickerDialog(SwingUtilities.getWindowAncestor(anchor), store, shareCodec,
                readableImport, toasts).setVisible(true));
        menu.add(importItem);

        menu.addSeparator();

        JMenuItem reset = new JMenuItem("Reset library...");
        reset.addActionListener(e -> {
            // Custom options with Cancel as the default-focused button so a stray Enter
            // can't wipe the whole library - there is no undo for this.
            String[] options = {"Cancel", "Delete all waypoints and categories"};
            int choice = JOptionPane.showOptionDialog(anchor,
                "Delete ALL waypoints and categories? This cannot be undone.",
                "Reset library", JOptionPane.DEFAULT_OPTION, JOptionPane.WARNING_MESSAGE,
                null, options, options[0]);
            if (choice == 1) store.bootstrap(new Library());
        });
        menu.add(reset);

        menu.show(near, 0, near.getHeight());
    }
}

package com.waypointer.ui;

import com.waypointer.WaypointerConfig;
import com.waypointer.model.Library;
import com.waypointer.model.route.RouteLibrary;
import com.waypointer.service.RouteStore;
import com.waypointer.service.RouteStorePersistence;
import com.waypointer.service.WaypointStore;
import com.waypointer.service.WaypointStorePersistence;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

/**
 * Static factories for the transient body banners panels can show above their content lists:
 * the "Shortest Path missing" notice (with a dismiss-forever button), the waypoint "library load
 * failed" reset banner, and its routes-tab equivalent. All are height-capped via
 * {@link Styles#cappedHeightPanel} so the containing {@code BoxLayout(Y_AXIS)} does not stretch them.
 */
final class PanelBanners
{
    private PanelBanners() {}

    /**
     * Shown while the Shortest Path plugin is unavailable and the user has not dismissed the
     * notice. {@code onDismiss} runs after the dismiss flag is persisted so the panel can rebuild.
     */
    static JComponent shortestPathMissing(WaypointerConfig config, Runnable onDismiss)
    {
        CardPanel p = new CardPanel(new BorderLayout(4, 4));
        p.setAlignmentX(Component.LEFT_ALIGNMENT);
        p.setOutline(new Color(140, 100, 0));
        p.setBorder(BorderFactory.createEmptyBorder(8, 10, 8, 10));
        JLabel msg = new JLabel("<html>Install the Shortest Path plugin to use Play.</html>");
        msg.setForeground(Color.WHITE);
        p.add(msg, BorderLayout.CENTER);
        JButton dismiss = new JButton("Don't show again");
        Styles.secondaryButton(dismiss);
        dismiss.addActionListener(e -> { config.setShortestPathBannerDismissed(true); onDismiss.run(); });
        p.add(dismiss, BorderLayout.EAST);
        return p;
    }

    /**
     * Shown when the library and its backup both failed to load and the store is refusing saves.
     * The Reset button confirms, calls {@code persistence.clear()} to wipe the config key and
     * lift the corrupt-saves freeze, then bootstraps a fresh library; the store's own listeners
     * drive the subsequent rebuild. {@code dialogParent} owns the confirm dialog.
     */
    static JComponent loadFailedReset(WaypointStorePersistence persistence, WaypointStore store,
        Component dialogParent)
    {
        CardPanel p = new CardPanel(new BorderLayout(4, 4));
        p.setAlignmentX(Component.LEFT_ALIGNMENT);
        p.setOutline(new Color(180, 40, 40));
        p.setBorder(BorderFactory.createEmptyBorder(8, 10, 8, 10));
        JLabel resetMsg = new JLabel("<html>Saved waypoints could not be read.<br>"
            + "Click Reset to start fresh.</html>");
        resetMsg.setForeground(Color.WHITE);
        p.add(resetMsg, BorderLayout.CENTER);
        JButton reset = new JButton("Reset library");
        Styles.secondaryButton(reset);
        reset.addActionListener(e -> {
            // Cancel is the default-focused button so a stray Enter can't discard the data.
            String[] options = {"Cancel", "Reset"};
            int choice = JOptionPane.showOptionDialog(dialogParent,
                "This will discard the unreadable saved waypoints. Continue?",
                "Reset library", JOptionPane.DEFAULT_OPTION, JOptionPane.WARNING_MESSAGE,
                null, options, options[0]);
            if (choice != 1) return;
            persistence.clear();
            store.bootstrap(new Library());
        });
        p.add(reset, BorderLayout.EAST);
        return p;
    }

    /**
     * Routes-tab equivalent of {@link #loadFailedReset}: shown when the route config key is
     * unreadable and the route store is refusing saves. Reset confirms, calls
     * {@code persistence.clear()} to wipe the config key and lift the freeze, then bootstraps an
     * empty route library; the store's own listeners drive the subsequent rebuild.
     * {@code dialogParent} owns the confirm dialog.
     */
    static JComponent routeLoadFailedReset(RouteStorePersistence persistence, RouteStore store,
        Component dialogParent)
    {
        CardPanel p = new CardPanel(new BorderLayout(4, 4));
        p.setAlignmentX(Component.LEFT_ALIGNMENT);
        p.setOutline(new Color(180, 40, 40));
        p.setBorder(BorderFactory.createEmptyBorder(8, 10, 8, 10));
        JLabel resetMsg = new JLabel("<html>Saved routes could not be read.<br>"
            + "Click Reset to start fresh.</html>");
        resetMsg.setForeground(Color.WHITE);
        p.add(resetMsg, BorderLayout.CENTER);
        JButton reset = new JButton("Reset routes");
        Styles.secondaryButton(reset);
        reset.addActionListener(e -> {
            String[] options = {"Cancel", "Reset"};
            int choice = JOptionPane.showOptionDialog(dialogParent,
                "This will discard the unreadable saved routes. Continue?",
                "Reset routes", JOptionPane.DEFAULT_OPTION, JOptionPane.WARNING_MESSAGE,
                null, options, options[0]);
            if (choice != 1) return;
            persistence.clear();
            store.bootstrap(new RouteLibrary());
        });
        p.add(reset, BorderLayout.EAST);
        return p;
    }
}

