// Something on screen that stands for one tile and can show that it is being pathed to. Lets
// the panel retint rows and tiles in place when the path target changes.
interface PathTarget
{
    int getPackedWorldPoint();

    void setActive(boolean active);
}

package com.waypointer.ui;

import com.waypointer.model.Waypoint;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.service.Wilderness;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import java.util.function.BiConsumer;
import java.util.function.Function;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingUtilities;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;

/**
 * Pinned waypoints as a grid of shortcut tiles above the category cards. Clicking a tile
 * paths to it (or stops, if it is the active target); the right-click menu edits, unpins or
 * deletes. An open editor sits under the grid. The caller skips this section when nothing is
 * pinned.
 */
public class PinnedSection extends JPanel
{
    public PinnedSection(
        List<Waypoint> pinned,
        int activePathTarget,
        BiConsumer<Waypoint, CategorySection.RowAction> onRowAction,
        Function<Waypoint, Component> inlineProvider,
        SpriteManager spriteManager)
    {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setOpaque(false);
        setAlignmentX(LEFT_ALIGNMENT);
        add(Styles.caption("Pinned"));

        JPanel grid = new JPanel(new GridLayout(0, 2, Styles.CARD_GAP, Styles.CARD_GAP));
        grid.setOpaque(false);
        grid.setAlignmentX(LEFT_ALIGNMENT);
        for (Waypoint w : pinned)
        {
            boolean active = activePathTarget != WorldPointPacker.UNDEFINED
                && w.getPackedWorldPoint() == activePathTarget;
            grid.add(new Tile(w, active, onRowAction, spriteManager));
        }
        add(grid);

        for (Waypoint w : pinned)
        {
            Component inline = inlineProvider.apply(w);
            if (inline == null) continue;
            if (inline instanceof JComponent) ((JComponent) inline).setAlignmentX(LEFT_ALIGNMENT);
            add(javax.swing.Box.createVerticalStrut(Styles.CARD_GAP));
            add(inline);
        }
    }

    @Override
    public Dimension getMaximumSize()
    {
        return Styles.capHeight(this);
    }

    /** One pinned waypoint. Implements the same in-place retint the rows use. */
    static final class Tile extends CardPanel implements PathTarget
    {
        private final Waypoint waypoint;
        private boolean hovered;
        private boolean active;

        Tile(Waypoint w, boolean active, BiConsumer<Waypoint, CategorySection.RowAction> onRowAction,
            SpriteManager spriteManager)
        {
            super(new BorderLayout(5, 0));
            this.waypoint = w;
            setBorder(BorderFactory.createEmptyBorder(3, 7, 3, 5));
            setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

            JLabel star = new JLabel(Glyphs.of(Glyphs.Shape.STAR, ColorScheme.BRAND_ORANGE));
            add(star, BorderLayout.WEST);

            boolean wild = Wilderness.isInWilderness(w.getPackedWorldPoint());
            // HTML so a long name wraps onto a second line instead of being cut off.
            JLabel name = new JLabel("<html>" + com.waypointer.util.Text.escapeHtml(w.getName()) + "</html>");
            name.setForeground(wild ? new Color(220, 130, 130) : Color.WHITE);
            name.setToolTipText(WaypointRow.buildHoverTooltip(w));
            name.getAccessibleContext().setAccessibleName(
                "Path to " + WaypointRow.accessibleName(w.getName(), wild, true));
            add(name, BorderLayout.CENTER);

            JPopupMenu popup = new JPopupMenu();
            JMenuItem edit = new JMenuItem("Edit");
            edit.addActionListener(e -> onRowAction.accept(w, CategorySection.RowAction.EXPAND_PINNED));
            JMenuItem unpin = new JMenuItem("Unpin");
            unpin.addActionListener(e -> onRowAction.accept(w, CategorySection.RowAction.TOGGLE_PIN));
            JMenuItem delete = new JMenuItem("Delete");
            delete.addActionListener(e -> onRowAction.accept(w, CategorySection.RowAction.DELETE));
            popup.add(edit);
            popup.add(unpin);
            popup.addSeparator();
            popup.add(delete);
            setComponentPopupMenu(popup);
            name.setInheritsPopupMenu(true);
            star.setInheritsPopupMenu(true);

            MouseAdapter ma = new MouseAdapter()
            {
                @Override public void mouseEntered(MouseEvent e) { hovered = true; restyle(); }
                @Override public void mouseExited(MouseEvent e)
                {
                    java.awt.Point p = SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Tile.this);
                    if (contains(p)) return;
                    hovered = false;
                    restyle();
                }
                @Override public void mouseClicked(MouseEvent e)
                {
                    if (SwingUtilities.isLeftMouseButton(e)) onRowAction.accept(w, CategorySection.RowAction.PLAY);
                }
            };
            addMouseListener(ma);
            name.addMouseListener(ma);
            star.addMouseListener(ma);
            setActive(active);
        }

        @Override public int getPackedWorldPoint() { return waypoint.getPackedWorldPoint(); }

        @Override public void setActive(boolean active)
        {
            this.active = active;
            restyle();
        }

        boolean isActiveForTest() { return active; }

        private void restyle()
        {
            setBackground(active ? Styles.ACTIVE_TINT : hovered ? Styles.ROW_HOVER : Styles.CARD_BG);
            setOutline(active ? ColorScheme.BRAND_ORANGE : null);
        }

        // Two lines of text tall, whatever the name, so the grid stays even.
        @Override public Dimension getPreferredSize()
        {
            return new Dimension(super.getPreferredSize().width, 36);
        }
    }
}

package com.waypointer.ui;

import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Insets;
import java.awt.RenderingHints;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import javax.swing.JTextField;
import net.runelite.client.ui.ColorScheme;

/**
 * JTextField that paints a faded hint over the empty, unfocused field. The hint is paint-only
 * and never enters the field's document, so {@link #getText()} stays empty until the user
 * types. Callers that filter on the field contents need no special handling.
 */
class PlaceholderTextField extends JTextField
{
    private String placeholder;

    PlaceholderTextField(String placeholder)
    {
        this.placeholder = placeholder == null ? "" : placeholder;
        // Explicit repaint on focus change; default JTextField repaint timing is LAF-dependent
        // and the hint must vanish the instant the field gains focus.
        addFocusListener(new FocusAdapter()
        {
            @Override public void focusGained(FocusEvent e) { repaint(); }
            @Override public void focusLost(FocusEvent e)   { repaint(); }
        });
    }

    void setPlaceholder(String placeholder)
    {
        this.placeholder = placeholder == null ? "" : placeholder;
        repaint();
    }

    String getPlaceholder()
    {
        return placeholder;
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        super.paintComponent(g);
        if (placeholder.isEmpty() || !getText().isEmpty() || isFocusOwner())
        {
            return;
        }
        Graphics2D g2 = (Graphics2D) g.create();
        try
        {
            g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
                RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            g2.setFont(getFont());
            g2.setColor(ColorScheme.LIGHT_GRAY_COLOR);
            Insets in = getInsets();
            int x = in.left;
            int y = in.top + g2.getFontMetrics().getAscent();
            g2.drawString(placeholder, x, y);
        }
        finally
        {
            g2.dispose();
        }
    }
}

package com.waypointer.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import net.runelite.client.ui.ColorScheme;

/** Per-row Play button styling: a grey glyph at rest, orange on hover, an orange stop square when active. */
final class PlayButton
{
    private PlayButton() {}

    private static final String CLIENT_PROP_ACTIVE = "waypointer.playActive";
    private static final String CLIENT_PROP_HOVER_ATTACHED = "waypointer.playHoverAttached";

    // Active flag is mirrored to a client property so the hover adapter can check it without
    // closure capture.
    static void style(JButton b, boolean active)
    {
        b.putClientProperty(CLIENT_PROP_ACTIVE, active);

        // Active row shows a stop square; resting shows the play triangle. Driven here so the
        // glyph follows every retint -- including when another row is played or the path
        // auto-clears on arrival.
        b.setText(active ? "■" : "▶");

        // U+25A0 is metrically smaller than the triangle at a given size, so the stop square gets
        // a larger point size to match the play arrow's visual weight.
        b.setFont(b.getFont().deriveFont(Font.BOLD, active ? 16f : 11f));
        Dimension size = new Dimension(26, 22);
        b.setPreferredSize(size);
        b.setMinimumSize(size);
        b.setFocusPainted(false);
        b.setBorderPainted(false);
        b.setMargin(new java.awt.Insets(0, 0, 0, 0));

        applyResting(b, active);

        // Attach the hover adapter once. Re-invocations on the same button would
        // otherwise stack listeners.
        if (b.getClientProperty(CLIENT_PROP_HOVER_ATTACHED) == null)
        {
            b.addMouseListener(new MouseAdapter()
            {
                @Override public void mouseEntered(MouseEvent e)
                {
                    if (Boolean.TRUE.equals(b.getClientProperty(CLIENT_PROP_ACTIVE))) return;
                    applyHover(b);
                }
                @Override public void mouseExited(MouseEvent e)
                {
                    if (Boolean.TRUE.equals(b.getClientProperty(CLIENT_PROP_ACTIVE))) return;
                    applyResting(b, false);
                }
            });
            b.putClientProperty(CLIENT_PROP_HOVER_ATTACHED, Boolean.TRUE);
        }
    }

    private static void applyResting(JButton b, boolean active)
    {
        b.setBorder(BorderFactory.createEmptyBorder());
        // Orange is kept for the row being pathed to; a resting row shows a plain grey glyph.
        // The row paints the tint behind an active button, so the button itself never fills.
        b.setContentAreaFilled(false);
        b.setOpaque(false);
        b.setForeground(active ? ColorScheme.BRAND_ORANGE : Styles.MUTED_TEXT);
    }

    private static void applyHover(JButton b)
    {
        b.setForeground(ColorScheme.BRAND_ORANGE);
    }
}

package com.waypointer.ui;

import com.waypointer.model.Library;
import com.waypointer.model.Waypoint;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.preset.Preset;
import com.waypointer.preset.PresetCatalog;
import com.waypointer.preset.PresetImport;
import com.waypointer.preset.PresetWaypoint;
import com.waypointer.service.WaypointStore;
import com.waypointer.util.Listeners;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollBar;
import javax.swing.JScrollPane;
import javax.swing.SwingUtilities;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

// Singleton preset browser. Lives for the lifetime of the plugin and reacts to store
// mutations from any source so the per-row "+" / "added" toggles stay in sync.
@Singleton
public class PresetBrowserPanel extends PluginPanel
{
    private final PresetCatalog catalog;
    private final WaypointStore store;
    private final SpriteManager spriteManager;
    private final JPanel body = new JPanel();
    private final ToastOverlay toastOverlay;
    private final JScrollBar bodyScrollBar;
    private String lastToastTextForTest;

    private Listeners.Subscription storeSub;
    private Listeners.Subscription catalogSub;
    private volatile boolean rebuildPending = false;

    @Inject
    public PresetBrowserPanel(PresetCatalog catalog, WaypointStore store,
        SpriteManager spriteManager)
    {
        super(false);
        this.catalog = catalog;
        this.store = store;
        this.spriteManager = spriteManager;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel header = buildHeader();
        header.setAlignmentX(LEFT_ALIGNMENT);
        add(header, BorderLayout.NORTH);

        body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
        body.setBackground(ColorScheme.DARK_GRAY_COLOR);
        body.setBorder(BorderFactory.createEmptyBorder(0, Styles.SIDE_PAD, 0, Styles.SIDE_PAD - 2));

        // Width-pinned so a long preset name cannot push the count and the add buttons past
        // the right edge.
        JPanel bodyHolder = Styles.sidebarWidthHolder(body);

        // Constructed during loadCorePlugins(), before ClientUI.init() installs RuneLiteLAF,
        // so the scrollbar's UI delegate would inherit Metal defaults. Styles.pinnedScrollPane
        // applies the dark-theme pin now; refreshScrollbarStyling() re-derives it from startUp()
        // once the LAF is live.
        JScrollPane scroll = Styles.pinnedScrollPane(bodyHolder);
        this.bodyScrollBar = scroll.getVerticalScrollBar();
        toastOverlay = new ToastOverlay(scroll);
        add(toastOverlay, BorderLayout.CENTER);

        storeSub = store.subscribe(this::scheduleRebuild);
        catalogSub = catalog.subscribe(this::scheduleRebuild);
        rebuild();
    }

    // PluginPanel feeds its layout-computed height to ClientUI; the inner JScrollPane
    // handles overflow, so the height reported outward stays 0 and the frame size keeps
    // tracking the game canvas. See the WaypointerPanel.getPreferredSize comment for the
    // full Windows-unmaximize explanation.
    @Override
    public Dimension getPreferredSize()
    {
        return new Dimension(super.getPreferredSize().width, 0);
    }

    @Override
    public Dimension getMinimumSize()
    {
        return new Dimension(super.getMinimumSize().width, 0);
    }

    /** Called from {@link com.waypointer.WaypointerPlugin#startUp()} after LAF init. */
    public void refreshScrollbarStyling()
    {
        SwingUtilities.invokeLater(() -> Styles.reapplyScrollbarPin(bodyScrollBar));
    }

    public void dispose()
    {
        if (storeSub != null) { storeSub.close(); storeSub = null; }
        if (catalogSub != null) { catalogSub.close(); catalogSub = null; }
    }

    private JPanel buildHeader()
    {
        JPanel header = new JPanel(new BorderLayout(8, 0));
        header.setBackground(ColorScheme.DARK_GRAY_COLOR);
        header.setBorder(BorderFactory.createEmptyBorder(Styles.CARD_GAP, Styles.SIDE_PAD, 0, Styles.SIDE_PAD));
        header.add(Styles.caption("Press + to copy one into your list"), BorderLayout.WEST);

        return header;
    }

    // Coalesce back-to-back rebuilds within one EDT cycle into a single call.
    // Mirrors WaypointerPanel.scheduleRebuild.
    private void scheduleRebuild()
    {
        if (rebuildPending) return;
        rebuildPending = true;
        SwingUtilities.invokeLater(() ->
        {
            rebuildPending = false;
            rebuild();
        });
    }

    // Test seam - drives the same rebuild path the store listener does, without
    // depending on SwingUtilities.invokeLater scheduling.
    void scheduleRebuildForTest()
    {
        rebuild();
    }

    private void rebuild()
    {
        Set<String> expandedPresetNames = snapshotExpandedPresetNames();
        body.removeAll();
        Map<Integer, UUID> existing = existingIdByPacked();
        List<Preset> presets = catalog.getPresets();
        if (presets.isEmpty())
        {
            JLabel none = new JLabel("<html><div style='text-align:center;padding:24px 12px;"
                + "color:" + Styles.MUTED_HEX + ";'>No presets available.</div></html>");
            none.setAlignmentX(LEFT_ALIGNMENT);
            none.setForeground(Color.LIGHT_GRAY);
            body.add(none);
        }
        else
        {
            for (Preset preset : presets)
            {
                PresetSection section = new PresetSection(
                    preset, spriteManager, existing,
                    wp -> addWaypoint(preset, wp),
                    id -> removeWaypoint(id));
                section.setAlignmentX(LEFT_ALIGNMENT);
                if (expandedPresetNames.contains(preset.getCategory()))
                {
                    // Restore previously-expanded state. PresetSection defaults to collapsed.
                    section.setExpanded(true);
                }
                body.add(section);
            }
        }
        body.add(Box.createVerticalGlue());
        body.revalidate();
        body.repaint();
    }

    private Set<String> snapshotExpandedPresetNames()
    {
        Set<String> out = new HashSet<>();
        for (java.awt.Component c : body.getComponents())
        {
            if (c instanceof PresetSection)
            {
                PresetSection s = (PresetSection) c;
                if (s.isExpanded())
                {
                    out.add(s.getPresetName());
                }
            }
        }
        return out;
    }

    private Map<Integer, UUID> existingIdByPacked()
    {
        Map<Integer, UUID> map = new HashMap<>();
        for (Waypoint w : store.getLibrary().getWaypoints())
        {
            map.put(w.getPackedWorldPoint(), w.getId());
        }
        return map;
    }

    UUID addWaypoint(Preset preset, PresetWaypoint wp)
    {
        store.importMerge(PresetImport.singleEntryLibrary(preset, wp));
        int packed = WorldPointPacker.pack(wp.getX(), wp.getY(), wp.getPlane());
        return findIdByPacked(store.getLibrary(), packed);
    }

    void removeWaypoint(UUID id)
    {
        Waypoint w = findWaypointById(store.getLibrary(), id);
        String name = w != null ? w.getName() : "waypoint";
        store.deleteWaypoint(id);
        String msg = "Removed " + name;
        lastToastTextForTest = msg;
        toastOverlay.show(msg);
    }

    private static UUID findIdByPacked(Library library, int packed)
    {
        for (Waypoint w : library.getWaypoints())
        {
            if (w.getPackedWorldPoint() == packed) return w.getId();
        }
        return null;
    }

    private static Waypoint findWaypointById(Library library, UUID id)
    {
        for (Waypoint w : library.getWaypoints())
        {
            if (w.getId().equals(id)) return w;
        }
        return null;
    }

    String lastToastTextForTest()
    {
        return lastToastTextForTest;
    }
}

package com.waypointer.ui;

import com.waypointer.model.WorldPointPacker;
import com.waypointer.util.Text;
import com.waypointer.preset.Preset;
import com.waypointer.preset.PresetWaypoint;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.event.ComponentAdapter;
import java.awt.event.ComponentEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.function.Consumer;
import java.util.function.Function;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.plaf.basic.BasicHTML;
import javax.swing.text.View;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

// One curated set, drawn as a collapsible card: a clickable header that toggles a
// stack of waypoint rows. Starts collapsed; rows are built lazily on first expand.
class PresetSection extends JPanel
{
    // Historical fallback width for the row label: used until componentResized fires with a
    // real container width. Derived from the old constant kept as a safety value for tests /
    // very early paint passes when getWidth() is still zero.
    private static final int FALLBACK_LABEL_WIDTH_PX = 107;
    // Row chrome reserved on either side of the label: border left (10) + border right (6)
    // + BorderLayout hgap (8) + AddRemoveToggle button (~23) + a small margin (6).
    private static final int ROW_RESERVED_PX = 10 + 6 + 8 + 23 + 6;
    private static final int MIN_LABEL_WIDTH_PX = 60;

    private final Preset preset;
    private final SpriteManager spriteManager;
    private final Map<Integer, UUID> existingIdByPacked;
    private final Function<PresetWaypoint, UUID> onAdd;
    private final Consumer<UUID> onRemove;
    private final JPanel rows = new JPanel();
    private final JLabel chevron = new JLabel();
    private final List<JLabel> rowLabels = new ArrayList<>();
    private int labelWidthPx;
    private boolean expanded;

    PresetSection(Preset preset, SpriteManager spriteManager, Map<Integer, UUID> existingIdByPacked,
        Function<PresetWaypoint, UUID> onAdd, Consumer<UUID> onRemove)
    {
        this.preset = preset;
        this.spriteManager = spriteManager;
        this.existingIdByPacked = existingIdByPacked;
        this.onAdd = onAdd;
        this.onRemove = onRemove;

        setLayout(new BorderLayout());
        setOpaque(false);
        // The bottom inset is the gap to the next card; see paintComponent.
        setBorder(BorderFactory.createEmptyBorder(0, 0, Styles.CARD_GAP, 0));

        add(buildHeader(), BorderLayout.NORTH);

        rows.setLayout(new BoxLayout(rows, BoxLayout.Y_AXIS));
        rows.setOpaque(false);
        rows.setBorder(BorderFactory.createEmptyBorder(0, 0, 2, 0));
        rows.setVisible(false);
        add(rows, BorderLayout.CENTER);

        // Recompute the row-label width as the container grows or shrinks. Drives
        // HTML wrap so descriptions stay inside the section instead of clipping at the
        // hard-coded 107 px the old constant used.
        addComponentListener(new ComponentAdapter()
        {
            @Override public void componentResized(ComponentEvent e)
            {
                int w = computeLabelWidth(getWidth());
                if (w == labelWidthPx) return;
                labelWidthPx = w;
                for (JLabel label : rowLabels) applyLabelWidth(label, labelWidthPx);
                rows.revalidate();
                rows.repaint();
            }
        });
    }

    private static int computeLabelWidth(int containerWidth)
    {
        if (containerWidth <= 0) return FALLBACK_LABEL_WIDTH_PX;
        return Math.max(MIN_LABEL_WIDTH_PX, containerWidth - ROW_RESERVED_PX);
    }

    private static void applyLabelWidth(JLabel label, int width)
    {
        if (width <= 0) return;
        View v = (View) label.getClientProperty(BasicHTML.propertyKey);
        if (v == null) return;
        v.setSize(width, 0);
        int h = (int) Math.ceil(v.getPreferredSpan(View.Y_AXIS));
        label.setPreferredSize(new Dimension(width, h));
    }

    // Cap the section to its own preferred height so the parent BoxLayout(Y_AXIS) stacks
    // sections tight instead of stretching them down the column.
    @Override
    public Dimension getMaximumSize()
    {
        return Styles.capHeight(this);
    }

    @Override
    protected void paintComponent(java.awt.Graphics g)
    {
        Styles.paintInsetCard(g, this, 0, 0, 0, Styles.CARD_GAP, null);
    }

    private javax.swing.Icon chevronIcon()
    {
        return Glyphs.of(expanded ? Glyphs.Shape.CHEVRON_DOWN : Glyphs.Shape.CHEVRON_RIGHT, Styles.FAINT_TEXT);
    }

    // "2 / 8" once any of the pack is in the library, otherwise just the size.
    private String countText()
    {
        int have = 0;
        for (PresetWaypoint wp : preset.getWaypoints())
        {
            if (existingIdByPacked.containsKey(WorldPointPacker.pack(wp.getX(), wp.getY(), wp.getPlane()))) have++;
        }
        int total = preset.getWaypoints().size();
        return have == 0 ? String.valueOf(total) : have + " / " + total;
    }

    private JPanel buildHeader()
    {
        JPanel header = new JPanel(new BorderLayout(6, 0));
        header.setOpaque(false);
        header.setBorder(BorderFactory.createEmptyBorder(5, 8, 5, 8));
        header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        chevron.setIcon(chevronIcon());

        JLabel name = new JLabel(preset.getCategory());
        name.setForeground(Color.WHITE);
        name.setFont(FontManager.getRunescapeBoldFont());

        if (preset.getIcon() != null)
        {
            JLabel icon = new JLabel();
            SpriteIcons.apply(icon, preset.getIcon(), spriteManager);
            header.add(icon, BorderLayout.WEST);
        }
        // The name takes whatever the count and chevron leave, and is cut with an ellipsis
        // when a long one ("God Wars Dungeon Bosses") does not fit.
        header.add(name, BorderLayout.CENTER);
        JLabel count = Styles.pill(countText());
        if (count.getText().indexOf('/') >= 0) count.setForeground(ColorScheme.PROGRESS_COMPLETE_COLOR);
        JPanel right = new JPanel(new FlowLayout(FlowLayout.RIGHT, 6, 0));
        right.setOpaque(false);
        right.add(count);
        right.add(chevron);
        header.add(right, BorderLayout.EAST);

        header.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseClicked(MouseEvent e)
            {
                toggle();
            }
        });
        return header;
    }

    private void toggle()
    {
        expanded = !expanded;
        applyExpandedState();
    }

    private void applyExpandedState()
    {
        chevron.setIcon(chevronIcon());
        if (expanded && rows.getComponentCount() == 0)
        {
            buildRows();
        }
        rows.setVisible(expanded);
        revalidate();
        repaint();
    }

    String getPresetName() { return preset.getCategory(); }

    boolean isExpanded() { return expanded; }

    void setExpanded(boolean expand)
    {
        if (expand == expanded) return;
        expanded = expand;
        applyExpandedState();
    }

    private void buildRows()
    {
        rowLabels.clear();
        if (labelWidthPx <= 0) labelWidthPx = computeLabelWidth(getWidth());
        String desc = preset.getDescription();
        if (desc != null && !desc.trim().isEmpty())
        {
            JLabel descLabel = new JLabel("<html><div style='padding:2px 9px 4px 10px;'>"
                + Text.escapeHtml(desc) + "</div></html>");
            descLabel.setForeground(Styles.MUTED_TEXT);
            descLabel.setFont(FontManager.getRunescapeSmallFont());
            descLabel.setAlignmentX(LEFT_ALIGNMENT);
            rows.add(descLabel);
        }
        for (PresetWaypoint wp : preset.getWaypoints())
        {
            JPanel row = buildRow(wp);
            row.setAlignmentX(LEFT_ALIGNMENT);
            rows.add(row);
        }
    }

    private JPanel buildRow(PresetWaypoint wp)
    {
        JPanel row = new JPanel(new BorderLayout(8, 0))
        {
            @Override
            public Dimension getMaximumSize()
            {
                return Styles.capHeight(this);
            }

            @Override
            protected void paintComponent(java.awt.Graphics g)
            {
                g.setColor(Styles.ROW_LINE);
                g.fillRect(8, 0, getWidth() - 16, 1);
            }
        };
        row.setOpaque(false);
        row.setBorder(BorderFactory.createEmptyBorder(3, 10, 2, 6));

        String descHtml = wp.getDescription() == null || wp.getDescription().trim().isEmpty()
            ? ""
            : "<br><span style='color:#7d7d7d;'>" + Text.escapeHtml(wp.getDescription())
                + "</span>";
        JLabel label = new JLabel("<html>"
            + Text.escapeHtml(wp.getName()) + descHtml + "</html>");
        label.setForeground(Color.WHITE);
        // BasicHTML's <div style='width:Npx'> trick is unreliable: JLabel still reports
        // its preferredSize at the unwrapped text width, which overflows the viewport and
        // clips the EAST button. Force the View to lay out at the current labelWidthPx,
        // then pin the label's preferredSize so BorderLayout honours the constraint. The
        // section's componentResized listener re-applies if the container resizes.
        applyLabelWidth(label, labelWidthPx);
        rowLabels.add(label);
        row.add(label, BorderLayout.CENTER);

        int packed = WorldPointPacker.pack(wp.getX(), wp.getY(), wp.getPlane());
        UUID existingId = existingIdByPacked.get(packed);
        AddRemoveToggle toggle = new AddRemoveToggle(
            existingId,
            () -> onAdd.apply(wp),
            id -> onRemove.accept(id));
        row.add(toggle, BorderLayout.EAST);
        return row;
    }
}

