package com.waypointer.ui;

import com.waypointer.codec.CoordinateText;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.model.route.Route;
import com.waypointer.model.route.RouteDistance;
import com.waypointer.model.route.RouteStep;
import com.waypointer.model.route.StepType;
import com.waypointer.service.RouteStore;
import java.awt.BorderLayout;
import java.awt.FlowLayout;
import java.util.UUID;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JTextField;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Edits one route's steps: an ordered list of {@link RouteStepRow}s plus add-step controls and a
 * repeating toggle. All mutations go through {@link RouteStore} so they persist and notify.
 */
final class RouteEditorPanel extends JPanel
{
    private final RouteStore store;
    private final UUID routeId;
    private final Runnable onBack;
    private final Runnable onMarkCurrentLocation;
    private final Runnable onAddFromLibrary;
    private final JPanel stepList = new JPanel();
    private final JLabel summary = new JLabel(" ");
    private final JLabel title = new JLabel(" ");

    RouteEditorPanel(RouteStore store, UUID routeId, Runnable onBack,
        Runnable onMarkCurrentLocation, Runnable onAddFromLibrary)
    {
        this.store = store;
        this.routeId = routeId;
        this.onBack = onBack;
        this.onMarkCurrentLocation = onMarkCurrentLocation;
        this.onAddFromLibrary = onAddFromLibrary;
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        // Nav row and the add-step controls both sit at the top: the add-step buttons are the
        // primary action here, so they belong above the step list rather than buried in a footer.
        JPanel top = new JPanel();
        top.setLayout(new BoxLayout(top, BoxLayout.Y_AXIS));
        top.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JPanel nav = buildNavRow();
        nav.setAlignmentX(LEFT_ALIGNMENT);
        top.add(nav);
        title.setForeground(java.awt.Color.WHITE);
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setAlignmentX(LEFT_ALIGNMENT);
        title.setBorder(BorderFactory.createEmptyBorder(2, 8, 2, 6));
        top.add(title);
        JPanel addBar = buildAddStepBar();
        addBar.setAlignmentX(LEFT_ALIGNMENT);
        top.add(addBar);
        summary.setFont(FontManager.getRunescapeSmallFont());
        summary.setForeground(Styles.MUTED_TEXT);
        summary.setAlignmentX(LEFT_ALIGNMENT);
        summary.setBorder(BorderFactory.createEmptyBorder(0, 8, 4, 6));
        top.add(summary);
        add(top, BorderLayout.NORTH);

        stepList.setLayout(new BoxLayout(stepList, BoxLayout.Y_AXIS));
        stepList.setOpaque(false);
        // All steps share one card, padded off the panel edges.
        CardPanel stepCard = new CardPanel(new BorderLayout());
        stepCard.add(stepList, BorderLayout.CENTER);
        JPanel padded = new JPanel(new BorderLayout());
        padded.setOpaque(false);
        padded.setBorder(BorderFactory.createEmptyBorder(0, Styles.SIDE_PAD, Styles.SIDE_PAD, Styles.SIDE_PAD - 2));
        padded.add(stepCard, BorderLayout.CENTER);
        add(Styles.pinnedScrollPane(Styles.sidebarWidthHolder(padded)), BorderLayout.CENTER);

        rebuild();
    }

    private JPanel buildNavRow()
    {
        JPanel header = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 4));
        header.setBackground(ColorScheme.DARK_GRAY_COLOR);
        // ◀ = left-pointing triangle for back navigation
        JButton back = new JButton("◀ Routes");
        Styles.compactSecondaryButton(back);
        back.addActionListener(e -> onBack.run());
        header.add(back);

        Route r = store.getRouteById(routeId);
        JCheckBox repeating = new JCheckBox("Repeating", r != null && r.isRepeating());
        repeating.setOpaque(false);
        repeating.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        repeating.addActionListener(e -> store.setRepeating(routeId, repeating.isSelected()));
        header.add(repeating);
        return header;
    }

    private JPanel buildAddStepBar()
    {
        JPanel bar = new JPanel();
        bar.setLayout(new BoxLayout(bar, BoxLayout.Y_AXIS));
        bar.setBackground(ColorScheme.DARK_GRAY_COLOR);
        bar.setBorder(BorderFactory.createEmptyBorder(4, Styles.SIDE_PAD, 4, Styles.SIDE_PAD));

        // ◉ = waypoint glyph; capture the player's current tile as a step
        bar.add(fullWidthButton("◉ Mark location", e -> onMarkCurrentLocation.run()));
        bar.add(Box.createVerticalStrut(4));
        bar.add(fullWidthButton("◉ From saved", e -> onAddFromLibrary.run()));
        bar.add(Box.createVerticalStrut(4));
        // ▤ = note-card glyph for a manual (text-only) step
        bar.add(fullWidthButton("▤ Add manual step", e -> {
            String text = JOptionPane.showInputDialog(this, "Instruction:");
            if (text != null && !text.trim().isEmpty()) store.addManualStep(routeId, text.trim());
        }));
        return bar;
    }

    // Full-width button for the vertical add-step bar: the height is capped so the Y_AXIS
    // BoxLayout does not stretch it, while the width expands to fill the column.
    private JButton fullWidthButton(String text, java.awt.event.ActionListener onClick)
    {
        JButton b = new JButton(text);
        Styles.secondaryButton(b);
        Styles.slim(b);
        b.setAlignmentX(LEFT_ALIGNMENT);
        b.setMaximumSize(Styles.capHeight(b));
        b.addActionListener(onClick);
        return b;
    }

    /** Rebuild the step list from the store. Call after any mutation. */
    void rebuild()
    {
        stepList.removeAll();
        Route r = store.getRouteById(routeId);
        if (r != null)
        {
            RouteStepDragHandler dragHandler = new RouteStepDragHandler(store, routeId);
            summary.setText(summaryText(r));
            title.setText(r.getName());
            int[] legs = RouteDistance.legs(r);
            int i = 0;
            for (RouteStep s : r.getSteps())
            {
                stepList.add(new RouteStepRow(i, legs[i], s,
                    () -> editStep(s),
                    step -> {
                        String[] options = {"Cancel", "Delete"};
                        int choice = JOptionPane.showOptionDialog(this,
                            "Delete this step?", "Delete step",
                            JOptionPane.DEFAULT_OPTION, JOptionPane.WARNING_MESSAGE,
                            null, options, options[0]);
                        if (choice == 1) store.deleteStep(routeId, step.getId());
                    },
                    dragHandler));
                i++;
            }
        }
        stepList.revalidate();
        stepList.repaint();
    }

    /** Header line: stop count, then the straight-line total when there is one. */
    static String summaryText(Route route)
    {
        int stops = RouteDistance.stops(route);
        String text = stops + (stops == 1 ? " stop" : " stops");
        int tiles = RouteDistance.total(route);
        if (tiles > 0) text += String.format(", %,d tiles straight-line", tiles);
        return text;
    }

    private void editStep(RouteStep s)
    {
        JTextField nameField = new JTextField(s.getLabel() == null ? "" : s.getLabel(), 20);
        JTextField boxField = new JTextField(s.getBoxText() == null ? "" : s.getBoxText(), 20);

        JPanel form = new JPanel();
        form.setLayout(new BoxLayout(form, BoxLayout.Y_AXIS));
        form.add(new JLabel("Name (sidebar)"));
        form.add(nameField);
        form.add(Box.createVerticalStrut(8));
        form.add(new JLabel("In-game box text (blank = use name)"));
        form.add(boxField);
        JTextField coordsField = null;
        if (s.getType() == StepType.WAYPOINT)
        {
            coordsField = new JTextField(CoordinateText.format(s.getPackedWorldPoint()), 20);
            form.add(Box.createVerticalStrut(8));
            form.add(new JLabel("Coordinates (x, y or x, y, plane)"));
            form.add(coordsField);
        }

        int result = JOptionPane.showConfirmDialog(this, form, "Edit step",
            JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
        if (result == JOptionPane.OK_OPTION)
        {
            String error = applyStepEdit(store, routeId, s, nameField.getText().trim(),
                boxField.getText().trim(), coordsField == null ? null : coordsField.getText());
            if (error != null)
            {
                JOptionPane.showMessageDialog(this, error, "Edit step",
                    JOptionPane.WARNING_MESSAGE);
            }
        }
    }

    /**
     * Saves the step edit dialog in one store change. {@code coordsText} is null for a manual
     * step; for a waypoint step it moves the step only, and the saved waypoint it was copied
     * from is left alone. Coordinates that do not parse keep the old tile, and the message to
     * show is returned; otherwise null.
     */
    static String applyStepEdit(RouteStore store, UUID routeId, RouteStep step, String name,
        String boxText, String coordsText)
    {
        int packed = WorldPointPacker.UNDEFINED;
        String error = null;
        if (coordsText != null)
        {
            try
            {
                packed = CoordinateText.parse(coordsText);
            }
            catch (IllegalArgumentException ex)
            {
                error = ex.getMessage();
            }
        }
        store.updateStep(routeId, step.getId(), name, boxText, packed);
        return error;
    }
}

package com.waypointer.ui;

import com.waypointer.WaypointerConfig;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.model.route.Route;
import com.waypointer.model.route.RouteStep;
import com.waypointer.model.route.StepType;
import com.waypointer.service.PlayerPosition;
import com.waypointer.service.RoutePlaybackEngine;
import com.waypointer.util.Bearing;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/** Read-only in-game step box. The player never clicks it; advancement is via hotkey / sidebar. */
@Singleton
public class RouteOverlay extends OverlayPanel
{
    private final RoutePlaybackEngine engine;
    private final WaypointerConfig config;
    private final PlayerPosition position;

    @Inject
    public RouteOverlay(RoutePlaybackEngine engine, WaypointerConfig config, PlayerPosition position)
    {
        this.engine = engine;
        this.position = position;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showRouteOverlay()) return null;
        Route r = engine.getActiveRoute();
        if (r == null) return null;

        panelComponent.getChildren().clear();
        panelComponent.getChildren().add(TitleComponent.builder()
            .text(r.getName())
            .build());

        for (String line : buildLines(r, engine.getCurrentIndex(), engine.getLap(), bearing()))
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left(line)
                .leftColor(line.startsWith("Next:") || line.startsWith("Step ")
                    ? Color.LIGHT_GRAY : Color.WHITE)
                .build());
        }
        return super.render(graphics);
    }

    /** Distance and direction to the current waypoint step while aboard, else null. Render runs on
     *  the client thread, so the client reads are safe. */
    @Nullable
    private String bearing()
    {
        RouteStep step = engine.getCurrentStep();
        if (step == null || step.getType() != StepType.WAYPOINT
            || step.getPackedWorldPoint() == WorldPointPacker.UNDEFINED) return null;
        if (!position.isAboard()) return null;
        WorldPoint here = position.current();
        return here == null ? null : Bearing.describe(here, step.getPackedWorldPoint());
    }

    /**
     * Pure display-line builder (testable without a Graphics2D). Returns: a step counter line,
     * the current step's text, the bearing line when given, and a dim "Next:" preview when a following step exists.
     */
    static List<String> buildLines(Route route, int currentIndex, int lap, @Nullable String bearing)
    {
        List<String> lines = new ArrayList<>();
        int total = route.getSteps().size();
        String counter = "Step " + (currentIndex + 1) + " / " + total;
        if (route.isRepeating()) counter += "  -  Lap " + lap;
        lines.add(counter);

        if (currentIndex >= 0 && currentIndex < total)
        {
            lines.add(route.getSteps().get(currentIndex).boxTextOrLabel());
            if (bearing != null) lines.add(bearing);
        }
        int next = currentIndex + 1;
        if (next < total)
        {
            RouteStep n = route.getSteps().get(next);
            lines.add("Next: " + n.boxTextOrLabel());
        }
        return lines;
    }
}

package com.waypointer.ui;

import com.waypointer.model.route.Route;
import com.waypointer.service.RoutePlaybackEngine;
import com.waypointer.util.Text;
import java.awt.BorderLayout;
import java.awt.Dimension;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

/** The running-route card: name, step counter, progress and Back / Next / Stop. Hidden when idle. */
final class RoutePlaybackBar extends JPanel
{
    private final RoutePlaybackEngine engine;
    private final JLabel label = new JLabel();
    private final JButton back = new JButton("Back");
    private final JButton next = new JButton("Next");
    private final JButton stop = new JButton("Stop");
    private final Progress progress = new Progress();

    RoutePlaybackBar(RoutePlaybackEngine engine)
    {
        this.engine = engine;
        setLayout(new BorderLayout(0, 5));
        setOpaque(false);
        // Outer margin plus card padding; see paintComponent.
        setBorder(BorderFactory.createEmptyBorder(
            Styles.CARD_GAP + 6, Styles.SIDE_PAD + 10, 8, Styles.SIDE_PAD + 10));
        setAlignmentX(LEFT_ALIGNMENT);

        label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        add(label, BorderLayout.NORTH);
        add(progress, BorderLayout.CENTER);

        JPanel buttons = new JPanel(new java.awt.GridLayout(1, 3, 4, 0));
        buttons.setOpaque(false);
        Styles.compactSecondaryButton(back);
        Styles.primaryButton(next);
        Styles.compactSecondaryButton(stop);
        next.setBorder(back.getBorder());
        back.setIcon(Glyphs.of(Glyphs.Shape.BACK, java.awt.Color.WHITE, 12));
        next.setIcon(Glyphs.of(Glyphs.Shape.PLAY, java.awt.Color.BLACK, 12));
        next.setHorizontalTextPosition(javax.swing.SwingConstants.LEFT);
        stop.setIcon(Glyphs.of(Glyphs.Shape.STOP, Styles.DELETE_RED, 12));
        back.getAccessibleContext().setAccessibleName("Previous route step");
        next.getAccessibleContext().setAccessibleName("Next route step");
        stop.getAccessibleContext().setAccessibleName("Stop route");
        back.addActionListener(e -> engine.back());
        next.addActionListener(e -> engine.advance());
        stop.addActionListener(e -> engine.stop());
        buttons.add(back);
        buttons.add(next);
        buttons.add(stop);
        add(buttons, BorderLayout.SOUTH);

        setVisible(false);
    }

    @Override
    protected void paintComponent(java.awt.Graphics g)
    {
        Styles.paintInsetCard(g, this, Styles.SIDE_PAD, Styles.CARD_GAP, Styles.SIDE_PAD, 0, null);
    }

    /** One segment per step: green for done, orange for the current one. */
    private static final class Progress extends javax.swing.JComponent
    {
        private int total;
        private int current;

        void set(int total, int current)
        {
            this.total = total;
            this.current = current;
            repaint();
        }

        @Override public Dimension getPreferredSize() { return new Dimension(0, 5); }

        @Override protected void paintComponent(java.awt.Graphics g)
        {
            if (total <= 0) return;
            java.awt.Graphics2D g2 = (java.awt.Graphics2D) g.create();
            g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING,
                java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
            int gap = total > 20 ? 1 : 3;
            double w = (getWidth() - gap * (total - 1)) / (double) total;
            for (int i = 0; i < total; i++)
            {
                g2.setColor(i < current ? ColorScheme.PROGRESS_COMPLETE_COLOR
                    : i == current ? ColorScheme.BRAND_ORANGE : Styles.RAISED);
                int x = (int) Math.round(i * (w + gap));
                g2.fillRoundRect(x, 0, Math.max(2, (int) Math.round(w)), getHeight(), 4, 4);
            }
            g2.dispose();
        }
    }

    void refresh()
    {
        // Read the route once: stop() can null it on the client thread between two reads.
        Route r = engine.getActiveRoute();
        if (r != null)
        {
            String text = "Step " + (engine.getCurrentIndex() + 1) + " / " + r.getSteps().size();
            if (r.isRepeating()) text += "  Lap " + engine.getLap();
            label.setText("<html><b style='color:white'>" + Text.escapeHtml(r.getName()) + "</b><br>"
                + text + "</html>");
            progress.set(r.getSteps().size(), engine.getCurrentIndex());
        }
        setVisible(r != null);
    }

    @Override
    public Dimension getMaximumSize()
    {
        return Styles.capHeight(this);
    }

    String getLabelTextForTest() { return label.getText(); }
    void clickNextForTest() { next.doClick(); }
    void clickBackForTest() { back.doClick(); }
    void clickStopForTest() { stop.doClick(); }
}

package com.waypointer.ui;

import com.waypointer.model.route.Route;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.FlowLayout;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.FontManager;

/** One route row: name + subtitle, with Play / Edit / overflow actions. */
final class RouteRow extends JPanel
{
    RouteRow(Route route, Runnable onPlay, Runnable onEdit, Runnable onOverflow)
    {
        setLayout(new BorderLayout(6, 0));
        setOpaque(false);
        // The bottom inset is the gap to the next card; see paintComponent.
        setBorder(BorderFactory.createEmptyBorder(5, 10, 5 + Styles.CARD_GAP, 4));

        JPanel text = new JPanel(new BorderLayout());
        text.setOpaque(false);
        JLabel name = new JLabel(route.getName());
        name.setForeground(java.awt.Color.WHITE);
        name.setFont(FontManager.getRunescapeBoldFont());
        JLabel sub = new JLabel(subtitle(route));
        sub.setForeground(Styles.MUTED_TEXT);
        sub.setFont(FontManager.getRunescapeSmallFont());
        text.add(name, BorderLayout.NORTH);
        text.add(sub, BorderLayout.SOUTH);
        add(text, BorderLayout.CENTER);

        JPanel actions = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
        actions.setOpaque(false);
        JButton play = new JButton("▶");
        JButton edit = new JButton("✎");
        JButton more = new JButton("⋮");
        Styles.glyphButton(play);
        Styles.glyphButton(edit);
        Styles.glyphButton(more);
        play.getAccessibleContext().setAccessibleName("Play route " + route.getName());
        edit.getAccessibleContext().setAccessibleName("Edit route " + route.getName());
        more.getAccessibleContext().setAccessibleName("More actions for " + route.getName());
        play.addActionListener(e -> onPlay.run());
        edit.addActionListener(e -> onEdit.run());
        more.addActionListener(e -> onOverflow.run());
        actions.add(play);
        actions.add(edit);
        actions.add(more);
        add(actions, BorderLayout.EAST);
    }

    @Override
    protected void paintComponent(java.awt.Graphics g)
    {
        Styles.paintInsetCard(g, this, 0, 0, 0, Styles.CARD_GAP, null);
    }

    static String subtitle(Route r)
    {
        int n = r.getSteps().size();
        String s = n + (n == 1 ? " step" : " steps");
        return r.isRepeating() ? s + "  -  repeating" : s;
    }

    @Override
    public Dimension getMaximumSize() { return Styles.capHeight(this); }
}

package com.waypointer.ui;

import com.waypointer.model.route.Route;
import com.waypointer.model.route.RouteStep;
import com.waypointer.service.RouteStore;
import java.awt.Point;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.StringSelection;
import java.awt.datatransfer.Transferable;
import java.awt.datatransfer.UnsupportedFlavorException;
import java.io.IOException;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseMotionListener;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import javax.swing.JComponent;
import javax.swing.TransferHandler;

/**
 * Drag-to-reorder for route step rows. Payload is "step:&lt;uuid&gt;"; a drop on a target row moves
 * the dragged step to immediately before it via {@link RouteStore#reorderSteps}. Drag fires from
 * the row's grip handle after a 5px threshold so the row's edit/delete buttons still work. A fresh
 * instance is created per editor rebuild because it closes over the route id.
 */
final class RouteStepDragHandler
{
    private static final DataFlavor STR = DataFlavor.stringFlavor;
    private static final String STEP_PREFIX = "step:";
    // 5 px squared: how far the mouse must move before a press becomes a drag.
    private static final int DRAG_THRESHOLD_SQ = 25;

    private final RouteStore store;
    private final UUID routeId;

    RouteStepDragHandler(RouteStore store, UUID routeId)
    {
        this.store = store;
        this.routeId = routeId;
    }

    /** Wires {@code row} as a drop target and {@code dragHandle} as the drag source for {@code stepId}. */
    void attach(JComponent row, JComponent dragHandle, UUID stepId)
    {
        row.setTransferHandler(new TransferHandler()
        {
            @Override public int getSourceActions(JComponent c) { return MOVE; }

            @Override protected Transferable createTransferable(JComponent c)
            {
                return new StringSelection(STEP_PREFIX + stepId);
            }

            @Override public boolean canImport(TransferSupport s)
            {
                if (!s.isDataFlavorSupported(STR)) return false;
                String payload = readPayload(s.getTransferable());
                return payload != null && payload.startsWith(STEP_PREFIX);
            }

            @Override public boolean importData(TransferSupport s)
            {
                String payload = readPayload(s.getTransferable());
                if (payload == null || !payload.startsWith(STEP_PREFIX)) return false;
                UUID dragged = UUID.fromString(payload.substring(STEP_PREFIX.length()));
                if (dragged.equals(stepId)) return false;
                moveBefore(dragged, stepId);
                return true;
            }
        });

        DragGesture gesture = new DragGesture(row);
        dragHandle.addMouseListener(gesture);
        dragHandle.addMouseMotionListener(gesture);
    }

    // Move dragged to immediately before target, then push the new order to the store.
    private void moveBefore(UUID dragged, UUID target)
    {
        Route r = store.getRouteById(routeId);
        if (r == null) return;
        List<UUID> order = new ArrayList<>();
        for (RouteStep s : r.getSteps()) order.add(s.getId());
        int from = order.indexOf(dragged);
        if (from < 0) return;
        order.remove(from);
        int to = order.indexOf(target);
        if (to < 0) return;
        order.add(to, dragged);
        store.reorderSteps(routeId, order);
    }

    private static String readPayload(Transferable t)
    {
        if (t == null) return null;
        try { return (String) t.getTransferData(STR); }
        catch (UnsupportedFlavorException | IOException e) { return null; }
    }

    // Starts a drag from the handle once the mouse moves past the threshold; until then a press
    // is just a click so the grip does not swallow taps.
    private final class DragGesture extends MouseAdapter implements MouseMotionListener
    {
        private final JComponent dragSource;
        private Point pressPoint;
        private boolean dragStarted;

        DragGesture(JComponent dragSource) { this.dragSource = dragSource; }

        @Override public void mousePressed(MouseEvent e) { pressPoint = e.getPoint(); dragStarted = false; }

        @Override public void mouseReleased(MouseEvent e) { pressPoint = null; dragStarted = false; }

        @Override public void mouseDragged(MouseEvent e)
        {
            if (pressPoint == null || dragStarted) return;
            int dx = e.getX() - pressPoint.x;
            int dy = e.getY() - pressPoint.y;
            if (dx * dx + dy * dy >= DRAG_THRESHOLD_SQ)
            {
                dragStarted = true;
                TransferHandler th = dragSource.getTransferHandler();
                if (th != null) th.exportAsDrag(dragSource, e, TransferHandler.MOVE);
            }
        }

        @Override public void mouseMoved(MouseEvent e) { }
    }
}

package com.waypointer.ui;

import com.waypointer.model.route.RouteStep;
import com.waypointer.model.route.StepType;
import java.awt.BorderLayout;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * One step row in {@link RouteEditorPanel}: grip + index + type glyph + label, with edit and
 * delete buttons. Drag the grip to reorder; click the pencil (or the label) to edit.
 */
final class RouteStepRow extends JPanel
{
    // ◉ = filled circle (WAYPOINT), ▤ = note card (MANUAL), ⠿ = drag grip,
    // ✎ = pencil (edit), ✕ = multiply/close (delete)
    private static final String GLYPH_WAYPOINT = "◉";
    private static final String GLYPH_MANUAL   = "▤";
    private static final String GLYPH_GRIP     = "⠿";
    private static final String GLYPH_EDIT     = "✎";
    private static final String GLYPH_DELETE   = "✕";

    /** Text for the distance from the previous stop, or null when there is none to show. */
    static String legText(int leg)
    {
        return leg < 0 ? null : String.format(leg == 1 ? "%,d tile" : "%,d tiles", leg);
    }

    RouteStepRow(int index, int leg, RouteStep step, Runnable onEdit, Consumer<RouteStep> onDelete,
        RouteStepDragHandler dragHandler)
    {
        setLayout(new BorderLayout(6, 0));
        setOpaque(false);
        setBorder(BorderFactory.createEmptyBorder(4, 8, 3, 4));

        // Grip handle (west): dragging it past the threshold starts a reorder.
        JLabel grip = new JLabel(GLYPH_GRIP);
        grip.setFont(FontManager.getRunescapeSmallFont());
        grip.setForeground(Styles.FAINT_TEXT);
        grip.setCursor(Cursor.getPredefinedCursor(Cursor.MOVE_CURSOR));
        grip.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 4));
        add(grip, BorderLayout.WEST);

        String labelText = step.getLabel() == null || step.getLabel().isEmpty()
            ? "(empty)" : step.getLabel();
        JLabel text = new JLabel((index + 1) + ". " + stepGlyph(step.getType()) + "  " + labelText);
        text.setFont(FontManager.getRunescapeSmallFont());
        text.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        // Long instructions are cut off by the panel width; the tooltip carries the rest.
        text.setToolTipText(labelText);
        text.addMouseListener(new java.awt.event.MouseAdapter()
        {
            @Override public void mouseClicked(java.awt.event.MouseEvent e) { onEdit.run(); }
        });

        // The leg distance sits on its own line under the label so it cannot crowd the buttons.
        JPanel center = new JPanel();
        center.setLayout(new BoxLayout(center, BoxLayout.Y_AXIS));
        center.setOpaque(false);
        text.setAlignmentX(LEFT_ALIGNMENT);
        center.add(text);
        String legText = legText(leg);
        if (legText != null)
        {
            JLabel legLabel = new JLabel(legText);
            legLabel.setFont(FontManager.getRunescapeSmallFont());
            legLabel.setForeground(Styles.MUTED_TEXT);
            legLabel.setAlignmentX(LEFT_ALIGNMENT);
            legLabel.setBorder(BorderFactory.createEmptyBorder(0, 14, 0, 0));
            center.add(legLabel);
        }
        add(center, BorderLayout.CENTER);

        // East: edit (pencil) then delete (x). Pencil is the primary, visible edit affordance.
        JPanel actions = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
        actions.setOpaque(false);

        JButton edit = new JButton(GLYPH_EDIT);
        Styles.glyphButton(edit);
        edit.getAccessibleContext().setAccessibleName("Edit step");
        edit.addActionListener(e -> onEdit.run());
        actions.add(edit);

        JButton del = new JButton(GLYPH_DELETE);
        Styles.glyphButton(del);
        del.getAccessibleContext().setAccessibleName("Delete step");
        del.addActionListener(e -> onDelete.accept(step));
        actions.add(del);

        add(actions, BorderLayout.EAST);

        dragHandler.attach(this, grip, step.getId());
    }

    // The step card behind the rows supplies the background; each row draws the line above it.
    @Override
    protected void paintComponent(java.awt.Graphics g)
    {
        g.setColor(Styles.ROW_LINE);
        g.fillRect(8, 0, getWidth() - 16, 1);
    }

    static String stepGlyph(StepType type)
    {
        return type == StepType.WAYPOINT ? GLYPH_WAYPOINT : GLYPH_MANUAL;
    }

    @Override
    public Dimension getMaximumSize() { return Styles.capHeight(this); }
}

package com.waypointer.ui;

