/** The Routes tab body: a list of routes, a playback bar, and create/edit nav. */
@Singleton
public class RoutesPanel extends JPanel
{
    private static final String CARD_LIST = "list";
    private static final String CARD_EDITOR = "editor";

    private final RouteStore store;
    private final RoutePlaybackEngine engine;
    private final RouteRecorder recorder;
    private final RouteShareCodec shareCodec;
    private final com.waypointer.service.WaypointStore waypointStore;
    private final RouteStorePersistence persistence;
    private final RoutePlaybackBar playbackBar;

    private final CardLayout cards = new CardLayout();
    private final JPanel cardHost = new JPanel(cards);
    private final JPanel listCard = new JPanel(new BorderLayout());
    private final JPanel routeList = new JPanel();
    private final JPanel editorHost = new JPanel(new BorderLayout());
    private final InlineInputForm inlineForm = new InlineInputForm();

    private final javax.swing.JScrollBar routeListScrollBar;
    private Listeners.Subscription storeSub;
    private Listeners.Subscription engineSub;
    private RouteEditorPanel openEditor;
    private Toasts toasts = Toasts.NO_OP;

    @Inject
    public RoutesPanel(RouteStore store, RoutePlaybackEngine engine, RouteRecorder recorder,
        RouteShareCodec shareCodec, com.waypointer.service.WaypointStore waypointStore,
        RouteStorePersistence persistence)
    {
        this.store = store;
        this.engine = engine;
        this.recorder = recorder;
        this.shareCodec = shareCodec;
        this.waypointStore = waypointStore;
        this.persistence = persistence;
        this.playbackBar = new RoutePlaybackBar(engine);

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel north = new JPanel();
        north.setLayout(new BoxLayout(north, BoxLayout.Y_AXIS));
        north.setBackground(ColorScheme.DARK_GRAY_COLOR);
        playbackBar.setAlignmentX(LEFT_ALIGNMENT);
        north.add(playbackBar);
        add(north, BorderLayout.NORTH);

        routeList.setLayout(new BoxLayout(routeList, BoxLayout.Y_AXIS));
        routeList.setBackground(ColorScheme.DARK_GRAY_COLOR);
        routeList.setBorder(BorderFactory.createEmptyBorder(0, Styles.SIDE_PAD, 0, Styles.SIDE_PAD - 2));
        listCard.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel listNorth = new JPanel();
        listNorth.setLayout(new BoxLayout(listNorth, BoxLayout.Y_AXIS));
        listNorth.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JPanel listHeader = buildListHeader();
        listHeader.setAlignmentX(LEFT_ALIGNMENT);
        listNorth.add(listHeader);
        inlineForm.setAlignmentX(LEFT_ALIGNMENT);
        listNorth.add(inlineForm);
        listCard.add(listNorth, BorderLayout.NORTH);

        // The panel is built before RuneLiteLAF installs, so pin the dark scrollbar now and
        // re-derive it from startUp() via refreshScrollbarStyling() once the LAF is live.
        javax.swing.JScrollPane listScroll = Styles.pinnedScrollPane(Styles.sidebarWidthHolder(routeList));
        this.routeListScrollBar = listScroll.getVerticalScrollBar();
        listCard.add(listScroll, BorderLayout.CENTER);

        editorHost.setBackground(ColorScheme.DARK_GRAY_COLOR);

        cardHost.add(listCard, CARD_LIST);
        cardHost.add(editorHost, CARD_EDITOR);
        add(cardHost, BorderLayout.CENTER);

        storeSub = store.subscribe(() -> SwingUtilities.invokeLater(this::rebuildList));
        engineSub = engine.subscribe(() -> SwingUtilities.invokeLater(playbackBar::refresh));

        rebuildList();
        playbackBar.refresh();
        cards.show(cardHost, CARD_LIST);
    }

    private JPanel buildListHeader()
    {
        JPanel header = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 4));
        header.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JButton create = new JButton("New route");
        Styles.secondaryButton(create);
        Styles.slim(create);
        create.addActionListener(e -> openNewRouteForm());
        header.add(create);

        JButton importBtn = new JButton("Import");
        Styles.secondaryButton(importBtn);
        Styles.slim(importBtn);
        importBtn.addActionListener(e -> openImportForm());
        header.add(importBtn);
        return header;
    }

    private void rebuildList()
    {
        routeList.removeAll();
        if (persistence.isRefusingSaves())
        {
            routeList.add(PanelBanners.routeLoadFailedReset(persistence, store, this));
        }
        for (Route r : store.getRoutesOrdered())
        {
            UUID id = r.getId();
            routeList.add(new RouteRow(r,
                () -> engine.start(store.getRouteById(id)),
                () -> openEditorFor(id),
                () -> showOverflow(id)));
        }
        if (openEditor != null) openEditor.rebuild();
        routeList.revalidate();
        routeList.repaint();
    }

    private void openEditorFor(UUID routeId)
    {
        editorHost.removeAll();
        openEditor = new RouteEditorPanel(store, routeId, this::showList,
            () -> recorder.addCurrentLocationTo(routeId),
            () -> addFromLibrary(routeId));
        editorHost.add(openEditor, BorderLayout.CENTER);
        editorHost.revalidate();
        editorHost.repaint();
        cards.show(cardHost, CARD_EDITOR);
    }

    private void showList()
    {
        openEditor = null;
        cards.show(cardHost, CARD_LIST);
        rebuildList();
    }

    private void showOverflow(UUID routeId)
    {
        JPopupMenu menu = new JPopupMenu();
        menu.add(menuItem("Export (copy code)", () -> exportToClipboard(routeId)));
        menu.add(menuItem("Rename", () -> {
            Route r = store.getRouteById(routeId);
            String name = JOptionPane.showInputDialog(this, "Rename route:", r == null ? "" : r.getName());
            if (name != null && !name.trim().isEmpty()) store.renameRoute(routeId, name.trim());
        }));
        menu.add(menuItem("Duplicate", () -> store.duplicateRoute(routeId)));
        menu.add(menuItem("Delete", () -> {
            Route r = store.getRouteById(routeId);
            String name = r == null ? "this route" : "'" + r.getName() + "'";
            String[] options = {"Cancel", "Delete"};
            int choice = JOptionPane.showOptionDialog(this,
                "Delete " + name + "? This cannot be undone.",
                "Delete route", JOptionPane.DEFAULT_OPTION, JOptionPane.WARNING_MESSAGE,
                null, options, options[0]);
            if (choice == 1) store.deleteRoute(routeId);
        }));
        menu.show(this, getWidth() / 2, 40);
    }

    private void exportToClipboard(UUID routeId)
    {
        Route r = store.getRouteById(routeId);
        if (r == null) return;
        String code = shareCodec.encodeRoute(r);
        java.awt.Toolkit.getDefaultToolkit().getSystemClipboard()
            .setContents(new java.awt.datatransfer.StringSelection(code), null);
        toasts.show("Route code copied to clipboard.");
    }

    private void openNewRouteForm()
    {
        inlineForm.openFor("New route", "Create", name ->
        {
            Route r = store.createRoute(name);
            openEditorFor(r.getId());
            return null;
        });
    }

    private void openImportForm()
    {
        inlineForm.openFor("Import route", "Import", this::importRouteFromCode);
    }

    /** Submit handler for the import form: returns an inline error message, or null on success. */
    private String importRouteFromCode(String code)
    {
        final Route imported;
        try
        {
            imported = shareCodec.decodeRoute(code);
        }
        catch (RouteShareCodec.MalformedCodeException ex)
        {
            return "Not a readable route code (expected RT1:).";
        }
        // Re-create through the store so the imported route gets fresh ids and persists.
        Route created = store.createRoute(imported.getName());
        store.setRepeating(created.getId(), imported.isRepeating());
        for (RouteStep s : imported.getSteps())
        {
            if (s.getType() == StepType.WAYPOINT)
            {
                store.addWaypointStep(created.getId(), s.getPackedWorldPoint(), s.getLabel(), null);
            }
            else
            {
                store.addManualStep(created.getId(), s.getLabel());
            }
        }
        toasts.show("Imported route: " + imported.getName());
        return null;
    }

    /**
     * Pick saved waypoints (or whole categories) from the library and append them as route
     * steps, snapshotting the tile + name and recording the source waypoint id (hybrid
     * sourcing: snapshot is authoritative, so deleting the library waypoint never breaks the
     * route).
     */
    private void addFromLibrary(UUID routeId)
    {
        if (waypointStore.getLibrary().getWaypoints().isEmpty())
        {
            toasts.show("No saved waypoints to choose from.");
            return;
        }
        new LibraryPickerDialog(SwingUtilities.getWindowAncestor(this), waypointStore.getLibrary(),
            picked -> addPickedWaypoints(routeId, picked)).setVisible(true);
    }

    /** Appends the picked waypoints to the route in the order given, as one change. */
    void addPickedWaypoints(UUID routeId, java.util.List<com.waypointer.model.Waypoint> picked)
    {
        if (picked == null || picked.isEmpty()) return;
        store.addWaypointSteps(routeId, picked);
    }

    private static JMenuItem menuItem(String text, Runnable action)
    {
        JMenuItem item = new JMenuItem(text);
        item.addActionListener(e -> action.run());
        return item;
    }

    /** Re-derive the dark scrollbar styling once RuneLiteLAF is live (called from startUp). */
    public void refreshScrollbarStyling()
    {
        SwingUtilities.invokeLater(() -> Styles.reapplyScrollbarPin(routeListScrollBar));
    }

    /** Called from the plugin shutDown to release subscriptions. */
    public void dispose()
    {
        if (storeSub != null) { storeSub.close(); storeSub = null; }
        if (engineSub != null) { engineSub.close(); engineSub = null; }
    }

    /** Injected by {@link TabHost} after the shared overlay is built. */
    void setToasts(Toasts toasts)
    {
        this.toasts = toasts == null ? Toasts.NO_OP : toasts;
    }

    // Test seams.
    Toasts getToastsForTest() { return toasts; }
    void addFromLibraryForTest(UUID routeId) { addFromLibrary(routeId); }
    void openNewRouteFormForTest() { openNewRouteForm(); }
    void openImportFormForTest() { openImportForm(); }
    InlineInputForm inlineFormForTest() { return inlineForm; }

    @Override public Dimension getPreferredSize() { return new Dimension(PluginPanel.PANEL_WIDTH, 0); }
    @Override public Dimension getMinimumSize() { return new Dimension(PluginPanel.PANEL_WIDTH, 0); }
}

package com.waypointer.ui;

import com.waypointer.sailing.SailingBoatPin;
import com.waypointer.sailing.SailingBoats;
import java.util.Collections;
import java.util.List;
import javax.swing.ButtonGroup;
import javax.swing.JMenu;
import javax.swing.JMenuItem;
import javax.swing.JRadioButtonMenuItem;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;

/** The boat choice for sea trips, offered as a submenu of the panel menu. Reads the live boat
 *  list on the client thread and keeps the last result for the menu. The persisted choice is
 *  the boat slot. */
public class SailingControls
{
    static final String MENU_TITLE = "Boat for sea trips";
    static final String NEAREST = "Nearest to the waypoint";

    private final SailingBoats boats;
    private final SailingBoatPin pin;
    private final Client client;
    private final ClientThread clientThread;

    private List<SailingBoats.BoatInfo> moored = Collections.emptyList();
    private boolean pinned;
    private int pinnedSlot = -1;
    private boolean visible;

    public SailingControls(SailingBoats boats, SailingBoatPin pin, Client client, ClientThread clientThread)
    {
        this.boats = boats;
        this.pin = pin;
        this.client = client;
        this.clientThread = clientThread;
    }

    /** Whether the menu entry is offered. The panel turns it on only when sea trips can run. */
    public boolean isVisible() { return visible; }

    public void setVisible(boolean visible) { this.visible = visible; }

    /** Re-read the live boats and the saved pin. Call from the panel rebuild. Does nothing
     *  until the player is logged in, since the boat varbits mean nothing before then. */
    public void refresh()
    {
        if (client.getGameState() != GameState.LOGGED_IN) return;
        clientThread.invoke(() -> {
            List<SailingBoats.BoatInfo> list = boats.mooredBoats();
            boolean enabled = pin.isEnabled();
            int slot = pin.slot();
            SwingUtilities.invokeLater(() -> render(list, enabled, slot));
            return true;
        });
    }

    void render(List<SailingBoats.BoatInfo> moored, boolean enabled, int savedSlot)
    {
        this.moored = moored;
        this.pinned = enabled;
        this.pinnedSlot = savedSlot;
    }

    /** The submenu: the default choice first, then one entry per moored boat. */
    JMenu buildMenu()
    {
        JMenu menu = new JMenu(MENU_TITLE);
        ButtonGroup group = new ButtonGroup();

        JRadioButtonMenuItem nearest = new JRadioButtonMenuItem(NEAREST, !pinned);
        nearest.addActionListener(e -> choose(false, -1, ""));
        group.add(nearest);
        menu.add(nearest);

        if (moored.isEmpty())
        {
            JMenuItem none = new JMenuItem("No boats moored at a port");
            none.setEnabled(false);
            menu.add(none);
            return menu;
        }
        menu.addSeparator();
        for (SailingBoats.BoatInfo b : moored)
        {
            JRadioButtonMenuItem item = new JRadioButtonMenuItem(
                b.name + " (" + b.dock.getDockName() + ")", pinned && b.slot == pinnedSlot);
            // The journey compares the bare boat name, so that is what gets stored.
            item.addActionListener(e -> choose(true, b.slot, b.name));
            group.add(item);
            menu.add(item);
        }
        return menu;
    }

    private void choose(boolean enabled, int slot, String name)
    {
        pinned = enabled;
        pinnedSlot = slot;
        pin.set(enabled, slot, name);
    }
}

package com.waypointer.ui;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import javax.swing.Timer;

/**
 * Spring-load auto-expand during a drag: hovering a collapsed category header schedules a
 * transient expand after a short delay, and drags that drift away or end revert it. Extracted
 * from {@link DragAndDropHandler} so the transfer-handler code stays focused on drop routing.
 * Per-cycle: a fresh controller is created with each handler on panel rebuild.
 */
final class SpringLoadController
{
    private static final int AUTO_EXPAND_DELAY_MS = 600;

    private final AutoExpandController autoExpand = new AutoExpandController();
    private final Map<UUID, CategorySection> sectionsByCategoryId = new HashMap<>();
    private Timer pendingExpandTimer;
    private CategorySection pendingExpandTarget;

    void register(UUID categoryId, CategorySection section)
    {
        sectionsByCategoryId.put(categoryId, section);
    }

    /** Hover bookkeeping for a target in {@code categoryId}; reverts sections drifted out of. */
    void onHover(UUID categoryId)
    {
        revert(autoExpand.onHover(categoryId));
    }

    void scheduleExpand(CategorySection section)
    {
        if (pendingExpandTarget == section) return;
        cancelExpand();
        pendingExpandTarget = section;
        pendingExpandTimer = new Timer(AUTO_EXPAND_DELAY_MS, e ->
        {
            section.setExpandedTransient(true);
            autoExpand.recordTransientExpand(section.getCategoryId());
            pendingExpandTimer = null;
            pendingExpandTarget = null;
        });
        pendingExpandTimer.setRepeats(false);
        pendingExpandTimer.start();
    }

    void cancelExpand()
    {
        if (pendingExpandTimer != null)
        {
            pendingExpandTimer.stop();
            pendingExpandTimer = null;
        }
        pendingExpandTarget = null;
    }

    void onDragEnd()
    {
        cancelExpand();
        revert(autoExpand.onDragEnd());
    }

    void resolveOnDrop(UUID destCategoryId)
    {
        cancelExpand();
        AutoExpandController.DropResolution r = autoExpand.onDropAt(destCategoryId);
        revert(r.getToRevert());
        if (r.getToConfirm() != null)
        {
            CategorySection s = sectionsByCategoryId.get(r.getToConfirm());
            if (s != null) s.confirmTransientExpand();
        }
    }

    private void revert(Set<UUID> ids)
    {
        for (UUID id : ids)
        {
            CategorySection s = sectionsByCategoryId.get(id);
            if (s != null) s.setExpandedTransient(false);
        }
    }
}

package com.waypointer.ui;

import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import net.runelite.client.game.SpriteManager;

// Process-wide ImageIcon cache keyed by sprite id. The full panel rebuild on every mutation
// creates fresh JLabels; without this cache, each row re-fires getSpriteAsync and re-allocates
// an ImageIcon for an already-decoded image. Unbounded: sprite count tops out around 1700.
final class SpriteIcons
{
    private static final Map<Integer, ImageIcon> CACHE = new ConcurrentHashMap<>();

    private SpriteIcons() {}

    // Synchronous on cache hit; on miss, falls back to spriteManager.getSpriteAsync and
    // populates the cache on success. Safe from the EDT.
    static void apply(JLabel label, int spriteId, SpriteManager spriteManager)
    {
        ImageIcon hit = CACHE.get(spriteId);
        if (hit != null)
        {
            label.setIcon(hit);
            return;
        }
        if (spriteManager == null) return;
        spriteManager.getSpriteAsync(spriteId, 0, (BufferedImage img) -> {
            if (img == null) return;
            ImageIcon icon = new ImageIcon(img);
            CACHE.put(spriteId, icon);
            SwingUtilities.invokeLater(() -> {
                label.setIcon(icon);
                label.revalidate();
                label.repaint();
            });
        });
    }
}

