import java.awt.event.MouseListener;
import javax.swing.BorderFactory;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JLayeredPane;
import javax.swing.JPanel;
import javax.swing.Timer;
import javax.swing.border.Border;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Floating-toast host. Wraps a piece of panel content in a JLayeredPane so a
 * confirmation card can appear over the content without consuming layout space.
 * Implements {@link Toasts} so callers depend on the small API rather than the
 * Swing internals.
 */
public final class ToastOverlay extends JLayeredPane implements Toasts
{
    private static final int MARGIN_PX = 8;
    private static final int DEFAULT_DURATION_MS = 2500;
    private static final int ACTION_DURATION_MS = 6000;
    private static final int ANIMATION_FRAMES = 12;
    private static final int ANIMATION_FRAME_DELAY_MS = 15;

    private final JComponent content;
    private final JPanel card = new JPanel();
    private final JLabel message = new JLabel();
    private final JLabel actionLabel = new JLabel();
    private Timer autoHideTimer;
    private int entryAnimationCount;
    private Timer entryTimer;
    private int entryStartY;
    private int entryTargetY;
    private int entryFrame;
    private int currentCardY = -1;
    private static final int PULSE_DURATION_MS = 120;
    private static final Color RESTING_BORDER_COLOR = ColorScheme.LIGHT_GRAY_COLOR;
    private Timer pulseTimer;
    private int pulseCount;

    public ToastOverlay(JComponent content)
    {
        this.content = content;
        setLayout(null);
        add(content, JLayeredPane.DEFAULT_LAYER);

        card.setLayout(new BorderLayout(8, 0));
        card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        card.setBorder(cardBorder(RESTING_BORDER_COLOR));

        message.setFont(FontManager.getRunescapeSmallFont());
        card.add(message, BorderLayout.CENTER);

        actionLabel.setForeground(ColorScheme.BRAND_ORANGE);
        actionLabel.setFont(FontManager.getRunescapeSmallFont());
        actionLabel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        actionLabel.setVisible(false);
        card.add(actionLabel, BorderLayout.EAST);

        add(card, JLayeredPane.POPUP_LAYER);
        card.setVisible(false);
    }

    // A control that floats over the bottom-right corner of the content (the Mark button).
    // Toasts land above it.
    private JComponent floating;
    private int floatingRightInset;

    void setFloating(JComponent c, int rightInset)
    {
        floating = c;
        floatingRightInset = rightInset;
        add(c, JLayeredPane.PALETTE_LAYER);
        revalidate();
    }

    private int floatingReserve()
    {
        return floating != null && floating.isVisible() ? floating.getPreferredSize().height + MARGIN_PX : 0;
    }

    @Override
    public void doLayout()
    {
        Dimension size = getSize();
        content.setBounds(0, 0, size.width, size.height);
        if (floating != null)
        {
            Dimension f = floating.getPreferredSize();
            floating.setBounds(size.width - f.width - floatingRightInset, size.height - f.height - MARGIN_PX,
                f.width, f.height);
        }
        if (card.isVisible()) positionCard();
    }

    @Override public Dimension getPreferredSize() { return content.getPreferredSize(); }
    @Override public Dimension getMinimumSize() { return content.getMinimumSize(); }

    private void positionCard()
    {
        Dimension size = getSize();
        if (size.width <= 0 || size.height <= 0) return;
        Dimension pref = card.getPreferredSize();
        int cardWidth = Math.max(0, size.width - 2 * MARGIN_PX);
        entryTargetY = Math.max(0, size.height - pref.height - MARGIN_PX - floatingReserve());
        if (currentCardY < 0) currentCardY = entryTargetY;
        card.setBounds(MARGIN_PX, currentCardY, cardWidth, pref.height);
    }

    private void presentEntry()
    {
        if (card.isVisible())
        {
            // Replace-in-place: the card stays put, so a slide would be invisible. Flash the
            // border to brand orange briefly so two quick actions don't read as one.
            pulse();
            return;
        }
        entryAnimationCount++;
        Dimension size = getSize();
        Dimension pref = card.getPreferredSize();
        entryStartY = size.height; // just below the visible area
        currentCardY = entryStartY;
        card.setBounds(MARGIN_PX, currentCardY, Math.max(0, size.width - 2 * MARGIN_PX), pref.height);
        entryFrame = 0;

        if (entryTimer != null && entryTimer.isRunning()) entryTimer.stop();
        entryTimer = new Timer(ANIMATION_FRAME_DELAY_MS, e -> {
            entryFrame++;
            double t = Math.min(1.0, (double) entryFrame / ANIMATION_FRAMES);
            currentCardY = (int) Math.round(entryStartY + (entryTargetY - entryStartY) * t);
            card.setLocation(MARGIN_PX, currentCardY);
            if (entryFrame >= ANIMATION_FRAMES) ((Timer) e.getSource()).stop();
        });
        entryTimer.start();
    }

    private static Border cardBorder(Color line)
    {
        return BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(line, 1),
            BorderFactory.createEmptyBorder(8, 12, 8, 12));
    }

    private void pulse()
    {
        pulseCount++;
        card.setBorder(cardBorder(ColorScheme.BRAND_ORANGE));
        if (pulseTimer != null && pulseTimer.isRunning()) pulseTimer.stop();
        pulseTimer = new Timer(PULSE_DURATION_MS, e -> card.setBorder(cardBorder(RESTING_BORDER_COLOR)));
        pulseTimer.setRepeats(false);
        pulseTimer.start();
    }

    private void restartAutoHide(int durationMs)
    {
        if (autoHideTimer != null && autoHideTimer.isRunning()) autoHideTimer.stop();
        autoHideTimer = new Timer(durationMs, e -> card.setVisible(false));
        autoHideTimer.setRepeats(false);
        autoHideTimer.start();
    }

    @Override
    public void show(String text)
    {
        show(text, Severity.SUCCESS);
    }

    @Override
    public void show(String text, Severity severity)
    {
        applyMessage(text, severity);
        actionLabel.setVisible(false);
        positionCard();
        presentEntry();
        card.setVisible(true);
        restartAutoHide(DEFAULT_DURATION_MS);
    }

    @Override
    public void show(String text, String actionLabel, Runnable onClick)
    {
        show(text, actionLabel, onClick, Severity.SUCCESS);
    }

    @Override
    public void show(String text, String actionLabelText, Runnable onClick, Severity severity)
    {
        applyMessage(text, severity);
        this.actionLabel.setText("<html><u>" + Text.escapeHtml(actionLabelText) + "</u></html>");
        this.actionLabel.setVisible(true);

        // Replace any previous listener so a stale runnable from the prior toast doesn't fire.
        for (MouseListener l : this.actionLabel.getMouseListeners())
        {
            this.actionLabel.removeMouseListener(l);
        }
        this.actionLabel.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseClicked(MouseEvent e)
            {
                if (autoHideTimer != null) autoHideTimer.stop();
                card.setVisible(false);
                if (onClick != null) onClick.run();
            }
        });

        positionCard();
        presentEntry();
        card.setVisible(true);
        restartAutoHide(ACTION_DURATION_MS);
    }

    private void applyMessage(String text, Severity severity)
    {
        message.setForeground(colorFor(severity));
        String glyph = glyphFor(severity);
        message.setText("<html>" + Text.escapeHtml(glyph + "  " + text) + "</html>");
    }

    private static Color colorFor(Severity severity)
    {
        switch (severity)
        {
            case WARN:  return ColorScheme.BRAND_ORANGE;
            case ERROR: return ColorScheme.PROGRESS_ERROR_COLOR;
            case SUCCESS:
            default:    return ColorScheme.PROGRESS_COMPLETE_COLOR;
        }
    }

    private static String glyphFor(Severity severity)
    {
        switch (severity)
        {
            case WARN:  return "⚠"; // U+26A0 warning sign
            case ERROR: return "✕"; // U+2715 multiplication X
            case SUCCESS:
            default:    return "✓"; // U+2713 check mark
        }
    }

    boolean cardIsVisibleForTest() { return card.isVisible(); }
    String cardLabelTextForTest() { return message.getText(); }
    Timer autoHideTimerForTest() { return autoHideTimer; }
    JLabel actionLabelForTest() { return actionLabel; }
    int entryAnimationCountForTest() { return entryAnimationCount; }
    int pulseCountForTest() { return pulseCount; }

    int cardCurrentYForTest()
    {
        return card.getY();
    }

    void completeEntryAnimationForTest()
    {
        if (entryTimer == null) return;
        while (entryFrame < ANIMATION_FRAMES)
        {
            entryFrame++;
            double t = Math.min(1.0, (double) entryFrame / ANIMATION_FRAMES);
            currentCardY = (int) Math.round(entryStartY + (entryTargetY - entryStartY) * t);
            card.setLocation(MARGIN_PX, currentCardY);
        }
        entryTimer.stop();
    }
}

package com.waypointer.ui;

/**
 * Surface used by callers that want to display a transient confirmation message.
 * Decouples those callers from the JLayeredPane-based ToastOverlay implementation
 * and lets tests substitute a capturing fake.
 */
public interface Toasts
{
    /**
     * Visual treatment for a toast: drives the message colour and the leading glyph
     * the {@link ToastOverlay} prepends. Callers that don't care about styling can
     * use the non-severity overloads, which default to {@link #SUCCESS}.
     */
    enum Severity { SUCCESS, WARN, ERROR }

    /** Show a self-dismissing message with the default short duration. */
    void show(String text);

    /**
     * Show a message with a clickable action label (e.g. "Undo"). The message
     * stays on screen longer so the user has time to click. Clicking the label
     * runs onClick and hides the toast immediately.
     */
    void show(String text, String actionLabel, Runnable onClick);

    /** Severity-flavoured variant. Default routes to {@link #show(String)} so legacy implementations still compile. */
    default void show(String text, Severity severity) { show(text); }

    /** Severity-flavoured variant with an action label. */
    default void show(String text, String actionLabel, Runnable onClick, Severity severity)
    {
        show(text, actionLabel, onClick);
    }

    /** Drop-in target for components that don't have a real overlay wired yet. */
    Toasts NO_OP = new Toasts()
    {
        @Override public void show(String text) {}
        @Override public void show(String text, String actionLabel, Runnable onClick) {}
    };
}

package com.waypointer.ui;

import java.awt.BasicStroke;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;
import net.runelite.client.ui.ColorScheme;

/** A three-state checkbox painted by hand so it stays font- and LAF-independent. */
final class TriStateBox extends JComponent
{
    enum State { UNCHECKED, CHECKED, PARTIAL }

    private static final int SIZE = 14;
    private State state = State.UNCHECKED;

    TriStateBox()
    {
        Dimension d = new Dimension(SIZE, SIZE);
        setPreferredSize(d);
        setMinimumSize(d);
        setMaximumSize(d);
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        setOpaque(false);
    }

    void setState(State s) { this.state = s; repaint(); }

    @Override protected void paintComponent(Graphics g)
    {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setColor(ColorScheme.DARKER_GRAY_COLOR);
        g2.fillRect(0, 0, SIZE - 1, SIZE - 1);
        g2.setColor(ColorScheme.LIGHT_GRAY_COLOR);
        g2.drawRect(0, 0, SIZE - 1, SIZE - 1);
        if (state == State.CHECKED)
        {
            g2.setColor(ColorScheme.BRAND_ORANGE);
            g2.setStroke(new BasicStroke(2f));
            g2.drawLine(3, 7, 6, 10);
            g2.drawLine(6, 10, 11, 3);
        }
        else if (state == State.PARTIAL)
        {
            g2.setColor(ColorScheme.BRAND_ORANGE);
            g2.fillRect(4, 4, SIZE - 8, SIZE - 8);
        }
        g2.dispose();
    }
}

package com.waypointer.ui;

import com.waypointer.model.Category;
import com.waypointer.model.Library;
import com.waypointer.model.Waypoint;
import com.waypointer.service.LibraryViews;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;

/**
 * Pure selection state behind {@link WaypointTreePicker}. The set of checked waypoints is the
 * source of truth; a separate set tracks explicitly-checked empty categories, which have no
 * child waypoint to carry the signal. A category's tri-state is derived from its children. No
 * Swing imports; fully unit-testable.
 */
final class WaypointPickerModel
{
    enum Tri { CHECKED, UNCHECKED, PARTIAL }

    private final List<Category> orderedCategories;
    private final Map<UUID, List<Waypoint>> waypointsByCategory;
    private final Set<UUID> checkedWaypoints = new HashSet<>();
    private final Set<UUID> checkedEmptyCategories = new HashSet<>();

    /** Builds a model from {@code library} with every waypoint and every empty category checked. */
    WaypointPickerModel(Library library)
    {
        this.waypointsByCategory = new HashMap<>();
        for (Waypoint w : library.getWaypoints())
        {
            waypointsByCategory.computeIfAbsent(w.getCategoryId(), k -> new ArrayList<>()).add(w);
            checkedWaypoints.add(w.getId());
        }
        Map<UUID, Category> categoriesById = new HashMap<>();
        for (Category c : library.getCategories()) categoriesById.put(c.getId(), c);
        for (Map.Entry<UUID, List<Waypoint>> e : waypointsByCategory.entrySet())
        {
            // Same order the main panel shows for the category's sort mode.
            Category cat = categoriesById.get(e.getKey());
            e.getValue().sort(LibraryViews.comparatorFor(cat == null ? null : cat.getSortMode()));
        }
        List<Category> cats = new ArrayList<>(library.getCategories());
        cats.sort(WaypointPickerModel::compareForDisplay);
        this.orderedCategories = cats;
        for (Category c : cats)
        {
            if (waypointsOf(c.getId()).isEmpty()) checkedEmptyCategories.add(c.getId());
        }
    }

    // Mirrors WaypointStore.getCategoriesOrdered: Uncategorized first, then user-created, then
    // bundled; ties broken by sortOrder.
    private static int compareForDisplay(Category a, Category b)
    {
        int tierA = a.isUncategorized() ? 0 : (a.isBundled() ? 2 : 1);
        int tierB = b.isUncategorized() ? 0 : (b.isBundled() ? 2 : 1);
        if (tierA != tierB) return Integer.compare(tierA, tierB);
        return Integer.compare(a.getSortOrder(), b.getSortOrder());
    }

    List<Category> getOrderedCategories() { return Collections.unmodifiableList(orderedCategories); }

    List<Waypoint> waypointsOf(UUID categoryId)
    {
        List<Waypoint> bucket = waypointsByCategory.get(categoryId);
        return bucket == null ? Collections.emptyList() : Collections.unmodifiableList(bucket);
    }

    boolean isWaypointChecked(UUID id) { return checkedWaypoints.contains(id); }

    void setWaypointChecked(UUID id, boolean checked)
    {
        if (checked) checkedWaypoints.add(id); else checkedWaypoints.remove(id);
    }

    Tri categoryState(UUID categoryId)
    {
        List<Waypoint> children = waypointsOf(categoryId);
        if (children.isEmpty())
        {
            return checkedEmptyCategories.contains(categoryId) ? Tri.CHECKED : Tri.UNCHECKED;
        }
        int checked = 0;
        for (Waypoint w : children) if (checkedWaypoints.contains(w.getId())) checked++;
        if (checked == 0) return Tri.UNCHECKED;
        if (checked == children.size()) return Tri.CHECKED;
        return Tri.PARTIAL;
    }

    void setCategoryChecked(UUID categoryId, boolean checked)
    {
        List<Waypoint> children = waypointsOf(categoryId);
        if (children.isEmpty())
        {
            if (checked) checkedEmptyCategories.add(categoryId);
            else checkedEmptyCategories.remove(categoryId);
            return;
        }
        for (Waypoint w : children) setWaypointChecked(w.getId(), checked);
    }

    void selectAll()
    {
        for (Category c : orderedCategories) setCategoryChecked(c.getId(), true);
    }

    void selectNone()
    {
        checkedWaypoints.clear();
        checkedEmptyCategories.clear();
    }

    /** Checked waypoints in display order: categories as listed, then each category's own order. */
    List<Waypoint> checkedWaypointsInOrder()
    {
        List<Waypoint> out = new ArrayList<>();
        for (Category c : orderedCategories)
        {
            for (Waypoint w : waypointsOf(c.getId()))
            {
                if (checkedWaypoints.contains(w.getId())) out.add(w);
            }
        }
        return out;
    }

    Set<UUID> getSelectedWaypointIds() { return new HashSet<>(checkedWaypoints); }

    Set<UUID> getSelectedCategoryIds()
    {
        Set<UUID> out = new HashSet<>();
        for (Category c : orderedCategories)
        {
            if (categoryState(c.getId()) == Tri.CHECKED) out.add(c.getId());
        }
        return out;
    }

    boolean isEmptySelection()
    {
        return checkedWaypoints.isEmpty() && checkedEmptyCategories.isEmpty();
    }
}

package com.waypointer.ui;

import com.waypointer.model.Waypoint;
import com.waypointer.util.Text;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingUtilities;
import javax.swing.border.Border;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;

/**
 * A single waypoint row inside a category card. Click body -> expand inline edit. Dragging
 * the name reorders. Icon-only Play button on the right (grey at rest, orange on hover or
 * when this row is the active path target); pin and menu buttons join it while the pointer is
 * over the row. Custom sprite icons (when set) attach to the name label so icon + text share
 * JLabel's built-in vertical centering and align with the Play button.
 *
 * In select mode the left edge shows a checkbox, the right-side buttons are hidden, and a
 * body click toggles selection (shift = range) instead of expanding the inline editor.
 */
public class WaypointRow extends JPanel implements DropIndicatable, PathTarget
{
    private final Waypoint waypoint;
    static final int ROW_HEIGHT = 24;

    private final JLabel dragHandle;
    private final JLabel name;
    private final boolean wilderness;
    private final MouseAdapter hover;
    private JPanel hoverControls;
    private boolean hovered;
    private final java.awt.Color restingBackground;
    private Border prevBorder;
    // Non-null only outside select mode (select mode hides the Play button). Held so the panel can
    // retint it in place on a path-target change instead of rebuilding the whole body tree (#67).
    private JButton playButton;
    private boolean activePathState;

    /** Start building a row for {@code waypoint}. Booleans default false; callbacks default no-op. */
    public static Spec spec(Waypoint waypoint)
    {
        return new Spec(waypoint);
    }

    /** Named, defaulted parameter object for {@link WaypointRow}. */
    public static final class Spec
    {
        private final Waypoint waypoint;
        private boolean active;
        private boolean isPinned;
        private boolean isWilderness;
        private boolean dragDisabled;
        private Runnable onPlay = () -> {};
        private Runnable onClickBody = () -> {};
        private Runnable onTogglePin = () -> {};
        private Runnable onDelete = () -> {};
        private SpriteManager spriteManager;
        private String originCategoryName;
        private boolean selectMode;
        private boolean selected;
        private java.util.function.Consumer<Boolean> onSelectClick = sel -> {};
        private Runnable onEnterSelectMode = () -> {};

        private Spec(Waypoint waypoint) { this.waypoint = waypoint; }

        public Spec active(boolean v) { this.active = v; return this; }
        public Spec pinned(boolean v) { this.isPinned = v; return this; }
        public Spec wilderness(boolean v) { this.isWilderness = v; return this; }
        public Spec dragDisabled(boolean v) { this.dragDisabled = v; return this; }
        public Spec onPlay(Runnable r) { this.onPlay = r; return this; }
        public Spec onClickBody(Runnable r) { this.onClickBody = r; return this; }
        public Spec onTogglePin(Runnable r) { this.onTogglePin = r; return this; }
        public Spec onDelete(Runnable r) { this.onDelete = r; return this; }
        public Spec spriteManager(SpriteManager sm) { this.spriteManager = sm; return this; }
        public Spec originCategoryName(String n) { this.originCategoryName = n; return this; }
        public Spec selectMode(boolean v) { this.selectMode = v; return this; }
        public Spec selected(boolean v) { this.selected = v; return this; }
        public Spec onSelectClick(java.util.function.Consumer<Boolean> c) { this.onSelectClick = c; return this; }
        public Spec onEnterSelectMode(Runnable r) { this.onEnterSelectMode = r; return this; }

        public WaypointRow build() { return new WaypointRow(this); }
    }

    private WaypointRow(Spec s)
    {
        this.waypoint = s.waypoint;
        this.wilderness = s.isWilderness;
        setLayout(new BorderLayout(4, 0));
        setBorder(BorderFactory.createEmptyBorder(1, 10, 0, 6));
        setOpaque(false);
        setBackground(Styles.CARD_BG);
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        // Hover is tracked on the row and on every child, since a child with its own listener
        // swallows the events. The exit point arrives in the child's coordinate space, so it is
        // converted before the bounds test.
        hover = new MouseAdapter()
        {
            @Override public void mouseEntered(MouseEvent e) { setHovered(true); }
            @Override public void mouseExited(MouseEvent e)
            {
                java.awt.Point p = SwingUtilities.convertPoint(
                    e.getComponent(), e.getPoint(), WaypointRow.this);
                if (contains(p)) return;
                setHovered(false);
            }
        };
        // Body click: in select mode toggle selection (shift = range); otherwise expand inline.
        final MouseAdapter ma = new MouseAdapter()
        {
            @Override public void mouseEntered(MouseEvent e) { hover.mouseEntered(e); }
            @Override public void mouseExited(MouseEvent e) { hover.mouseExited(e); }
            @Override public void mouseClicked(MouseEvent e)
            {
                if (!SwingUtilities.isLeftMouseButton(e)) return;
                if (s.selectMode) s.onSelectClick.accept(e.isShiftDown());
                else s.onClickBody.run();
            }
        };
        addMouseListener(ma);

        // Right-click popup (pin / delete) stays available in both modes. Outside select mode it
        // also offers "Select multiple", the way into bulk selection.
        JPopupMenu popup = new JPopupMenu();
        if (!s.selectMode)
        {
            JMenuItem selectItem = new JMenuItem("Select multiple");
            selectItem.addActionListener(e -> s.onEnterSelectMode.run());
            popup.add(selectItem);
            popup.addSeparator();
        }
        JMenuItem pinItem = new JMenuItem(s.isPinned ? "Unpin" : "Pin to top");
        pinItem.addActionListener(e -> s.onTogglePin.run());
        JMenuItem deleteItem = new JMenuItem("Delete");
        deleteItem.addActionListener(e -> s.onDelete.run());
        popup.add(pinItem);
        popup.addSeparator();
        popup.add(deleteItem);
        setComponentPopupMenu(popup);

        if (s.selectMode)
        {
            TriStateBox box = new TriStateBox();
            box.setState(s.selected ? TriStateBox.State.CHECKED : TriStateBox.State.UNCHECKED);
            box.addMouseListener(ma);
            JPanel west = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
            west.setOpaque(false);
            west.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 4));
            west.add(box);
            add(west, BorderLayout.WEST);
        }

        // CENTER: the name, optionally prefixed with a 16x16 custom sprite. Outside select mode
        // it doubles as the drag handle, so a row is picked up by its name.
        name = buildNameLabel(s, ma);
        add(name, BorderLayout.CENTER);
        dragHandle = s.selectMode || s.dragDisabled ? null : name;

        this.restingBackground = getBackground();
        this.activePathState = s.active;
        applyNameColour();

        buildEastControls(s, popup);
    }

    private JLabel buildNameLabel(Spec s, MouseAdapter ma)
    {
        String displayName = (s.isWilderness ? "☠ " : "") + s.waypoint.getName();
        JLabel label = new JLabel(displayName);
        label.setToolTipText(buildHoverTooltip(s.waypoint, s.originCategoryName));
        label.getAccessibleContext().setAccessibleName(
            accessibleName(s.waypoint.getName(), s.isWilderness, s.isPinned));
        if (s.waypoint.getIconId() != null && s.spriteManager != null)
        {
            label.setIconTextGap(6);
            SpriteIcons.apply(label, s.waypoint.getIconId(), s.spriteManager);
        }
        label.addMouseListener(ma);
        return label;
    }

    // EAST: pin and menu (shown only under the pointer) and the Play button. All hidden in
    // select mode.
    private void buildEastControls(Spec s, JPopupMenu popup)
    {
        if (s.selectMode) return;
        JButton pin = Styles.iconButton(
            Glyphs.of(s.isPinned ? Glyphs.Shape.STAR : Glyphs.Shape.STAR_OUTLINE,
                s.isPinned ? ColorScheme.BRAND_ORANGE : Styles.MUTED_TEXT),
            s.isPinned ? "Unpin" : "Pin to top");
        HoverHint.shared().attach(pin, () -> s.isPinned ? "Unpin" : "Pin to top");
        pin.addActionListener(e -> s.onTogglePin.run());

        JButton menu = Styles.iconButton(Glyphs.of(Glyphs.Shape.MENU, Styles.MUTED_TEXT), "Waypoint options");
        menu.addActionListener(e -> popup.show(menu, 0, menu.getHeight()));

        JButton play = new JButton("▶"); // black right-pointing triangle
        this.playButton = play;
        PlayButton.style(play, s.active);
        HoverHint.shared().attach(play, () -> activePathState ? "Stop pathing here" : "Path to here");
        play.getAccessibleContext().setAccessibleName(playAccessibleName(s.active));
        play.addActionListener(e -> s.onPlay.run());

        hoverControls = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
        hoverControls.setOpaque(false);
        hoverControls.add(pin);
        hoverControls.add(menu);
        hoverControls.setVisible(false);

        JPanel eastPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
        eastPanel.setOpaque(false);
        eastPanel.add(hoverControls);
        eastPanel.add(play);
        for (java.awt.Component c : new java.awt.Component[]{pin, menu, play, hoverControls, eastPanel})
        {
            c.addMouseListener(hover);
        }
        add(eastPanel, BorderLayout.EAST);
    }

    private void setHovered(boolean on)
    {
        if (hovered == on) return;
        hovered = on;
        if (hoverControls != null)
        {
            hoverControls.setVisible(on);
            revalidate();
        }
        repaint();
    }

    private void applyNameColour()
    {
        name.setForeground(activePathState ? ColorScheme.BRAND_ORANGE
            : wilderness ? new Color(220, 130, 130) : Color.WHITE);
    }

    // The card behind the row supplies the background; the row adds the divider above it and
    // a rounded tint while hovered, dragged over, or being pathed to.
    @Override
    protected void paintComponent(java.awt.Graphics g)
    {
        java.awt.Graphics2D g2 = (java.awt.Graphics2D) g.create();
        g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING,
            java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setColor(Styles.ROW_LINE);
        g2.fillRect(8, 0, getWidth() - 16, 1);
        Color fill = null;
        if (activePathState) fill = Styles.ACTIVE_TINT;
        else if (hovered || !getBackground().equals(restingBackground)) fill = Styles.ROW_HOVER;
        if (fill != null)
        {
            g2.setColor(fill);
            g2.fillRoundRect(2, 1, getWidth() - 4, getHeight() - 1, 8, 8);
        }
        g2.dispose();
    }

    @Override
    public Dimension getPreferredSize()
    {
        return new Dimension(super.getPreferredSize().width, ROW_HEIGHT);
    }

    /** Packed world point this row represents; used by the panel to find the active row. */
    @Override
    public int getPackedWorldPoint()
    {
        return waypoint.getPackedWorldPoint();
    }

    /**
     * Retint the Play button to reflect whether this row is the active path target, in place.
     * No-op in select mode, where the Play button is hidden. Lets the panel respond to a
     * path-target change without rebuilding the body tree (#67).
     */
    @Override
    public void setActive(boolean active)
    {
        activePathState = active;
        applyNameColour();
        repaint();
        if (playButton == null) return;
        PlayButton.style(playButton, active);
        playButton.getAccessibleContext().setAccessibleName(playAccessibleName(active));
        playButton.repaint();
    }

    // "Stop pathing to X" while this row is the active target, "Path to X" otherwise, so the
    // screen-reader name tracks the same toggle the glyph and tooltip show.
    private String playAccessibleName(boolean active)
    {
        String n = waypoint.getName();
        if (n == null || n.isEmpty())
        {
            return active ? "Stop pathing to waypoint" : "Path to waypoint";
        }
        return (active ? "Stop pathing to " : "Path to ") + n;
    }

    public JLabel getDragHandle() { return dragHandle; }

    @Override
    public void setDropIndicator(DropIndicatorMode mode)
    {
        // Lazily snapshot the resting border the first time the accent is added, so a later NONE
        // restores it. prevBorder stays null until then, which topAccentOver() tolerates.
        if (mode == DropIndicatorMode.BORDER_AND_TINT && prevBorder == null) prevBorder = getBorder();
        Border resting = prevBorder != null ? prevBorder : getBorder();
        DropIndicators.apply(this, mode, resting, restingBackground);
        if (mode == DropIndicatorMode.NONE) prevBorder = null;
    }

    /**
     * Screen-reader name for a row: the waypoint name plus parenthetical state tags so the
     * wilderness skull and pinned glyph -- which are visual-only on the label -- are spoken.
     * Mirrors the Play button, which already names its path target.
     */
    static String accessibleName(String baseName, boolean wilderness, boolean pinned)
    {
        StringBuilder sb = new StringBuilder(baseName == null ? "" : baseName);
        if (wilderness) sb.append(" (in Wilderness)");
        if (pinned) sb.append(" (pinned)");
        return sb.toString();
    }

    /**
     * Hover tooltip: name on its own when notes are empty; with notes, shows the first
     * line of notes below the name (HTML-escaped).
     */
    static String buildHoverTooltip(Waypoint w)
    {
        String name = w.getName() == null ? "" : w.getName();
        String notes = w.getNotes();
        if (notes == null || notes.isEmpty()) return name;
        int nl = notes.indexOf('\n');
        String firstLine = nl < 0 ? notes : notes.substring(0, nl);
        firstLine = firstLine.trim();
        if (firstLine.isEmpty()) return name;
        return "<html>" + Text.escapeHtml(name) + "<br><span style='color:#bbb'>"
            + Text.escapeHtml(firstLine) + "</span></html>";
    }

    /** Extended tooltip with optional origin-category line. Null origin = same as the one-arg form. */
    static String buildHoverTooltip(Waypoint w, String originCategoryName)
    {
        if (originCategoryName == null || originCategoryName.isEmpty())
        {
            return buildHoverTooltip(w);
        }
        String name = w.getName() == null ? "" : w.getName();
        String notes = w.getNotes();
        StringBuilder html = new StringBuilder("<html>").append(Text.escapeHtml(name));
        if (notes != null && !notes.isEmpty())
        {
            int nl = notes.indexOf('\n');
            String firstLine = (nl < 0 ? notes : notes.substring(0, nl)).trim();
            if (!firstLine.isEmpty())
            {
                html.append("<br><span style='color:#bbb'>")
                    .append(Text.escapeHtml(firstLine))
                    .append("</span>");
            }
        }
        html.append("<br><span style='color:#bbb'><i>in ")
            .append(Text.escapeHtml(originCategoryName))
            .append("</i></span></html>");
        return html.toString();
    }

    @Override public Dimension getMaximumSize()
    {
        return Styles.capHeight(this);
    }
}

package com.waypointer.ui;

import com.waypointer.model.Category;
import com.waypointer.model.Waypoint;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Renders a {@link WaypointPickerModel} as a collapsible, dark-themed checkbox tree, reusing the
 * panel's section idiom instead of a {@code JTree}. A tree's renderers and icons come from
 * the look and feel, which can still be Metal when panels are built, so it would not match the
 * dark theme. Category rows carry a tri-state box, an expand caret, the name, and a count;
 * waypoint leaves carry an indented box and a name. Toggling any box updates the model and fires
 * {@code onChange} so the host dialog can re-gate its confirm buttons.
 */
final class WaypointTreePicker extends JPanel
{
    private final WaypointPickerModel model;
    private final Runnable onChange;
    private final List<CategoryView> categoryViews = new ArrayList<>();

    WaypointTreePicker(WaypointPickerModel model, Runnable onChange)
    {
        this.model = model;
        this.onChange = onChange == null ? () -> {} : onChange;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        for (Category c : model.getOrderedCategories())
        {
            CategoryView cv = new CategoryView(c);
            categoryViews.add(cv);
            add(cv);
        }
        add(Box.createVerticalGlue());
    }

    /** Re-reads every box from the model. Called by the host dialog after Select all / none. */
    void refreshAll()
    {
        for (CategoryView cv : categoryViews) cv.refresh();
    }

    private void fireChanged()
    {
        onChange.run();
    }

    private final class CategoryView extends JPanel
    {
        private final Category category;
        private final TriStateBox headerBox = new TriStateBox();
        private final JPanel body = new JPanel();
        private final List<LeafView> leaves = new ArrayList<>();
        private final JLabel caret = new JLabel("▶"); // black right-pointing triangle
        private boolean collapsed = true;

        CategoryView(Category category)
        {
            this.category = category;
            setLayout(new BorderLayout());
            setBackground(ColorScheme.DARK_GRAY_COLOR);
            setAlignmentX(LEFT_ALIGNMENT);

            JPanel header = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 2));
            header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            header.setAlignmentX(LEFT_ALIGNMENT);

            headerBox.addMouseListener(new MouseAdapter() {
                @Override public void mouseClicked(MouseEvent e)
                {
                    boolean check = model.categoryState(category.getId())
                        != WaypointPickerModel.Tri.CHECKED;
                    model.setCategoryChecked(category.getId(), check);
                    refresh();
                    fireChanged();
                }
            });

            caret.setForeground(Color.LIGHT_GRAY);
            caret.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            MouseAdapter toggle = new MouseAdapter() {
                @Override public void mouseClicked(MouseEvent e) { toggleCollapsed(); }
            };
            caret.addMouseListener(toggle);

            JLabel name = new JLabel(category.getName());
            name.setForeground(Color.WHITE);
            name.setFont(name.getFont().deriveFont(Font.BOLD));
            name.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            name.addMouseListener(toggle);

            JLabel count = new JLabel("(" + model.waypointsOf(category.getId()).size() + ")");
            count.setForeground(Color.LIGHT_GRAY);
            count.setFont(FontManager.getRunescapeSmallFont());

            header.add(headerBox);
            header.add(caret);
            header.add(name);
            header.add(count);
            add(header, BorderLayout.NORTH);

            body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
            body.setBackground(ColorScheme.DARK_GRAY_COLOR);
            body.setAlignmentX(LEFT_ALIGNMENT);
            for (Waypoint w : model.waypointsOf(category.getId()))
            {
                LeafView lv = new LeafView(w, this);
                leaves.add(lv);
                body.add(lv);
            }
            body.setVisible(false);
            add(body, BorderLayout.CENTER);

            refresh();
        }

        private void toggleCollapsed()
        {
            collapsed = !collapsed;
            caret.setText(collapsed ? "▶" : "▼"); // right / down triangle
            body.setVisible(!collapsed);
            revalidate();
            repaint();
        }

        void refresh()
        {
            switch (model.categoryState(category.getId()))
            {
                case CHECKED:  headerBox.setState(TriStateBox.State.CHECKED); break;
                case PARTIAL:  headerBox.setState(TriStateBox.State.PARTIAL); break;
                default:       headerBox.setState(TriStateBox.State.UNCHECKED); break;
            }
            for (LeafView lv : leaves) lv.refresh();
        }

        @Override public Dimension getMaximumSize()
        {
            return Styles.capHeight(this);
        }
    }

    private final class LeafView extends JPanel
    {
        private final Waypoint waypoint;
        private final TriStateBox box = new TriStateBox();
        private final CategoryView owner;

        LeafView(Waypoint waypoint, CategoryView owner)
        {
            this.waypoint = waypoint;
            this.owner = owner;
            setLayout(new FlowLayout(FlowLayout.LEFT, 4, 1));
            setBackground(ColorScheme.DARK_GRAY_COLOR);
            setAlignmentX(LEFT_ALIGNMENT);
            setBorder(BorderFactory.createEmptyBorder(0, 18, 0, 0));
            setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

            MouseAdapter toggle = new MouseAdapter() {
                @Override public void mouseClicked(MouseEvent e) { toggleChecked(); }
            };
            box.addMouseListener(toggle);
            addMouseListener(toggle);

            JLabel name = new JLabel(waypoint.getName());
            name.setForeground(Color.WHITE);
            name.addMouseListener(toggle);
            add(box);
            add(name);
        }

        private void toggleChecked()
        {
            model.setWaypointChecked(waypoint.getId(), !model.isWaypointChecked(waypoint.getId()));
            owner.refresh();
            fireChanged();
        }

        void refresh()
        {
            box.setState(model.isWaypointChecked(waypoint.getId())
                ? TriStateBox.State.CHECKED : TriStateBox.State.UNCHECKED);
        }

        @Override public Dimension getMaximumSize()
        {
            return Styles.capHeight(this);
        }
    }

}

