package com.waypointer.codec;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;
import com.waypointer.model.WorldPointPacker;
import org.junit.Test;

public class CoordinateTextTest
{
    private static final String FORMAT_MSG = "Enter coordinates as x, y or x, y, plane.";
    private static final String RANGE_MSG = "x and y must be between 0 and 16383.";
    private static final String PLANE_MSG = "Plane must be between 0 and 3.";

    @Test
    public void parsesCommaAndSpaceForms()
    {
        int plane0 = WorldPointPacker.pack(2301, 3690, 0);
        assertEquals(plane0, CoordinateText.parse("2301, 3690"));
        assertEquals(plane0, CoordinateText.parse("2301 3690"));
        assertEquals(plane0, CoordinateText.parse("2301\t3690"));
        assertEquals(WorldPointPacker.pack(2301, 3690, 1), CoordinateText.parse("2301,3690,1"));
        assertEquals(WorldPointPacker.pack(2301, 3690, 1), CoordinateText.parse(" 2301  3690  1 "));
    }

    @Test
    public void formatRoundTrips()
    {
        assertEquals("2301, 3690", CoordinateText.format(CoordinateText.parse("2301,3690")));
        assertEquals("2301, 3690, 1", CoordinateText.format(CoordinateText.parse("2301,3690,1")));
    }

    @Test
    public void rejectsBadInput()
    {
        assertRejected("", FORMAT_MSG);
        assertRejected("2301", FORMAT_MSG);
        assertRejected("a, b", FORMAT_MSG);
        assertRejected("1,2,3,4", FORMAT_MSG);
        assertRejected("-1, 5", RANGE_MSG);
        assertRejected("16384, 5", RANGE_MSG);
        assertRejected("99999999999, 5", RANGE_MSG);
        assertRejected("5, 5, 4", PLANE_MSG);
    }

    private static void assertRejected(String text, String message)
    {
        try
        {
            CoordinateText.parse(text);
            fail("expected rejection of '" + text + "'");
        }
        catch (IllegalArgumentException e)
        {
            assertEquals(message, e.getMessage());
        }
    }
}

package com.waypointer.codec;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.waypointer.model.Category;
import com.waypointer.model.Library;
import com.waypointer.model.Waypoint;
import java.time.Instant;
import java.util.UUID;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class LibraryJsonCodecTest
{
    private LibraryJsonCodec codec;

    @Before
    public void setUp()
    {
        Gson gson = new GsonBuilder()
            .registerTypeAdapter(Instant.class, new com.google.gson.JsonSerializer<Instant>() {
                @Override public com.google.gson.JsonElement serialize(Instant src,
                    java.lang.reflect.Type t, com.google.gson.JsonSerializationContext c) {
                    return new com.google.gson.JsonPrimitive(src.toString());
                }
            })
            .registerTypeAdapter(Instant.class, new com.google.gson.JsonDeserializer<Instant>() {
                @Override public Instant deserialize(com.google.gson.JsonElement e,
                    java.lang.reflect.Type t, com.google.gson.JsonDeserializationContext c) {
                    return Instant.parse(e.getAsString());
                }
            })
            .create();
        codec = new LibraryJsonCodec(gson);
    }

    @Test
    public void emptyLibraryRoundTrips()
    {
        Library lib = new Library();
        String json = codec.encode(lib);
        Library back = codec.decode(json);
        assertEquals(Library.CURRENT_SCHEMA_VERSION, back.getSchemaVersion());
        assertTrue(back.getCategories().isEmpty());
        assertTrue(back.getWaypoints().isEmpty());
    }

    @Test
    public void populatedLibraryRoundTripsAllFields()
    {
        Library lib = new Library();
        UUID catId = UUID.randomUUID();
        lib.getCategories().add(new Category(catId, "Bossing", 0, false, null, false));
        lib.getWaypoints().add(new Waypoint(
            UUID.randomUUID(), "Vorkath", 42, catId, 8059, "best icon",
            Instant.parse("2026-05-02T12:00:00Z"), 0, false, null, false));

        Library back = codec.decode(codec.encode(lib));
        assertEquals(1, back.getCategories().size());
        assertEquals("Bossing", back.getCategories().get(0).getName());
        assertEquals(1, back.getWaypoints().size());
        Waypoint w = back.getWaypoints().get(0);
        assertEquals("Vorkath", w.getName());
        assertEquals(42, w.getPackedWorldPoint());
        assertEquals(Integer.valueOf(8059), w.getIconId());
        assertEquals("best icon", w.getNotes());
        assertEquals(Instant.parse("2026-05-02T12:00:00Z"), w.getCreatedAt());
    }

    @Test
    public void categoryIconIdRoundTrips()
    {
        Library lib = new Library();
        UUID catId = UUID.randomUUID();
        lib.getCategories().add(new Category(catId, "Mining", 0, false, 199, false));

        Library back = codec.decode(codec.encode(lib));
        assertEquals(1, back.getCategories().size());
        assertEquals(Integer.valueOf(199), back.getCategories().get(0).getIconId());

        // null iconId also round-trips
        Library lib2 = new Library();
        lib2.getCategories().add(new Category(UUID.randomUUID(), "Plain", 0, false, null, false));
        Library back2 = codec.decode(codec.encode(lib2));
        assertNull(back2.getCategories().get(0).getIconId());
    }

    @Test(expected = LibraryJsonCodec.UnsupportedSchemaException.class)
    public void rejectsSchemaVersionTooNew()
    {
        Library lib = new Library();
        lib.setSchemaVersion(Library.CURRENT_SCHEMA_VERSION + 5);
        String json = codec.encode(lib);
        codec.decode(json);
    }

    @Test
    public void missingFieldsDecodeWithDefaults()
    {
        String minimal = "{\"schemaVersion\":1}";
        Library back = codec.decode(minimal);
        assertNotNull(back.getCategories());
        assertNotNull(back.getWaypoints());
        assertTrue(back.getCategories().isEmpty());
        assertTrue(back.getWaypoints().isEmpty());
    }

    @Test(expected = LibraryJsonCodec.MalformedLibraryException.class)
    public void malformedJsonThrows()
    {
        codec.decode("not json {{");
    }

    @Test
    public void categoryWithSortMode_roundTrips()
    {
        Library lib = new Library();
        UUID catId = UUID.randomUUID();
        Category c = new Category(catId, "POIs", 0, false, null, false);
        c.setSortMode(com.waypointer.model.CategorySortMode.NAME);
        lib.getCategories().add(c);

        Library back = codec.decode(codec.encode(lib));

        assertEquals(1, back.getCategories().size());
        assertEquals(com.waypointer.model.CategorySortMode.NAME,
            back.getCategories().get(0).getSortMode());
    }

    @Test
    public void categoryColorRoundTrips()
    {
        Library lib = new Library();
        UUID catId = UUID.randomUUID();
        Category c = new Category(catId, "Danger", 0, false, null, false);
        c.setColor(0xCC4040);
        lib.getCategories().add(c);

        Library back = codec.decode(codec.encode(lib));
        assertEquals(Integer.valueOf(0xCC4040), back.getCategories().get(0).getColor());

        // null colour also round-trips
        Library lib2 = new Library();
        lib2.getCategories().add(new Category(UUID.randomUUID(), "Plain", 0, false, null, false));
        Library back2 = codec.decode(codec.encode(lib2));
        assertNull(back2.getCategories().get(0).getColor());
    }

    @Test
    public void waypointTargetNpcNameRoundTrips()
    {
        Library lib = new Library();
        Waypoint w = new Waypoint(
            UUID.randomUUID(), "Banker", 42, null, null, "",
            Instant.parse("2026-05-02T12:00:00Z"), 0, false, null, false);
        w.setTargetNpcName("Banker");
        lib.getWaypoints().add(w);

        Library back = codec.decode(codec.encode(lib));
        assertEquals("Banker", back.getWaypoints().get(0).getTargetNpcName());

        // a non-NPC waypoint keeps it null
        Library lib2 = new Library();
        lib2.getWaypoints().add(new Waypoint(
            UUID.randomUUID(), "Tile", 7, null, null, "",
            Instant.parse("2026-05-02T12:00:00Z"), 0, false, null, false));
        assertNull(codec.decode(codec.encode(lib2)).getWaypoints().get(0).getTargetNpcName());
    }

    @Test
    public void legacyJsonWithoutSortMode_decodesAsNull()
    {
        String legacyJson =
            "{\"schemaVersion\":2,"
            + "\"categories\":["
            + "{\"id\":\"" + UUID.randomUUID() + "\",\"name\":\"Old\","
            + "\"sortOrder\":0,\"uncategorized\":false,\"bundled\":false}"
            + "],"
            + "\"waypoints\":[]}";

        Library back = codec.decode(legacyJson);

        assertEquals(1, back.getCategories().size());
        assertNull("legacy category must decode with null sortMode",
            back.getCategories().get(0).getSortMode());
    }

    @Test
    public void dropsInvalidWaypointsKeepsValid()
    {
        UUID catId = UUID.randomUUID();
        String json = "{\"schemaVersion\":2,"
            + "\"categories\":[{\"id\":\"" + catId + "\",\"name\":\"Bossing\","
            + "\"sortOrder\":0,\"uncategorized\":false,\"bundled\":false}],"
            + "\"waypoints\":["
            + "{\"id\":\"" + UUID.randomUUID() + "\",\"name\":\"Good\",\"packedWorldPoint\":42,"
            + "\"categoryId\":\"" + catId + "\",\"notes\":\"\"},"
            + "{\"name\":\"NoId\",\"packedWorldPoint\":42},"
            + "{\"id\":\"" + UUID.randomUUID() + "\",\"packedWorldPoint\":42},"
            + "{\"id\":\"" + UUID.randomUUID() + "\",\"name\":\"ZeroCoord\",\"packedWorldPoint\":0}"
            + "]}";

        Library back = codec.decode(json);

        assertEquals(1, back.getWaypoints().size());
        assertEquals("Good", back.getWaypoints().get(0).getName());
    }

    @Test
    public void dropsCategoryWithNullName()
    {
        String json = "{\"schemaVersion\":2,"
            + "\"categories\":["
            + "{\"id\":\"" + UUID.randomUUID() + "\",\"name\":\"Keep\",\"sortOrder\":0,"
            + "\"uncategorized\":false,\"bundled\":false},"
            + "{\"id\":\"" + UUID.randomUUID() + "\",\"sortOrder\":1,"
            + "\"uncategorized\":false,\"bundled\":false}"
            + "],\"waypoints\":[]}";

        Library back = codec.decode(json);

        assertEquals(1, back.getCategories().size());
        assertEquals("Keep", back.getCategories().get(0).getName());
    }

    @Test
    public void keepsUncategorizedSentinelWithMissingFields()
    {
        String json = "{\"schemaVersion\":2,"
            + "\"categories\":[{\"uncategorized\":true,\"sortOrder\":0,\"bundled\":false}],"
            + "\"waypoints\":[]}";

        Library back = codec.decode(json);

        assertEquals(1, back.getCategories().size());
        assertTrue(back.getCategories().get(0).isUncategorized());
    }

    @Test
    public void keepsFullyValidLibraryUnchanged()
    {
        UUID c = UUID.randomUUID();
        String json = "{\"schemaVersion\":2,"
            + "\"categories\":[{\"id\":\"" + c + "\",\"name\":\"Bossing\",\"sortOrder\":0,"
            + "\"uncategorized\":false,\"bundled\":false}],"
            + "\"waypoints\":["
            + "{\"id\":\"" + UUID.randomUUID() + "\",\"name\":\"A\",\"packedWorldPoint\":42,\"categoryId\":\"" + c + "\"},"
            + "{\"id\":\"" + UUID.randomUUID() + "\",\"name\":\"B\",\"packedWorldPoint\":99,\"categoryId\":\"" + c + "\"}]}";

        Library back = codec.decode(json);

        assertEquals(1, back.getCategories().size());
        assertEquals(2, back.getWaypoints().size());
    }

    @Test
    public void decodeWithReportCountsDroppedEntries()
    {
        UUID catId = UUID.randomUUID();
        String json = "{\"schemaVersion\":2,"
            + "\"categories\":["
            + "{\"id\":\"" + catId + "\",\"name\":\"Keep\",\"sortOrder\":0,\"uncategorized\":false,\"bundled\":false},"
            + "{\"id\":\"" + UUID.randomUUID() + "\",\"sortOrder\":1,\"uncategorized\":false,\"bundled\":false}"
            + "],\"waypoints\":["
            + "{\"id\":\"" + UUID.randomUUID() + "\",\"name\":\"Good\",\"packedWorldPoint\":42,\"categoryId\":\"" + catId + "\"},"
            + "{\"name\":\"NoId\",\"packedWorldPoint\":42},"
            + "{\"id\":\"" + UUID.randomUUID() + "\",\"name\":\"Zero\",\"packedWorldPoint\":0}"
            + "]}";

        DecodeReport report = codec.decodeWithReport(json);

        assertEquals(1, report.library.getCategories().size());
        assertEquals(1, report.library.getWaypoints().size());
        assertEquals(2, report.droppedWaypoints);
        assertEquals(1, report.droppedCategories);
        assertEquals(3, report.totalDropped());
    }

    @Test
    public void decodeStillReturnsCleanLibrary()
    {
        String json = "{\"schemaVersion\":2,\"categories\":[],\"waypoints\":["
            + "{\"id\":\"" + UUID.randomUUID() + "\",\"name\":\"Good\",\"packedWorldPoint\":42}]}";
        Library lib = codec.decode(json);
        assertEquals(1, lib.getWaypoints().size());
    }
}

