        List<Waypoint> in = Arrays.asList(good, wp(null, "NoId", 42), wp(UUID.randomUUID(), "Zero", 0));
        List<Waypoint> out = ModelSanitizer.sanitizeWaypoints(in);
        assertEquals(1, out.size());
        assertEquals("Bank", out.get(0).getName());
