    }

    @Test
    public void dropsWaypointStepWithUnusableCoordinate()
    {
        RouteStep s = new RouteStep(UUID.randomUUID(), StepType.WAYPOINT, "Bank",
            WorldPointPacker.UNDEFINED, null, null);
        assertFalse(ModelSanitizer.isValidStep(s));
    }

    @Test
    public void manualStepNeedsNoCoordinate()
    {
        RouteStep s = RouteStep.manual("Withdraw seeds"); // packed = UNDEFINED by construction
        assertTrue(ModelSanitizer.isValidStep(s));
    }

    @Test
    public void dropsRouteWithNullIdOrName()
    {
        assertFalse(ModelSanitizer.isValidRoute(new Route(null, "R", new ArrayList<>(), false, null, 0)));
        assertFalse(ModelSanitizer.isValidRoute(new Route(UUID.randomUUID(), null, new ArrayList<>(), false, null, 0)));
    }

    @Test
    public void sanitizeRoutesDropsInvalidRoutesAndStripsBadSteps()
    {
        RouteStep good = RouteStep.manual("Withdraw seeds");
        RouteStep bad = new RouteStep(UUID.randomUUID(), StepType.MANUAL, null,
            WorldPointPacker.UNDEFINED, null, null);
        Route keep = new Route(UUID.randomUUID(), "Herb run",
            new ArrayList<>(Arrays.asList(good, bad)), false, null, 0);
        Route dropById = new Route(null, "Nameless route", new ArrayList<>(), false, null, 0);

        List<Route> out = ModelSanitizer.sanitizeRoutes(new ArrayList<>(Arrays.asList(keep, dropById)));

        assertEquals(1, out.size());
        assertEquals("Herb run", out.get(0).getName());
        assertEquals("bad step must be stripped from surviving route", 1, out.get(0).getSteps().size());
    }
}

package com.waypointer.codec;

import com.google.gson.Gson;
import com.waypointer.model.Waypoint;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.preset.Preset;
import com.waypointer.preset.PresetCatalog;
import com.waypointer.preset.PresetWaypoint;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

/**
 * Guards that every bundled preset waypoint survives ModelSanitizer. A preset waypoint at a
 * coordinate the sanitizer rejects (UNDEFINED or (0,0)) or with a null name would survive its
 * first session in memory, then vanish when the library is re-decoded on the next startup.
 */
public class PresetSanitizationTest
{
    @Test
    public void bundledPresetWaypointsAllSurviveSanitization()
    {
        List<PresetWaypoint> presetWaypoints = new ArrayList<>();
        for (Preset p : new PresetCatalog(new Gson()).getPresets())
        {
            presetWaypoints.addAll(p.getWaypoints());
        }
        assertFalse("preset catalog must not be empty", presetWaypoints.isEmpty());

        List<Waypoint> asLibrary = new ArrayList<>();
        for (PresetWaypoint pw : presetWaypoints)
        {
            asLibrary.add(new Waypoint(
                UUID.randomUUID(), pw.getName(),
                WorldPointPacker.pack(pw.getX(), pw.getY(), pw.getPlane()),
                UUID.randomUUID(), null, "", Instant.parse("2026-06-01T00:00:00Z"),
                0, false, null, false));
        }

        List<Waypoint> kept = ModelSanitizer.sanitizeWaypoints(asLibrary);

        assertEquals("a bundled preset waypoint would be dropped on reload",
            asLibrary.size(), kept.size());
    }
}

package com.waypointer.codec;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import com.google.gson.Gson;
import com.waypointer.model.Category;
import com.waypointer.model.Library;
import com.waypointer.model.Waypoint;
import com.waypointer.model.WorldPointPacker;
import java.time.Instant;
import java.util.UUID;
import org.junit.Test;

public class ReadableImportTest
{
    private final ReadableImport importer = new ReadableImport(new Gson());

    private static Waypoint only(Library lib, String name)
    {
        for (Waypoint w : lib.getWaypoints())
        {
            if (w.getName().equals(name)) return w;
        }
        fail("no waypoint " + name);
        return null;
    }

    private static String catName(Library lib, Waypoint w)
    {
        for (Category c : lib.getCategories())
        {
            if (c.getId().equals(w.getCategoryId())) return c.getName();
        }
        return null;
    }

    private static void assertRejected(ReadableImport imp, String text, String message)
    {
        try
        {
            imp.parse(text, new Library());
            fail("expected rejection: " + message);
        }
        catch (ReadableImport.MalformedListException e)
        {
            assertEquals(message, e.getMessage());
        }
    }

    @Test
    public void linesWithCategoriesAndDefaultCategory()
    {
        Library lib = importer.parse("Loose one, 100, 200\n# Charting\n"
            + "Shipwreck one, 2301, 3690\nCurrent duck 4, 2410 3725 0\n", new Library()).library;

        assertEquals(2, lib.getCategories().size());
        assertEquals("Imported", lib.getCategories().get(0).getName());
        assertEquals("Charting", lib.getCategories().get(1).getName());
        assertEquals(3, lib.getWaypoints().size());
        assertEquals("Loose one", lib.getWaypoints().get(0).getName());
        assertEquals(WorldPointPacker.pack(100, 200, 0), lib.getWaypoints().get(0).getPackedWorldPoint());
        assertEquals("Imported", catName(lib, lib.getWaypoints().get(0)));
        assertEquals("Shipwreck one", lib.getWaypoints().get(1).getName());
        assertEquals("Current duck 4", lib.getWaypoints().get(2).getName());
        assertEquals(WorldPointPacker.pack(2410, 3725, 0), lib.getWaypoints().get(2).getPackedWorldPoint());
        assertEquals("Charting", catName(lib, lib.getWaypoints().get(2)));
    }

    @Test
    public void namesWithDigitsAndCommas()
    {
        Library lib = importer.parse("Rock, north, 2301 3690\nDuck 4 2410 3725\nSpot 7 100 200 1\n",
            new Library()).library;
        assertEquals(WorldPointPacker.pack(2301, 3690, 0), only(lib, "Rock, north").getPackedWorldPoint());
        assertEquals(WorldPointPacker.pack(2410, 3725, 0), only(lib, "Duck 4").getPackedWorldPoint());
        assertEquals(WorldPointPacker.pack(100, 200, 1), only(lib, "Spot 7").getPackedWorldPoint());
    }

    @Test
    public void crlfTabsAndTrailingBlankLines()
    {
        Library lib = importer.parse("\r\n  Alpha,\t10,\t20 \r\n\r\n# Sea \r\nBeta 30 40\r\n\r\n\r\n",
            new Library()).library;
        assertEquals(2, lib.getWaypoints().size());
        assertEquals(WorldPointPacker.pack(10, 20, 0), only(lib, "Alpha").getPackedWorldPoint());
        assertEquals("Sea", catName(lib, only(lib, "Beta")));
    }

    @Test
    public void jsonArray()
    {
        Library lib = importer.parse(
            "[{\"name\":\"A\",\"x\":1,\"y\":2},{\"name\":\"B\",\"x\":3,\"y\":4,\"plane\":1,\"category\":\"Sea\"}]",
            new Library()).library;
        assertEquals(WorldPointPacker.pack(1, 2, 0), only(lib, "A").getPackedWorldPoint());
        assertEquals("Imported", catName(lib, only(lib, "A")));
        assertEquals(WorldPointPacker.pack(3, 4, 1), only(lib, "B").getPackedWorldPoint());
        assertEquals("Sea", catName(lib, only(lib, "B")));
    }

    private static Library existingWith(String category, String waypoint, int packed)
    {
        Library existing = new Library();
        Category c = new Category(UUID.randomUUID(), category, 3, false, 77, false);
        existing.getCategories().add(c);
        existing.getWaypoints().add(new Waypoint(UUID.randomUUID(), waypoint, packed, c.getId(), null,
            "", Instant.EPOCH, 0, false, null, false));
        return existing;
    }

    @Test
    public void reusesExistingCategoryIgnoringCase()
    {
        Library existing = existingWith("charting", "Old", WorldPointPacker.pack(5, 5, 0));
        UUID id = existing.getCategories().get(0).getId();
        Library lib = importer.parse("# Charting\nNew 10 20", existing).library;
        assertEquals(1, lib.getCategories().size());
        assertEquals(id, lib.getCategories().get(0).getId());
        assertEquals(Integer.valueOf(77), lib.getCategories().get(0).getIconId());
        assertEquals(id, lib.getWaypoints().get(0).getCategoryId());
    }

    @Test
    public void skipsEntriesAlreadyPresent()
    {
        Library existing = existingWith("Charting", "Wreck", WorldPointPacker.pack(10, 20, 0));
        ReadableImport.Result r = importer.parse("# Charting\nWRECK 10 20\nOther 1 2", existing);
        assertEquals(1, r.alreadyPresent);
        assertEquals(1, r.library.getWaypoints().size());
        assertEquals("Other", r.library.getWaypoints().get(0).getName());
    }

    @Test
    public void sameNameDifferentTileIsKept()
    {
        Library existing = existingWith("Charting", "Wreck", WorldPointPacker.pack(10, 20, 0));
        ReadableImport.Result r = importer.parse("# Charting\nWreck 11 20", existing);
        assertEquals(0, r.alreadyPresent);
        assertEquals(1, r.library.getWaypoints().size());
    }

    @Test
    public void freshUuidsEveryParse()
    {
        Library a = importer.parse("X 1 2", new Library()).library;
        Library b = importer.parse("X 1 2", new Library()).library;
        assertNotEquals(a.getWaypoints().get(0).getId(), b.getWaypoints().get(0).getId());
        assertNotEquals(a.getCategories().get(0).getId(), b.getCategories().get(0).getId());
    }

    @Test
    public void badLineReportsLineNumber()
    {
        assertRejected(importer, "A 1 2\n\nJust a name\n", "Line 3: expected a name followed by x, y.");
        assertRejected(importer, "# Cat\nA 1", "Line 2: expected a name followed by x, y.");
    }

    @Test
    public void badEntryReportsIndex()
    {
        assertRejected(importer, "[{\"name\":\"A\",\"x\":1,\"y\":2},{\"name\":\"B\",\"x\":3}]",
            "Entry 2: needs a name, x and y.");
        assertRejected(importer, "[{\"name\":\" \",\"x\":1,\"y\":2}]", "Entry 1: needs a name, x and y.");
        assertRejected(importer, "[5]", "Entry 1: needs a name, x and y.");
    }

    @Test
    public void outOfRangeCoordinateReportsLine()
    {
        assertRejected(importer, "A 1 2\nB 99999 5", "Line 2: x and y must be between 0 and 16383.");
        assertRejected(importer, "[{\"name\":\"B\",\"x\":99999,\"y\":5}]",
            "Entry 1: x and y must be between 0 and 16383.");
        assertRejected(importer, "[{\"name\":\"B\",\"x\":1,\"y\":5,\"plane\":4}]",
            "Entry 1: Plane must be between 0 and 3.");
    }

    @Test
    public void emptyAndOversizedInputRejected()
    {
        assertRejected(importer, "", "Nothing to import.");
        assertRejected(importer, " \n# only a heading\n\n", "Nothing to import.");
        assertRejected(importer, "[]", "Nothing to import.");
        StringBuilder big = new StringBuilder();
        while (big.length() <= 1_048_576) big.append("A 1 2\n");
        assertRejected(importer, big.toString(), "That list is too large.");
    }

    @Test
    public void brokenJsonRejected()
    {
        assertRejected(importer, "[{\"name\":", "That is not a valid list.");
        assertRejected(importer, "[1,2] trailing", "That is not a valid list.");
    }

    @Test
    public void shareCodePrefixDetected()
    {
        assertTrue(ReadableImport.isShareCode(" WPL1:abc"));
        assertTrue(ReadableImport.isShareCode("WP1:abc"));
        assertFalse(ReadableImport.isShareCode("# x"));
        assertFalse(ReadableImport.isShareCode(null));
    }

    @Test(timeout = 5000)
    public void longSeparatorRunDoesNotHang()
    {
        StringBuilder huge = new StringBuilder("a");
        for (int i = 0; i < 100_000; i++) huge.append(',');
        huge.append("b 1 2");
        assertRejected(importer, huge.toString(), "Line 1: too long.");

        StringBuilder name = new StringBuilder();
        for (int i = 0; i < 25; i++) name.append("abcdefghi").append(',');
        for (int i = 0; i < 175; i++) name.append(',');
        long start = System.nanoTime();
        try
        {
            importer.parse(name + "z 1 2", new Library());
        }
        catch (ReadableImport.MalformedListException ignored)
        {
            // either outcome is fine; only the time matters
        }
        assertTrue(System.nanoTime() - start < 1_000_000_000L);
    }

    @Test(timeout = 5000)
    public void hugeExponentNumberRejectedQuickly()
    {
        assertRejected(importer, "[{\"name\":\"A\",\"x\":1e100000000,\"y\":2}]",
            "Entry 1: needs a name, x and y.");
    }

    @Test
    public void zeroZeroRejectedWithLineNumber()
    {
        assertRejected(importer, "A 1 2\nSpot 0 0", "Line 2: x and y cannot both be 0.");
        assertRejected(importer, "Spot 0, 0, 1", "Line 1: x and y cannot both be 0.");
    }

    @Test
    public void zeroZeroRejectedWithEntryNumber()
    {
        assertRejected(importer,
            "[{\"name\":\"A\",\"x\":1,\"y\":2},{\"name\":\"B\",\"x\":0,\"y\":0}]",
            "Entry 2: x and y cannot both be 0.");
    }

    @Test
    public void overlongLineRejected()
    {
        StringBuilder line = new StringBuilder();
        while (line.length() < 300) line.append('x');
        assertRejected(importer, "A 1 2\n" + line + " 1 2", "Line 2: too long.");
        assertRejected(importer, "# " + line, "Line 1: too long.");
    }

    @Test
    public void bracketFirstLineIsNotAValidList()
    {
        assertRejected(importer, "[Boat] Wreck 1 2", "That is not a valid list.");
    }

    private static final String NEEDS = "Entry 1: needs a name, x and y.";

    private static String withX(String x)
    {
        return "[{\"name\":\"A\",\"x\":" + x + ",\"y\":2}]";
    }

    @Test(timeout = 2000)
    public void hugeNegativeExponentRejectedQuickly()
    {
        assertRejected(importer, withX("1e-100000000"), NEEDS);
    }

    @Test(timeout = 2000)
    public void fractionalNumberRejected()
    {
        assertRejected(importer, withX("1.5"), NEEDS);
        assertRejected(importer, withX("1.0"), NEEDS);
    }

    @Test(timeout = 2000)
    public void exponentFormRejected()
    {
        assertRejected(importer, withX("1e3"), NEEDS);
    }

    @Test(timeout = 2000)
    public void veryLongDigitRunRejectedQuickly()
    {
        StringBuilder digits = new StringBuilder();
        for (int i = 0; i < 100_000; i++) digits.append('1');
        assertRejected(importer, withX(digits.toString()), NEEDS);
    }

    @Test(timeout = 2000)
    public void plainIntegersStillAccepted()
    {
        Library lib = importer.parse(
            "[{\"name\":\"A\",\"x\":2301,\"y\":3690,\"plane\":1}]", new Library()).library;
        assertEquals(WorldPointPacker.pack(2301, 3690, 1), lib.getWaypoints().get(0).getPackedWorldPoint());
        assertRejected(importer, "[{\"name\":\"A\",\"x\":\"12\",\"y\":2}]", NEEDS);
    }
}

package com.waypointer.codec;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.model.route.Route;
import com.waypointer.model.route.RouteLibrary;
import com.waypointer.model.route.RouteStep;
import com.waypointer.model.route.StepType;
import java.time.Instant;
import java.util.Arrays;
import java.util.UUID;
import org.junit.Test;

public class RouteJsonCodecTest
{
    private static Gson buildGson()
    {
        return new GsonBuilder()
            .registerTypeAdapter(Instant.class,
                (com.google.gson.JsonSerializer<Instant>) (src, t, c) ->
                    new com.google.gson.JsonPrimitive(src.toString()))
            .registerTypeAdapter(Instant.class,
                (com.google.gson.JsonDeserializer<Instant>) (e, t, c) ->
                    Instant.parse(e.getAsString()))
            .create();
    }

    private final RouteJsonCodec codec = new RouteJsonCodec(buildGson());

    private RouteLibrary sample()
    {
        Route r = new Route(UUID.randomUUID(), "Herb run",
            Arrays.asList(
                RouteStep.waypoint(WorldPointPacker.pack(3200, 3200, 0), "Bank"),
                RouteStep.manual("Withdraw seeds")),
            true, Instant.parse("2026-06-01T00:00:00Z"), 0);
        RouteLibrary lib = new RouteLibrary();
        lib.getRoutes().add(r);
        return lib;
    }

    @Test
    public void roundTripsRoutes()
    {
        RouteLibrary decoded = codec.decode(codec.encode(sample()));
        assertEquals(1, decoded.getRoutes().size());
        Route r = decoded.getRoutes().get(0);
        assertEquals("Herb run", r.getName());
        assertTrue(r.isRepeating());
        assertEquals(2, r.getSteps().size());
        assertEquals(StepType.WAYPOINT, r.getSteps().get(0).getType());
        assertEquals(StepType.MANUAL, r.getSteps().get(1).getType());
        assertEquals("Withdraw seeds", r.getSteps().get(1).getLabel());
    }

    @Test
    public void stepBoxTextRoundTrips()
    {
        RouteStep step = RouteStep.manual("Bank");
        step.setBoxText("Withdraw 5 ranarr seeds");
        Route route = new Route(UUID.randomUUID(), "Herb run",
            Arrays.asList(step), false, Instant.parse("2026-06-01T00:00:00Z"), 0);
        RouteLibrary lib = new RouteLibrary();
        lib.getRoutes().add(route);

        RouteLibrary decoded = codec.decode(codec.encode(lib));
        assertEquals("Withdraw 5 ranarr seeds",
            decoded.getRoutes().get(0).getSteps().get(0).getBoxText());
    }

    @Test
    public void missingFieldsDecodeToEmptyDefaults()
    {
        RouteLibrary lib = codec.decode("{}");
        assertEquals(0, lib.getRoutes().size());
        assertEquals(RouteLibrary.CURRENT_SCHEMA_VERSION, lib.getSchemaVersion());
    }

    @Test(expected = RouteJsonCodec.UnsupportedSchemaException.class)
    public void newerSchemaIsRejected()
    {
        String json = "{\"schemaVersion\":999,\"routes\":[]}";
        codec.decode(json);
    }

    @Test(expected = RouteJsonCodec.MalformedRouteException.class)
    public void garbageJsonThrowsMalformed()
    {
        codec.decode("not json");
    }

    @Test
    public void dropsRouteWithNullName()
    {
        String json = "{\"schemaVersion\":2,\"routes\":["
            + "{\"id\":\"" + UUID.randomUUID() + "\",\"name\":\"Keep\",\"steps\":[]},"
            + "{\"id\":\"" + UUID.randomUUID() + "\",\"steps\":[]}"
            + "]}";

        RouteLibrary lib = codec.decode(json);

        assertEquals(1, lib.getRoutes().size());
        assertEquals("Keep", lib.getRoutes().get(0).getName());
    }

    @Test
    public void dropsStepsMissingBothLabelAndBoxText()
    {
        String json = "{\"schemaVersion\":2,\"routes\":[{"
            + "\"id\":\"" + UUID.randomUUID() + "\",\"name\":\"R\",\"steps\":["
            + "{\"id\":\"" + UUID.randomUUID() + "\",\"type\":\"MANUAL\",\"label\":\"Good\"},"
            + "{\"id\":\"" + UUID.randomUUID() + "\",\"type\":\"MANUAL\"}"
            + "]}]}";

        RouteLibrary lib = codec.decode(json);

        assertEquals(1, lib.getRoutes().size());
        assertEquals(1, lib.getRoutes().get(0).getSteps().size());
        assertEquals("Good", lib.getRoutes().get(0).getSteps().get(0).getLabel());
    }
}

package com.waypointer.codec;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import org.junit.Test;

public class RouteMigratorTest
{
    @SuppressWarnings("deprecation")
    private static JsonObject parse(String json)
    {
        return new JsonParser().parse(json).getAsJsonObject();
    }

    @Test
    public void backfillsBoxTextFromLabelForV1Steps()
    {
        JsonObject v1 = parse(
            "{\"schemaVersion\":1,\"routes\":[{\"steps\":["
            + "{\"label\":\"Bank\"},"
            + "{\"label\":\"Withdraw seeds\"}"
            + "]}]}");

        JsonObject migrated = RouteMigrator.migrate(v1, 1);

        JsonObject route = migrated.getAsJsonArray("routes").get(0).getAsJsonObject();
        JsonObject step0 = route.getAsJsonArray("steps").get(0).getAsJsonObject();
        JsonObject step1 = route.getAsJsonArray("steps").get(1).getAsJsonObject();
        assertEquals("Bank", step0.get("boxText").getAsString());
        assertEquals("Withdraw seeds", step1.get("boxText").getAsString());
        assertEquals(2, migrated.get("schemaVersion").getAsInt());
    }

    @Test
    public void doesNotOverwriteExistingBoxText()
    {
        JsonObject v1 = parse(
            "{\"schemaVersion\":1,\"routes\":[{\"steps\":["
            + "{\"label\":\"Bank\",\"boxText\":\"Withdraw 5 seeds\"}"
            + "]}]}");

        JsonObject migrated = RouteMigrator.migrate(v1, 1);

        JsonObject step0 = migrated.getAsJsonArray("routes").get(0).getAsJsonObject()
            .getAsJsonArray("steps").get(0).getAsJsonObject();
        assertEquals("Withdraw 5 seeds", step0.get("boxText").getAsString());
    }

    @Test
    public void v2IsIdentityAndAddsNothing()
    {
        JsonObject v2 = parse(
            "{\"schemaVersion\":2,\"routes\":[{\"steps\":[{\"label\":\"Bank\"}]}]}");

        JsonObject migrated = RouteMigrator.migrate(v2, 2);

        JsonObject step0 = migrated.getAsJsonArray("routes").get(0).getAsJsonObject()
            .getAsJsonArray("steps").get(0).getAsJsonObject();
        assertFalse("v2 step must not be backfilled", step0.has("boxText"));
        assertEquals(2, migrated.get("schemaVersion").getAsInt());
    }
}

package com.waypointer.codec;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.model.route.Route;
import com.waypointer.model.route.RouteStep;
import java.time.Instant;
import java.util.Arrays;
import java.util.UUID;
import org.junit.Test;

public class RouteShareCodecTest
{
    private static Gson buildGson()
    {
        return new GsonBuilder()
            .registerTypeAdapter(Instant.class,
                (com.google.gson.JsonSerializer<Instant>) (src, t, c) ->
                    new com.google.gson.JsonPrimitive(src.toString()))
            .registerTypeAdapter(Instant.class,
                (com.google.gson.JsonDeserializer<Instant>) (e, t, c) ->
                    Instant.parse(e.getAsString()))
            .create();
    }

    private final RouteShareCodec codec = new RouteShareCodec(buildGson());

    private Route sample()
    {
        return new Route(UUID.randomUUID(), "Herb run",
            Arrays.asList(
                RouteStep.waypoint(WorldPointPacker.pack(3200, 3200, 0), "Bank"),
                RouteStep.manual("Withdraw seeds")),
            true, Instant.parse("2026-06-01T00:00:00Z"), 0);
    }

    @Test
    public void encodeStartsWithMagic()
    {
        assertTrue(codec.encodeRoute(sample()).startsWith(RouteShareCodec.ROUTE_MAGIC));
    }

    @Test
    public void roundTripsRoute()
    {
        Route decoded = codec.decodeRoute(codec.encodeRoute(sample()));
        assertEquals("Herb run", decoded.getName());
        assertEquals(2, decoded.getSteps().size());
        assertEquals("Withdraw seeds", decoded.getSteps().get(1).getLabel());
        assertTrue(decoded.isRepeating());
    }

    @Test
    public void roundTripsStepBoxText()
    {
        RouteStep step = RouteStep.manual("Bank");
        step.setBoxText("Withdraw 5 ranarr seeds");
        Route route = new Route(UUID.randomUUID(), "Herb run",
            Arrays.asList(step), false, Instant.parse("2026-06-01T00:00:00Z"), 0);

        Route decoded = codec.decodeRoute(codec.encodeRoute(route));
        assertEquals("Withdraw 5 ranarr seeds", decoded.getSteps().get(0).getBoxText());
    }

    @Test(expected = RouteShareCodec.MalformedCodeException.class)
    public void wrongMagicThrows()
    {
        codec.decodeRoute("WP1:whatever");
    }

    @Test(expected = RouteShareCodec.MalformedCodeException.class)
    public void garbageBase64Throws()
    {
        codec.decodeRoute("RT1:!!!notbase64!!!");
    }

    private static String rt1(String innerJson) throws java.io.IOException
    {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        try (java.util.zip.GZIPOutputStream gz = new java.util.zip.GZIPOutputStream(baos))
        {
            gz.write(innerJson.getBytes(java.nio.charset.StandardCharsets.UTF_8));
        }
        return "RT1:" + java.util.Base64.getEncoder().withoutPadding()
            .encodeToString(baos.toByteArray());
    }

    @Test(expected = RouteShareCodec.MalformedCodeException.class)
    public void rejectsRouteWithNullId() throws Exception
    {
        codec.decodeRoute(rt1("{\"name\":\"Herb run\",\"steps\":[]}"));
    }

    @Test(expected = RouteShareCodec.MalformedCodeException.class)
    public void rejectsWrongTopLevelType() throws Exception
    {
        codec.decodeRoute(rt1("[]"));
    }

    @Test
    public void decodesRouteWithNullStepsAsEmpty() throws Exception
    {
        // A null steps array must sanitize to zero steps, not NPE in sanitizeSteps.
        Route decoded = codec.decodeRoute(
            rt1("{\"id\":\"" + UUID.randomUUID() + "\",\"name\":\"R\",\"steps\":null}"));
        assertNotNull(decoded);
        assertEquals(0, decoded.getSteps().size());
    }

    @Test
    public void dropsInvalidStepsButKeepsRoute() throws Exception
    {
        String json = "{\"id\":\"" + UUID.randomUUID() + "\",\"name\":\"Herb run\",\"steps\":["
            + "{\"id\":\"" + UUID.randomUUID() + "\",\"type\":\"MANUAL\",\"label\":\"Good\"},"
            + "{\"id\":\"" + UUID.randomUUID() + "\",\"type\":\"MANUAL\"}"
            + "]}";

        Route decoded = codec.decodeRoute(rt1(json));

        assertEquals(1, decoded.getSteps().size());
        assertEquals("Good", decoded.getSteps().get(0).getLabel());
        assertNotNull("survivor must have non-null overlay text",
            decoded.getSteps().get(0).boxTextOrLabel());
    }
}

package com.waypointer.codec;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.waypointer.model.Category;
import com.waypointer.model.Library;
import com.waypointer.model.Waypoint;
import java.time.Instant;
import java.util.UUID;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class WaypointShareCodecTest
{
    private WaypointShareCodec codec;

    private final Gson fixtureGson = new GsonBuilder()
        .registerTypeAdapter(Instant.class,
            (com.google.gson.JsonSerializer<Instant>) (src, t, c) ->
                new com.google.gson.JsonPrimitive(src.toString()))
        .registerTypeAdapter(Instant.class,
            (com.google.gson.JsonDeserializer<Instant>) (e, t, c) ->
                Instant.parse(e.getAsString()))
        .create();

    private String wpl1(String innerJson) throws java.io.IOException
    {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        try (java.util.zip.GZIPOutputStream gz = new java.util.zip.GZIPOutputStream(baos))
        {
            gz.write(innerJson.getBytes(java.nio.charset.StandardCharsets.UTF_8));
        }
        return "WPL1:" + java.util.Base64.getEncoder().withoutPadding()
            .encodeToString(baos.toByteArray());
    }

    private String legacyWp1(Waypoint w, Category c) throws java.io.IOException
    {
        com.google.gson.JsonObject obj = new com.google.gson.JsonObject();
        obj.add("waypoint", fixtureGson.toJsonTree(w));
        obj.add("category", fixtureGson.toJsonTree(c));
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        try (java.util.zip.GZIPOutputStream gz = new java.util.zip.GZIPOutputStream(baos))
        {
            gz.write(obj.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));
        }
        // Unpadded base64 matches what the deleted encodeSingle produced; the codec's
        // ungzipBase64 uses a plain Base64.getDecoder(), which accepts unpadded input. Do NOT
        // switch this to a padded / URL / MIME encoder or the legacy decode contract drifts.
        return "WP1:" + java.util.Base64.getEncoder().withoutPadding()
            .encodeToString(baos.toByteArray());
    }

    @Before
    public void setUp()
    {
        Gson gson = new GsonBuilder()
            .registerTypeAdapter(Instant.class,
                (com.google.gson.JsonSerializer<Instant>) (src, t, c) ->
                    new com.google.gson.JsonPrimitive(src.toString()))
            .registerTypeAdapter(Instant.class,
                (com.google.gson.JsonDeserializer<Instant>) (e, t, c) ->
                    Instant.parse(e.getAsString()))
            .create();
        codec = new WaypointShareCodec(gson, new LibraryJsonCodec(gson));
    }

    @Test
    public void legacySingleCodeStillDecodes() throws Exception
    {
        UUID catId = UUID.randomUUID();
        Category c = new Category(catId, "Bossing", 0, false, null, false);
        Waypoint w = new Waypoint(UUID.randomUUID(), "Vorkath", 42, catId, null, "",
            Instant.parse("2026-05-02T00:00:00Z"), 0, false, null, false);

        String code = legacyWp1(w, c);
        assertTrue(code.startsWith("WP1:"));

        WaypointShareCodec.SingleResult result = codec.decodeSingle(code);
        assertEquals("Vorkath", result.waypoint.getName());
        assertEquals(42, result.waypoint.getPackedWorldPoint());
        assertEquals("Bossing", result.category.getName());
    }

    @Test
    public void legacySingleCodeDecodesAsOneWaypointLibrary() throws Exception
    {
        UUID catId = UUID.randomUUID();
        Category c = new Category(catId, "Bossing", 0, false, null, false);
        Waypoint w = new Waypoint(UUID.randomUUID(), "Vorkath", 42, catId, null, "",
            Instant.parse("2026-05-02T00:00:00Z"), 0, false, null, false);

        Library lib = codec.decodeLibrary(legacyWp1(w, c));
        assertEquals(1, lib.getWaypoints().size());
        assertEquals(1, lib.getCategories().size());
        assertEquals("Vorkath", lib.getWaypoints().get(0).getName());
    }

    @Test
    public void libraryRoundTrip()
    {
        Library lib = new Library();
        UUID c = UUID.randomUUID();
        lib.getCategories().add(new Category(c, "Banks", 0, false, null, false));
        lib.getWaypoints().add(new Waypoint(UUID.randomUUID(), "GE", 99, c, null, "",
            Instant.parse("2026-05-02T00:00:00Z"), 0, false, null, false));

        String code = codec.encodeLibrary(lib);
        assertTrue(code.startsWith("WPL1:"));

        Library back = codec.decodeLibrary(code);
        assertEquals(1, back.getCategories().size());
        assertEquals(1, back.getWaypoints().size());
    }

    @Test
    public void whitespaceTrimmedFromInput()
    {
        Library lib = new Library();
        String code = codec.encodeLibrary(lib);
        Library back = codec.decodeLibrary("  \n  " + code + "  \r\n  ");
        assertNotNull(back);
    }

    @Test(expected = WaypointShareCodec.MalformedCodeException.class)
    public void rejectsBadMagic()
    {
        codec.decodeLibrary("XYZ:1:abcd");
    }

    @Test(expected = WaypointShareCodec.MalformedCodeException.class)
    public void rejectsUnknownVersion()
    {
        codec.decodeLibrary("WPL99:abcd");
    }

    @Test(expected = WaypointShareCodec.MalformedCodeException.class)
    public void rejectsGarbage()
    {
        codec.decodeLibrary("not a code at all");
    }

    @Test
    public void libraryRoundTripPreservesIconAndBundledFlag()
    {
        Library lib = new Library();
        UUID c = UUID.randomUUID();
        lib.getCategories().add(new Category(c, "Bundled bosses", 0, false, 1234, true));
        lib.getWaypoints().add(new Waypoint(UUID.randomUUID(), "Vorkath", 7, c, 5678, "notes",
            Instant.parse("2026-05-02T00:00:00Z"), 0, false, null, false));

        Library back = codec.decodeLibrary(codec.encodeLibrary(lib));

        Category restoredCat = back.getCategories().get(0);
        assertEquals("Bundled bosses", restoredCat.getName());
        assertEquals(Integer.valueOf(1234), restoredCat.getIconId());
        assertTrue("bundled flag must round-trip", restoredCat.isBundled());

        Waypoint restoredWp = back.getWaypoints().get(0);
        assertEquals(Integer.valueOf(5678), restoredWp.getIconId());
        assertEquals("notes", restoredWp.getNotes());
    }

    @Test
    public void libraryRoundTripPreservesSchemaVersion()
    {
        Library lib = new Library();
        // Library defaults schemaVersion to CURRENT; verify it survives round-trip.
        Library back = codec.decodeLibrary(codec.encodeLibrary(lib));
        assertEquals(Library.CURRENT_SCHEMA_VERSION, back.getSchemaVersion());
    }

    @Test
    public void legacySingleCodePreservesIconNotesAndCreatedAt() throws Exception
    {
        UUID catId = UUID.randomUUID();
        Category c = new Category(catId, "Skilling", 0, false, 99, false);
        Instant ts = Instant.parse("2026-05-02T12:34:56Z");
        Waypoint w = new Waypoint(UUID.randomUUID(), "Yew tree", 100, catId, 42,
            "100k/hr at 90 wc", ts, 3, false, null, false);

        WaypointShareCodec.SingleResult r = codec.decodeSingle(legacyWp1(w, c));
        assertEquals(Integer.valueOf(42), r.waypoint.getIconId());
        assertEquals("100k/hr at 90 wc", r.waypoint.getNotes());
        assertEquals(ts, r.waypoint.getCreatedAt());
        assertEquals(Integer.valueOf(99), r.category.getIconId());
    }

    @Test(expected = WaypointShareCodec.MalformedCodeException.class)
    public void rejectsOversizedPayload() throws Exception
    {
        // Build a library big enough that the inflated JSON exceeds the 1 MiB cap.
        Library lib = new Library();
        UUID c = UUID.randomUUID();
        lib.getCategories().add(new Category(c, "X", 0, false, null, false));
        StringBuilder bigName = new StringBuilder();
        for (int i = 0; i < 200_000; i++) bigName.append('X');
        for (int i = 0; i < 10; i++)
        {
            lib.getWaypoints().add(new Waypoint(UUID.randomUUID(), bigName.toString(), 1, c, null,
                "", Instant.parse("2026-05-02T00:00:00Z"), i, false, null, false));
        }
        String code = codec.encodeLibrary(lib);
        codec.decodeLibrary(code);  // should throw on size cap
    }

    @Test(expected = WaypointShareCodec.MalformedCodeException.class)
    public void rejectsLibraryCodeFromNewerSchema() throws Exception
    {
        // Inner library schemaVersion newer than supported must be rejected, like the file-load path.
        String json = "{\"schemaVersion\":" + (Library.CURRENT_SCHEMA_VERSION + 1)
            + ",\"categories\":[],\"waypoints\":[]}";
        codec.decodeLibrary(wpl1(json));
    }

    @Test
    public void legacyLibraryCodeWithoutSchemaDecodesViaMigrator() throws Exception
    {
        // A pre-versioned inner payload (no schemaVersion) must run through the migrator and be
        // normalised to CURRENT, proving the share path now shares the file-load decode contract.
        String json = "{\"categories\":[],\"waypoints\":[]}";
        Library back = codec.decodeLibrary(wpl1(json));
        assertNotNull(back);
        assertEquals(Library.CURRENT_SCHEMA_VERSION, back.getSchemaVersion());
    }

    private static String wp1(String innerJson) throws java.io.IOException
    {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        try (java.util.zip.GZIPOutputStream gz = new java.util.zip.GZIPOutputStream(baos))
        {
            gz.write(innerJson.getBytes(java.nio.charset.StandardCharsets.UTF_8));
        }
        return "WP1:" + java.util.Base64.getEncoder().withoutPadding()
            .encodeToString(baos.toByteArray());
    }

    @Test(expected = WaypointShareCodec.MalformedCodeException.class)
    public void rejectsSingleWithEmptyWaypointAndCategory() throws Exception
    {
        codec.decodeSingle(wp1("{\"waypoint\":{},\"category\":{}}"));
    }

    @Test(expected = WaypointShareCodec.MalformedCodeException.class)
    public void rejectsSingleWithZeroCoordinate() throws Exception
    {
        UUID catId = UUID.randomUUID();
        String json = "{\"waypoint\":{\"id\":\"" + UUID.randomUUID() + "\",\"name\":\"X\","
            + "\"packedWorldPoint\":0,\"categoryId\":\"" + catId + "\"},"
            + "\"category\":{\"id\":\"" + catId + "\",\"name\":\"Bossing\","
            + "\"sortOrder\":0,\"uncategorized\":false,\"bundled\":false}}";
        codec.decodeSingle(wp1(json));
    }

    @Test(expected = WaypointShareCodec.MalformedCodeException.class)
    public void rejectsSingleWithNamelessCategory() throws Exception
    {
        UUID catId = UUID.randomUUID();
        String json = "{\"waypoint\":{\"id\":\"" + UUID.randomUUID() + "\",\"name\":\"Vorkath\","
            + "\"packedWorldPoint\":42,\"categoryId\":\"" + catId + "\"},"
            + "\"category\":{\"id\":\"" + catId + "\",\"sortOrder\":0,"
            + "\"uncategorized\":false,\"bundled\":false}}";
        codec.decodeSingle(wp1(json));
    }

    @Test(expected = WaypointShareCodec.MalformedCodeException.class)
    public void rejectsLibraryWithNullSchemaVersion() throws Exception
    {
        codec.decodeLibrary(wpl1("{\"schemaVersion\":null,\"categories\":[],\"waypoints\":[]}"));
    }

    @Test(expected = WaypointShareCodec.MalformedCodeException.class)
    public void rejectsLibraryWithStringSchemaVersion() throws Exception
    {
        codec.decodeLibrary(wpl1("{\"schemaVersion\":\"x\",\"categories\":[],\"waypoints\":[]}"));
    }

    @Test(expected = WaypointShareCodec.MalformedCodeException.class)
    public void rejectsLibraryWithInvalidBase64()
    {
        codec.decodeLibrary("WPL1:!!!notbase64!!!");
    }

    @Test(expected = WaypointShareCodec.MalformedCodeException.class)
    public void rejectsLibraryWithArrayTopLevel() throws Exception
    {
        codec.decodeLibrary(wpl1("[]"));
    }

    @Test(expected = WaypointShareCodec.MalformedCodeException.class)
    public void rejectsLibraryWithStringTopLevel() throws Exception
    {
        codec.decodeLibrary(wpl1("\"not an object\""));
    }

    @Test
    public void decodesLibraryWithNullArrays() throws Exception
    {
        // Null categories/waypoints must decode to an empty library, not crash. Asserts the
        // LibraryJsonCodec null-array defense reached through the share path.
        Library back = codec.decodeLibrary(wpl1("{\"categories\":null,\"waypoints\":null}"));
        assertNotNull(back);
        assertEquals(0, back.getCategories().size());
        assertEquals(0, back.getWaypoints().size());
    }

    @Test
    public void decodeLibraryWithReportCountsDrops() throws Exception
    {
        UUID catId = UUID.randomUUID();
        String json = "{\"schemaVersion\":2,"
            + "\"categories\":[{\"id\":\"" + catId + "\",\"name\":\"Keep\",\"sortOrder\":0,"
            + "\"uncategorized\":false,\"bundled\":false}],"
            + "\"waypoints\":["
            + "{\"id\":\"" + UUID.randomUUID() + "\",\"name\":\"Good\",\"packedWorldPoint\":42,\"categoryId\":\"" + catId + "\"},"
            + "{\"name\":\"NoId\",\"packedWorldPoint\":42}"
            + "]}";

        DecodeReport r = codec.decodeLibraryWithReport(wpl1(json));

        assertEquals(1, r.library.getWaypoints().size());
        assertEquals(1, r.droppedWaypoints);
        assertEquals(0, r.droppedCategories);
    }

    @Test
    public void decodeLibraryWithReportForSingleHasZeroDrops() throws Exception
    {
        UUID catId = UUID.randomUUID();
        Category c = new Category(catId, "Bossing", 0, false, null, false);
        Waypoint w = new Waypoint(UUID.randomUUID(), "Vorkath", 42, catId, null, "",
            Instant.parse("2026-05-02T00:00:00Z"), 0, false, null, false);

        DecodeReport r = codec.decodeLibraryWithReport(legacyWp1(w, c));

        assertEquals(1, r.library.getWaypoints().size());
        assertEquals(0, r.droppedWaypoints);
        assertEquals(0, r.droppedCategories);
    }
