package com.waypointer.sailing;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import org.junit.BeforeClass;
import org.junit.Test;

public class WaterMapTest
{
    private static final String[] LANDMARK_FILES = {
        "altars", "anvils", "bank-chests", "banks", "charter-ships", "fairy-rings", "furnaces",
        "landmarks", "looms", "slayer-masters", "spinning-wheels", "spirit-trees", "tanners",
    };

    /** The one bundled landmark that really is on the open sea. */
    private static final String KNOWN_AT_SEA = "Bank Boat Bank";

    private static WaterMap map;

    @BeforeClass
    public static void loadRealData()
    {
        map = new WaterMap(); // the real bundled resource
        map.warm();
    }

    @Test
    public void portSarimSeaIsWater()
    {
        assertTrue(map.isWater(WaterMap.SEED_X, WaterMap.SEED_Y));
        assertTrue(map.isAtSea(WaterMap.SEED_X, WaterMap.SEED_Y));
    }

    @Test
    public void adjacentDockTileIsLand()
    {
        assertFalse(map.isWater(3048, 3192));
        assertFalse(map.isAtSea(3048, 3192));
    }

    @Test
    public void tileMissingFromTheDataIsLand()
    {
        assertFalse(map.isWater(3222, 3218));
        assertFalse(map.isAtSea(3222, 3218));
    }

    @Test
    public void wrongPlaneIsNotWater()
    {
        assertFalse(map.isWater(new WorldPoint(3051, 3195, 1)));
        assertFalse(map.isAtSea(new WorldPoint(3051, 3195, 1)));
    }

    @Test
    public void walkableTownTilesAreLand()
    {
        // All three are open (walkable) in the collision map but not connected to the sea.
        int[][] land = { {3166, 3487}, {3254, 3421}, {3093, 3244} }; // GE, Varrock East Bank, Draynor Bank
        for (int[] t : land)
        {
            assertFalse(t[0] + "," + t[1], map.isWater(t[0], t[1]));
            assertFalse(t[0] + "," + t[1], map.isAtSea(t[0], t[1]));
        }
    }

    @Test
    public void seaHoldsMostOpenTiles() throws IOException
    {
        // Guards against a seed that lands in a lake after a data refresh.
        long open = 0;
        for (WaterCollisionData.Chunk c : readRealChunks().values())
        {
            open += Long.bitCount(c.known & ~c.blocked);
        }
        assertTrue("sea " + map.seaSize() + " of open " + open, map.seaSize() * 2L > open);
    }

    @Test
    public void bundledLandmarksAndPresetsOnLandAreNotAtSea() throws IOException
    {
        List<String> atSea = new ArrayList<>();
        int checked = 0;
        for (String file : LANDMARK_FILES)
        {
            try (BufferedReader in = reader("/com/waypointer/landmarks/" + file + "-bboxes.tsv"))
            {
                String line;
                while ((line = in.readLine()) != null)
                {
                    if (line.startsWith("#") || line.trim().isEmpty()) continue;
                    String[] cols = line.split("\t");
                    String[] c = cols[0].trim().split("\\s+");
                    int x = (Integer.parseInt(c[0]) + Integer.parseInt(c[2])) / 2;
                    int y = (Integer.parseInt(c[1]) + Integer.parseInt(c[3])) / 2;
                    checked++;
                    if (map.isAtSea(new WorldPoint(x, y, Integer.parseInt(c[4]))) && !KNOWN_AT_SEA.equals(cols[1]))
                    {
                        atSea.add(file + ": " + cols[1]);
                    }
                }
            }
        }
        try (BufferedReader in = reader("/com/waypointer/preset-waypoints.json"))
        {
            JsonObject root = new JsonParser().parse(in).getAsJsonObject();
            for (JsonElement cat : root.getAsJsonArray("presets"))
            {
                for (JsonElement w : cat.getAsJsonObject().getAsJsonArray("waypoints"))
                {
                    JsonObject o = w.getAsJsonObject();
                    int plane = o.has("plane") ? o.get("plane").getAsInt() : 0;
                    checked++;
                    if (map.isAtSea(new WorldPoint(o.get("x").getAsInt(), o.get("y").getAsInt(), plane)))
                    {
                        atSea.add("preset: " + o.get("name").getAsString());
                    }
                }
            }
        }
        assertTrue("nothing checked", checked > 500);
        assertEquals(new ArrayList<String>(), atSea);
    }

    @Test
    public void bankBoatIsAtSea()
    {
        assertTrue(map.isAtSea(2280, 2544));
    }

    @Test
    public void everyDockIsWithinThreeTilesOfTheSea()
    {
        for (SailingDock dock : SailingDock.values())
        {
            WorldPoint p = dock.getNavigationLocation();
            boolean near = false;
            for (int dx = -3; dx <= 3 && !near; dx++)
            {
                for (int dy = -3; dy <= 3 && !near; dy++)
                {
                    near = map.isWater(p.getX() + dx, p.getY() + dy);
                }
            }
            assertTrue(dock.name(), near);
        }
    }

    @Test
    public void blockedTileInOpenWaterIsAtSea()
    {
        assertTrue(fixture(48).isAtSea(1000, 1000));
    }

    @Test
    public void halfWaterCoastIsNotAtSea()
    {
        assertFalse(fixture(24).isAtSea(1000, 1000));
    }

    @Test
    public void thresholdIsThirtySevenOfFortyNine()
    {
        assertFalse(fixture(36).isAtSea(1000, 1000));
        assertTrue(fixture(37).isAtSea(1000, 1000));
    }

    @Test
    public void openTilesCutOffFromTheSeedAreLand()
    {
        // Two open tiles with a blocked one between them: only the seed's side is sea.
        Map<Long, WaterCollisionData.Chunk> chunks = new HashMap<>();
        long known = 0b111L;
        long blocked = 0b010L;
        chunks.put(WaterCollisionData.key(0, 0), new WaterCollisionData.Chunk(known, blocked));
        WaterMap m = new WaterMap(new WaterCollisionData(chunks), 0, 0);
        assertTrue(m.isWater(0, 0));
        assertFalse(m.isWater(1, 0));
        assertFalse(m.isWater(2, 0));
    }

    @Test
    public void seedThatIsNotOpenLeavesEverythingLand()
    {
        WaterMap m = new WaterMap(new WaterCollisionData(new HashMap<>()), 0, 0);
        assertFalse(m.isWater(0, 0));
        assertFalse(m.isAtSea(0, 0));
    }

    /** Known area 984..1015 squared, all blocked except {@code open} tiles taken in row order
     *  from the 7x7 box around (1000, 1000). The centre is never open. The open tiles touch, and
     *  the first of them, (997, 997), seeds the sea. */
    private static WaterMap fixture(int open)
    {
        Map<Long, WaterCollisionData.Chunk> chunks = new HashMap<>();
        int remaining = open;
        for (int x = 984; x < 1016; x++)
        {
            for (int y = 984; y < 1016; y++)
            {
                boolean inBox = Math.abs(x - 1000) <= 3 && Math.abs(y - 1000) <= 3;
                boolean isOpen = false;
                if (inBox && !(x == 1000 && y == 1000) && remaining > 0)
                {
                    isOpen = true;
                    remaining--;
                }
                long key = WaterCollisionData.key(x >> 3, y >> 3);
                WaterCollisionData.Chunk c = chunks.get(key);
                long known = c == null ? 0 : c.known;
                long blocked = c == null ? 0 : c.blocked;
                long bit = 1L << ((x & 7) + ((y & 7) << 3));
                known |= bit;
                if (!isOpen)
                {
                    blocked |= bit;
                }
                chunks.put(key, new WaterCollisionData.Chunk(known, blocked));
            }
        }
        return new WaterMap(new WaterCollisionData(chunks), 997, 997);
    }

    private static Map<Long, WaterCollisionData.Chunk> readRealChunks() throws IOException
    {
        try (InputStream in = WaterMapTest.class.getResourceAsStream("/com/waypointer/sailing/water-collision.txt"))
        {
            return WaterCollisionCodec.readText(in);
        }
    }

    private static BufferedReader reader(String resource)
    {
        InputStream in = WaterMapTest.class.getResourceAsStream(resource);
        if (in == null) throw new AssertionError("missing resource " + resource);
        return new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
    }
}

package com.waypointer.service;

import com.waypointer.model.WorldPointPacker;
import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class BboxIndexTest
{
    @Test
    public void loadsBundledTsvs()
    {
        BboxIndex idx = new BboxIndex();
        // (0, 0, 0) is outside every known bbox so the bundled-resource ctor must return null
        // rather than throwing — proves loadResource walked every TSV without error.
        assertNull(idx.lookup(WorldPointPacker.pack(0, 0, 0)));
    }

    @Test
    public void forTestingBuildsFromLiteralEntries()
    {
        BboxIndex idx = BboxIndex.forTesting(Arrays.asList(
            new BboxIndex.Entry(3087, 3486, 3103, 3502, 0, "Edgeville Bank")));
        assertEquals("Edgeville Bank", idx.lookup(WorldPointPacker.pack(3094, 3493, 0)));
    }

    @Test
    public void entryComputesAreaInclusive()
    {
        BboxIndex.Entry e = new BboxIndex.Entry(0, 0, 4, 4, 0, "x");
        assertTrue(e.area == 25); // (4-0+1) * (4-0+1)
    }

    @Test
    public void tileInsideBboxReturnsName()
    {
        BboxIndex idx = BboxIndex.forTesting(Arrays.asList(
            new BboxIndex.Entry(3087, 3486, 3103, 3502, 0, "Edgeville Bank")));

        assertEquals("Edgeville Bank", idx.lookup(WorldPointPacker.pack(3094, 3493, 0)));
    }

    @Test
    public void tileOutsideBboxReturnsNull()
    {
        BboxIndex idx = BboxIndex.forTesting(Arrays.asList(
            new BboxIndex.Entry(3087, 3486, 3103, 3502, 0, "Edgeville Bank")));

        assertNull(idx.lookup(WorldPointPacker.pack(3200, 3200, 0)));
    }

    @Test
    public void smallestAreaWinsOnOverlap()
    {
        // Outer 100x100 polygon, inner 5x5 polygon, point inside both.
        BboxIndex idx = BboxIndex.forTesting(Arrays.asList(
            new BboxIndex.Entry(3000, 3000, 3099, 3099, 0, "Big Area"),
            new BboxIndex.Entry(3050, 3050, 3054, 3054, 0, "Small POI")));

        assertEquals("Small POI", idx.lookup(WorldPointPacker.pack(3052, 3052, 0)));
    }

    @Test
    public void ignoresOtherPlanes()
    {
        BboxIndex idx = BboxIndex.forTesting(Arrays.asList(
            new BboxIndex.Entry(3087, 3486, 3103, 3502, 0, "Edgeville Bank")));

        assertNull(idx.lookup(WorldPointPacker.pack(3094, 3493, 1)));
    }

    @Test
    public void degenerateOneByOneBboxMatchesExactTile()
    {
        BboxIndex idx = BboxIndex.forTesting(Arrays.asList(
            new BboxIndex.Entry(2412, 4434, 2412, 4434, 0, "Zanaris Fairy Ring")));

        assertEquals("Zanaris Fairy Ring", idx.lookup(WorldPointPacker.pack(2412, 4434, 0)));
        assertNull(idx.lookup(WorldPointPacker.pack(2413, 4434, 0)));
    }

    @Test
    public void bundledTsvsCoverEdgevilleBank()
    {
        BboxIndex idx = new BboxIndex();
        String name = idx.lookup(WorldPointPacker.pack(3094, 3493, 0));
        assertEquals("Edgeville Bank", name);
    }

    @Test
    public void bundledTsvsCoverGrandExchangePlaza()
    {
        BboxIndex idx = new BboxIndex();
        String name = idx.lookup(WorldPointPacker.pack(3163, 3490, 0));
        assertNotNull(name);
        assertTrue("expected GE-area bbox, got " + name, name.toLowerCase().contains("grand exchange"));
    }

    // --- nearest(type, from) -----------------------------------------------------

    @Test
    public void nearest_picksClosestOfRequestedType()
    {
        // Two banks at different distances; player at (3094, 3493). The Edgeville one
        // (centre ~3094, 3494) is right next to the player; Falador (~3014, 3357) is far.
        BboxIndex idx = BboxIndex.forTesting(java.util.Arrays.asList(
            new BboxIndex.Entry(3087, 3486, 3103, 3502, 0, "Edgeville Bank", LandmarkType.BANK),
            new BboxIndex.Entry(3010, 3353, 3018, 3361, 0, "Falador West Bank", LandmarkType.BANK)));

        BboxIndex.Hit hit = idx.nearest(LandmarkType.BANK, WorldPointPacker.pack(3094, 3493, 0));

        assertNotNull(hit);
        assertEquals("Edgeville Bank", hit.name);
    }

    @Test
    public void nearest_distanceClampsToEdgeButTargetsCentre()
    {
        // 5x5 bank at (3050..3054, 3050..3054). Player at (3056, 3052) is 2 tiles east of the
        // bbox: distance ranks by the nearest edge (2), but the path target is the bbox CENTRE
        // (3052, 3052) so quick-nav ends inside the bank, not on its boundary.
        BboxIndex idx = BboxIndex.forTesting(java.util.Collections.singletonList(
            new BboxIndex.Entry(3050, 3050, 3054, 3054, 0, "Test Bank", LandmarkType.BANK)));

        BboxIndex.Hit hit = idx.nearest(LandmarkType.BANK, WorldPointPacker.pack(3056, 3052, 0));

        assertNotNull(hit);
        assertEquals(2, hit.distance);
        assertEquals(3052, WorldPointPacker.getX(hit.packed));
        assertEquals(3052, WorldPointPacker.getY(hit.packed));
        assertEquals(0, WorldPointPacker.getPlane(hit.packed));
    }

    @Test
    public void nearest_isPlaneAgnostic()
    {
        // Player on plane 1 (dungeon), only bank is on plane 0 (overworld).
        // Plane-agnostic search returns it, and the Hit carries the bbox's plane (0).
        BboxIndex idx = BboxIndex.forTesting(java.util.Collections.singletonList(
            new BboxIndex.Entry(3087, 3486, 3103, 3502, 0, "Edgeville Bank", LandmarkType.BANK)));

        BboxIndex.Hit hit = idx.nearest(LandmarkType.BANK, WorldPointPacker.pack(3094, 3493, 1));

        assertNotNull(hit);
        assertEquals(0, WorldPointPacker.getPlane(hit.packed));
    }

    @Test
    public void nearest_returnsNullWhenNoEntriesOfType()
    {
        BboxIndex idx = BboxIndex.forTesting(java.util.Collections.singletonList(
            new BboxIndex.Entry(3087, 3486, 3103, 3502, 0, "Edgeville Bank", LandmarkType.BANK)));

        // No altars in the index at all.
        assertNull(idx.nearest(LandmarkType.ALTAR, WorldPointPacker.pack(3094, 3493, 0)));
    }

    @Test
    public void nearest_chebyshevDiagonalIsOne()
    {
        // 1x1 bank at (3050, 3050). Player at (3051, 3051) is one tile diagonally away.
        // Chebyshev gives 1 (matches OSRS movement), not sqrt(2).
        BboxIndex idx = BboxIndex.forTesting(java.util.Collections.singletonList(
            new BboxIndex.Entry(3050, 3050, 3050, 3050, 0, "Tile Bank", LandmarkType.BANK)));

        BboxIndex.Hit hit = idx.nearest(LandmarkType.BANK, WorldPointPacker.pack(3051, 3051, 0));

        assertNotNull(hit);
        assertEquals(1, hit.distance);
    }

    @Test
    public void nearest_includesBankChests()
    {
        // Use the production constructor so the bank-chests TSV's BANK mapping is actually
        // exercised. The Lunar Isle bank chest lives around (2099, 3919). Asking for the
        // nearest BANK from that tile must return a hit (could be the chest or a Piscarilius
        // bank further away -- both are LandmarkType.BANK).
        BboxIndex idx = new BboxIndex();
        BboxIndex.Hit hit = idx.nearest(LandmarkType.BANK, WorldPointPacker.pack(2099, 3919, 0));

        assertNotNull(hit);
        // distance to the nearest BANK from inside the dataset must be small (this point
        // sits on or near the Lunar Isle bank chest itself).
        assertTrue("expected nearby bank, got distance " + hit.distance, hit.distance < 10);
    }
}

package com.waypointer.service;

import com.waypointer.model.WorldPointPacker;
