package com.waypointer.ui;

import com.waypointer.model.Waypoint;
import java.time.Instant;
import java.util.UUID;
import org.junit.Test;
import static org.junit.Assert.*;

public class AccessibleNamesTest
{
    @Test
    public void palettePopupItemsAreNamed()
    {
        javax.swing.JPopupMenu p = ColorPalettePopup.build(null, rgb -> {});
        javax.swing.JMenuItem first = (javax.swing.JMenuItem) p.getComponent(0);
        assertNotNull(first.getAccessibleContext().getAccessibleName());
        assertFalse(first.getAccessibleContext().getAccessibleName().isEmpty());
    }

    @Test
    public void waypointRowPlayButtonIsNamed()
    {
        Waypoint wp = new Waypoint(UUID.randomUUID(), "Bank", 0, UUID.randomUUID(), null,
            "", Instant.parse("2026-05-02T00:00:00Z"), 0, false, null, false);
        // selectMode=false so the row builds its Play button, which the accessibility
        // sweep names "Path to <name>". SpriteManager may be null (icon is unset).
        WaypointRow row = WaypointRow.spec(wp)
            .onPlay(() -> {})
            .onClickBody(() -> {})
            .onTogglePin(() -> {})
            .onDelete(() -> {})
            .onSelectClick(sel -> {})
            .build();
        assertTrue("expected a 'Path to ...' accessible name on a row control",
            hasAccessibleNameStartingWith(row, "Path to"));
    }

    private static boolean hasAccessibleNameStartingWith(java.awt.Component c, String prefix)
    {
        if (c instanceof javax.accessibility.Accessible)
        {
            javax.accessibility.AccessibleContext ctx = ((javax.accessibility.Accessible) c).getAccessibleContext();
            if (ctx != null)
            {
                String n = ctx.getAccessibleName();
                if (n != null && n.startsWith(prefix)) return true;
            }
        }
        if (c instanceof java.awt.Container)
        {
            for (java.awt.Component child : ((java.awt.Container) c).getComponents())
            {
                if (hasAccessibleNameStartingWith(child, prefix)) return true;
            }
        }
        return false;
    }
}

package com.waypointer.ui;

import com.waypointer.WaypointerConfig;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.service.WaypointPathfinder;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class ActivePathBannerTest
{
    private WaypointPathfinder pathfinder;
    private WaypointerConfig config;
    private ActivePathBanner banner;
    // Flipped by tests that exercise the saved-waypoint suppression branch. Default false so the
    // existing rowless-path assertions (landmark/preset/route) keep showing the banner.

    @Before
    public void setUp()
    {
        pathfinder = mock(WaypointPathfinder.class);
        config = mock(WaypointerConfig.class);
        when(config.showPathingBanner()).thenReturn(true);
        when(pathfinder.getActiveTarget()).thenReturn(WorldPointPacker.UNDEFINED);
        banner = new ActivePathBanner(com.waypointer.service.LandNavigator.over(pathfinder), config);
    }

    @Test
    public void hiddenWhenNoActiveTarget()
    {
        banner.refresh();
        assertFalse(banner.isVisible());
    }

    @Test
    public void visibleAndLabelledWhenPathActive()
    {
        when(pathfinder.getActiveTarget()).thenReturn(WorldPointPacker.pack(3162, 3486, 0));
        when(pathfinder.getActiveName()).thenReturn("Vorkath");
        banner.refresh();
        assertTrue(banner.isVisible());
        assertTrue("label should mention the destination, got: " + banner.getLabelText(),
            banner.getLabelText().contains("Vorkath"));
    }

    @Test
    public void hiddenWhenSettingDisabledEvenWithActiveTarget()
    {
        when(pathfinder.getActiveTarget()).thenReturn(WorldPointPacker.pack(3162, 3486, 0));
        when(pathfinder.getActiveName()).thenReturn("Vorkath");
        when(config.showPathingBanner()).thenReturn(false);
        banner.refresh();
        assertFalse(banner.isVisible());
    }

    @Test
    public void hidesAfterClearedTarget()
    {
        when(pathfinder.getActiveTarget()).thenReturn(WorldPointPacker.pack(3162, 3486, 0));
        when(pathfinder.getActiveName()).thenReturn("Vorkath");
        banner.refresh();
        assertTrue(banner.isVisible());

        when(pathfinder.getActiveTarget()).thenReturn(WorldPointPacker.UNDEFINED);
        when(pathfinder.getActiveName()).thenReturn(null);
        banner.refresh();
        assertFalse(banner.isVisible());
    }

    @Test
    public void stopButtonClearsPath()
    {
        when(pathfinder.getActiveTarget()).thenReturn(WorldPointPacker.pack(3162, 3486, 0));
        when(pathfinder.getActiveName()).thenReturn("Vorkath");
        banner.refresh();
        banner.clickStopForTest();
        verify(pathfinder).clearPath();
    }

    @Test
    public void escapesHtmlInWaypointName()
    {
        when(pathfinder.getActiveTarget()).thenReturn(WorldPointPacker.pack(3162, 3486, 0));
        when(pathfinder.getActiveName()).thenReturn("<b>cheeky</b>");
        banner.refresh();
        String html = banner.getLabelText();
        assertFalse("raw <b> should not appear in label HTML, got: " + html,
            html.contains("<b>cheeky</b>"));
        assertTrue("escaped marker should appear, got: " + html, html.contains("&lt;b&gt;"));
    }
}

package com.waypointer.ui;

import java.util.Set;
import java.util.UUID;
import org.junit.Test;
import static org.junit.Assert.*;

public class AutoExpandControllerTest
{
    @Test
    public void recordAndIsTransientlyExpanded()
    {
        AutoExpandController c = new AutoExpandController();
        UUID a = UUID.randomUUID();
        assertFalse(c.isTransientlyExpanded(a));
        c.recordTransientExpand(a);
        assertTrue(c.isTransientlyExpanded(a));
    }

    @Test
    public void onHoverInsideAutoExpandedDoesNotRevertIt()
    {
        AutoExpandController c = new AutoExpandController();
        UUID a = UUID.randomUUID();
        c.recordTransientExpand(a);
        Set<UUID> reverted = c.onHover(a);
        assertTrue(reverted.isEmpty());
        assertTrue(c.isTransientlyExpanded(a));
    }

    @Test
    public void onHoverOutsideAutoExpandedRevertsIt()
    {
        AutoExpandController c = new AutoExpandController();
        UUID a = UUID.randomUUID();
        UUID other = UUID.randomUUID();
        c.recordTransientExpand(a);
        Set<UUID> reverted = c.onHover(other);
        assertEquals(java.util.Collections.singleton(a), reverted);
        assertFalse(c.isTransientlyExpanded(a));
    }

    @Test
    public void onHoverWithMultipleAutoExpandedRevertsOnlyOutsideOnes()
    {
        AutoExpandController c = new AutoExpandController();
        UUID a = UUID.randomUUID();
        UUID b = UUID.randomUUID();
        c.recordTransientExpand(a);
        c.recordTransientExpand(b);
        Set<UUID> reverted = c.onHover(a);
        assertEquals(java.util.Collections.singleton(b), reverted);
        assertTrue(c.isTransientlyExpanded(a));
        assertFalse(c.isTransientlyExpanded(b));
    }

    @Test
    public void onDropAtAutoExpandedConfirmsIt()
    {
        AutoExpandController c = new AutoExpandController();
        UUID a = UUID.randomUUID();
        c.recordTransientExpand(a);
        AutoExpandController.DropResolution r = c.onDropAt(a);
        assertEquals(a, r.getToConfirm());
        assertTrue(r.getToRevert().isEmpty());
        assertFalse(c.isTransientlyExpanded(a));
    }

    @Test
    public void onDropAtAutoExpandedRevertsOthers()
    {
        AutoExpandController c = new AutoExpandController();
        UUID a = UUID.randomUUID();
        UUID b = UUID.randomUUID();
        c.recordTransientExpand(a);
        c.recordTransientExpand(b);
        AutoExpandController.DropResolution r = c.onDropAt(a);
        assertEquals(a, r.getToConfirm());
        assertEquals(java.util.Collections.singleton(b), r.getToRevert());
        assertFalse(c.isTransientlyExpanded(a));
        assertFalse(c.isTransientlyExpanded(b));
    }

    @Test
    public void onDropAtNonAutoExpandedRevertsAll()
    {
        AutoExpandController c = new AutoExpandController();
        UUID a = UUID.randomUUID();
        UUID b = UUID.randomUUID();
        UUID dest = UUID.randomUUID();
        c.recordTransientExpand(a);
        c.recordTransientExpand(b);
        AutoExpandController.DropResolution r = c.onDropAt(dest);
        assertNull(r.getToConfirm());
        assertEquals(2, r.getToRevert().size());
        assertTrue(r.getToRevert().contains(a));
        assertTrue(r.getToRevert().contains(b));
    }

    @Test
    public void onDragEndReturnsAllAutoExpandedAndClears()
    {
        AutoExpandController c = new AutoExpandController();
        UUID a = UUID.randomUUID();
        UUID b = UUID.randomUUID();
        c.recordTransientExpand(a);
        c.recordTransientExpand(b);
        Set<UUID> reverted = c.onDragEnd();
        assertEquals(2, reverted.size());
        assertTrue(reverted.contains(a));
        assertTrue(reverted.contains(b));
        assertFalse(c.isTransientlyExpanded(a));
        assertFalse(c.isTransientlyExpanded(b));
    }

    @Test
    public void onDragEndWithNothingExpandedReturnsEmpty()
    {
        AutoExpandController c = new AutoExpandController();
        assertTrue(c.onDragEnd().isEmpty());
    }
}

package com.waypointer.ui;

import com.waypointer.codec.WaypointShareCodec;
import com.waypointer.model.Category;
import com.waypointer.model.Library;
import com.waypointer.model.Waypoint;
import com.waypointer.service.WaypointStore;
import java.awt.Window;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;

public class BulkSelectControllerTest
{
    // No-op host: counts rebuilds, never touches a real window.
    private static final class CountingHost implements BulkSelectController.Host
    {
        int rebuilds;
        @Override public void rebuild() { rebuilds++; }
        @Override public void revalidateAndRepaint() { }
        @Override public Window windowAncestor() { return null; }
    }

    private static WaypointStore freshStore()
    {
        WaypointStore store = new WaypointStore();
        store.bootstrap(new Library());
        return store;
    }

    private static BulkSelectController newController(WaypointStore store, CountingHost host)
    {
        return new BulkSelectController(
            store,
            Toasts.NO_OP,
            mock(WaypointShareCodec.class),
            host);
    }

    @Test
    public void enterAndExitSelectModeFlipTheFlag()
    {
        WaypointStore store = freshStore();
        BulkSelectController c = newController(store, new CountingHost());

        assertFalse(c.isSelectMode());
        c.enterSelectMode();
        assertTrue(c.isSelectMode());
        c.exitSelectMode();
        assertFalse(c.isSelectMode());
    }

    @Test
    public void toggleSelectModeFlipsTheFlag()
    {
        WaypointStore store = freshStore();
        BulkSelectController c = newController(store, new CountingHost());

        assertFalse(c.isSelectMode());
        c.toggleSelectMode();
        assertTrue(c.isSelectMode());
        c.toggleSelectMode();
        assertFalse(c.isSelectMode());
    }

    @Test
    public void bulkDeleteRemovesSelectedAndClearsSelection()
    {
        WaypointStore store = freshStore();
        Category cat = store.getUncategorized();
        Waypoint a = store.createWaypoint(1, "A", cat.getId());
        Waypoint b = store.createWaypoint(2, "B", cat.getId());

        CountingHost host = new CountingHost();
        BulkSelectController c = newController(store, host);
        c.toggleSelectMode();
        c.onRowSelectClicked(a, false);
        c.onRowSelectClicked(b, false);
        assertEquals(2, c.selection().size());

        c.bulkDeleteForTest();

        assertTrue("selection cleared after delete", c.selection().isEmpty());
        assertTrue("both waypoints removed from the store",
            store.getWaypointsInCategory(cat.getId()).isEmpty());
    }

    @Test
    public void bulkMoveReassignsCategoryAndClearsSelection()
    {
        WaypointStore store = freshStore();
        Category src = store.getUncategorized();
        Category dst = store.createCategory("Dest");
        Waypoint a = store.createWaypoint(1, "A", src.getId());

        CountingHost host = new CountingHost();
        BulkSelectController c = newController(store, host);
        c.toggleSelectMode();
        c.onRowSelectClicked(a, false);

        c.bulkMoveToForTest(dst.getId());

        assertTrue("selection cleared after move", c.selection().isEmpty());
        assertEquals(1, store.getWaypointsInCategory(dst.getId()).size());
        assertTrue(store.getWaypointsInCategory(src.getId()).isEmpty());
    }
}

package com.waypointer.ui;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.UUID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class BulkSelectionTest
{
    @Test
    public void toggleAddsThenRemoves()
    {
        BulkSelection s = new BulkSelection();
        UUID a = UUID.randomUUID();
        assertTrue(s.isEmpty());
        s.toggle(a);
        assertTrue(s.ids().contains(a));
        assertEquals(1, s.size());
        s.toggle(a);
        assertFalse(s.ids().contains(a));
        assertTrue(s.isEmpty());
    }

    @Test
    public void selectRangeForwardIsInclusiveAndAdditive()
    {
        BulkSelection s = new BulkSelection();
        UUID a = UUID.randomUUID(), b = UUID.randomUUID(), c = UUID.randomUUID(), d = UUID.randomUUID();
        List<UUID> ordered = Arrays.asList(a, b, c, d);
        s.selectRange(ordered, b, d);
        assertTrue(s.ids().contains(b));
        assertTrue(s.ids().contains(c));
        assertTrue(s.ids().contains(d));
        assertFalse(s.ids().contains(a));
    }

    @Test
    public void selectRangeBackwardAnchorWorks()
    {
        BulkSelection s = new BulkSelection();
        UUID a = UUID.randomUUID(), b = UUID.randomUUID(), c = UUID.randomUUID();
        List<UUID> ordered = Arrays.asList(a, b, c);
        s.selectRange(ordered, c, a); // anchor after target
        assertEquals(3, s.size());
    }

    @Test
    public void selectRangeWithMissingAnchorIsNoOp()
    {
        BulkSelection s = new BulkSelection();
        UUID a = UUID.randomUUID(), b = UUID.randomUUID();
        s.selectRange(Arrays.asList(a, b), UUID.randomUUID(), b);
        assertTrue(s.isEmpty());
    }

    @Test
    public void setCategorySelectsAndDeselects()
    {
        BulkSelection s = new BulkSelection();
        UUID a = UUID.randomUUID(), b = UUID.randomUUID();
        List<UUID> cat = Arrays.asList(a, b);
        s.setCategory(cat, true);
        assertEquals(2, s.size());
        s.setCategory(cat, false);
        assertTrue(s.isEmpty());
    }

    @Test
    public void categoryStateTriState()
    {
        BulkSelection s = new BulkSelection();
        UUID a = UUID.randomUUID(), b = UUID.randomUUID();
        List<UUID> cat = Arrays.asList(a, b);
        assertEquals(BulkSelection.TriState.NONE, s.categoryState(cat));
        s.toggle(a);
        assertEquals(BulkSelection.TriState.PARTIAL, s.categoryState(cat));
        s.toggle(b);
        assertEquals(BulkSelection.TriState.ALL, s.categoryState(cat));
    }

    @Test
    public void emptyCategoryStateIsNone()
    {
        BulkSelection s = new BulkSelection();
        assertEquals(BulkSelection.TriState.NONE, s.categoryState(Collections.emptyList()));
    }

    @Test
    public void clearEmptiesSelection()
    {
        BulkSelection s = new BulkSelection();
        s.toggle(UUID.randomUUID());
        s.clear();
        assertTrue(s.isEmpty());
    }

    @Test
    public void selectionIsIdKeyedAndSurvivesADifferentVisibleList()
    {
        BulkSelection s = new BulkSelection();
        UUID a = UUID.randomUUID();
        s.toggle(a);
        // A later visible list that does not even contain 'a'; id-keyed selection must stand
        // and the range adds on top of it.
        UUID x = UUID.randomUUID(), y = UUID.randomUUID();
        s.selectRange(Arrays.asList(x, y), x, y);
        assertTrue(s.ids().contains(a));
        assertEquals(3, s.size());
    }

    @Test
    public void idsPreservesInsertionOrder()
    {
        BulkSelection s = new BulkSelection();
        UUID a = UUID.randomUUID(), b = UUID.randomUUID(), c = UUID.randomUUID();
        s.toggle(b);
        s.toggle(a);
        s.toggle(c);
        assertEquals(Arrays.asList(b, a, c), new java.util.ArrayList<>(s.ids()));
    }

    @Test
    public void idsReturnsACopy()
    {
        BulkSelection s = new BulkSelection();
        UUID a = UUID.randomUUID();
        s.toggle(a);
        s.ids().clear(); // mutating the returned set must not affect internal state
        assertTrue(s.ids().contains(a));
    }

    @Test
    public void selectRangeFromEqualsToSelectsExactlyOne()
    {
        BulkSelection s = new BulkSelection();
        UUID a = UUID.randomUUID(), b = UUID.randomUUID(), c = UUID.randomUUID();
        s.selectRange(Arrays.asList(a, b, c), b, b);
        assertEquals(1, s.size());
        assertTrue(s.ids().contains(b));
    }

    @Test
    public void setCategoryOverlapKeepsExistingAndAddsRest()
    {
        BulkSelection s = new BulkSelection();
        UUID a = UUID.randomUUID(), b = UUID.randomUUID();
        s.toggle(a);                                   // pre-existing partial selection
        s.setCategory(Arrays.asList(a, b), true);      // overlap: a already in
        assertEquals(2, s.size());
        assertTrue(s.ids().contains(a));
        assertTrue(s.ids().contains(b));
    }
}

package com.waypointer.ui;

import com.waypointer.model.Library;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.service.WaypointCapture;
import com.waypointer.service.WaypointStore;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class CaptureFormTest
{
    private WaypointStore store;
    private WaypointCapture capture;
    private CaptureForm form;
    private int packed;

    @Before
    public void setUp()
    {
        store = new WaypointStore();
        store.bootstrap(new Library());
        capture = mock(WaypointCapture.class);
        packed = WorldPointPacker.pack(3222, 3218, 0);
        when(capture.defaultName(packed)).thenReturn("Lumbridge");
        form = new CaptureForm(store, capture);
    }

    @Test
    public void hiddenByDefault()
    {
        assertFalse(form.isVisible());
    }

    @Test
    public void showPopulatesDefaultNameAndBecomesVisible()
    {
        form.show(packed);
        assertTrue(form.isVisible());
        assertEquals("Lumbridge", form.getNameText());
    }

    @Test
    public void dismissFlipsVisibilityOff()
    {
        form.show(packed);
        form.dismiss();
        assertFalse(form.isVisible());
    }

    @Test
    public void saveCreatesWaypointWithTypedNameInSelectedCategory()
    {
        store.createCategory("Bosses");
        form.show(packed);
        form.setNameText("Vorkath");
        form.selectCategoryByName("Bosses");

        form.clickSave();

        assertFalse(form.isVisible());
        assertEquals(1, store.getLibrary().getWaypoints().size());
        com.waypointer.model.Waypoint w = store.getLibrary().getWaypoints().get(0);
        assertEquals("Vorkath", w.getName());
        assertEquals(packed, w.getPackedWorldPoint());
        assertEquals(store.getCategoryByName("Bosses").getId(), w.getCategoryId());
    }

    @Test
    public void saveWithBlankNameFallsBackToDefault()
    {
        form.show(packed);
        form.setNameText("   ");

        form.clickSave();

        assertEquals("Lumbridge", store.getLibrary().getWaypoints().get(0).getName());
    }

    @Test
    public void cancelHidesFormAndCreatesNoWaypoint()
    {
        form.show(packed);
        form.setNameText("ignored");

        form.clickCancel();

        assertFalse(form.isVisible());
        assertEquals(0, store.getLibrary().getWaypoints().size());
    }

    @Test
    public void newCategorySentinelRevealsInlineSubRow()
    {
        form.show(packed);
        assertFalse(form.isNewCategoryRowVisible());

        form.selectNewCategorySentinel();

        assertTrue(form.isNewCategoryRowVisible());
    }

    @Test
    public void createInlineCategoryAddsCategoryAndSelectsIt()
    {
        form.show(packed);
        form.selectNewCategorySentinel();
        form.setNewCategoryNameText("Bosses");

        form.clickCreateNewCategory();

        assertFalse("sub-row should hide once category is created",
            form.isNewCategoryRowVisible());
        assertEquals("Bosses",
            ((CategoryComboItem) form.selectedCategoryItem()).toString());
    }

    @Test
    public void saveAfterCreateInlineCategoryStoresWaypointInThatCategory()
    {
        form.show(packed);
        form.selectNewCategorySentinel();
        form.setNewCategoryNameText("Bosses");
        form.clickCreateNewCategory();
        form.setNameText("Vorkath");

        form.clickSave();

        com.waypointer.model.Category created = store.getCategoryByName("Bosses");
        assertEquals(created.getId(),
            store.getLibrary().getWaypoints().get(0).getCategoryId());
    }

    @Test
    public void cancelInlineCategoryRevertsComboSelection()
    {
        store.createCategory("Existing");
        form.show(packed);
        form.selectCategoryByName("Existing");
        form.selectNewCategorySentinel();

        form.clickCancelNewCategory();

        assertFalse(form.isNewCategoryRowVisible());
        assertEquals("Existing",
            ((CategoryComboItem) form.selectedCategoryItem()).toString());
    }

    @Test
    public void duplicateCategoryNameShowsInlineErrorAndKeepsFormOpen()
    {
        store.createCategory("Bosses");
        form.show(packed);
        form.selectNewCategorySentinel();
        form.setNewCategoryNameText("Bosses");

        form.clickCreateNewCategory();

        assertTrue(form.isVisible());
        assertTrue(form.isNewCategoryRowVisible());
        assertTrue("inline error should mention duplicate name, got: " + form.getErrorText(),
            form.getErrorText().contains("Bosses"));
        assertEquals("no second category should have been created",
            1L, store.getCategoriesOrdered().stream()
                .filter(c -> "Bosses".equals(c.getName())).count());
    }

    @Test
    public void showResetsNameAndClearsOpenSubRow()
    {
        int packed2 = WorldPointPacker.pack(2964, 3380, 0);
        when(capture.defaultName(packed2)).thenReturn("Falador");

        form.show(packed);
        form.setNameText("scratch");
        form.selectNewCategorySentinel();
        form.setNewCategoryNameText("WIP");

        form.show(packed2);

        assertEquals("Falador", form.getNameText());
        assertFalse("sub-row should be cleared on re-entry",
            form.isNewCategoryRowVisible());
    }

    @Test
    public void showWithDefaultNamePrefillsThatNameInsteadOfCaptureDefault()
    {
        form.show(packed, "Vorkath", null);
        assertTrue(form.isVisible());
        assertEquals("Vorkath", form.getNameText());
    }

    @Test
    public void saveWithNpcNamePersistsTheNpcLink()
    {
        form.show(packed, "Hans", "Hans");
        form.clickSave();

        assertEquals(1, store.getLibrary().getWaypoints().size());
        com.waypointer.model.Waypoint w = store.getLibrary().getWaypoints().get(0);
        assertEquals("Hans", w.getName());
        assertEquals("Hans", w.getTargetNpcName());
    }

    @Test
    public void subsequentPlainShowClearsNpcLink()
    {
        form.show(packed, "Hans", "Hans");
        form.clickSave(); // first save: NPC waypoint

        int packed2 = WorldPointPacker.pack(3222, 3219, 0);
        when(capture.defaultName(packed2)).thenReturn("Tile");
        form.show(packed2); // plain show - no NPC
        form.clickSave();   // second save: plain tile

        com.waypointer.model.Waypoint second = store.getLibrary().getWaypoints().get(1);
        assertNull("targetNpcName must not leak into a non-NPC capture", second.getTargetNpcName());
    }
}

package com.waypointer.ui;

import com.waypointer.model.Category;
import com.waypointer.model.Library;
import com.waypointer.service.WaypointStore;
import java.util.UUID;
import javax.swing.JComboBox;
import org.junit.Test;
import static org.junit.Assert.*;

public class CategoryComboControllerTest
{
    private static WaypointStore freshStore()
    {
        // In-memory store, bootstrapped with an empty library (no debounced persistence wired).
        // Mirrors the existing CaptureFormTest setup.
        WaypointStore store = new WaypointStore();
        store.bootstrap(new Library());
        return store;
    }

    @Test
    public void rebuildListsOrderedCategoriesPlusSentinel()
    {
        WaypointStore store = freshStore();
        Category a = store.createCategory("Alpha");
        JComboBox<CategoryComboItem> combo = new JComboBox<>();
        CategoryComboController c = new CategoryComboController(combo, store);

        c.rebuild(a.getId());

        // last item is the "+ New category..." sentinel
        CategoryComboItem last = combo.getItemAt(combo.getItemCount() - 1);
        assertTrue("last item should be the sentinel", last.isSentinel());
        // the requested id is selected
        CategoryComboItem sel = (CategoryComboItem) combo.getSelectedItem();
        assertNotNull(sel);
        assertEquals(a.getId(), sel.id());
    }

    @Test
    public void resolveSelectedIdReturnsUncategorizedForSentinel()
    {
        WaypointStore store = freshStore();
        JComboBox<CategoryComboItem> combo = new JComboBox<>();
        CategoryComboController c = new CategoryComboController(combo, store);
        c.rebuild(store.getUncategorized().getId());

        // select the sentinel (last item)
        combo.setSelectedIndex(combo.getItemCount() - 1);

        assertTrue(c.isSentinelSelected());
        assertEquals(store.getUncategorized().getId(), c.resolveSelectedId());
    }

    @Test
    public void resolveSelectedIdReturnsRealCategoryWhenSelected()
    {
        WaypointStore store = freshStore();
        Category a = store.createCategory("Alpha");
        JComboBox<CategoryComboItem> combo = new JComboBox<>();
        CategoryComboController c = new CategoryComboController(combo, store);
        c.rebuild(a.getId());

        assertFalse(c.isSentinelSelected());
        assertEquals(a.getId(), c.resolveSelectedId());
    }

    @Test
    public void rebuildWithUnknownIdSelectsFirstItemAndLeavesLastNonSentinelNull()
    {
        WaypointStore store = freshStore();
        store.createCategory("Alpha");
        JComboBox<CategoryComboItem> combo = new JComboBox<>();
        CategoryComboController c = new CategoryComboController(combo, store);

        // An id that is not in the store: rebuild finds no match, so it selects nothing
        // explicitly -- JComboBox defaults to index 0 -- and lastNonSentinel stays null.
        c.rebuild(UUID.randomUUID());

        assertEquals(0, combo.getSelectedIndex());
        assertFalse("first item is a real category, not the sentinel", c.isSentinelSelected());
        assertNull("no match means lastNonSentinel was never assigned", c.lastNonSentinel());
    }
}

