package com.waypointer.ui;

import com.waypointer.model.Library;
import com.waypointer.preset.Preset;
import com.waypointer.preset.PresetCatalog;
import com.waypointer.preset.PresetWaypoint;
import com.waypointer.service.WaypointStore;
import java.awt.Component;
import java.util.Arrays;
import java.util.Collections;
import java.util.UUID;
import net.runelite.client.game.SpriteManager;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class PresetBrowserPanelTest
{
    @Test
    public void reportedHeightIsZero()
    {
        PresetBrowserPanel panel = buildPanel();
        assertEquals(0, panel.getPreferredSize().height);
        assertEquals(0, panel.getMinimumSize().height);
    }

    @Test
    public void noToastTextAfterConstruction()
    {
        PresetBrowserPanel panel = buildPanel();
        org.junit.Assert.assertNull("no toast text expected at construction",
            panel.lastToastTextForTest());
    }

    @Test
    public void addDoesNotShowToast()
    {
        PresetBrowserPanel panel = buildPanel();
        Preset preset = new Preset("Cities", "", null,
            Collections.singletonList(new PresetWaypoint("Varrock", "", 3210, 3424, 0)));

        UUID newId = panel.addWaypoint(preset, preset.getWaypoints().get(0));
        assertNotNull("addWaypoint should return the new UUID", newId);
        org.junit.Assert.assertNull("add path should not call toast",
            panel.lastToastTextForTest());
    }

    @Test
    public void toastShowsRemovedMessageAfterRemove()
    {
        PresetBrowserPanel panel = buildPanel();
        Preset preset = new Preset("Cities", "", null,
            Collections.singletonList(new PresetWaypoint("Varrock", "", 3210, 3424, 0)));

        UUID newId = panel.addWaypoint(preset, preset.getWaypoints().get(0));
        panel.removeWaypoint(newId);

        String last = panel.lastToastTextForTest();
        assertNotNull("remove should fire a toast", last);
        assertTrue("expected toast to mention the waypoint, got: " + last,
            last.contains("Varrock"));
    }

    @Test
    public void rebuildAfterStoreMutationPreservesExpandedSections()
    {
        WaypointStore store = new WaypointStore();
        store.bootstrap(new Library());

        Preset cities = new Preset("Cities", "", null,
            Arrays.asList(new PresetWaypoint("Varrock", "", 3210, 3424, 0)));
        Preset bosses = new Preset("Bosses", "", null,
            Arrays.asList(new PresetWaypoint("Vorkath", "", 2272, 4052, 0)));
        PresetCatalog catalog = mock(PresetCatalog.class);
        when(catalog.getPresets()).thenReturn(Arrays.asList(cities, bosses));

        PresetBrowserPanel panel = new PresetBrowserPanel(catalog, store, mock(SpriteManager.class));
        PresetSection citiesSection = findSection(panel, "Cities");
        assertNotNull("Cities section must render", citiesSection);
        citiesSection.setExpanded(true);
        assertTrue("Cities should be expanded after setExpanded", citiesSection.isExpanded());

        panel.scheduleRebuildForTest();

        PresetSection citiesAfter = findSection(panel, "Cities");
        assertNotNull("Cities section still renders after rebuild", citiesAfter);
        assertTrue("Cities should remain expanded across rebuild",
            citiesAfter.isExpanded());

        PresetSection bossesAfter = findSection(panel, "Bosses");
        assertFalse("Bosses (not expanded before) should remain collapsed",
            bossesAfter.isExpanded());
    }

    @Test
    public void disposeReleasesStoreSubscription()
    {
        WaypointStore store = new WaypointStore();
        store.bootstrap(new Library());

        int before = store.listenerCountForTest();
        PresetBrowserPanel panel = buildPanelWithStore(store);
        int afterConstruct = store.listenerCountForTest();
        assertEquals("constructor must add exactly one listener",
            before + 1, afterConstruct);

        panel.dispose();
        assertEquals("dispose must release the listener",
            before, store.listenerCountForTest());
    }

    private static PresetBrowserPanel buildPanel()
    {
        WaypointStore store = new WaypointStore();
        store.bootstrap(new Library());
        return buildPanelWithStore(store);
    }

    private static PresetBrowserPanel buildPanelWithStore(WaypointStore store)
    {
        PresetCatalog catalog = mock(PresetCatalog.class);
        when(catalog.getPresets()).thenReturn(Collections.emptyList());
        return new PresetBrowserPanel(catalog, store, mock(SpriteManager.class));
    }

    private static PresetSection findSection(PresetBrowserPanel panel, String name)
    {
        return findSectionIn(panel, name);
    }

    private static PresetSection findSectionIn(Component c, String name)
    {
        if (c instanceof PresetSection)
        {
            PresetSection s = (PresetSection) c;
            if (name.equals(s.getPresetName())) return s;
        }
        if (c instanceof java.awt.Container)
        {
            for (Component child : ((java.awt.Container) c).getComponents())
            {
                PresetSection found = findSectionIn(child, name);
                if (found != null) return found;
            }
        }
        return null;
    }
}

package com.waypointer.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.waypointer.model.Category;
import com.waypointer.model.Library;
import com.waypointer.model.Waypoint;
import com.waypointer.model.route.RouteLibrary;
import com.waypointer.service.RouteStore;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import org.junit.Test;

public class RouteLibraryPickerTest
{
    private static Waypoint wp(String name, UUID cat, int sortOrder)
    {
        return new Waypoint(UUID.randomUUID(), name, 100 + sortOrder, cat, null, "",
            Instant.parse("2026-05-02T00:00:00Z"), sortOrder, false, null, false);
    }

    private static Library library(UUID catA, UUID catB)
    {
        Library lib = new Library();
        lib.getCategories().add(new Category(catB, "B", 1, false, null, false));
        lib.getCategories().add(new Category(catA, "A", 0, false, null, false));
        // Stored out of order on purpose.
        lib.getWaypoints().add(wp("b1", catB, 0));
        lib.getWaypoints().add(wp("a2", catA, 1));
        lib.getWaypoints().add(wp("a1", catA, 0));
        return lib;
    }

    private static List<String> names(List<Waypoint> list)
    {
        List<String> out = new ArrayList<>();
        for (Waypoint w : list) out.add(w.getName());
        return out;
    }

    @Test
    public void wholeCategoryAddsInStoredOrder()
    {
        UUID catA = UUID.randomUUID();
        UUID catB = UUID.randomUUID();
        WaypointPickerModel model = new WaypointPickerModel(library(catA, catB));
        model.selectNone();
        model.setCategoryChecked(catB, true);
        model.setCategoryChecked(catA, true);

        List<Waypoint> picked = model.checkedWaypointsInOrder();
        assertEquals(java.util.Arrays.asList("a1", "a2", "b1"), names(picked));

        RouteStore routes = new RouteStore();
        routes.bootstrap(new RouteLibrary());
        UUID routeId = routes.createRoute("R").getId();
        routes.addWaypointSteps(routeId, picked);
        assertEquals(3, routes.getRouteById(routeId).getSteps().size());
        assertEquals("a1", routes.getRouteById(routeId).getSteps().get(0).getLabel());
    }

    @Test
    public void nothingCheckedAddsNothing()
    {
        UUID catA = UUID.randomUUID();
        WaypointPickerModel model = new WaypointPickerModel(library(catA, UUID.randomUUID()));
        model.selectNone();
        assertTrue(model.checkedWaypointsInOrder().isEmpty());
        assertTrue(model.getSelectedWaypointIds().isEmpty());

        RouteStore routes = new RouteStore();
        routes.bootstrap(new RouteLibrary());
        UUID routeId = routes.createRoute("R").getId();
        int[] fires = {0};
        routes.subscribe(() -> fires[0]++);
        routes.addWaypointSteps(routeId, model.checkedWaypointsInOrder());
        assertEquals(0, fires[0]);
        assertTrue(routes.getRouteById(routeId).getSteps().isEmpty());
    }

    private static Waypoint wpAt(String name, UUID cat, int sortOrder, String created)
    {
        return new Waypoint(UUID.randomUUID(), name, 100 + sortOrder, cat, null, "",
            Instant.parse(created), sortOrder, false, null, false);
    }

    private static List<String> pickedFrom(com.waypointer.model.CategorySortMode mode)
    {
        UUID cat = UUID.randomUUID();
        Category c = new Category(cat, "C", 0, false, null, false);
        c.setSortMode(mode);
        Library lib = new Library();
        lib.getCategories().add(c);
        // sortOrder, name order and age all disagree with each other.
        lib.getWaypoints().add(wpAt("Bravo", cat, 0, "2026-01-02T00:00:00Z"));
        lib.getWaypoints().add(wpAt("Charlie", cat, 1, "2026-01-03T00:00:00Z"));
        lib.getWaypoints().add(wpAt("alpha", cat, 2, "2026-01-01T00:00:00Z"));
        WaypointPickerModel model = new WaypointPickerModel(lib);
        model.selectNone();
        model.setCategoryChecked(cat, true);
        return names(model.checkedWaypointsInOrder());
    }

    @Test
    public void wholeCategoryAddsInPanelOrderForNameSortedCategory()
    {
        assertEquals(java.util.Arrays.asList("alpha", "Bravo", "Charlie"),
            pickedFrom(com.waypointer.model.CategorySortMode.NAME));
    }

    @Test
    public void wholeCategoryAddsInPanelOrderForNewestFirstCategory()
    {
        assertEquals(java.util.Arrays.asList("Charlie", "Bravo", "alpha"),
            pickedFrom(com.waypointer.model.CategorySortMode.DATE_ADDED));
    }

    @Test
    public void manualCategoryKeepsSortOrder()
    {
        assertEquals(java.util.Arrays.asList("Bravo", "Charlie", "alpha"),
            pickedFrom(com.waypointer.model.CategorySortMode.MANUAL));
    }
}

package com.waypointer.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.waypointer.model.WorldPointPacker;
import com.waypointer.model.route.Route;
import com.waypointer.model.route.RouteStep;
import java.time.Instant;
import java.util.Arrays;
import java.util.List;
import java.util.UUID;
import org.junit.Test;

public class RouteOverlayTest
{
    private Route route(boolean repeating, RouteStep... steps)
    {
        return new Route(UUID.randomUUID(), "Herb run", Arrays.asList(steps), repeating, Instant.now(), 0);
    }

    @Test
    public void linesShowStepCounterAndCurrentText()
    {
        Route r = route(false,
            RouteStep.waypoint(WorldPointPacker.pack(1, 1, 0), "Bank"),
            RouteStep.manual("Withdraw seeds"),
            RouteStep.manual("Plant"));
        List<String> lines = RouteOverlay.buildLines(r, 1, 1, null);
        assertEquals("Step 2 / 3", lines.get(0));
        assertTrue(lines.contains("Withdraw seeds"));
        assertTrue(lines.stream().anyMatch(l -> l.startsWith("Next:")));
    }

    @Test
    public void repeatingShowsLapInCounter()
    {
        Route r = route(true, RouteStep.manual("a"), RouteStep.manual("b"));
        List<String> lines = RouteOverlay.buildLines(r, 0, 3, null);
        assertEquals("Step 1 / 2  -  Lap 3", lines.get(0));
    }

    @Test
    public void lastStepHasNoNextLine()
    {
        Route r = route(false, RouteStep.manual("only"));
        List<String> lines = RouteOverlay.buildLines(r, 0, 1, null);
        assertTrue(lines.stream().noneMatch(l -> l.startsWith("Next:")));
    }

    @Test
    public void boxTextOverridesLabelForCurrentAndNextLines()
    {
        RouteStep s0 = RouteStep.manual("Bank");
        s0.setBoxText("Withdraw 5 seeds");
        RouteStep s1 = RouteStep.manual("Plant");
        s1.setBoxText("Plant in patch 3");
        Route r = route(false, s0, s1);

        List<String> lines = RouteOverlay.buildLines(r, 0, 1, null);

        assertTrue(lines.contains("Withdraw 5 seeds"));
        assertFalse(lines.contains("Bank"));
        assertTrue(lines.contains("Next: Plant in patch 3"));
    }

    @Test
    public void fallsBackToLabelWhenNoBoxText()
    {
        Route r = route(false, RouteStep.manual("Withdraw seeds"));
        List<String> lines = RouteOverlay.buildLines(r, 0, 1, null);
        assertTrue(lines.contains("Withdraw seeds"));
    }

    @Test
    public void bearingLineSitsUnderCurrentStep()
    {
        Route r = route(false, RouteStep.waypoint(WorldPointPacker.pack(1, 1, 0), "Dock"),
            RouteStep.manual("Next thing"));
        List<String> lines = RouteOverlay.buildLines(r, 0, 1, "14 tiles NE");
        int at = lines.indexOf("Dock");
        assertEquals("14 tiles NE", lines.get(at + 1));
    }

    @Test
    public void noBearingLineWhenNull()
    {
        Route r = route(false, RouteStep.waypoint(WorldPointPacker.pack(1, 1, 0), "Dock"));
        assertFalse(RouteOverlay.buildLines(r, 0, 1, null).stream().anyMatch(l -> l.contains("tile")));
    }
}

package com.waypointer.ui;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;
import com.waypointer.model.route.Route;
