            mock(SailingBoats.class), mock(SailingBoatPin.class));
        PresetBrowserPanel presetPanel =
            new PresetBrowserPanel(catalog, store, mock(SpriteManager.class));

        RouteStore routeStore = mock(RouteStore.class);
        when(routeStore.subscribe(any())).thenReturn(mock(Listeners.Subscription.class));
        when(routeStore.getRoutesOrdered()).thenReturn(Collections.emptyList());
        RoutePlaybackEngine routeEngine = mock(RoutePlaybackEngine.class);
        when(routeEngine.subscribe(any())).thenReturn(mock(Listeners.Subscription.class));
        RouteRecorder routeRecorder = mock(RouteRecorder.class);
        RouteStorePersistence routePersistence = mock(RouteStorePersistence.class);
        when(routePersistence.isRefusingSaves()).thenReturn(false);
        RoutesPanel routesPanel = new RoutesPanel(routeStore, routeEngine, routeRecorder,
            mock(com.waypointer.codec.RouteShareCodec.class),
            mock(com.waypointer.service.WaypointStore.class), routePersistence);

        new TabHost(waypointerPanel, presetPanel, routesPanel, navigator, config,
            mock(ClientToolbar.class), store);

        assertEquals(false, routesPanel.getToastsForTest() == Toasts.NO_OP);
        org.junit.Assert.assertTrue(routesPanel.getToastsForTest() instanceof ToastOverlay);
    }

    private static TabHost buildHost()
    {
        WaypointPathfinder pathfinder = mock(WaypointPathfinder.class);
        when(pathfinder.subscribe(any())).thenReturn(mock(Listeners.Subscription.class));
        return buildHostWithPathfinder(pathfinder);
    }

    // Mocking WaypointerPanel directly is not viable: Mockito's subclass mock-maker
    // produces a JPanel subclass whose Container fields are uninitialized, and adding
    // such an instance to a real Container blows up inside Container.addImpl. So the
    // test uses a real WaypointerPanel built from mocks (same pattern as
    // WaypointerPanelTest.newPanel) — the inner panel's behaviour isn't under test
    // here; TabHost's tab/card wiring and subscription lifecycle are.
    private static TabHost buildHostWithPathfinder(WaypointPathfinder pathfinder)
    {
        WaypointStore store = new WaypointStore();
        store.bootstrap(new Library());

        PresetCatalog catalog = mock(PresetCatalog.class);
        when(catalog.getPresets()).thenReturn(Collections.emptyList());

        WaypointerConfig config = mock(WaypointerConfig.class);
        when(config.showPathingBanner()).thenReturn(true);
        when(config.categoryCollapsedJson()).thenReturn("{}");
        when(config.shortestPathBannerDismissed()).thenReturn(true);
        when(config.landmarkSelectionJson()).thenReturn("");
        when(config.routesEnabled()).thenReturn(false);

        WaypointStorePersistence persistence = mock(WaypointStorePersistence.class);
        when(persistence.isRefusingSaves()).thenReturn(false);

        Navigator navigator = LandNavigator.over(pathfinder);

        NearestLandmarkBar nearestLandmarkBar = new NearestLandmarkBar(
            mock(BboxIndex.class),
            pathfinder,
            navigator,
            mock(Client.class),
            mock(ClientThread.class),
            mock(SpriteManager.class),
            config,
            new Gson(),
            mock(com.waypointer.service.PlayerPosition.class));

        SailingJourneyOrchestrator sailingOrchestratorB = mock(SailingJourneyOrchestrator.class);
        WaypointerPanel waypointerPanel = new WaypointerPanel(
            store,
            mock(WaypointCapture.class),
            pathfinder,
            config,
            new CollapseStateCodec(new Gson()),
            persistence,
            mock(SpriteManager.class),
            null,
            null,
            nearestLandmarkBar,
            mock(Client.class),
            mock(ClientThread.class),
            mock(WildernessConfirmGate.class),
            mock(WaypointShareCodec.class),
            navigator,
            sailingOrchestratorB,
            mock(SailingBoats.class),
            mock(SailingBoatPin.class));
        PresetBrowserPanel presetPanel =
            new PresetBrowserPanel(catalog, store, mock(SpriteManager.class));

        RouteStore routeStore = mock(RouteStore.class);
        when(routeStore.subscribe(any())).thenReturn(mock(Listeners.Subscription.class));
        when(routeStore.getRoutesOrdered()).thenReturn(Collections.emptyList());
        RoutePlaybackEngine routeEngine = mock(RoutePlaybackEngine.class);
        when(routeEngine.subscribe(any())).thenReturn(mock(Listeners.Subscription.class));
        RouteRecorder routeRecorder = mock(RouteRecorder.class);
        RouteStorePersistence routePersistence = mock(RouteStorePersistence.class);
        when(routePersistence.isRefusingSaves()).thenReturn(false);
        RoutesPanel routesPanel = new RoutesPanel(routeStore, routeEngine, routeRecorder, mock(com.waypointer.codec.RouteShareCodec.class), mock(com.waypointer.service.WaypointStore.class), routePersistence);

        return new TabHost(waypointerPanel, presetPanel, routesPanel, navigator, config, mock(ClientToolbar.class), store);
    }
}

package com.waypointer.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;

import java.awt.event.MouseEvent;
import java.util.function.Consumer;
import javax.swing.JLabel;
import javax.swing.border.CompoundBorder;
import javax.swing.border.MatteBorder;
import net.runelite.client.ui.ColorScheme;
import org.junit.Test;

public class TabStripTest
{
    @Test
    public void initialActiveTabIsMyWaypoints()
    {
        TabStrip strip = new TabStrip(t -> { });
        assertEquals(TabStrip.Tab.MY_WAYPOINTS, strip.getActive());
        assertActiveBorderIsBrandOrange(strip, TabStrip.Tab.MY_WAYPOINTS);
        assertInactiveBorderIsDarkerGray(strip, TabStrip.Tab.PRESETS);
    }

    @Test
    public void setActiveSwapsBorders()
    {
        TabStrip strip = new TabStrip(t -> { });
        strip.setActive(TabStrip.Tab.PRESETS);
        assertEquals(TabStrip.Tab.PRESETS, strip.getActive());
        assertActiveBorderIsBrandOrange(strip, TabStrip.Tab.PRESETS);
        assertInactiveBorderIsDarkerGray(strip, TabStrip.Tab.MY_WAYPOINTS);
    }

    @Test
    public void clickFiresCallbackWithCorrectTab()
    {
        @SuppressWarnings("unchecked")
        Consumer<TabStrip.Tab> callback = mock(Consumer.class);
        TabStrip strip = new TabStrip(callback);

        clickLabel(strip.labelFor(TabStrip.Tab.PRESETS));
        verify(callback, times(1)).accept(TabStrip.Tab.PRESETS);

        clickLabel(strip.labelFor(TabStrip.Tab.MY_WAYPOINTS));
        verify(callback, times(1)).accept(TabStrip.Tab.MY_WAYPOINTS);
    }

    @Test
    public void labelsExistForBothTabs()
    {
        TabStrip strip = new TabStrip(t -> { });
        assertNotNull(strip.labelFor(TabStrip.Tab.MY_WAYPOINTS));
        assertNotNull(strip.labelFor(TabStrip.Tab.PRESETS));
    }

    @Test
    public void variableTabConstructorRendersThreeTabs()
    {
        TabStrip strip = new TabStrip(t -> {},
            java.util.Arrays.asList(TabStrip.Tab.MY_WAYPOINTS,
                TabStrip.Tab.PRESETS, TabStrip.Tab.ROUTES));
        assertNotNull(strip.labelFor(TabStrip.Tab.ROUTES));
    }

    private static void assertActiveBorderIsBrandOrange(TabStrip strip, TabStrip.Tab tab)
    {
        JLabel l = strip.labelFor(tab);
        assertNotNull("label must have a border", l.getBorder());
        CompoundBorder cb = (CompoundBorder) l.getBorder();
        MatteBorder mb = (MatteBorder) cb.getOutsideBorder();
        assertSame(ColorScheme.BRAND_ORANGE, mb.getMatteColor());
    }

    private static void assertInactiveBorderIsDarkerGray(TabStrip strip, TabStrip.Tab tab)
    {
        JLabel l = strip.labelFor(tab);
        CompoundBorder cb = (CompoundBorder) l.getBorder();
        MatteBorder mb = (MatteBorder) cb.getOutsideBorder();
        assertSame(ColorScheme.DARKER_GRAY_COLOR, mb.getMatteColor());
    }

    private static void clickLabel(JLabel label)
    {
        MouseEvent click = new MouseEvent(label, MouseEvent.MOUSE_CLICKED,
            System.currentTimeMillis(), 0, 5, 5, 1, false);
        for (java.awt.event.MouseListener ml : label.getMouseListeners())
        {
            ml.mouseClicked(click);
        }
    }
}

package com.waypointer.ui;

import javax.swing.JLabel;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ToastOverlayTest
{
    @Test
    public void wrapsContentAndStartsWithCardHidden()
    {
        JLabel content = new JLabel("inner");
        ToastOverlay overlay = new ToastOverlay(content);

        // The wrapped content is a direct child of the overlay (in some layer).
        boolean found = false;
        for (java.awt.Component c : overlay.getComponents())
        {
            if (c == content) found = true;
        }
        assertTrue("expected content to be a child of the overlay", found);

        // No card is visible until show() is called.
        assertFalse("toast card should be hidden initially", overlay.cardIsVisibleForTest());
    }

    @Test
    public void showMakesCardVisibleAndSetsText()
    {
        ToastOverlay overlay = new ToastOverlay(new JLabel("inner"));
        overlay.setSize(200, 300); // give it a non-zero bound so layout runs

        overlay.show("Added Varrock");

        assertTrue("card should be visible after show()", overlay.cardIsVisibleForTest());
        assertTrue("expected label to mention the message, got: " + overlay.cardLabelTextForTest(),
            overlay.cardLabelTextForTest().contains("Added Varrock"));
    }

    @Test
    public void showEscapesHtmlInMessage()
    {
        ToastOverlay overlay = new ToastOverlay(new JLabel("inner"));
        overlay.setSize(200, 300);

        overlay.show("<b>cheeky</b>");

        String rendered = overlay.cardLabelTextForTest();
        assertFalse("raw <b> should not appear in label HTML, got: " + rendered,
            rendered.contains("<b>cheeky</b>"));
        assertTrue("escaped marker should appear, got: " + rendered, rendered.contains("&lt;b&gt;"));
    }

    @Test
    public void showSchedulesAutoHideAtDefaultDuration()
    {
        ToastOverlay overlay = new ToastOverlay(new JLabel("inner"));
        overlay.setSize(200, 300);

        overlay.show("hi");

        javax.swing.Timer t = overlay.autoHideTimerForTest();
        org.junit.Assert.assertNotNull("expected timer to exist after show()", t);
        org.junit.Assert.assertTrue("expected timer to be running", t.isRunning());
        org.junit.Assert.assertEquals(2500, t.getDelay());
    }

    @Test
    public void showWithActionRendersActionLabel()
    {
        ToastOverlay overlay = new ToastOverlay(new JLabel("inner"));
        overlay.setSize(200, 300);

        overlay.show("Deleted Catherby", "Undo", () -> {});

        JLabel action = overlay.actionLabelForTest();
        org.junit.Assert.assertNotNull("expected action label to be rendered", action);
        org.junit.Assert.assertTrue("expected action label text 'Undo', got: " + action.getText(),
            action.getText().contains("Undo"));
        org.junit.Assert.assertTrue("expected action label visible", action.isVisible());
    }

    @Test
    public void clickingActionInvokesRunnableAndHidesCard()
    {
        ToastOverlay overlay = new ToastOverlay(new JLabel("inner"));
        overlay.setSize(200, 300);
        java.util.concurrent.atomic.AtomicInteger calls = new java.util.concurrent.atomic.AtomicInteger();
        overlay.show("Deleted Catherby", "Undo", calls::incrementAndGet);

        // Simulate a mouse click on the action label by dispatching the canonical click event.
        JLabel action = overlay.actionLabelForTest();
        java.awt.event.MouseEvent click = new java.awt.event.MouseEvent(
            action, java.awt.event.MouseEvent.MOUSE_CLICKED, System.currentTimeMillis(),
            0, 0, 0, 1, false);
        for (java.awt.event.MouseListener l : action.getMouseListeners()) l.mouseClicked(click);

        org.junit.Assert.assertEquals("runnable should fire exactly once", 1, calls.get());
        assertFalse("card should hide after action click", overlay.cardIsVisibleForTest());
    }

    @Test
    public void showWithActionUsesLongerDuration()
    {
        ToastOverlay overlay = new ToastOverlay(new JLabel("inner"));
        overlay.setSize(200, 300);

        overlay.show("Deleted Catherby", "Undo", () -> {});

        org.junit.Assert.assertEquals(6000, overlay.autoHideTimerForTest().getDelay());
    }

    @Test
    public void rapidShowReusesSameEntryAndDoesNotIncrementAnimationCount()
    {
        ToastOverlay overlay = new ToastOverlay(new JLabel("inner"));
        overlay.setSize(200, 300);

        overlay.show("first");
        int afterFirst = overlay.entryAnimationCountForTest();
        overlay.show("second");
        int afterSecond = overlay.entryAnimationCountForTest();

        org.junit.Assert.assertEquals(
            "second show() should reuse visible card, entry animation count must not increment",
            afterFirst, afterSecond);
        org.junit.Assert.assertTrue("expected second show() text to be reflected",
            overlay.cardLabelTextForTest().contains("second"));
    }

    @Test
    public void firstShowStartsAnimationOffScreenAndSettlesAtRestingY()
    {
        ToastOverlay overlay = new ToastOverlay(new JLabel("inner"));
        overlay.setSize(200, 300);

        overlay.show("hello");

        // Right after show(), the card should be at the off-screen start position.
        int startY = overlay.cardCurrentYForTest();
        org.junit.Assert.assertEquals("card should start at the bottom edge", 300, startY);

        // Finish the animation synchronously.
        overlay.completeEntryAnimationForTest();
        int settledY = overlay.cardCurrentYForTest();
        org.junit.Assert.assertTrue("card must settle above the bottom edge, got y=" + settledY,
            settledY < 300);
    }

    @Test
    public void replaceInPlacePulsesWithoutReanimatingEntry()
    {
        ToastOverlay overlay = new ToastOverlay(new JLabel("inner"));
        overlay.setSize(200, 300);

        overlay.show("first");
        int entryAfterFirst = overlay.entryAnimationCountForTest();
        org.junit.Assert.assertEquals("first show() slides in, it must not pulse",
            0, overlay.pulseCountForTest());

        overlay.show("second");

        org.junit.Assert.assertEquals("replace must not re-run the slide entry",
            entryAfterFirst, overlay.entryAnimationCountForTest());
        org.junit.Assert.assertEquals("replace must pulse exactly once",
            1, overlay.pulseCountForTest());
    }
}

package com.waypointer.ui;

import com.waypointer.model.Category;
import com.waypointer.model.Library;
import com.waypointer.model.Waypoint;
import java.time.Instant;
import java.util.UUID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class WaypointPickerModelTest
{
    private static Waypoint wp(UUID id, UUID catId)
    {
        return new Waypoint(id, "w", 1, catId, null, "",
            Instant.parse("2026-05-02T00:00:00Z"), 0, false, null, false);
    }

    @Test
    public void defaultsToAllChecked()
    {
        UUID cat = UUID.randomUUID();
        UUID a = UUID.randomUUID();
        Library lib = new Library();
        lib.getCategories().add(new Category(cat, "C", 0, false, null, false));
        lib.getWaypoints().add(wp(a, cat));

        WaypointPickerModel m = new WaypointPickerModel(lib);
        assertTrue(m.isWaypointChecked(a));
        assertEquals(WaypointPickerModel.Tri.CHECKED, m.categoryState(cat));
        assertFalse(m.isEmptySelection());
    }

    @Test
    public void childTogglesRollUpToPartialThenUnchecked()
    {
        UUID cat = UUID.randomUUID();
        UUID a = UUID.randomUUID();
        UUID b = UUID.randomUUID();
        Library lib = new Library();
        lib.getCategories().add(new Category(cat, "C", 0, false, null, false));
        lib.getWaypoints().add(wp(a, cat));
        lib.getWaypoints().add(wp(b, cat));

        WaypointPickerModel m = new WaypointPickerModel(lib);
        m.setWaypointChecked(a, false);
        assertEquals(WaypointPickerModel.Tri.PARTIAL, m.categoryState(cat));
        m.setWaypointChecked(b, false);
        assertEquals(WaypointPickerModel.Tri.UNCHECKED, m.categoryState(cat));
    }

    @Test
    public void categoryToggleCascadesToChildren()
    {
        UUID cat = UUID.randomUUID();
        UUID a = UUID.randomUUID();
        UUID b = UUID.randomUUID();
        Library lib = new Library();
        lib.getCategories().add(new Category(cat, "C", 0, false, null, false));
        lib.getWaypoints().add(wp(a, cat));
        lib.getWaypoints().add(wp(b, cat));

        WaypointPickerModel m = new WaypointPickerModel(lib);
        m.setCategoryChecked(cat, false);
        assertFalse(m.isWaypointChecked(a));
        assertFalse(m.isWaypointChecked(b));
        assertTrue(m.getSelectedWaypointIds().isEmpty());

        m.setCategoryChecked(cat, true);
        assertTrue(m.isWaypointChecked(a));
        assertEquals(2, m.getSelectedWaypointIds().size());
    }

    @Test
    public void emptyCategoryCheckTrackedExplicitly()
    {
        UUID cat = UUID.randomUUID();
        Library lib = new Library();
        lib.getCategories().add(new Category(cat, "Empty", 0, false, null, false));

        WaypointPickerModel m = new WaypointPickerModel(lib);
        assertEquals(WaypointPickerModel.Tri.CHECKED, m.categoryState(cat));
        assertTrue(m.getSelectedCategoryIds().contains(cat));

        m.setCategoryChecked(cat, false);
        assertEquals(WaypointPickerModel.Tri.UNCHECKED, m.categoryState(cat));
        assertTrue(m.isEmptySelection());
    }

    @Test
    public void selectNoneThenSelectAll()
    {
        UUID cat = UUID.randomUUID();
        UUID a = UUID.randomUUID();
        Library lib = new Library();
        lib.getCategories().add(new Category(cat, "C", 0, false, null, false));
        lib.getWaypoints().add(wp(a, cat));

        WaypointPickerModel m = new WaypointPickerModel(lib);
        m.selectNone();
        assertTrue(m.isEmptySelection());
        assertTrue(m.getSelectedWaypointIds().isEmpty());
        m.selectAll();
        assertEquals(1, m.getSelectedWaypointIds().size());
    }

    @Test
    public void partialCategoryIsExcludedFromSelectedCategoryIds()
    {
        UUID cat = UUID.randomUUID();
        UUID a = UUID.randomUUID();
        UUID b = UUID.randomUUID();
        Library lib = new Library();
        lib.getCategories().add(new Category(cat, "C", 0, false, null, false));
        lib.getWaypoints().add(wp(a, cat));
        lib.getWaypoints().add(wp(b, cat));

        WaypointPickerModel m = new WaypointPickerModel(lib);
        m.setWaypointChecked(a, false);
        assertEquals(WaypointPickerModel.Tri.PARTIAL, m.categoryState(cat));
        assertFalse(m.getSelectedCategoryIds().contains(cat));
        assertEquals(1, m.getSelectedWaypointIds().size());

        m.setWaypointChecked(a, true);
        assertEquals(WaypointPickerModel.Tri.CHECKED, m.categoryState(cat));
    }

    @Test
    public void fullyCheckedNonEmptyCategoryIsInSelectedCategoryIds()
    {
        UUID cat = UUID.randomUUID();
        UUID a = UUID.randomUUID();
        Library lib = new Library();
        lib.getCategories().add(new Category(cat, "C", 0, false, null, false));
        lib.getWaypoints().add(wp(a, cat));

        WaypointPickerModel m = new WaypointPickerModel(lib);
        assertTrue(m.getSelectedCategoryIds().contains(cat));
    }

    @Test
    public void selectAllCoversEveryCategory()
    {
        UUID c1 = UUID.randomUUID();
        UUID c2 = UUID.randomUUID();
        UUID a = UUID.randomUUID();
        UUID b = UUID.randomUUID();
        Library lib = new Library();
        lib.getCategories().add(new Category(c1, "One", 0, false, null, false));
        lib.getCategories().add(new Category(c2, "Two", 1, false, null, false));
        lib.getWaypoints().add(wp(a, c1));
        lib.getWaypoints().add(wp(b, c2));

        WaypointPickerModel m = new WaypointPickerModel(lib);
        m.selectNone();
        assertTrue(m.isEmptySelection());
        m.selectAll();
        assertEquals(2, m.getSelectedWaypointIds().size());
        assertEquals(WaypointPickerModel.Tri.CHECKED, m.categoryState(c1));
        assertEquals(WaypointPickerModel.Tri.CHECKED, m.categoryState(c2));
    }

    @Test
    public void uncategorizedSortsFirst()
    {
        UUID user = UUID.randomUUID();
        UUID unc = UUID.randomUUID();
        Library lib = new Library();
        lib.getCategories().add(new Category(user, "Banks", 0, false, null, false));
        lib.getCategories().add(new Category(unc, "Uncategorized", 5, true, null, false));

        WaypointPickerModel m = new WaypointPickerModel(lib);
        assertTrue(m.getOrderedCategories().get(0).isUncategorized());
    }
}

package com.waypointer.ui;

import com.waypointer.model.Waypoint;
import java.time.Instant;
import java.util.UUID;
import org.junit.Test;
import static org.junit.Assert.*;

/** Tests for {@link WaypointRow}'s pure helpers. The row itself is Swing-driven and untested. */
public class WaypointRowTest
{
    private static Waypoint wp(String name, String notes)
    {
        return new Waypoint(UUID.randomUUID(), name, 0, UUID.randomUUID(), null,
            notes == null ? "" : notes, Instant.parse("2026-05-02T00:00:00Z"), 0, false, null, false);
    }

    @Test
    public void emptyNotesReturnNamePlain()
    {
        assertEquals("Vorkath", WaypointRow.buildHoverTooltip(wp("Vorkath", "")));
        assertEquals("Vorkath", WaypointRow.buildHoverTooltip(wp("Vorkath", null)));
    }

    @Test
    public void notesPreviewWrapsNameAndFirstLineInHtml()
    {
        String tip = WaypointRow.buildHoverTooltip(wp("Vorkath", "Drops dragonbones"));
        assertTrue("expected HTML tooltip with name + notes preview, got: " + tip,
            tip.startsWith("<html>"));
        assertTrue(tip.contains("Vorkath"));
        assertTrue(tip.contains("Drops dragonbones"));
    }

    @Test
    public void multilineNotesShowOnlyFirstLine()
    {
        String tip = WaypointRow.buildHoverTooltip(
            wp("Yew", "100k/hr at 90 wc\nbring axe and energy pots\nbank at varrock"));
        assertTrue(tip.contains("100k/hr at 90 wc"));
        assertFalse("only first line of notes belongs in the preview",
            tip.contains("bring axe"));
    }

    @Test
    public void whitespaceOnlyFirstLineFallsBackToBareName()
    {
        // notes starts with newlines / blank line: preview is empty, so show name only.
        String tip = WaypointRow.buildHoverTooltip(wp("Yew", "   \n actual content"));
        assertEquals("Yew", tip);
    }

    @Test
    public void htmlInUserFieldsIsEscaped()
    {
        String tip = WaypointRow.buildHoverTooltip(
            wp("<script>alert('x')</script>", "more <evil> stuff"));
        assertFalse("name must be HTML-escaped", tip.contains("<script>"));
        assertTrue(tip.contains("&lt;script&gt;"));
        assertTrue(tip.contains("&lt;evil&gt;"));
    }

    @Test
    public void originCategoryAppendedAsThirdTooltipLine()
    {
        Waypoint w = wp("Home", "");
        String tip = WaypointRow.buildHoverTooltip(w, "Houses");
        assertTrue("expected html, got: " + tip, tip.startsWith("<html>"));
        assertTrue(tip.contains("Home"));
        assertTrue(tip.contains("Houses"));
        assertTrue("origin tag should appear", tip.contains("in Houses"));
    }

    @Test
    public void nullOriginCategoryFallsBackToOriginalTooltip()
    {
        Waypoint w = wp("Home", "Personal");
        assertEquals(WaypointRow.buildHoverTooltip(w), WaypointRow.buildHoverTooltip(w, null));
    }

    @Test
    public void accessibleNamePlainWhenNoState()
    {
        assertEquals("Varrock", WaypointRow.accessibleName("Varrock", false, false));
    }

    @Test
    public void accessibleNameAppendsWilderness()
    {
        assertEquals("Chaos Altar (in Wilderness)",
            WaypointRow.accessibleName("Chaos Altar", true, false));
    }

    @Test
    public void accessibleNameAppendsPinned()
    {
        assertEquals("Home (pinned)", WaypointRow.accessibleName("Home", false, true));
    }

    @Test
    public void accessibleNameAppendsBothInOrder()
    {
        assertEquals("Rev Caves (in Wilderness) (pinned)",
            WaypointRow.accessibleName("Rev Caves", true, true));
    }

    @Test
    public void accessibleNameNullBaseIsEmptyPrefix()
    {
        assertEquals(" (pinned)", WaypointRow.accessibleName(null, false, true));
    }
}

